async function refreshMyApiModels() {
  if (!window.CanvasAuth?.isLoggedIn?.()) return;
  try {
    const data = await api("/api/media-models");
    const myapi = Array.isArray(data?.myapi) ? data.myapi : [];
    const pub = Array.isArray(data?.public) ? data.public : [];
    const merged = [...pub, ...myapi];
    const nextMap = new Map();
    const nextPrices = new Map();
    const ingestPrices = (id, prices) => {
      const normalized = normalizeResolutionPriceMap(prices);
      if (id && normalized) nextPrices.set(String(id), normalized);
    };
    for (const m of merged) {
      if (!m?.id) continue;
      ingestPrices(m.id, m.resolution_prices);
      nextMap.set(m.id, {
        ...m,
        public: !!m.public || String(m.id).startsWith("public_"),
        points_required: !!m.points_required,
        billing_mode: m.billing_mode || "per_use",
        points_price: m.points_price || "0.000",
        resolution_prices: normalizeResolutionPriceMap(m.resolution_prices) || nextPrices.get(String(m.id)) || null,
      });
    }
    // Overlay billing fields from typed lists (video/image/text).
    for (const list of [data?.video, data?.image, data?.text]) {
      if (!Array.isArray(list)) continue;
      for (const m of list) {
        if (!m?.id) continue;
        ingestPrices(m.id, m.resolution_prices);
        if (!nextMap.has(m.id)) continue;
        const prev = nextMap.get(m.id);
        const prices =
          normalizeResolutionPriceMap(m.resolution_prices) ||
          nextPrices.get(String(m.id)) ||
          prev.resolution_prices;
        nextMap.set(m.id, {
          ...prev,
          points_required: m.points_required != null ? !!m.points_required : prev.points_required,
          billing_mode: m.billing_mode || prev.billing_mode,
          points_price: m.points_price || prev.points_price,
          resolution_prices: prices,
          public: !!(m.public || prev.public || String(m.id).startsWith("public_")),
        });
      }
    }
    // Commit atomically so a mid-refresh error cannot wipe prices.
    MYAPI_MODELS_BY_ID.clear();
    for (const [id, meta] of nextMap) MYAPI_MODELS_BY_ID.set(id, meta);
    PUBLIC_RESOLUTION_PRICES.clear();
    for (const [id, prices] of nextPrices) PUBLIC_RESOLUTION_PRICES.set(id, prices);
    // Ensure every mapped public video keeps its price table on the meta object.
    for (const [id, prices] of PUBLIC_RESOLUTION_PRICES) {
      const meta = MYAPI_MODELS_BY_ID.get(id);
      if (meta && !meta.resolution_prices) {
        meta.resolution_prices = prices;
        MYAPI_MODELS_BY_ID.set(id, meta);
      }
    }
    // 关闭「允许前台自定义模型」时，选择器只保留公共模型
    const allowCustom = window.AppConfig?.allow_frontend_custom_models !== false;
    const forPicker = (m) =>
      allowCustom || !!(m.public || String(m.id || "").startsWith("public_"));
    MYAPI_IMAGE_MODELS = merged.filter((m) => m.kind === "image" && forPicker(m)).map(mapMyApiModelEntry);
    MYAPI_VIDEO_MODELS = merged.filter((m) => m.kind === "video" && forPicker(m)).map(mapMyApiModelEntry);
    MYAPI_TEXT_MODELS = merged.filter((m) => m.kind === "text" && forPicker(m)).map(mapMyApiModelEntry);
    MYAPI_VOICE_MODELS = merged.filter((m) => m.kind === "voice" && forPicker(m)).map(mapMyApiModelEntry);
    const preferDefault = (a, b) => (b.is_default ? 1 : 0) - (a.is_default ? 1 : 0);
    MYAPI_IMAGE_MODELS.sort(preferDefault);
    MYAPI_VIDEO_MODELS.sort(preferDefault);
    MYAPI_TEXT_MODELS.sort(preferDefault);
    MYAPI_VOICE_MODELS.sort(preferDefault);
    MYAPI_MODELS_VERSION += 1;
    if (!allowCustom && typeof CanvasStore !== "undefined" && CanvasStore.boards) {
      let snapped = false;
      for (const board of CanvasStore.boards) {
        for (const node of board.nodes || []) {
          if (!node || !isGenerativeNode(node)) continue;
          if (node.channel !== "myapi" && !isMyApiModel(node.model)) continue;
          const mid = String(node.model || "");
          const meta = getMyApiModelMeta(mid);
          const isPublic = !!(meta?.public || mid.startsWith("public_"));
          if (isPublic) continue;
          const list =
            node.type === "video"
              ? MYAPI_VIDEO_MODELS
              : node.type === "voice"
                ? MYAPI_VOICE_MODELS
                : isTextGenNode(node)
                  ? MYAPI_TEXT_MODELS
                  : MYAPI_IMAGE_MODELS;
          const next = list[0]?.id || null;
          if (node.model !== next) {
            CanvasStore.updateNode(node.id, { model: next }, false);
            snapped = true;
          }
        }
      }
      if (snapped) CanvasStore.save?.();
    }
    const snappedModels = typeof ensureMyApiNodeModels === "function" && ensureMyApiNodeModels({ persist: true });
    const onCanvas = !document.getElementById("app-root")?.classList.contains("is-workspace");
    if (snappedModels && onCanvas && typeof refreshMyApiNodeToolbars === "function") {
      refreshMyApiNodeToolbars();
    } else if (typeof CanvasStore !== "undefined" && CanvasStore.activeBoard) {
      for (const node of CanvasStore.activeBoard()?.nodes || []) {
        if (isGenerativeNode(node)) {
          if (typeof updateGenCostBadge === "function") updateGenCostBadge(node.id);
        }
      }
    }
  } catch {
    /* keep previous */
  }
  // Drop orphaned MyApi channel when that kind has no models
  if (typeof CanvasStore !== "undefined" && CanvasStore.boards) {
    for (const board of CanvasStore.boards) {
      for (const node of board.nodes || []) {
        if (node.channel !== "myapi" && !isMyApiModel(node.model)) continue;
        if (hasMyApiModelsForType(node.type)) continue;
        // Canvas-only pack stays on MyApi — clear stale model id, show「模型无」.
        if (!isBrowserChannelEnabled()) {
          if (node.channel !== "myapi" || node.model) {
            CanvasStore.updateNode(node.id, { channel: "myapi", model: null });
          }
          continue;
        }
        const fallback = isDoubaoChannelEnabled()
          ? "doubao"
          : preferredChannelForType(node.type, { allowGpt: node.type !== "video" });
        const patch = {
          channel: fallback,
          model: defaultModelForChannel(fallback, node.type) || null,
        };
        if (node.type === "image") patch.style = node.style || null;
        CanvasStore.updateNode(node.id, patch);
      }
    }
    syncMyApiVideoNodesFromModelConfig();
  }
}


/** Assign default MyApi/public model when node.model is empty/stale so toolbar + points match. */
function ensureMyApiNodeModels({ persist = false } = {}) {
  if (typeof CanvasStore === "undefined" || !CanvasStore.boards) return false;
  let changed = false;
  for (const board of CanvasStore.boards) {
    for (const node of board.nodes || []) {
      if (!node || !isGenerativeNode(node)) continue;
      if (isReferenceNode(node)) continue;
      const channel = typeof normalizeChannel === "function"
        ? normalizeChannel(node.channel, node.model)
        : node.channel;
      if (channel !== "myapi" && !(typeof isMyApiModel === "function" && isMyApiModel(node.model))) continue;
      if (
        typeof hasMyApiModelsForType === "function" &&
        !hasMyApiModelsForType(isTextGenNode(node) ? "text" : node.type)
      )
        continue;
      const list =
        node.type === "video"
          ? MYAPI_VIDEO_MODELS
          : node.type === "voice"
            ? MYAPI_VOICE_MODELS
            : isTextGenNode(node)
              ? MYAPI_TEXT_MODELS
              : MYAPI_IMAGE_MODELS;
      if (list.some((m) => m.id === node.model)) continue;
      const next = list[0]?.id || null;
      if (node.model === next && node.channel === "myapi") continue;
      node.channel = "myapi";
      node.model = next;
      if (node.type === "video" && next) {
        if (node.duration == null) node.duration = 10;
        if (!node.resolution) node.resolution = "自动";
        if (typeof clampVideoDuration === "function") {
          node.duration = clampVideoDuration(node.duration ?? 10, next);
        }
      }
      changed = true;
    }
  }
  if (changed && persist) CanvasStore.save?.();
  return changed;
}
window.ensureMyApiNodeModels = ensureMyApiNodeModels;

async function applyMyApiModelsToCanvas() {
  await refreshMyApiModels();
  ensureMyApiNodeModels({ persist: true });
  const onCanvas = !document.getElementById("app-root")?.classList.contains("is-workspace");
  if (onCanvas) refreshMyApiNodeToolbars();
  // Workbench model dropdowns are separate from canvas node toolbars.
  if (typeof refreshWorkbenchMyApiToolbars === "function") refreshWorkbenchMyApiToolbars();
}

function refreshMyApiNodeToolbars() {
  const board = CanvasStore.activeBoard?.();
  if (!board) return;
  for (const node of board.nodes || []) {
    if (!isGenerativeNode(node)) continue;
    if (isReferenceNode(node)) continue;
    refreshNodeMediaToolbar(node);
  }
}

function refreshNodeMediaToolbar(node) {
  const wrap = document.querySelector(`.node-wrap[data-id="${CSS.escape(node.id)}"]`);
  if (!wrap) return;
  const old = wrap.querySelector(".panel-toolbar");
  if (!old) return;
  const isVideo = node.type === "video";
  const inner = isVideo
    ? renderVideoToolbar(node)
    : node.type === "image"
      ? renderImageToolbar(node)
      : node.type === "voice"
        ? renderVoiceToolbar(node)
        : renderTextToolbar(node);
  const cls = `panel-toolbar${isVideo ? " video-toolbar" : ""}`;
  const tmp = document.createElement("div");
  tmp.innerHTML = `<div class="${cls}">${inner}</div>`;
  const next = tmp.firstElementChild;
  if (!next) return;
  old.replaceWith(next);
  wrap.dataset.fp = nodeDomFingerprint(node);
  wrap.dataset.structFp = nodeStructuralFingerprint(node);
}

