/** Migrate legacy model ids saved on canvas nodes */
function normalizeNodeModelId(type, modelId) {
  const id = String(modelId || "");
  if (type === "video") {
    if (id === "seedance_v2.0_pro") return "seedance_v2.0";
    return id;
  }
  if (type === "image") {
    if (id === "seedream_v5.0") return "seedream_v5.0_pro";
    return id;
  }
  return id;
}
const IMAGE_RATIOS = ["自动", "16:9", "9:16", "2:3", "3:4", "1:1", "4:3", "3:2"];
const VIDEO_RATIOS = ["自动", "16:9", "3:4", "4:3", "9:16", "1:1", "21:9"];
function isDolaVideoModel(modelId) {
  const id = String(modelId || "");
  return DOLA_VIDEO_MODELS.some((m) => m.id === id);
}
const DEFAULT_VIDEO_RESOLUTIONS = ["480p", "720p", "1080p"];
