function formatFcTime(seconds) {
  const s = Math.max(0, Number(seconds) || 0);
  const m = Math.floor(s / 60);
  const rem = s - m * 60;
  const whole = Math.floor(rem);
  const cs = Math.round((rem - whole) * 100);
  const csClamped = cs === 100 ? 99 : cs;
  return `${String(m).padStart(2, "0")}:${String(whole).padStart(2, "0")}.${String(csClamped).padStart(2, "0")}`;
}

function parseFcTime(raw) {
  const text = String(raw || "").trim();
  if (!text) return null;
  if (/^\d+(\.\d+)?$/.test(text)) return Math.max(0, Number(text));
  const parts = text.split(":");
  if (parts.length === 2) {
    const m = Number(parts[0]);
    const sec = Number(parts[1]);
    if (!Number.isFinite(m) || !Number.isFinite(sec)) return null;
    return Math.max(0, m * 60 + sec);
  }
  if (parts.length === 3) {
    const h = Number(parts[0]);
    const m = Number(parts[1]);
    const sec = Number(parts[2]);
    if (![h, m, sec].every(Number.isFinite)) return null;
    return Math.max(0, h * 3600 + m * 60 + sec);
  }
  return null;
}

const VIDEO_SEEK_END = Infinity;
let frameCaptureHelper = null;
let frameCaptureHelperUrl = "";

function peekNodePreviewVideoEl(nodeId) {
  const preview = document.querySelector(`.node-preview.has-video[data-video-node="${nodeId}"]`);
  return preview?.querySelector("video") || null;
}

function nodePreviewVideoEl(nodeId) {
  const preview = document.querySelector(`.node-preview.has-video[data-video-node="${nodeId}"]`);
  if (preview) ensureNodeVideoLoaded(preview);
  return preview?.querySelector("video") || null;
}

/** Prefetch a video URL into a hidden warmer so the first lightbox open after refresh is not cold. */
let _vlUrlWarmer = null;
function warmVideoUrl(url) {
  const resolved = resolveMediaUrl(url);
  if (!resolved || /^data:/i.test(resolved)) return;
  if (VideoLightbox.isOpen()) return;
  // Warm the actual modal player: a second hidden player cannot hand over its
  // decoded frames or in-flight request when the user double-clicks.
  _vlUrlWarmer = document.getElementById("vl-video");
  if (!_vlUrlWarmer) return;
  VideoLightbox.retainVideoBriefly();
  if (lightboxVideoMatchesUrl(_vlUrlWarmer, resolved)) return;
  _vlUrlWarmer.dataset.warmUrl = resolved;
  try {
    _vlUrlWarmer.pause();
  } catch {
    /* ignore */
  }
  _vlUrlWarmer.src = resolved;
  try {
    _vlUrlWarmer.load();
  } catch {
    /* ignore */
  }
}

function lightboxVideoMatchesUrl(video, url) {
  if (!video || video.error) return false;
  const src = video.getAttribute("src");
  if (!src) return false;
  try {
    return new URL(src, window.location.origin).href === new URL(url, window.location.origin).href;
  } catch {
    return src === url;
  }
}

function warmVideoLightboxNode(nodeId) {
  if (!nodeId) return;
  const preview = document.querySelector(`.node-preview.has-video[data-video-node="${nodeId}"]`);
  const previewVid = preview?.querySelector("video");
  const fromEl =
    previewVid?.dataset?.src ||
    previewVid?.getAttribute("src") ||
    previewVid?.currentSrc ||
    "";
  if (fromEl) {
    warmVideoUrl(fromEl);
    return;
  }
  let node =
    (typeof VideoLightbox !== "undefined" && VideoLightbox._nodesById?.get?.(nodeId)) ||
    CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId) ||
    null;
  if (!node && typeof workbenchMediaNode === "function") {
    try {
      node = workbenchMediaNode(nodeId);
    } catch {
      node = null;
    }
  }
  const url = node?.videoUrl ? resolveMediaUrl(node.videoUrl) : "";
  if (url) warmVideoUrl(url);
}

/** Prefer lightbox playhead when that video is open; else canvas preview. */
function getVideoCaptureCurrentTime(nodeId) {
  if (typeof VideoLightbox !== "undefined" && VideoLightbox.isOpen?.()) {
    const openId = VideoLightbox.nodeIds?.[VideoLightbox.index];
    const vl = VideoLightbox.video?.();
    if (openId === nodeId && vl && Number.isFinite(vl.currentTime)) {
      try {
        vl.pause();
      } catch {
        /* ignore */
      }
      VideoLightbox.syncPlayUi?.();
      return Math.max(0, vl.currentTime || 0);
    }
  }
  const previewVideo = nodePreviewVideoEl(nodeId);
  return Math.max(0, previewVideo?.currentTime || 0);
}

function videoSrcKey(video) {
  return String(video?.currentSrc || video?.src || "");
}

function videoSeekableEnd(video) {
  try {
    const ranges = video?.seekable;
    if (ranges && ranges.length > 0) {
      const end = ranges.end(ranges.length - 1);
      if (Number.isFinite(end) && end > 0) return end;
    }
  } catch {
    /* ignore */
  }
  const dur = Number.isFinite(video?.duration) && video.duration > 0 ? video.duration : 0;
  return dur;
}

function videoEndCaptureTime(video) {
  const end = videoSeekableEnd(video);
  if (!(end > 0)) return 0;
  return Math.max(0, end - 0.05);
}

function videoNearTime(video, target, ratio = 0.4) {
  const end = videoEndCaptureTime(video) || videoSeekableEnd(video);
  if (!(end > 0)) return false;
  return (video?.currentTime || 0) >= end * ratio;
}

async function waitForVideoMeta(video, timeoutMs = 5000) {
  if (!video) throw new Error("未找到视频");
  if (video.readyState >= 1 && videoSeekableEnd(video) > 0) return;
  await new Promise((resolve, reject) => {
    let done = false;
    const finish = (ok) => {
      if (done) return;
      done = true;
      cleanup();
      if (ok) resolve();
      else reject(new Error("视频加载失败"));
    };
    const cleanup = () => {
      clearTimeout(timer);
      video.removeEventListener("loadedmetadata", onMeta);
      video.removeEventListener("error", onErr);
    };
    const onMeta = () => {
      if (video.readyState >= 1 && videoSeekableEnd(video) > 0) finish(true);
    };
    const onErr = () => finish(false);
    const timer = setTimeout(() => finish(video.readyState >= 1), timeoutMs);
    video.addEventListener("loadedmetadata", onMeta);
    video.addEventListener("error", onErr);
    if (video.readyState >= 1) onMeta();
  });
}

async function waitVideoFramePainted(video) {
  if (!video) return;
  if (typeof video.requestVideoFrameCallback === "function") {
    await new Promise((resolve) => {
      video.requestVideoFrameCallback(() => resolve());
    });
    return;
  }
  await new Promise((r) => requestAnimationFrame(r));
}

function ensureFrameCaptureHelper() {
  if (!frameCaptureHelper) {
    frameCaptureHelper = document.createElement("video");
    frameCaptureHelper.muted = true;
    frameCaptureHelper.playsInline = true;
    frameCaptureHelper.preload = "metadata";
    frameCaptureHelper.style.cssText =
      "position:fixed;width:1px;height:1px;opacity:0;pointer-events:none;left:-9999px;top:-9999px";
    document.body.appendChild(frameCaptureHelper);
  }
  return frameCaptureHelper;
}

async function loadCaptureVideoFromUrl(url) {
  const playable = await ensureBrowserPlayableVideoUrl(url);
  const video = ensureFrameCaptureHelper();
  if (frameCaptureHelperUrl !== playable) {
    video.pause();
    video.removeAttribute("src");
    video.src = playable;
    video.load();
    frameCaptureHelperUrl = playable;
    await waitForVideoMeta(video);
  } else if (video.readyState < 1) {
    await waitForVideoMeta(video);
  }
  video.pause();
  return video;
}

function canUsePreviewCapture(previewVideo, node) {
  const url = resolveMediaUrl(node?.videoUrl);
  if (!previewVideo || !url) return false;
  if (videoSrcKey(previewVideo) !== url) return false;
  return previewVideo.readyState >= 1 && videoSeekableEnd(previewVideo) > 0;
}

async function acquireCaptureVideo(node, previewVideo) {
  if (canUsePreviewCapture(previewVideo, node)) {
    previewVideo.pause();
    return previewVideo;
  }
  return loadCaptureVideoFromUrl(resolveMediaUrl(node.videoUrl));
}

async function seekVideoToLastFrame(video) {
  await waitForVideoMeta(video, 4000);
  const end = videoEndCaptureTime(video);
  if (!(end > 0)) throw new Error("无法读取视频时长");
  await seekVideoElement(video, end, { fast: true });
  if (videoNearTime(video, end)) return video.currentTime || 0;
  if (end > 2) {
    await seekVideoElement(video, end * 0.92, { fast: true });
    await seekVideoElement(video, end, { fast: true });
  }
  if (!videoNearTime(video, end)) {
    throw new Error("尾帧定位失败，请用「自定义截帧」手动选取");
  }
  return video.currentTime || 0;
}

function clampVideoScrubTime(video, time) {
  if (!video) return 0;
  const seekEnd = videoSeekableEnd(video);
  const dur =
    Number.isFinite(video.duration) && video.duration > 0 ? video.duration : seekEnd;
  if (!(dur > 0)) return 0;
  const maxT = seekEnd > 0 ? Math.max(0, seekEnd - 0.04) : Math.max(0, dur - 0.04);
  return Math.max(0, Math.min(time, maxT));
}

function scrubVideoTime(video, time, { pause = true } = {}) {
  if (!video) return 0;
  const t = clampVideoScrubTime(video, time);
  try {
    if (pause && !video.paused) video.pause();
    video.currentTime = t;
  } catch {
    /* ignore */
  }
  return t;
}

async function seekVideoElement(video, time, opts = {}) {
  const fast = !!opts.fast;
  if (!video) throw new Error("未找到视频");
  if (video.readyState < 1) {
    await waitForVideoMeta(video, fast ? 4000 : 8000);
  }
  const seekEnd = videoSeekableEnd(video);
  const wantEnd = time === VIDEO_SEEK_END || (seekEnd > 0 && Number.isFinite(time) && time >= seekEnd - 0.001);
  const target = wantEnd
    ? videoEndCaptureTime(video)
    : Math.max(0, Math.min(time, seekEnd > 0 ? Math.max(0, seekEnd - 0.04) : 0));
  if (Math.abs((video.currentTime || 0) - target) < 0.02 && video.readyState >= 2) {
    return target;
  }
  await new Promise((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      video.removeEventListener("seeked", onSeeked);
      resolve();
    };
    const onSeeked = () => finish();
    const timer = setTimeout(finish, fast ? 1200 : 3000);
    video.addEventListener("seeked", onSeeked);
    try {
      video.currentTime = target;
    } catch {
      finish();
    }
  });
  if (!fast && video.readyState < 2) {
    await new Promise((resolve) => {
      const timer = setTimeout(resolve, 1500);
      const finish = () => {
        clearTimeout(timer);
        video.removeEventListener("loadeddata", finish);
        video.removeEventListener("seeked", finish);
        resolve();
      };
      video.addEventListener("loadeddata", finish, { once: true });
      video.addEventListener("seeked", finish, { once: true });
    });
  }
  return target;
}

async function captureVideoElementFrame(video) {
  const w = video.videoWidth;
  const h = video.videoHeight;
  if (!w || !h) throw new Error("视频尚未就绪");
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("截帧失败");
  ctx.drawImage(video, 0, 0, w, h);
  const blob = await new Promise((resolve, reject) => {
    canvas.toBlob((b) => (b ? resolve(b) : reject(new Error("截帧失败"))), "image/png");
  });
  return { blob, width: w, height: h, dataUrl: canvas.toDataURL("image/jpeg", 0.72) };
}

async function createCapturedFrameNodeFromServer(sourceNode, result, label, index = 0, opts = {}) {
  const width = result.width || sourceNode.mediaWidth || 16;
  const height = result.height || sourceNode.mediaHeight || 9;
  const base = getAlignedDerivedPosition(sourceNode, width, height);
  const stackGap = 28;
  const x = base.x;
  const y = base.y + index * ((base.previewH || 120) + stackGap);
  if (!opts.skipHistory) CanvasHistory.push();
  const node = CanvasStore.addNode("ref-image", x, y);
  CanvasStore.updateNode(node.id, {
    status: "completed",
    imageUrl: result.url,
    mediaWidth: width,
    mediaHeight: height,
    ratio: sourceNode.ratio || (width >= height ? "16:9" : "9:16"),
    customName: label || "截帧",
  });
  CanvasStore.addConnection(sourceNode.id, node.id);
  await CanvasStore.flushSave();
  renderNodes();
  scheduleRenderConnections(true);
  updateNodeCount();
  return node.id;
}

async function createCapturedFrameNode(sourceNode, blob, width, height, label, index = 0, opts = {}) {
  const file = new File([blob], `frame-${Date.now()}-${index}.png`, { type: "image/png" });
  const base = getAlignedDerivedPosition(sourceNode, width, height);
  const stackGap = 28;
  const x = base.x;
  const y = base.y + index * ((base.previewH || 120) + stackGap);
  if (!opts.skipHistory) CanvasHistory.push();
  const node = CanvasStore.addNode("ref-image", x, y);
  CanvasStore.updateNode(node.id, {
    status: "uploading",
    mediaWidth: width,
    mediaHeight: height,
    // Inherit source ratio so 尾帧/截帧 match video card size on canvas
    ratio: sourceNode.ratio || (width >= height ? "16:9" : "9:16"),
    customName: label || "截帧",
  });
  CanvasStore.addConnection(sourceNode.id, node.id);
  renderNodes();
  scheduleRenderConnections(true);
  try {
    const uploaded = await uploadMediaFile(file, width, height);
    CanvasStore.updateNode(node.id, {
      status: "completed",
      imageUrl: uploaded.url,
      mediaWidth: uploaded.width || width,
      mediaHeight: uploaded.height || height,
      ...mediaThumbPatchFromUpload(uploaded, "image"),
    });
    await CanvasStore.flushSave();
  } catch (err) {
    CanvasStore.updateNode(node.id, { status: "failed", error: err.message || "上传失败" });
    await CanvasStore.flushSave();
  }
  renderNodes();
  scheduleRenderConnections(true);
  updateNodeCount();
  return node.id;
}

const FrameCapture = {
  customNodeId: null,
  busy: false,
  staged: [],
  frameStep: 1 / 24,
  _raf: 0,
  _scrubbing: false,
  _bound: false,
  _filmGen: 0,

  isOpen() {
    return !document.getElementById("frame-capture-studio")?.classList.contains("hidden");
  },

  closeMenus(exceptNodeId) {
    document.querySelectorAll(".media-tool-menu.is-pinned").forEach((el) => {
      if (exceptNodeId && el.dataset.node === exceptNodeId) return;
      el.classList.remove("is-pinned");
    });
    syncMediaMenuOpenState();
  },

  openMenu(_nodeId, _menuKey) {
    // no-op: menus open on hover
  },

  exitCustom() {
    this.closeStudio();
  },

  enterCustom(nodeId) {
    this.openStudio(nodeId);
  },

  restoreAfterRender() {
    // studio is overlay — nothing to restore on node
  },

  getVideoEl(nodeId) {
    if (this.isOpen() && this.customNodeId === nodeId) {
      return document.getElementById("fc-video");
    }
    return nodePreviewVideoEl(nodeId);
  },

  openStudio(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasCapturableVideo(node)) {
      showCanvasToast("当前节点没有可截取的视频");
      return;
    }
    const box = document.getElementById("frame-capture-studio");
    const video = document.getElementById("fc-video");
    if (!box || !video) return;

    this.closeMenus();
    this.customNodeId = nodeId;
    this.staged = [];
    this._filmGen += 1;
    this.renderStaged();
    this.updateConfirmLabel();

    const nodeVideo = nodePreviewVideoEl(nodeId);
    try {
      nodeVideo?.pause();
    } catch {
      /* ignore */
    }

    video.pause();
    video.removeAttribute("src");
    video.src = resolveMediaUrl(node.videoUrl);
    video.load();

    revealOverlay(box);
    box.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";

    const onMeta = () => {
      this.syncMeta();
      this.syncTimeUi();
      this.buildFilmstrip();
    };
    video.addEventListener("loadedmetadata", onMeta, { once: true });
    if (video.readyState >= 1) onMeta();

    this.bindStudioEvents();
    this.startTick();
    this.syncPlayUi();
  },

  closeStudio() {
    this.stopTick();
    const box = document.getElementById("frame-capture-studio");
    const video = document.getElementById("fc-video");
    if (video) {
      try {
        video.pause();
      } catch {
        /* ignore */
      }
      video.removeAttribute("src");
      video.load();
    }
    dismissOverlay(box);
    box?.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
    this.customNodeId = null;
    this.staged = [];
    this._scrubbing = false;
    this._filmGen += 1;
    const track = document.getElementById("fc-filmstrip-track");
    if (track) track.innerHTML = "";
  },

  bindStudioEvents() {
    if (this._bound) return;
    this._bound = true;
    const video = document.getElementById("fc-video");
    const strip = document.getElementById("fc-filmstrip");

    document.getElementById("fc-studio-close")?.addEventListener("click", () => this.closeStudio());
    document.getElementById("fc-cancel-btn")?.addEventListener("click", () => this.closeStudio());
    document.getElementById("fc-confirm-btn")?.addEventListener("click", () => this.confirm());
    document.getElementById("fc-stage-btn")?.addEventListener("click", () => this.stageCurrent());
    document.getElementById("fc-jump-btn")?.addEventListener("click", () => this.jumpFromInput());
    document.getElementById("fc-jump-input")?.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        this.jumpFromInput();
      }
    });
    document.getElementById("fc-play-overlay")?.addEventListener("click", () => this.togglePlay());
    document.getElementById("fc-video-wrap")?.addEventListener("click", (e) => {
      if (e.target.closest(".fc-play-overlay")) return;
      this.togglePlay();
    });

    document.querySelector(".fc-transport")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-fc]");
      if (!btn) return;
      const act = btn.dataset.fc;
      if (act === "toggle") this.togglePlay();
      else if (act === "home") this.seekTo(0);
      else if (act === "end") this.seekTo(VIDEO_SEEK_END);
      else if (act === "prev-frame") this.nudge(-this.frameStep);
      else if (act === "next-frame") this.nudge(this.frameStep);
      else if (act === "back-1") this.nudge(-1);
      else if (act === "fwd-1") this.nudge(1);
    });

    document.getElementById("fc-staged-list")?.addEventListener("click", (e) => {
      const rm = e.target.closest("[data-fc-remove]");
      if (!rm) return;
      const idx = Number(rm.dataset.fcRemove);
      if (!Number.isFinite(idx)) return;
      this.staged.splice(idx, 1);
      this.renderStaged();
      this.updateConfirmLabel();
    });

    video?.addEventListener("play", () => this.syncPlayUi());
    video?.addEventListener("pause", () => this.syncPlayUi());
    video?.addEventListener("seeked", () => this.syncTimeUi());
    video?.addEventListener("timeupdate", () => {
      if (!this._scrubbing) this.syncTimeUi();
    });

    let stripScrubbing = false;
    const scrubFromEvent = (e) => {
      if (!strip) return;
      const rect = strip.getBoundingClientRect();
      if (!rect.width) return;
      const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
      const v = this.video();
      if (!v) return;
      scrubVideoTime(v, ratio * this.duration());
      this.syncTimeUi();
    };
    const endStripScrub = (e) => {
      if (!stripScrubbing) return;
      stripScrubbing = false;
      this._scrubbing = false;
      if (strip && e?.pointerId != null) {
        try {
          strip.releasePointerCapture?.(e.pointerId);
        } catch {
          /* ignore */
        }
      }
      window.removeEventListener("pointermove", scrubFromEvent);
      window.removeEventListener("pointerup", endStripScrub);
      window.removeEventListener("pointercancel", endStripScrub);
    };
    strip?.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      e.stopPropagation();
      stripScrubbing = true;
      this._scrubbing = true;
      try {
        video?.pause();
      } catch {
        /* ignore */
      }
      strip.setPointerCapture?.(e.pointerId);
      scrubFromEvent(e);
      window.addEventListener("pointermove", scrubFromEvent);
      window.addEventListener("pointerup", endStripScrub);
      window.addEventListener("pointercancel", endStripScrub);
    });

    window.addEventListener("keydown", (e) => this.onKeyDown(e), true);
  },

  onKeyDown(e) {
    if (!this.isOpen()) return;
    if (isTextInputTarget(e.target) && e.target.id === "fc-jump-input") {
      if (e.key === "Escape") {
        e.preventDefault();
        e.target.blur();
      }
      return;
    }
    const key = e.key;
    if (key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      this.closeStudio();
      return;
    }
    if (key === " " || key === "Spacebar") {
      e.preventDefault();
      this.togglePlay();
      return;
    }
    if (key === "ArrowLeft") {
      e.preventDefault();
      this.nudge(e.shiftKey ? -1 : -this.frameStep);
      return;
    }
    if (key === "ArrowRight") {
      e.preventDefault();
      this.nudge(e.shiftKey ? 1 : this.frameStep);
      return;
    }
    if (key === "Home") {
      e.preventDefault();
      this.seekTo(0);
      return;
    }
    if (key === "End") {
      e.preventDefault();
      this.seekTo(VIDEO_SEEK_END);
      return;
    }
    if (key === "s" || key === "S") {
      e.preventDefault();
      this.stageCurrent();
      return;
    }
    if (key === "Enter") {
      e.preventDefault();
      this.confirm();
    }
  },

  video() {
    return document.getElementById("fc-video");
  },

  duration() {
    const v = this.video();
    return v && Number.isFinite(v.duration) ? v.duration : 0;
  },

  startTick() {
    this.stopTick();
    const tick = () => {
      if (!this.isOpen()) return;
      if (!this._scrubbing) this.syncTimeUi();
      this._raf = requestAnimationFrame(tick);
    };
    this._raf = requestAnimationFrame(tick);
  },

  stopTick() {
    if (this._raf) cancelAnimationFrame(this._raf);
    this._raf = 0;
  },

  syncMeta() {
    const v = this.video();
    const w = v?.videoWidth || 0;
    const h = v?.videoHeight || 0;
    const res = w && h ? `${w} × ${h}` : "—";
    const dur = formatFcTime(this.duration());
    const resEl = document.getElementById("fc-studio-res");
    const metaRes = document.getElementById("fc-meta-res");
    const metaDur = document.getElementById("fc-meta-duration");
    if (resEl) resEl.textContent = res;
    if (metaRes) metaRes.textContent = res;
    if (metaDur) metaDur.textContent = dur;
  },

  syncTimeUi() {
    const v = this.video();
    const t = v?.currentTime || 0;
    const d = this.duration();
    const cur = formatFcTime(t);
    const stamp = document.getElementById("fc-video-time");
    const readout = document.getElementById("fc-time-readout");
    const jump = document.getElementById("fc-jump-input");
    if (stamp) stamp.textContent = cur;
    if (readout) readout.textContent = `${cur} / ${formatFcTime(d)}`;
    if (jump && document.activeElement !== jump) jump.value = cur;
    const head = document.getElementById("fc-filmstrip-playhead");
    if (head) {
      const pct = d > 0 ? (t / d) * 100 : 0;
      head.style.left = `${Math.max(0, Math.min(100, pct))}%`;
    }
  },

  syncPlayUi() {
    const v = this.video();
    const playing = Boolean(v && !v.paused && !v.ended);
    document.getElementById("fc-play-overlay")?.classList.toggle("hidden", playing);
    const playIcon = document.querySelector("#fc-btn-play .fc-icon-play");
    const pauseIcon = document.querySelector("#fc-btn-play .fc-icon-pause");
    playIcon?.classList.toggle("hidden", playing);
    pauseIcon?.classList.toggle("hidden", !playing);
  },

  async seekTo(time) {
    const v = this.video();
    if (!v) return;
    try {
      v.pause();
    } catch {
      /* ignore */
    }
    try {
      await seekVideoElement(v, time);
    } catch {
      /* ignore */
    }
    this.syncTimeUi();
    this.syncPlayUi();
  },

  async nudge(delta) {
    const v = this.video();
    if (!v) return;
    await this.seekTo((v.currentTime || 0) + delta);
  },

  togglePlay() {
    const v = this.video();
    if (!v) return;
    if (v.paused || v.ended) {
      v.play().catch(() => {});
    } else {
      v.pause();
    }
    this.syncPlayUi();
  },

  jumpFromInput() {
    const raw = document.getElementById("fc-jump-input")?.value;
    const t = parseFcTime(raw);
    if (t == null) {
      showCanvasToast("时间格式无效");
      return;
    }
    this.seekTo(t);
  },

  async buildFilmstrip() {
    const track = document.getElementById("fc-filmstrip-track");
    if (!track) return;
    const gen = ++this._filmGen;
    const src = this.video()?.currentSrc || this.video()?.src;
    const dur = this.duration();
    track.innerHTML = `<div class="fc-filmstrip-loading">正在生成时间轴…</div>`;
    if (!src || !(dur > 0)) return;

    const count = Math.min(28, Math.max(12, Math.round(dur * 1.2)));
    const helper = document.createElement("video");
    helper.muted = true;
    helper.playsInline = true;
    helper.preload = "auto";
    helper.src = src;
    try {
      await new Promise((resolve, reject) => {
        const ok = () => {
          cleanup();
          resolve();
        };
        const bad = () => {
          cleanup();
          reject(new Error("filmstrip"));
        };
        const cleanup = () => {
          helper.removeEventListener("loadedmetadata", ok);
          helper.removeEventListener("error", bad);
        };
        helper.addEventListener("loadedmetadata", ok);
        helper.addEventListener("error", bad);
      });
      const thumbs = [];
      for (let i = 0; i < count; i++) {
        if (gen !== this._filmGen) return;
        const t = (dur * i) / Math.max(1, count - 1);
        await seekVideoElement(helper, Math.min(t, Math.max(0, dur - 0.04)));
        const canvas = document.createElement("canvas");
        const w = helper.videoWidth || 160;
        const h = helper.videoHeight || 90;
        const scale = 120 / Math.max(w, 1);
        canvas.width = Math.max(1, Math.round(w * scale));
        canvas.height = Math.max(1, Math.round(h * scale));
        const ctx = canvas.getContext("2d");
        if (ctx) ctx.drawImage(helper, 0, 0, canvas.width, canvas.height);
        thumbs.push(canvas.toDataURL("image/jpeg", 0.55));
      }
      if (gen !== this._filmGen) return;
      track.innerHTML = thumbs
        .map((url) => `<img class="fc-filmstrip-thumb" src="${url}" alt="" draggable="false" />`)
        .join("");
    } catch {
      if (gen === this._filmGen) {
        track.innerHTML = `<div class="fc-filmstrip-loading">时间轴不可用，仍可用进度条定位</div>`;
      }
    } finally {
      helper.removeAttribute("src");
      helper.load();
    }
  },

  async stageCurrent() {
    if (this.busy || !this.isOpen()) return;
    const v = this.video();
    if (!v) return;
    try {
      v.pause();
    } catch {
      /* ignore */
    }
    try {
      await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
      const frame = await captureVideoElementFrame(v);
      this.staged.push({
        blob: frame.blob,
        width: frame.width,
        height: frame.height,
        time: v.currentTime || 0,
        thumb: frame.dataUrl,
      });
      this.renderStaged();
      this.updateConfirmLabel();
      showCanvasToast(`已暂存 ${this.staged.length} 帧`);
    } catch (err) {
      showCanvasToast(err.message || "暂存失败");
    }
  },

  renderStaged() {
    const list = document.getElementById("fc-staged-list");
    const count = document.getElementById("fc-staged-count");
    if (count) count.textContent = String(this.staged.length);
    if (!list) return;
    if (!this.staged.length) {
      list.innerHTML =
        `<p class="fc-staged-empty" id="fc-staged-empty">按 S 或点「暂存此帧」收集多帧，最后一次性添加到画布。</p>`;
      return;
    }
    list.innerHTML = this.staged
      .map(
        (item, i) => `<div class="fc-staged-item">
        <img class="fc-staged-thumb" src="${item.thumb}" alt="" />
        <div class="fc-staged-meta">${formatFcTime(item.time)}</div>
        <button type="button" class="fc-staged-remove" data-fc-remove="${i}" title="移除"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button>
      </div>`
      )
      .join("");
  },

  updateConfirmLabel() {
    const btn = document.getElementById("fc-confirm-btn");
    if (!btn) return;
    btn.textContent = this.staged.length > 0 ? `添加 ${this.staged.length} 帧到画布` : "提取当前帧";
  },

  async confirm() {
    if (this.busy || !this.isOpen()) return;
    if (this.staged.length > 0) {
      await this.commitStaged();
    } else {
      await this.commitCurrent();
    }
  },

  async commitCurrent() {
    const nodeId = this.customNodeId;
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    const v = this.video();
    if (!node || !v) return;
    this.busy = true;
    const btn = document.getElementById("fc-confirm-btn");
    if (btn) btn.disabled = true;
    showLoadingToast("正在截取当前帧…");
    try {
      try {
        v.pause();
      } catch {
        /* ignore */
      }
      await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
      const { blob, width, height } = await captureVideoElementFrame(v);
      const outId = await createCapturedFrameNode(node, blob, width, height, "截帧", 0);
      hideLoadingToast();
      this.closeStudio();
      showCanvasToast("截帧完成");
      if (outId) selectSingle(outId);
    } catch (err) {
      hideLoadingToast();
      showCanvasToast(err.message || "截帧失败");
    } finally {
      this.busy = false;
      if (btn) btn.disabled = false;
    }
  },

  async commitStaged() {
    const nodeId = this.customNodeId;
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!node || !this.staged.length) return;
    const frames = this.staged.slice();
    this.busy = true;
    const btn = document.getElementById("fc-confirm-btn");
    if (btn) btn.disabled = true;
    showLoadingToast(`正在添加 ${frames.length} 帧…`);
    let lastId = null;
    try {
      CanvasHistory.push();
      for (let i = 0; i < frames.length; i++) {
        const f = frames[i];
        lastId = await createCapturedFrameNode(
          node,
          f.blob,
          f.width,
          f.height,
          `截帧 ${formatFcTime(f.time)}`,
          i,
          { skipHistory: true }
        );
      }
      hideLoadingToast();
      this.closeStudio();
      showCanvasToast(`已添加 ${frames.length} 帧`);
      if (lastId) selectSingle(lastId);
    } catch (err) {
      hideLoadingToast();
      showCanvasToast(err.message || "添加失败");
    } finally {
      this.busy = false;
      if (btn) btn.disabled = false;
    }
  },

  async run(nodeId, mode) {
    if (this.busy) return;
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasCapturableVideo(node)) {
      showCanvasToast("当前节点没有可截取的视频");
      return;
    }
    if (!node.videoUrl) {
      showCanvasToast("当前节点没有可截取的视频地址");
      return;
    }

    const labels = {
      first: "正在截取首帧…",
      last: "正在截取尾帧…",
      current: "正在截取当前帧…",
    };
    const nameLabels = { first: "首帧", last: "尾帧", current: "截帧" };
    this.busy = true;
    this.closeMenus();
    showLoadingToast(labels[mode] || "正在截帧…");

    try {
      let start = 0;
      if (mode === "last") start = -1;
      else if (mode === "current") {
        start = getVideoCaptureCurrentTime(nodeId);
      }
      const result = await MediaTools.callApi("extract_frame", node.videoUrl, { start });
      const outId = await createCapturedFrameNodeFromServer(node, result, nameLabels[mode] || "截帧");
      hideLoadingToast();
      showCanvasToast("截帧完成");
      if (outId) selectSingle(outId);
    } catch (err) {
      hideLoadingToast();
      showCanvasToast(err.message || "截帧失败");
    } finally {
      this.busy = false;
    }
  },
};
window.FrameCapture = FrameCapture;

function syncMediaMenuOpenState() {
  document.querySelectorAll(".node-wrap").forEach((wrap) => {
    const open = Boolean(wrap.querySelector(".media-tool-item:hover, .media-tool-menu.is-pinned"));
    wrap.classList.toggle("is-media-menu-open", open);
  });
}

const MEDIA_TOOL_LABELS = {
  extract_audio: "提取音频",
  extract_video: "提取视频",
  trim: "长度裁剪",
  trim_audio: "音频裁剪",
  convert_audio: "格式转换",
  crop: "宽高裁剪",
  compress: "视频压缩",
  upscale: "视频超分",
  reverse: "倒序",
  to_gif: "转动图",
  image_crop: "图片裁剪",
  image_paint: "画笔标注",
  image_compress: "图片压缩",
  image_mirror: "镜像",
  image_rotate: "旋转",
  image_ai_mark: "AI标记",
};

async function createDerivedMediaNode(sourceNode, result, label, opts = {}) {
  const kind = result.kind || "video";
  const type = kind === "audio" ? "ref-audio" : kind === "image" ? "ref-image" : "ref-video";
  const mw = result.width || sourceNode.mediaWidth || 16;
  const mh = result.height || sourceNode.mediaHeight || 9;
  let x;
  let y;
  if (opts.position) {
    x = opts.position.x;
    y = opts.position.y;
  } else if (type === "ref-audio") {
    x = sourceNode.x + getNodeWidth(sourceNode) + 72;
    y = sourceNode.y;
  } else {
    ({ x, y } = getAlignedDerivedPosition(sourceNode, mw, mh));
  }
  if (!opts.skipHistory) CanvasHistory.push();
  const node = CanvasStore.addNode(type, x, y);
  const pending = Boolean(opts.pending);
  const patch = {
    status: opts.initialStatus || (pending ? "generating" : "completed"),
    customName: label || MEDIA_TOOL_LABELS[result.op] || "工具输出",
    mediaWidth: result.width || sourceNode.mediaWidth || null,
    mediaHeight: result.height || sourceNode.mediaHeight || null,
    mediaOp: result.op || null,
    genStartedAt: pending && patchStatusIsActive(opts.initialStatus || "generating") ? Date.now() : null,
    imageUrl: null,
    videoUrl: null,
    audioUrl: null,
  };
  if (!pending) {
    if (type === "ref-image") patch.imageUrl = result.url;
    else if (type === "ref-video") patch.videoUrl = result.url;
    else patch.audioUrl = result.url;
  }
  CanvasStore.updateNode(node.id, patch);
  CanvasStore.addConnection(sourceNode.id, node.id);
  if (!opts.deferSave) {
    await CanvasStore.flushSave();
    renderNodes();
    scheduleRenderConnections(true);
    updateNodeCount();
    if (pending && typeof window.ensureProgressTicker === "function") {
      window.ensureProgressTicker();
    }
  }
  return node.id;
}

function patchStatusIsActive(status) {
  return status === "generating" || status === "pending";
}

const MediaTools = {
  busy: false,
  pendingNodeId: null,
  compressScale: "smart",
  compressFps: 0,
  upscaleQueue: [],
  upscaleRunning: 0,
  _upscalePollers: new Set(),

  async callApi(op, url, extra = {}) {
    let res;
    try {
      res = await fetch("/api/video/tools", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ op, url, board_id: CanvasStore.activeBoardId, ...extra }),
      });
    } catch (err) {
      const msg = String(err?.message || err || "");
      if (/failed to fetch|networkerror|load failed/i.test(msg)) {
        throw new Error(
          "无法连接画布服务（Failed to fetch）。请确认「启动画布服务器」与「启动任务服务」(8089) 都在运行，并刷新页面后重试"
        );
      }
      throw err;
    }
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      let detail = err.detail;
      if (Array.isArray(detail)) {
        detail = detail
          .map((d) => (typeof d === "string" ? d : d?.msg || d?.message || JSON.stringify(d)))
          .filter(Boolean)
          .join("；");
      }
      if (typeof detail !== "string" || !detail.trim()) {
        if (res.status === 404) {
          detail = "视频工具接口不可用，请重启后端后再试";
        } else if (res.status === 503) {
          detail = "任务服务（8089）未启动，请运行「启动任务服务.bat」后重试";
        } else {
          detail = `处理失败（HTTP ${res.status}）`;
        }
      }
      throw new Error(detail.trim());
    }
    return res.json();
  },

  async waitRemoteUpscaleJob(jobId, outId, { interval = 2000, timeout = 7200000 } = {}) {
    const started = Date.now();
    while (Date.now() - started < timeout) {
      const res = await fetch(`/api/upscale/jobs/${encodeURIComponent(jobId)}`);
      if (!res.ok) {
        const err = await res.json().catch(() => ({}));
        throw new Error(err.detail || `查询超分任务失败（HTTP ${res.status}）`);
      }
      const data = await res.json();
      if (data.status === "completed") return data;
      if (data.status === "failed") throw new Error(data.error || "远程超分失败");
      if (outId) {
        if (data.status === "pending") {
          CanvasStore.updateNode(outId, { status: "generating", error: "排队中（等待本地 GPU）" });
        } else if (data.status === "claimed" || data.status === "processing") {
          CanvasStore.updateNode(outId, { status: "generating", error: "远程超分中" });
        }
        renderNodes();
      }
      await new Promise((r) => setTimeout(r, interval));
    }
    throw new Error("远程超分超时");
  },

  async resolveUpscaleResult(result, outId) {
    if (result?.remote && result?.id) {
      CanvasStore.updateNode(outId, { upscaleJobId: result.id });
      if (result.status === "completed") return result;
      return this.waitRemoteUpscaleJob(result.id, outId);
    }
    return result;
  },

  _finishUpscaleNode(outId, result) {
    CanvasStore.updateNode(outId, {
      status: "completed",
      videoUrl: result.url,
      mediaWidth: result.width || null,
      mediaHeight: result.height || null,
      error: null,
      genStartedAt: null,
      upscaleJobId: null,
    });
  },

  resumeUpscalePoll(outId, jobId) {
    if (!outId || !jobId || this._upscalePollers.has(outId)) return;
    this._upscalePollers.add(outId);
    void this.waitRemoteUpscaleJob(jobId, outId)
      .then((result) => {
        this._finishUpscaleNode(outId, result);
        return CanvasStore.flushSave();
      })
      .then(() => {
        renderNodes();
        scheduleRenderConnections(true);
      })
      .catch((err) => {
        CanvasStore.updateNode(outId, {
          status: "failed",
          error: err.message || "远程超分失败",
          genStartedAt: null,
          upscaleJobId: null,
        });
        return CanvasStore.flushSave();
      })
      .then(() => renderNodes())
      .finally(() => this._upscalePollers.delete(outId));
  },

  async run(nodeId, op, extra = {}, opts = {}) {
    if (op === "upscale") {
      const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
      if (!nodeHasCapturableVideo(node)) {
        if (!opts.quiet) showCanvasToast("当前节点没有可处理的视频");
        return false;
      }
      await this.startBatchUpscale([nodeId], extra, { quiet: opts.quiet });
      return true;
    }
    if (this.busy || FrameCapture.busy) {
      if (!opts.quiet) showCanvasToast("有其他任务正在进行，请稍候");
      return false;
    }
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasCapturableVideo(node)) {
      showCanvasToast("当前节点没有可处理的视频");
      return false;
    }
    const url = node.videoUrl;
    if (!url) {
      showCanvasToast("当前节点没有可处理的视频地址");
      return false;
    }
    this.busy = true;
    FrameCapture.closeMenus();
    let outId = null;
    try {
      CanvasHistory.push();
      outId = await createDerivedMediaNode(
        node,
        { kind: op === "extract_audio" ? "audio" : op === "to_gif" ? "image" : "video", width: node.mediaWidth, height: node.mediaHeight, op },
        MEDIA_TOOL_LABELS[op],
        { pending: true, skipHistory: true }
      );
      const raw = await this.callApi(op, url, extra);
      const result = raw;
      result.op = op;
      const patch = {
        status: "completed",
        mediaWidth: result.width || node.mediaWidth || null,
        mediaHeight: result.height || node.mediaHeight || null,
      };
      if (result.kind === "audio") patch.audioUrl = result.url;
      else if (result.kind === "image") patch.imageUrl = result.url;
      else patch.videoUrl = result.url;
      CanvasStore.updateNode(outId, patch);
      await CanvasStore.flushSave();
      renderNodes();
      scheduleRenderConnections(true);
      if (!opts.quiet) {
        showCanvasToast(`${MEDIA_TOOL_LABELS[op] || "处理"}完成`);
        if (outId) selectSingle(outId);
      }
      return true;
    } catch (err) {
      if (outId) {
        CanvasStore.updateNode(outId, { status: "failed", error: err.message || "处理失败" });
        await CanvasStore.flushSave();
        renderNodes();
      }
      if (!opts.quiet) showCanvasToast(err.message || "处理失败");
      return false;
    } finally {
      this.busy = false;
    }
  },

  getUpscaleConcurrency() {
    const server =
      typeof getUserThreadLimit === "function"
        ? getUserThreadLimit()
        : Math.min(8, Math.max(1, Number(window.__serverMaxThreads) || 2));
    const workerCap = Number(window.__upscaleWorkerCapacity);
    if (Number.isFinite(workerCap) && workerCap > 0) {
      return Math.min(8, Math.max(1, Math.min(server, workerCap)));
    }
    return Math.min(8, Math.max(1, server));
  },

  async startBatchUpscale(sourceIds, payload, opts = {}) {
    const board = CanvasStore.activeBoard();
    const label = payload.mode === "basic" ? "常规高清" : MEDIA_TOOL_LABELS.upscale;
    const jobs = [];
    CanvasHistory.push();
    for (const sourceId of sourceIds) {
      const source = board.nodes.find((n) => n.id === sourceId);
      if (!nodeHasCapturableVideo(source)) continue;
      const outId = await createDerivedMediaNode(
        source,
        { kind: "video", width: source.mediaWidth, height: source.mediaHeight, op: "upscale" },
        label,
        { pending: true, initialStatus: "waiting", skipHistory: true, deferSave: true }
      );
      jobs.push({ sourceId, outId, payload });
    }
    if (!jobs.length) {
      showCanvasToast("没有可处理的视频");
      return;
    }
    await CanvasStore.flushSave();
    renderNodes();
    scheduleRenderConnections(true);
    updateNodeCount();
    if (typeof window.ensureProgressTicker === "function") window.ensureProgressTicker();
    this.upscaleQueue.push(...jobs);
    const queued = this.upscaleQueue.length;
    const running = this.upscaleRunning;
    const max = this.getUpscaleConcurrency();
    if (typeof loadUpscaleWorkerCapacity === "function") {
      await loadUpscaleWorkerCapacity().catch(() => {});
    }
    if (!opts.quiet) {
      const effectiveMax = this.getUpscaleConcurrency();
      const tail =
        queued > 1 || running > 0
          ? `（并行 ${Math.min(effectiveMax, queued + running)} 路，队列共 ${queued + running} 个）`
          : "";
      showCanvasToast(`已加入${label}${tail}`);
    }
    this.pumpUpscaleQueue();
  },

  pumpUpscaleQueue() {
    const max = this.getUpscaleConcurrency();
    while (this.upscaleQueue.length && this.upscaleRunning < max) {
      const job = this.upscaleQueue.shift();
      this.upscaleRunning += 1;
      void this._executeUpscaleJob(job).finally(() => {
        this.upscaleRunning -= 1;
        this.pumpUpscaleQueue();
      });
    }
  },

  async _executeUpscaleJob(job) {
    const { sourceId, outId, payload } = job;
    const board = CanvasStore.activeBoard();
    const source = board.nodes.find((n) => n.id === sourceId);
    const out = board.nodes.find((n) => n.id === outId);
    if (!source || !out || !nodeHasCapturableVideo(source)) {
      if (out) {
        CanvasStore.updateNode(outId, { status: "failed", error: "源视频不可用" });
        await CanvasStore.flushSave();
        renderNodes();
      }
      return;
    }
    CanvasStore.updateNode(outId, { status: "generating", genStartedAt: Date.now(), error: null });
    renderNodes();
    try {
      const raw = await this.callApi("upscale", source.videoUrl, payload);
      const result = await this.resolveUpscaleResult(raw, outId);
      this._finishUpscaleNode(outId, {
        ...result,
        width: result.width || source.mediaWidth || null,
        height: result.height || source.mediaHeight || null,
      });
    } catch (err) {
      CanvasStore.updateNode(outId, { status: "failed", error: err.message || "处理失败" });
    }
    await CanvasStore.flushSave();
    renderNodes();
    scheduleRenderConnections(true);
  },

  async runAudio(nodeId, op, extra = {}) {
    if (this.busy || FrameCapture.busy) return;
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasAudio(node)) {
      showCanvasToast("当前节点没有可处理的音频");
      return;
    }
    const url = node.audioUrl;
    this.busy = true;
    FrameCapture.closeMenus();
    const label =
      op === "convert_audio"
        ? `转 ${(extra.format || "mp3").toUpperCase()}`
        : MEDIA_TOOL_LABELS[op] || "处理";
    try {
      CanvasHistory.push();
      // 原地替换：语音生成节点 / 上传音频裁剪转码后直接覆盖，不另开新节点。
      CanvasStore.updateNode(nodeId, { status: "generating", error: null });
      renderNodes();
      const result = await this.callApi(op, url, extra);
      result.op = op;
      CanvasStore.updateNode(nodeId, {
        status: "completed",
        audioUrl: result.url,
        mediaWidth: null,
        mediaHeight: null,
        error: null,
      });
      await CanvasStore.flushSave();
      renderNodes();
      scheduleRenderConnections(true);
      showCanvasToast(`${label}完成（已替换原音频）`);
      selectSingle(nodeId);
    } catch (err) {
      CanvasStore.updateNode(nodeId, {
        status: "completed",
        error: null,
      });
      // Keep previous audioUrl on failure — node still playable.
      await CanvasStore.flushSave();
      renderNodes();
      showCanvasToast(err.message || "处理失败");
    } finally {
      this.busy = false;
    }
  },

  cycleAudioRate(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasAudio(node)) return;
    const rates = [1, 1.25, 1.5, 2, 0.75];
    const cur = Number(node.audioRate) > 0 ? Number(node.audioRate) : 1;
    const idx = rates.findIndex((r) => Math.abs(r - cur) < 0.001);
    const next = rates[(idx + 1) % rates.length];
    CanvasStore.updateNode(nodeId, { audioRate: next });
    const audio = document.querySelector(`audio[data-audio-el="${nodeId}"]`);
    if (audio) audio.playbackRate = next;
    const btn = document.querySelector(`.media-tool-rate[data-node="${nodeId}"]`);
    if (btn) btn.textContent = `${Number.isInteger(next) ? next : next}x`;
  },

  async download(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!node) return;
    // Overlay marks are not in pixels — bake a copy only for this download.
    if (nodeNeedsAiMarkOverlay(node) && node.imageUrl) {
      if (this.busy || FrameCapture.busy) {
        showCanvasToast("有其他任务正在进行，请稍候");
        return;
      }
      this.busy = true;
      try {
        showCanvasToast("正在导出带 AI 标记的图片…");
        const result = await this.callImageApi("image_ai_mark", node.imageUrl);
        const board = CanvasStore.activeBoard();
        const baseName = sanitizeDownloadFilename(getNodeDisplayName(node, board));
        const a = document.createElement("a");
        a.href = resolveMediaUrl(result.url);
        a.download = `${baseName}.${guessMediaExt(result.url, "png")}`;
        a.rel = "noopener";
        document.body.appendChild(a);
        a.click();
        a.remove();
        showCanvasToast("开始下载");
      } catch (err) {
        showCanvasToast(err.message || "导出标记图失败");
      } finally {
        this.busy = false;
      }
      return;
    }
    const info = getNodeDownloadInfo(node);
    if (!info) return;
    const a = document.createElement("a");
    a.href = info.url;
    a.download = info.filename;
    a.rel = "noopener";
    document.body.appendChild(a);
    a.click();
    a.remove();
    showCanvasToast("开始下载");
  },

  expand(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (nodeHasCapturableVideo(node)) {
      VideoLightbox.open(nodeId);
      return;
    }
    if (nodeHasImage(node)) {
      ImageLightbox.open(nodeId);
    }
  },

  openTrim(nodeId) {
    VideoTrimStudio.open(nodeId);
  },

  openAudioTrim(nodeId) {
    AudioTrimStudio.open(nodeId);
  },

  openCrop(nodeId) {
    VideoCropStudio.open(nodeId);
  },

  openCompress(nodeId) {
    VideoCompressModal.open(nodeId);
  },

  openUpscale(nodeId, mode = "ai") {
    if (!isUpscaleEnabled()) {
      showCanvasToast("超分功能已关闭");
      return;
    }
    VideoUpscaleModal.open(nodeId, mode);
  },

  openGif(nodeId) {
    VideoGifStudio.open(nodeId);
  },

  async callImageApi(op, url, extra = {}) {
    let res;
    try {
      res = await fetch("/api/image/tools", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ op, url, board_id: CanvasStore.activeBoardId, ...extra }),
      });
    } catch (err) {
      const msg = String(err?.message || err || "");
      if (/failed to fetch|networkerror|load failed/i.test(msg)) {
        throw new Error(
          "无法连接画布服务（Failed to fetch）。请确认「启动画布服务器」与「启动任务服务」(8089) 都在运行"
        );
      }
      throw err;
    }
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      let detail = err.detail;
      if (Array.isArray(detail)) {
        detail = detail
          .map((d) => (typeof d === "string" ? d : d?.msg || d?.message || JSON.stringify(d)))
          .filter(Boolean)
          .join("；");
      }
      if (typeof detail !== "string" || !detail.trim()) {
        if (res.status === 404) detail = "图片工具接口不可用，请重启后端后再试";
        else if (res.status === 503) detail = "任务服务（8089）未启动，请运行「启动任务服务.bat」";
        else detail = `处理失败（HTTP ${res.status}）`;
      }
      throw new Error(detail.trim());
    }
    return res.json();
  },

  /** Bake AI watermark into pixels and replace node.imageUrl (API / 预览 / 上传都用标记后的图). */
  async toggleAiMark(nodeId) {
    if (this.busy || FrameCapture.busy) return;
    const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
    if (!nodeHasImage(node)) {
      showCanvasToast("当前节点没有可处理的图片");
      return;
    }
    FrameCapture.closeMenus();
    this.busy = true;
    try {
      if (nodeHasAiMark(node)) {
        const patch = {
          aiMarked: false,
          aiMarkBaseUrl: null,
          thumbUrl: null,
        };
        const base = String(node.aiMarkBaseUrl || "").trim();
        const cur = String(node.imageUrl || "").trim();
        if (base && cur && base !== cur) patch.imageUrl = base;
        CanvasStore.updateNode(nodeId, patch);
        CanvasHistory.push();
        await CanvasStore.flushSave();
        if (typeof softRefreshNodeMedia === "function") softRefreshNodeMedia(nodeId);
        else {
          renderNodes();
          scheduleRenderConnections(true);
        }
        showCanvasToast("已取消 AI 标记");
        return;
      }
      const baseUrl = node.imageUrl;
      if (!baseUrl) {
        showCanvasToast("当前节点没有可处理的图片地址");
        return;
      }
      showCanvasToast("正在添加 AI 标记…");
      const result = await this.callImageApi("image_ai_mark", baseUrl);
      CanvasStore.updateNode(nodeId, {
        imageUrl: result.url,
        thumbUrl: null,
        mediaWidth: result.width || node.mediaWidth || null,
        mediaHeight: result.height || node.mediaHeight || null,
        aiMarked: true,
        aiMarkBaseUrl: baseUrl,
      });
      CanvasHistory.push();
      const saved = await CanvasStore.flushSave();
      if (typeof softRefreshNodeMedia === "function") softRefreshNodeMedia(nodeId);
      else {
        renderNodes();
        scheduleRenderConnections(true);
      }
      if (saved === false) showCanvasToast("已添加 AI 标记（正在同步到服务器…）");
      else showCanvasToast("已添加 AI 标记");
    } catch (err) {
      showCanvasToast(err.message || "标记失败");
    } finally {
      this.busy = false;
    }
  },

  async pollImageTaskUntilDone(taskId, { timeoutMs = 600000, intervalMs = 2000 } = {}) {
    const started = Date.now();
    while (Date.now() - started < timeoutMs) {
      if (typeof api !== "function") throw new Error("接口未就绪");
      const task = await api(`/api/tasks/${encodeURIComponent(taskId)}`);
      const st = String(task?.status || "");
      if (st === "completed") {
        if (!task.image_url) throw new Error("生成完成但没有图片");
        return task;
      }
      if (st === "failed" || st === "cancelled") {
        throw new Error(task.error || "AI过检失败");
      }
      await new Promise((r) => setTimeout(r, intervalMs));
    }
    throw new Error("AI过检超时，请稍后重试");
  },

  /** Face-tune via Doubao; replace current image in place. Admin/internal only. */
  async runAiPass(nodeId) {
    if (!canUseBrowserAiTools()) {
      showCanvasToast("普通用户请到官方 App 里手动换个脸即可；内部/管理员账号可在此直接过检");
      return;
    }
    const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
    if (!nodeHasImage(node) || !node.imageUrl) {
      showCanvasToast("当前节点没有可处理的图片");
      return;
    }
    if (node.status === "generating" || node.status === "pending" || node.mediaOp === "ai-pass") {
      return;
    }
    FrameCapture.closeMenus();
    const prevUrl = node.imageUrl;
    const snapshot = {
      imageUrl: node.imageUrl || null,
      thumbUrl: node.thumbUrl || null,
      aiMarked: !!node.aiMarked,
      aiMarkBaseUrl: node.aiMarkBaseUrl || null,
      aiPassCount: nodeAiPassCount(node),
      mediaWidth: node.mediaWidth || null,
      mediaHeight: node.mediaHeight || null,
    };
    const genOpts = resolveAiPassGenerateOptions(node.ratio);
    CanvasStore.updateNode(nodeId, {
      status: "generating",
      genStartedAt: Date.now(),
      error: null,
      isError: false,
      imageUrl: null,
      thumbUrl: null,
      mediaOp: "ai-pass",
      _aiPassSnapshot: snapshot,
      taskId: null,
    });
    renderNodes();
    scheduleRenderConnections(true);
    if (typeof window.ensureProgressTicker === "function") window.ensureProgressTicker();
    try {
      if (typeof api !== "function") throw new Error("接口未就绪");
      const board = CanvasStore.activeBoard();
      const task = await api("/api/image/generate", {
        method: "POST",
        body: JSON.stringify({
          ...genOpts,
          board_id: board?.id || null,
          node_id: null,
          reference_images: [prevUrl],
        }),
      });
      const live = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
      if (!live || live.mediaOp !== "ai-pass") return;
      CanvasStore.updateNode(nodeId, { taskId: task.id }, false);
      const done = await this.pollImageTaskUntilDone(task.id);
      const still = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
      if (!still || still.mediaOp !== "ai-pass") return;
      const newUrl = done.image_url;
      const passCount = snapshot.aiPassCount + 1;
      const entry = {
        id: `aipass-${Date.now().toString(36)}`,
        taskId: done.id,
        prompt: genOpts.prompt,
        model: genOpts.model,
        ratio: genOpts.ratio,
        imageUrl: newUrl,
        thumbUrl: done.thumb_url || null,
        mediaWidth: done.width || snapshot.mediaWidth || null,
        mediaHeight: done.height || snapshot.mediaHeight || null,
        kind: "image",
        typeLabel: "AI过检",
        status: "success",
        createdAt: Date.now(),
        references: [{ kind: "image", url: prevUrl }],
      };
      const genHistory = pushGenHistory(still, entry);
      const kept =
        genHistory.find((h) => h.taskId === entry.taskId) ||
        genHistory.find((h) => h.imageUrl === newUrl) ||
        entry;
      CanvasStore.updateNode(nodeId, {
        imageUrl: newUrl,
        thumbUrl: null,
        mediaWidth: done.width || snapshot.mediaWidth || null,
        mediaHeight: done.height || snapshot.mediaHeight || null,
        aiPassCount: passCount,
        aiMarked: false,
        aiMarkBaseUrl: null,
        genHistory,
        activeHistoryId: kept.id,
        status: "completed",
        error: null,
        genStartedAt: null,
        taskId: null,
        mediaOp: null,
        _aiPassSnapshot: null,
      });
      CanvasHistory.push();
      await CanvasStore.flushSave();
      renderNodes();
      scheduleRenderConnections(true);
    } catch (err) {
      const still = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
      if (!still || still.mediaOp !== "ai-pass") return;
      const errMsg = String(err?.message || "AI过检失败").trim() || "AI过检失败";
      const taskId = still.taskId || null;
      const failEntry = {
        id: `aipass-fail-${Date.now().toString(36)}`,
        taskId,
        prompt: genOpts.prompt,
        model: genOpts.model,
        ratio: genOpts.ratio,
        imageUrl: null,
        thumbUrl: null,
        kind: "image",
        typeLabel: "AI过检",
        status: "failed",
        error: errMsg,
        createdAt: Date.now(),
        references: snapshot.imageUrl ? [{ kind: "image", url: snapshot.imageUrl }] : [],
      };
      const genHistory = pushGenHistory(still, failEntry);
      // 恢复原图并保持可操作：不要整块变成「处理失败」死节点。
      CanvasStore.updateNode(nodeId, {
        imageUrl: snapshot.imageUrl,
        thumbUrl: snapshot.thumbUrl,
        aiMarked: snapshot.aiMarked,
        aiMarkBaseUrl: snapshot.aiMarkBaseUrl,
        aiPassCount: snapshot.aiPassCount,
        mediaWidth: snapshot.mediaWidth,
        mediaHeight: snapshot.mediaHeight,
        status: "failed",
        error: errMsg,
        isError: true,
        genHistory,
        genStartedAt: null,
        taskId,
        mediaOp: null,
        _aiPassSnapshot: null,
      });
      if (typeof showCanvasToast === "function") showCanvasToast(errMsg);
      await CanvasStore.flushSave();
      renderNodes();
      scheduleRenderConnections(true);
    }
  },

  async runImage(nodeId, op, extra = {}) {
    if (this.busy || FrameCapture.busy) return;
    if (op === "image_ai_mark") {
      await this.toggleAiMark(nodeId);
      return;
    }
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasImage(node)) {
      showCanvasToast("当前节点没有可处理的图片");
      return;
    }
    const url = node.imageUrl;
    if (!url) {
      showCanvasToast("当前节点没有可处理的图片地址");
      return;
    }
    let label = MEDIA_TOOL_LABELS[op] || "图片处理";
    if (op === "image_crop" && extra.ratio) label = `裁剪 ${extra.ratio}`;
    if (op === "image_mirror") label = extra.direction === "v" ? "垂直镜像" : "水平镜像";
    if (op === "image_rotate") label = `旋转 ${Math.abs(extra.degrees || 90)}°`;

    this.busy = true;
    FrameCapture.closeMenus();
    let outId = null;
    try {
      CanvasHistory.push();
      outId = await createDerivedMediaNode(
        node,
        { kind: "image", width: node.mediaWidth, height: node.mediaHeight, op },
        label,
        { pending: true, skipHistory: true }
      );
      const result = await this.callImageApi(op, url, extra);
      result.op = op;
      CanvasStore.updateNode(outId, {
        status: "completed",
        imageUrl: result.url,
        mediaWidth: result.width || node.mediaWidth || null,
        mediaHeight: result.height || node.mediaHeight || null,
        customName: result.label || label,
        ratio: extra.ratio && extra.ratio !== "origin" ? extra.ratio : node.ratio || null,
      });
      await CanvasStore.flushSave();
      renderNodes();
      scheduleRenderConnections(true);
      showCanvasToast(`${result.label || label}完成`);
      if (outId) selectSingle(outId);
    } catch (err) {
      if (outId) {
        CanvasStore.updateNode(outId, { status: "failed", error: err.message || "处理失败" });
        await CanvasStore.flushSave();
        renderNodes();
      }
      showCanvasToast(err.message || "处理失败");
    } finally {
      this.busy = false;
    }
  },
};
window.MediaTools = MediaTools;

/** Mic recording for 音频生成 → 录音 mode (writes audioUrl on the same voice node). */
const AudioRecordSession = {
  /** @type {Map<string, { recorder: MediaRecorder, stream: MediaStream, chunks: Blob[], timer: any, startedAt: number }>} */
  _byNode: new Map(),

  isRecording(nodeId) {
    return this._byNode.has(String(nodeId || ""));
  },

  async toggle(nodeId) {
    const id = String(nodeId || "");
    if (!id) return;
    if (this._byNode.has(id)) {
      await this.stop(id);
      return;
    }
    await this.start(id);
  },

  async start(nodeId) {
    const id = String(nodeId || "");
    const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === id);
    if (!node || node.type !== "voice") return;
    // Mic APIs need a secure context: https://… or http://localhost / 127.0.0.1
    if (!window.isSecureContext || !navigator.mediaDevices?.getUserMedia) {
      const host = location.hostname || "";
      const viaLanHttp =
        location.protocol === "http:" && host && host !== "localhost" && host !== "127.0.0.1";
      showCanvasToast?.(
        viaLanHttp
          ? "录音需要安全环境：请用 http://127.0.0.1 或 https 打开（局域网 IP 的 http 不可用）"
          : "当前环境不支持录音（需 Chrome/Edge，并用 https 或本机 localhost 打开）"
      );
      return;
    }
    let stream;
    try {
      stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    } catch (err) {
      const name = String(err?.name || "");
      const tip =
        name === "NotAllowedError" || name === "PermissionDeniedError"
          ? "麦克风权限被拒绝，请在浏览器地址栏允许麦克风后重试"
          : name === "NotFoundError" || name === "DevicesNotFoundError"
            ? "未检测到麦克风设备"
            : name === "NotReadableError" || name === "TrackStartError"
              ? "麦克风被其他程序占用"
              : err?.message || "无法使用麦克风";
      showCanvasToast?.(tip);
      return;
    }
    const mime =
      MediaRecorder.isTypeSupported?.("audio/webm;codecs=opus")
        ? "audio/webm;codecs=opus"
        : MediaRecorder.isTypeSupported?.("audio/webm")
          ? "audio/webm"
          : "";
    let recorder;
    try {
      recorder = mime ? new MediaRecorder(stream, { mimeType: mime }) : new MediaRecorder(stream);
    } catch (err) {
      stream.getTracks().forEach((t) => t.stop());
      showCanvasToast?.(err?.message || "无法开始录音");
      return;
    }
    const chunks = [];
    recorder.ondataavailable = (ev) => {
      if (ev.data && ev.data.size > 0) chunks.push(ev.data);
    };
    const startedAt = Date.now();
    const timer = setInterval(() => {
      const elapsed = Math.floor((Date.now() - startedAt) / 1000);
      const sessNow = this._byNode.get(id);
      if (!sessNow) return;
      sessNow.elapsed = elapsed;
      const panel = document.querySelector(`.audio-record-panel[data-node="${CSS.escape(id)}"]`);
      const title = panel?.querySelector(".audio-record-title");
      if (title) title.textContent = `录音中 ${elapsed}s`;
      if (Date.now() - startedAt >= AUDIO_RECORD_MAX_MS) {
        void this.stop(id);
      }
    }, 500);
    this._byNode.set(id, { recorder, stream, chunks, timer, startedAt, elapsed: 0 });
    CanvasStore.updateNode(id, { _recording: true, _recordElapsedSec: 0, status: "idle", error: null });
    renderNodes({ immediate: true });
    recorder.start(250);
    showCanvasToast?.("开始录音");
  },

  async stop(nodeId) {
    const id = String(nodeId || "");
    const sess = this._byNode.get(id);
    if (!sess) return;
    this._byNode.delete(id);
    clearInterval(sess.timer);
    await new Promise((resolve) => {
      sess.recorder.onstop = () => resolve();
      try {
        if (sess.recorder.state !== "inactive") sess.recorder.stop();
        else resolve();
      } catch {
        resolve();
      }
    });
    sess.stream.getTracks().forEach((t) => t.stop());
    CanvasStore.updateNode(id, { _recording: false, _recordElapsedSec: 0 });
    const blob = new Blob(sess.chunks, { type: sess.recorder.mimeType || "audio/webm" });
    if (!blob.size) {
      showCanvasToast?.("没有录到声音");
      renderNodes({ immediate: true });
      return;
    }
    try {
      showCanvasToast?.("正在上传录音…");
      const file = new File([blob], `录音_${Date.now()}.webm`, { type: blob.type || "audio/webm" });
      const boardId = CanvasStore.activeBoardId || CanvasStore.activeBoard()?.id || "";
      const data = await uploadMediaFile(file, null, null, boardId, {});
      const url = data?.url || data?.path || "";
      if (!url) throw new Error("上传失败");
      const namePatch = nodeDisplayNamePatch(id, "录音");
      CanvasStore.updateNode(id, {
        audioUrl: url,
        status: "completed",
        error: null,
        _recording: false,
        ...(namePatch ? { name: namePatch } : {}),
      });
      await CanvasStore.flushSave?.();
      renderNodes({ immediate: true });
      showCanvasToast?.("录音已保存，可裁剪 / 转格式");
    } catch (err) {
      CanvasStore.updateNode(id, { status: "failed", error: err.message || "上传失败", _recording: false });
      renderNodes({ immediate: true });
      showCanvasToast?.(err.message || "录音上传失败");
    }
  },
};

function nodeDisplayNamePatch(nodeId, fallback) {
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  const cur = String(node?.name || "").trim();
  if (cur && !/^音频生成\s*\d*$/i.test(cur) && !/^音频应用\s*\d*$/i.test(cur) && !/^语音生成\s*\d*$/i.test(cur)) return cur;
  return fallback || cur || "录音";
}

window.AudioRecordSession = AudioRecordSession;

async function reconcileStuckUpscaleNodes() {
  if (!window.CanvasStore || !window.CanvasAuth?.isLoggedIn?.()) return;
  const pending = [];
  for (const board of CanvasStore.boards) {
    for (const node of board.nodes) {
      if (node.mediaOp !== "upscale") continue;
      if (!["waiting", "pending", "generating"].includes(node.status)) continue;
      pending.push(node);
    }
  }
  if (!pending.length) return;

  let changed = false;
  for (const node of pending) {
    let jobId = node.upscaleJobId;
    if (!jobId) {
      const upstream = CanvasStore.getUpstreamNodes(node.id)[0];
      const src = upstream?.videoUrl;
      if (!src) continue;
      try {
        const res = await fetch(`/api/upscale/jobs/lookup?url=${encodeURIComponent(src)}`);
        if (!res.ok) continue;
        const data = await res.json();
        jobId = data?.id;
        if (!jobId) continue;
        CanvasStore.updateNode(node.id, { upscaleJobId: jobId }, false);
        changed = true;
      } catch {
        continue;
      }
    }
    try {
      const res = await fetch(`/api/upscale/jobs/${encodeURIComponent(jobId)}`);
      if (!res.ok) continue;
      const data = await res.json();
      if (data.status === "completed" && data.url) {
        MediaTools._finishUpscaleNode(node.id, data);
        changed = true;
      } else if (data.status === "failed") {
        CanvasStore.updateNode(node.id, {
          status: "failed",
          error: data.error || "远程超分失败",
          genStartedAt: null,
          upscaleJobId: null,
        }, false);
        changed = true;
      } else {
        const err = data.status === "pending" ? "排队中（等待本地 GPU）" : "远程超分中";
        if (node.status !== "generating" || node.error !== err) {
          CanvasStore.updateNode(node.id, { status: "generating", error: err, upscaleJobId: jobId }, false);
          changed = true;
        }
        MediaTools.resumeUpscalePoll(node.id, jobId);
      }
    } catch {
      /* ignore */
    }
  }
  if (changed) {
    await CanvasStore.flushSave();
    renderNodes();
    scheduleRenderConnections(true);
  }
}
window.reconcileStuckUpscaleNodes = reconcileStuckUpscaleNodes;
let _upscaleReconcileBusy = false;
let _upscaleReconcileAt = 0;

async function reconcileStuckUpscaleNodesThrottled() {
  const now = Date.now();
  if (_upscaleReconcileBusy || now - _upscaleReconcileAt < 4000) return;
  _upscaleReconcileBusy = true;
  try {
    await reconcileStuckUpscaleNodes();
  } finally {
    _upscaleReconcileBusy = false;
    _upscaleReconcileAt = Date.now();
  }
}
window.reconcileStuckUpscaleNodesThrottled = reconcileStuckUpscaleNodesThrottled;

function formatHistoryTime(ts) {
  const d = new Date(ts || Date.now());
  if (!Number.isFinite(d.getTime())) return "";
  const m = d.getMonth() + 1;
  const day = d.getDate();
  const hh = String(d.getHours()).padStart(2, "0");
  const mm = String(d.getMinutes()).padStart(2, "0");
  const ss = String(d.getSeconds()).padStart(2, "0");
  return `${m}/${day} ${hh}:${mm}:${ss}`;
}

function buildGenHistoryEntry(node, task, statusOverride) {
  const isVideo = (node.type === "video") || Boolean(task?.video_url || node.videoUrl);
  const status =
    statusOverride ||
    (task?.status === "failed" ? "failed" : task?.status === "completed" ? "success" : "success");
  const w = (task && task.width) || node.mediaWidth || null;
  const h = (task && task.height) || node.mediaHeight || null;
  const videoUrl = (task && task.video_url) || (status === "failed" ? null : node.videoUrl) || null;
  const imageUrl = (task && task.image_url) || (status === "failed" ? null : node.imageUrl) || null;
  let coverUrl = (task && task.cover_url) || null;
  let thumbUrl = (task && task.thumb_url) || null;
  if (!coverUrl && status !== "failed" && node.coverUrl) {
    // Only reuse node cover when it still matches this result media.
    const match = videoUrl ? videoStillCoverMatches(videoUrl, node.coverUrl) : null;
    if (videoUrl && match !== false) coverUrl = node.coverUrl;
    else if (!videoUrl && imageUrl) coverUrl = node.coverUrl;
  }
  if (!thumbUrl && status !== "failed" && node.thumbUrl) {
    const match = videoUrl ? videoStillCoverMatches(videoUrl, node.thumbUrl) : null;
    if (videoUrl && match !== false) thumbUrl = node.thumbUrl;
    else if (!videoUrl) thumbUrl = node.thumbUrl;
  }
  return {
    id: uid(),
    taskId: (task && task.id) || node.taskId || null,
    prompt: node.prompt || "",
    ratio: (task && task.ratio) || node.ratio || "自动",
    model: node.model || null,
    duration: node.duration ?? (task && task.duration) ?? null,
    style: node.style || null,
    videoUrl,
    imageUrl,
    coverUrl,
    thumbUrl,
    mediaWidth: w,
    mediaHeight: h,
    resolution: w && h ? `${w}×${h}` : null,
    references: node._lastRefs || null,
    videoMode: isVideo ? getNodeVideoGenMode(node) : null,
    kind: isVideo ? "video" : "image",
    typeLabel: isVideo ? "视频生成" : "图片生成",
    status,
    error: (task && task.error) || node.error || null,
    createdAt: Date.now(),
  };
}

function pushGenHistory(node, entry) {
  const list = Array.isArray(node.genHistory) ? node.genHistory.slice() : [];
  if (entry.taskId) {
    const idx = list.findIndex((h) => h.taskId === entry.taskId);
    if (idx >= 0) {
      list[idx] = { ...list[idx], ...entry, id: list[idx].id };
      return list.slice(0, 40);
    }
  }
  const mediaKey = entry.videoUrl || entry.imageUrl;
  if (mediaKey && entry.status === "success" && list.some((h) => (h.videoUrl || h.imageUrl) === mediaKey)) {
    return list;
  }
  list.unshift(entry);
  return list.slice(0, 40);
}
window.pushGenHistory = pushGenHistory;
window.buildGenHistoryEntry = buildGenHistoryEntry;

function collectBoardHistoryRecords() {
  const board = CanvasStore.activeBoard();
  if (!board) return [];
  const records = [];
  board.nodes.forEach((n) => {
    if (isReferenceNode(n) || isTextGenNode(n)) return;
    if (n.type !== "image" && n.type !== "video") return;
    const list = Array.isArray(n.genHistory) ? n.genHistory : [];
    list.forEach((h) => {
      records.push({
        ...h,
        nodeId: n.id,
        nodeName: getNodeDisplayName(n, board),
        kind: h.kind || (n.type === "video" ? "video" : "image"),
      });
    });
    if (["waiting", "pending", "generating"].includes(n.status)) {
      records.push({
        id: `gen:${n.id}`,
        nodeId: n.id,
        nodeName: getNodeDisplayName(n, board),
        status: "generating",
        kind: n.type === "image" ? "image" : "video",
        typeLabel: n.type === "image" ? "图片生成" : "视频生成",
        prompt: n.prompt || "",
        model: n.model,
        ratio: n.ratio,
        duration: n.duration,
        createdAt: n.genStartedAt || Date.now(),
        taskId: n.taskId,
        videoUrl: null,
        imageUrl: null,
        coverUrl: null,
      });
      return;
    }
    if (n.status === "failed") {
      const already = list.some((h) => h.status === "failed" && (h.taskId === n.taskId || !n.taskId));
      if (!already) {
        records.push({
          id: `fail:${n.id}`,
          nodeId: n.id,
          nodeName: getNodeDisplayName(n, board),
          status: "failed",
          kind: n.type === "video" ? "video" : "image",
          prompt: n.prompt || "",
          model: n.model,
          ratio: n.ratio,
          duration: n.duration,
          createdAt: n.updatedAt || n.genStartedAt || Date.now(),
          error: n.error || null,
          imageUrl: n.imageUrl || null,
          videoUrl: n.videoUrl || null,
          coverUrl: n.coverUrl || null,
        });
      }
    }
    // Nodes that finished before genHistory existed / was empty — still list current media.
    const hasMedia = !!(n.imageUrl || n.videoUrl || n.coverUrl);
    if (!list.length && hasMedia && n.status !== "failed") {
      records.push({
        id: `current:${n.id}`,
        nodeId: n.id,
        nodeName: getNodeDisplayName(n, board),
        status: "completed",
        kind: n.type === "video" ? "video" : "image",
        prompt: n.prompt || "",
        model: n.model,
        ratio: n.ratio,
        duration: n.duration,
        createdAt: n.updatedAt || n.createdAt || n.genStartedAt || Date.now(),
        imageUrl: n.imageUrl || null,
        videoUrl: n.videoUrl || null,
        coverUrl: n.coverUrl || null,
      });
    }
  });
  records.sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0));
  return records;
}

function historyMethodLabel(entry) {
  const refs = Array.isArray(entry?.references) ? entry.references : [];
  if (!refs.length) return entry?.kind === "image" ? "图片生成" : "视频生成";
  const hasVideo = refs.some((r) => r.kind === "video");
  const hasAudio = refs.some((r) => r.kind === "audio");
  const hasImage = refs.some((r) => !r.kind || r.kind === "image");
  if (hasVideo || hasAudio) return "多模态参考";
  if (hasImage) return "图文参考";
  return "参考生成";
}

const HistoryDock = {
  refresh() {
    if (typeof BoardHistoryPanel !== "undefined") BoardHistoryPanel.refreshIfOpen();
  },
  bind() {},
};
window.HistoryDock = HistoryDock;

function formatHistoryClock(ts) {
  const d = new Date(ts || Date.now());
  if (Number.isNaN(d.getTime())) return "";
  const hh = String(d.getHours()).padStart(2, "0");
  const mm = String(d.getMinutes()).padStart(2, "0");
  const ss = String(d.getSeconds()).padStart(2, "0");
  return `${hh}:${mm}:${ss}`;
}

function formatHistoryDayLabel(ts) {
  const d = new Date(ts || Date.now());
  if (Number.isNaN(d.getTime())) return "未知日期";
  return `${d.getMonth() + 1}月${d.getDate()}日`;
}

function formatHistoryWeekday(ts) {
  const d = new Date(ts || Date.now());
  if (Number.isNaN(d.getTime())) return "";
  return ["日", "一", "二", "三", "四", "五", "六"][d.getDay()] || "";
}

const BoardHistoryPanel = {
  filter: "all",
  view: "grid",
  thumbSize: "sm",
  page: 1,
  pageSize: 42,
  showFailed: false,
  multiSelect: false,
  selectedKey: "",
  selectedKeys: new Set(),
  _bound: false,
  _records: [],
  _closeTimer: null,

  isOpen() {
    const root = document.getElementById("board-history-drawer");
    return !!(root && root.classList.contains("is-open"));
  },

  open() {
    closeExclusiveChromePopovers("board-history");
    this._bindOnce();
    const root = document.getElementById("board-history-drawer");
    if (!root) return;
    clearTimeout(this._closeTimer);
    root.classList.remove("hidden", "is-closing");
    root.setAttribute("aria-hidden", "false");
    // Double rAF so closed styles paint before is-open (enables slide-in).
    requestAnimationFrame(() => {
      requestAnimationFrame(() => root.classList.add("is-open"));
    });
    document.getElementById("btn-dock-history")?.setAttribute("aria-expanded", "true");
    document.getElementById("btn-dock-history")?.classList.add("is-active");
    this.render();
  },

  close(opts = {}) {
    const root = document.getElementById("board-history-drawer");
    if (!root) return;
    // Keep visible during exit so opacity/transform can animate (avoid instant flash-out).
    root.classList.remove("is-open");
    root.classList.add("is-closing");
    root.setAttribute("aria-hidden", "true");
    document.getElementById("btn-dock-history")?.setAttribute("aria-expanded", "false");
    document.getElementById("btn-dock-history")?.classList.remove("is-active");
    clearTimeout(this._closeTimer);
    this._closeTimer = setTimeout(() => {
      root.classList.add("hidden");
      root.classList.remove("is-closing", "has-detail", "is-multiselect");
      this.selectedKey = "";
      this.selectedKeys = new Set();
      this.multiSelect = false;
      this._renderDetail(null);
    }, 360);
    if (!opts.fromDock) {
      try {
        window.ChromeDock?.syncDockBtnStates?.();
        window.ChromeDock?.scheduleHide?.();
      } catch {
        /* ignore */
      }
    }
  },

  toggle() {
    if (this.isOpen()) this.close();
    else this.open();
  },

  refreshIfOpen() {
    if (this.isOpen()) this.render();
  },

  setMultiSelect(on) {
    this.multiSelect = !!on;
    if (this.multiSelect) {
      this.selectedKey = "";
      this._renderDetail(null);
    } else {
      this.selectedKeys = new Set();
    }
    this.render();
  },

  _bindOnce() {
    if (this._bound) return;
    this._bound = true;
    document.getElementById("board-history-close")?.addEventListener("click", () => this.close());
    document.getElementById("board-history-backdrop")?.addEventListener("click", () => this.close());
    document.getElementById("board-history-multi")?.addEventListener("click", () => {
      this.setMultiSelect(!this.multiSelect);
    });
    document.getElementById("board-history-filters")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-filter]");
      if (!btn) return;
      this.filter = btn.dataset.filter || "all";
      this.page = 1;
      this.selectedKey = "";
      this.selectedKeys = new Set();
      this.render();
    });
    document.getElementById("board-history-size")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-size]");
      if (!btn) return;
      this.thumbSize = btn.dataset.size || "sm";
      this.render();
    });
    document.getElementById("board-history-view-grid")?.addEventListener("click", () => {
      this.view = "grid";
      this.render();
    });
    document.getElementById("board-history-view-list")?.addEventListener("click", () => {
      this.view = "list";
      this.render();
    });
    document.getElementById("board-history-page-size")?.addEventListener("change", (e) => {
      const n = parseInt(e.target.value, 10);
      this.pageSize = Number.isFinite(n) ? n : 42;
      this.page = 1;
      this.render();
    });
    document.getElementById("board-history-show-failed")?.addEventListener("change", (e) => {
      this.showFailed = !!e.target.checked;
      this.page = 1;
      this.selectedKeys = new Set();
      this.render();
    });
    document.getElementById("board-history-select-all")?.addEventListener("click", () => this.selectAllPage());
    document.getElementById("board-history-clear-sel")?.addEventListener("click", () => {
      this.selectedKeys = new Set();
      this.render();
    });
    document.getElementById("board-history-pack")?.addEventListener("click", () => void this.packDownloadSelected());
    document.getElementById("board-history-locate")?.addEventListener("click", () => this.locateSelected());
    document.getElementById("board-history-place")?.addEventListener("click", () => this.placeSelected());
    document.getElementById("board-history-detail-locate")?.addEventListener("click", () => this.locateDetail());
    document.getElementById("board-history-detail-place")?.addEventListener("click", () => this.placeDetail());
    document.getElementById("board-history-pager")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-page]");
      if (!btn || btn.disabled) return;
      const page = parseInt(btn.dataset.page, 10);
      if (!Number.isFinite(page)) return;
      this.page = page;
      this.render();
    });
  },

  _isFailed(r) {
    const s = String(r?.status || "").toLowerCase();
    return s === "failed" || s === "error" || s === "fail";
  },

  _filtered() {
    let all = collectBoardHistoryRecords();
    this._records = all;
    if (!this.showFailed) all = all.filter((r) => !this._isFailed(r));
    if (this.filter === "image") all = all.filter((r) => (r.kind || "") === "image");
    else if (this.filter === "video") all = all.filter((r) => (r.kind || "") === "video");
    else all = all.filter((r) => r.kind === "image" || r.kind === "video" || !r.kind);
    return all;
  },

  _recordKey(r) {
    return `${r.nodeId || ""}::${r.id || r.createdAt || ""}`;
  },

  _pageRows(all) {
    const totalPages = Math.max(1, Math.ceil(all.length / this.pageSize) || 1);
    if (this.page > totalPages) this.page = totalPages;
    if (this.page < 1) this.page = 1;
    const start = (this.page - 1) * this.pageSize;
    return { rows: all.slice(start, start + this.pageSize), totalPages, total: all.length };
  },

  _groupByDay(rows) {
    const groups = [];
    const map = new Map();
    rows.forEach((r) => {
      const d = new Date(r.createdAt || 0);
      const key = Number.isNaN(d.getTime())
        ? "unknown"
        : `${d.getFullYear()}-${d.getMonth() + 1}-${d.getDate()}`;
      if (!map.has(key)) {
        const g = { key, label: "", items: [] };
        map.set(key, g);
        groups.push(g);
      }
      map.get(key).items.push(r);
    });
    groups.forEach((g) => {
      const sample = g.items[0];
      const wd = formatHistoryWeekday(sample?.createdAt);
      g.label = `${formatHistoryDayLabel(sample?.createdAt)}${wd ? ` 周${wd}` : ""}`;
      g.count = g.items.length;
    });
    return groups;
  },

  _syncChrome() {
    const root = document.getElementById("board-history-drawer");
    root?.classList.toggle("is-multiselect", !!this.multiSelect);
    document.querySelectorAll(".board-history-filter").forEach((btn) => {
      btn.classList.toggle("is-active", btn.dataset.filter === this.filter);
    });
    document.querySelectorAll(".board-history-size-btn").forEach((btn) => {
      btn.classList.toggle("is-active", btn.dataset.size === this.thumbSize);
    });
    document.getElementById("board-history-view-grid")?.classList.toggle("is-active", this.view === "grid");
    document.getElementById("board-history-view-list")?.classList.toggle("is-active", this.view === "list");
    const multiBtn = document.getElementById("board-history-multi");
    if (multiBtn) {
      multiBtn.classList.toggle("is-active", !!this.multiSelect);
      multiBtn.setAttribute("aria-pressed", this.multiSelect ? "true" : "false");
    }
    const sizeSel = document.getElementById("board-history-page-size");
    if (sizeSel) sizeSel.value = String(this.pageSize);
    const failed = document.getElementById("board-history-show-failed");
    if (failed) failed.checked = !!this.showFailed;
    const body = document.getElementById("board-history-body");
    if (body) {
      body.dataset.size = this.thumbSize;
      body.dataset.view = this.view;
    }
  },

  _syncSelBar() {
    const bar = document.getElementById("board-history-selbar");
    const count = document.getElementById("board-history-sel-count");
    const n = this.selectedKeys.size;
    if (bar) bar.hidden = !this.multiSelect;
    if (count) count.textContent = `已选 ${n}`;
  },

  _renderPager(totalPages) {
    const pager = document.getElementById("board-history-pager");
    if (!pager) return;
    if (totalPages <= 1) {
      pager.innerHTML = "";
      return;
    }
    const page = this.page;
    const buttons = [];
    buttons.push(
      `<button type="button" class="board-history-page-btn" data-page="${page - 1}" ${page <= 1 ? "disabled" : ""} aria-label="上一页">‹</button>`
    );
    const windowSize = 5;
    let start = Math.max(1, page - Math.floor(windowSize / 2));
    let end = Math.min(totalPages, start + windowSize - 1);
    start = Math.max(1, end - windowSize + 1);
    for (let i = start; i <= end; i++) {
      buttons.push(
        `<button type="button" class="board-history-page-btn${i === page ? " is-active" : ""}" data-page="${i}">${i}</button>`
      );
    }
    buttons.push(
      `<button type="button" class="board-history-page-btn" data-page="${page + 1}" ${page >= totalPages ? "disabled" : ""} aria-label="下一页">›</button>`
    );
    pager.innerHTML = buttons.join("");
  },

  _kv(label, value) {
    if (value == null || value === "") return "";
    return `<div class="board-history-kv"><span>${escapeHtml(label)}</span><strong title="${escapeAttr(String(value))}">${escapeHtml(String(value))}</strong></div>`;
  },

  _renderDetail(sel) {
    const root = document.getElementById("board-history-drawer");
    const sheet = document.getElementById("board-history-detail-sheet");
    const preview = document.getElementById("board-history-detail-preview");
    const meta = document.getElementById("board-history-detail-meta");
    const promptEl = document.getElementById("board-history-detail-prompt");
    const grid = document.getElementById("board-history-detail-grid");
    if (!sheet) return;
    if (!sel || this.multiSelect) {
      root?.classList.remove("has-detail");
      sheet.setAttribute("aria-hidden", "true");
      return;
    }
    root?.classList.add("has-detail");
    sheet.setAttribute("aria-hidden", "false");
    if (preview) {
      if (sel.videoUrl) {
        preview.innerHTML = `<video src="${escapeAttr(sel.videoUrl)}" controls playsinline preload="metadata"></video>`;
      } else if (sel.coverUrl || sel.imageUrl) {
        preview.innerHTML = `<img src="${escapeAttr(sel.coverUrl || sel.imageUrl)}" alt="" />`;
      } else {
        preview.innerHTML = `<div class="board-history-thumb-fallback">${escapeHtml(this._isFailed(sel) ? "失败" : sel.status === "generating" ? "生成中" : "无预览")}</div>`;
      }
    }
    if (meta) {
      meta.textContent = [
        sel.nodeName || "节点",
        historyMethodLabel(sel),
        `${formatHistoryDayLabel(sel.createdAt)} ${formatHistoryClock(sel.createdAt)}`,
      ]
        .filter(Boolean)
        .join(" · ");
    }
    if (promptEl) promptEl.textContent = sel.prompt || "（无提示词）";
    if (grid) {
      grid.innerHTML = [
        this._kv("类型", historyMethodLabel(sel)),
        this._kv("模型", sel.model),
        this._kv("比例", sel.ratio),
        this._kv("时长", sel.duration != null ? `${sel.duration}秒` : ""),
        this._kv("节点", sel.nodeName || sel.nodeId),
        this._kv("任务", sel.taskId || sel.id),
      ].join("");
    }
  },

  _cardHtml(r) {
    const key = this._recordKey(r);
    const selected = this.multiSelect && this.selectedKeys.has(key);
    const active = !this.multiSelect && key === this.selectedKey;
    const thumb =
      r.coverUrl || r.imageUrl
        ? `<img src="${escapeAttr(r.coverUrl || r.imageUrl)}" alt="" loading="lazy" />`
        : r.videoUrl
          ? `<video src="${escapeAttr(r.videoUrl)}" muted preload="metadata" playsinline></video>`
          : `<div class="board-history-thumb-fallback">${escapeHtml(this._isFailed(r) ? "失败" : r.status === "generating" ? "生成中" : "无预览")}</div>`;
    const play =
      r.kind === "video" || r.videoUrl ? `<span class="board-history-card-play" aria-hidden="true">▶</span>` : "";
    const title = r.nodeName || (r.kind === "video" ? "视频" : "图片");
    const meta =
      this.view === "list"
        ? `<div class="board-history-card-meta"><strong title="${escapeAttr(title)}">${escapeHtml(title)}</strong><span>${escapeHtml(historyMethodLabel(r))} · ${escapeHtml(formatHistoryClock(r.createdAt))}</span></div>`
        : "";
    const check = this.multiSelect
      ? `<span class="board-history-card-check" aria-hidden="true"></span>`
      : "";
    return `<button type="button" class="board-history-card${selected ? " is-selected" : ""}${active ? " is-active" : ""}" data-key="${escapeAttr(key)}" draggable="true">
      ${check}
      <div class="board-history-thumb">${thumb}</div>
      ${play}
      ${this.view === "grid" ? `<span class="board-history-card-time">${escapeHtml(formatHistoryClock(r.createdAt))}</span>` : ""}
      ${meta}
    </button>`;
  },

  render() {
    const body = document.getElementById("board-history-body");
    const countEl = document.getElementById("board-history-count");
    if (!body) return;
    this._syncChrome();
    const all = this._filtered();
    const valid = new Set(all.map((r) => this._recordKey(r)));
    this.selectedKeys = new Set([...this.selectedKeys].filter((k) => valid.has(k)));
    if (this.selectedKey && !valid.has(this.selectedKey)) this.selectedKey = "";
    const { rows, totalPages, total } = this._pageRows(all);
    if (countEl) countEl.textContent = `共 ${total} 项`;
    this._renderPager(totalPages);
    this._syncSelBar();
    const sel = this.selectedKey ? all.find((r) => this._recordKey(r) === this.selectedKey) || null : null;
    this._renderDetail(sel);

    if (!rows.length) {
      body.innerHTML = `<div class="board-history-empty">${this.showFailed ? "当前筛选下没有记录" : "还没有生成结果"}</div>`;
      return;
    }

    const groups = this._groupByDay(rows);
    body.innerHTML = groups
      .map((g) => {
        const cards = g.items.map((r) => this._cardHtml(r)).join("");
        return `<section class="board-history-day"><h3 class="board-history-day-title">${escapeHtml(g.label)}<span class="board-history-day-count">${g.count} 项</span></h3><div class="board-history-day-grid">${cards}</div></section>`;
      })
      .join("");

    body.querySelectorAll(".board-history-card").forEach((card) => {
      card.addEventListener("click", (e) => {
        e.preventDefault();
        const key = card.dataset.key || "";
        if (!key) return;
        if (this.multiSelect) {
          if (this.selectedKeys.has(key)) this.selectedKeys.delete(key);
          else this.selectedKeys.add(key);
          this.render();
          return;
        }
        this.selectedKey = this.selectedKey === key ? "" : key;
        this.render();
      });
      card.addEventListener("dblclick", (e) => {
        e.preventDefault();
        const rec = all.find((r) => this._recordKey(r) === card.dataset.key);
        if (rec) placeCleanHistoryNode(rec);
      });
      card.addEventListener("dragstart", (e) => {
        const rec = all.find((r) => this._recordKey(r) === card.dataset.key);
        if (!rec) return;
        e.dataTransfer.setData(
          "application/x-board-history",
          JSON.stringify({
            nodeId: rec.nodeId,
            id: rec.id,
            kind: rec.kind,
            prompt: rec.prompt || "",
            model: rec.model,
            ratio: rec.ratio,
            duration: rec.duration,
            imageUrl: rec.imageUrl || null,
            videoUrl: rec.videoUrl || null,
            coverUrl: rec.coverUrl || null,
          })
        );
        e.dataTransfer.effectAllowed = "copy";
      });
    });
  },

  selectAllPage() {
    if (!this.multiSelect) return;
    const all = this._filtered();
    const { rows } = this._pageRows(all);
    rows.forEach((r) => this.selectedKeys.add(this._recordKey(r)));
    this.render();
  },

  _selectedRecords() {
    const all = this._filtered();
    return all.filter((r) => this.selectedKeys.has(this._recordKey(r)));
  },

  _detailRecord() {
    if (!this.selectedKey) return null;
    return this._filtered().find((r) => this._recordKey(r) === this.selectedKey) || null;
  },

  locateSelected() {
    const list = this._selectedRecords();
    const sel = list[0];
    if (!sel?.nodeId) {
      if (typeof showCanvasToast === "function") showCanvasToast("请先选择一项");
      return;
    }
    if (typeof NodeListPanel !== "undefined") NodeListPanel.open();
    if (typeof focusNodeOnCanvasSmooth === "function") focusNodeOnCanvasSmooth(sel.nodeId, { durationMs: 560, save: true });
    else if (typeof focusNodeOnCanvas === "function") focusNodeOnCanvas(sel.nodeId);
  },

  locateDetail() {
    const sel = this._detailRecord();
    if (!sel?.nodeId) return;
    if (typeof NodeListPanel !== "undefined") NodeListPanel.open();
    if (typeof focusNodeOnCanvasSmooth === "function") focusNodeOnCanvasSmooth(sel.nodeId, { durationMs: 560, save: true });
    else if (typeof focusNodeOnCanvas === "function") focusNodeOnCanvas(sel.nodeId);
  },

  placeSelected() {
    const list = this._selectedRecords();
    if (!list.length) {
      if (typeof showCanvasToast === "function") showCanvasToast("请先选择要放入的项");
      return;
    }
    list.forEach((rec, i) => {
      const base =
        typeof screenToWorld === "function"
          ? screenToWorld(window.innerWidth / 2 + i * 36, window.innerHeight / 2 + i * 28)
          : { x: 120 + i * 40, y: 120 + i * 30 };
      placeCleanHistoryNode(rec, base);
    });
  },

  placeDetail() {
    const sel = this._detailRecord();
    if (!sel) return;
    placeCleanHistoryNode(sel);
  },

  async packDownloadSelected() {
    const list = this._selectedRecords().filter((r) => r.imageUrl || r.videoUrl || r.coverUrl);
    if (!list.length) {
      if (typeof showCanvasToast === "function") showCanvasToast("所选没有可下载的媒体");
      return;
    }
    if (typeof showLoadingToast === "function") showLoadingToast(`正在打包 ${list.length} 个文件…`);
    try {
      const used = new Set();
      const entries = [];
      for (let i = 0; i < list.length; i++) {
        const r = list[i];
        const url = r.videoUrl || r.imageUrl || r.coverUrl;
        const res = await fetch(url, { credentials: "same-origin" });
        if (!res.ok) throw new Error("下载失败");
        const blob = await res.blob();
        const ext = r.videoUrl
          ? ".mp4"
          : /\.png(\?|$)/i.test(url)
            ? ".png"
            : /\.webp(\?|$)/i.test(url)
              ? ".webp"
              : ".jpg";
        const base =
          typeof sanitizeDownloadFilename === "function"
            ? sanitizeDownloadFilename(
                `${r.nodeName || r.kind || "media"}-${formatHistoryClock(r.createdAt).replace(/:/g, "") || i}`
              )
            : `media-${i}`;
        let name = `${base}${ext}`;
        let n = 1;
        while (used.has(name)) {
          name = `${base}-${n}${ext}`;
          n += 1;
        }
        used.add(name);
        entries.push({ name, data: blob });
      }
      const boardName =
        typeof sanitizeDownloadFilename === "function"
          ? sanitizeDownloadFilename(CanvasStore.activeBoard()?.name || "canvas")
          : "canvas";
      const stamp = new Date().toISOString().slice(0, 10);
      const zipBlob = await buildZipBlob(entries);
      triggerBlobDownload(zipBlob, `${boardName}-历史-${list.length}项-${stamp}.zip`);
      if (typeof hideLoadingToast === "function") hideLoadingToast();
      if (typeof showCanvasToast === "function") showCanvasToast(`已打包下载 ${list.length} 个文件`);
    } catch (err) {
      if (typeof hideLoadingToast === "function") hideLoadingToast();
      if (typeof showCanvasToast === "function") showCanvasToast(err.message || "打包下载失败");
    }
  },
};
window.BoardHistoryPanel = BoardHistoryPanel;

function placeCleanHistoryNode(entry, worldPos) {
  if (!entry) return null;
  const kind = entry.kind === "video" ? "video" : "image";
  const pos =
    worldPos ||
    (typeof screenToWorld === "function"
      ? screenToWorld(window.innerWidth / 2, window.innerHeight / 2)
      : { x: 120, y: 120 });
  CanvasHistory.push();
  const node = CanvasStore.addNode(kind, pos.x, pos.y);
  if (!node) return null;
  CanvasStore.updateNode(node.id, {
    prompt: entry.prompt || "",
    model: entry.model || node.model,
    ratio: entry.ratio || node.ratio,
    duration: entry.duration ?? node.duration,
    imageUrl: entry.imageUrl || null,
    videoUrl: entry.videoUrl || null,
    coverUrl: entry.coverUrl || null,
    status: entry.imageUrl || entry.videoUrl ? "completed" : "idle",
    genHistory: [],
    activeHistoryId: null,
    softRefIds: [],
    taskId: null,
    error: null,
  });
  if (typeof renderNodes === "function") renderNodes();
  if (typeof scheduleRenderConnections === "function") scheduleRenderConnections(true);
  if (typeof updateNodeCount === "function") updateNodeCount();
  if (typeof showCanvasToast === "function") showCanvasToast("已放到画布（干净节点）");
  return node.id;
}
window.placeCleanHistoryNode = placeCleanHistoryNode;

const ChromeDock = {
  revealed: true,
  _hideTimer: null,
  _bound: false,
  /** Bottom pad (px) used only under the dock's own horizontal span. */
  REVEAL_EDGE: 56,
  /** Extra horizontal slack around the dock / peek when waking. */
  WAKE_PAD_X: 28,
  HIDE_DELAY_MS: 260,

  init() {
    if (this._bound) return;
    this._bound = true;
    if (typeof CanvasPrefs !== "undefined") CanvasPrefs.load();
    this.syncPinUi();
    this.syncSettingsChecks();
    try {
      window.CanvasMinimap?.setOpen?.(!!CanvasPrefs.showMinimap);
    } catch {
      /* ignore */
    }
    if (typeof applyViewportGrid === "function") applyViewportGrid();
    if (CanvasPrefs.dockPinned) {
      this.setCollapsed(false, { immediate: true });
    } else {
      this.setCollapsed(true, { immediate: true });
    }

    const peek = document.getElementById("chrome-dock-peek");
    const wrap = document.querySelector(".tool-dock-wrap");
    const hotzone = document.getElementById("chrome-dock-hotzone");

    const onMove = (e) => {
      this._lastPointer = { clientX: e.clientX, clientY: e.clientY, target: e.target };
      if (CanvasPrefs.dockPinned) {
        this.reveal();
        return;
      }
      if (this._shouldStayOpen(e)) {
        this.reveal();
        return;
      }
      // Side panels (节点列表 / 资产等) must not expand the center dock, and must not
      // start a hide timer that races the user toward those panels.
      if (this._hasAttachedChromeOpen()) {
        clearTimeout(this._hideTimer);
        this._hideTimer = null;
        return;
      }
      this.scheduleHide();
    };
    document.addEventListener("mousemove", onMove, { passive: true });
    hotzone?.addEventListener("mouseenter", () => {
      if (!CanvasPrefs.dockPinned) this.reveal();
    });
    peek?.addEventListener("mouseenter", () => this.reveal());
    peek?.addEventListener("click", () => this.reveal());
    wrap?.addEventListener("mouseenter", () => this.reveal());
    wrap?.addEventListener("mouseleave", (e) => {
      if (CanvasPrefs.dockPinned) return;
      if (this._shouldStayOpen({ clientX: e.clientX, clientY: e.clientY, target: e.relatedTarget })) return;
      this.scheduleHide();
    });

    document.getElementById("btn-dock-assets")?.addEventListener("click", () => {
      this.reveal();
      const root = document.getElementById("asset-picker");
      const open =
        !!(root && typeof isOverlayOpen === "function" && isOverlayOpen(root) && AssetPicker?.placeMode);
      if (open) {
        AssetPicker.close();
        this.syncDockBtnStates();
        return;
      }
      closeExclusiveChromePopovers("assets");
      AssetPicker.openBrowse();
      this.syncDockBtnStates();
    });
    document.getElementById("btn-dock-history")?.addEventListener("click", () => {
      this.reveal();
      BoardHistoryPanel.toggle();
      this.syncDockBtnStates();
    });
    document.getElementById("btn-dock-locate")?.addEventListener("click", () => {
      this.reveal();
      if (typeof NodeListPanel !== "undefined") NodeListPanel.toggle();
      else window.NodeListPanel?.toggle?.();
      this.syncDockBtnStates();
    });
    document.getElementById("btn-dock-canvas-settings")?.addEventListener("click", () => {
      this.reveal();
      this.toggleSettings();
      this.syncDockBtnStates();
    });
    document.getElementById("dock-canvas-settings-close")?.addEventListener("click", () => {
      this.closeSettings();
      this.syncDockBtnStates();
    });
    document.getElementById("btn-dock-pin")?.addEventListener("click", () => {
      CanvasPrefs.dockPinned = !CanvasPrefs.dockPinned;
      CanvasPrefs.save();
      this.syncPinUi();
      if (CanvasPrefs.dockPinned) this.reveal();
      else this.scheduleHide();
      const pinCb = document.getElementById("dock-pref-dock-pinned");
      if (pinCb) pinCb.checked = !!CanvasPrefs.dockPinned;
    });

    const bindPref = (id, key, apply) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.checked = !!CanvasPrefs[key];
      el.addEventListener("change", () => {
        CanvasPrefs[key] = !!el.checked;
        CanvasPrefs.save();
        apply?.(!!el.checked);
        if (key === "dockPinned") {
          this.syncPinUi();
          if (CanvasPrefs.dockPinned) this.reveal();
          else this.scheduleHide();
        }
      });
    };
    bindPref("dock-pref-snap-align", "snapAlign");
    bindPref("dock-pref-show-grid", "showGrid", () => {
      document.getElementById("btn-grid-toggle")?.classList.toggle("is-active", CanvasPrefs.showGrid);
      document.getElementById("btn-grid-toggle")?.setAttribute("aria-pressed", CanvasPrefs.showGrid ? "true" : "false");
      if (typeof applyViewportGrid === "function") applyViewportGrid();
    });
    bindPref("dock-pref-show-minimap", "showMinimap", (on) => {
      window.CanvasMinimap?.setOpen?.(on);
    });
    bindPref("dock-pref-conn-flow", "connFlowAnim", () => {
      if (typeof scheduleRenderConnections === "function") scheduleRenderConnections(true);
    });
    bindPref("dock-pref-dock-pinned", "dockPinned");

    const viewport = document.getElementById("viewport") || document.querySelector(".viewport");
    viewport?.addEventListener("dragover", (e) => {
      if ([...e.dataTransfer.types].includes("application/x-board-history")) {
        e.preventDefault();
        e.dataTransfer.dropEffect = "copy";
      }
    });
    viewport?.addEventListener("drop", (e) => {
      const raw = e.dataTransfer.getData("application/x-board-history");
      if (!raw) return;
      e.preventDefault();
      try {
        const data = JSON.parse(raw);
        const pos = screenToWorld(e.clientX, e.clientY);
        placeCleanHistoryNode(data, pos);
      } catch {
        /* ignore */
      }
    });
  },

  _hitRect(el, pad = 10) {
    if (!el || el.hidden) return null;
    if (el.classList?.contains("hidden") && el.id !== "chrome-dock-peek") return null;
    const r = el.getBoundingClientRect();
    if (r.width < 1 && r.height < 1) return null;
    return {
      left: r.left - pad,
      right: r.right + pad,
      top: r.top - pad,
      bottom: r.bottom + pad,
    };
  },

  _pointIn(rect, x, y) {
    return !!(rect && x >= rect.left && x <= rect.right && y >= rect.top && y <= rect.bottom);
  },

  _addMenuOpen() {
    const menu = document.getElementById("add-menu");
    if (!menu || menu.classList.contains("hidden")) return false;
    if (typeof isFloatingMenuOpen === "function") return !!isFloatingMenuOpen(menu);
    return true;
  },

  /** Popovers opened from dock / status bar — keep them from being auto-dismissed. */
  _hasAttachedChromeOpen() {
    if (this._settingsOpen()) return true;
    if (this._addMenuOpen()) return true;
    if (this._nodeListOpen()) return true;
    try {
      if (BoardHistoryPanel.isOpen()) return true;
    } catch {
      /* ignore */
    }
    if (this._assetsOpen() && AssetPicker?.placeMode) return true;
    return false;
  },

  /** Horizontal band of the center tool dock (works even while collapsed/translated). */
  _dockWakeXRange() {
    const wrap = document.querySelector(".tool-dock-wrap");
    const peek = document.getElementById("chrome-dock-peek");
    const dock = document.getElementById("tool-dock");
    const pad = this.WAKE_PAD_X;
    for (const el of [dock, wrap, peek]) {
      if (!el || el.hidden) continue;
      const r = el.getBoundingClientRect();
      if (r.width < 1) continue;
      return { left: r.left - pad, right: r.right + pad };
    }
    const cx = window.innerWidth / 2;
    return { left: cx - 120, right: cx + 120 };
  },

  _inDockWakeBand(x, y) {
    if (y < window.innerHeight - this.REVEAL_EDGE) return false;
    const band = this._dockWakeXRange();
    return x >= band.left && x <= band.right;
  },

  _shouldStayOpen(e) {
    const x = e?.clientX ?? -1;
    const y = e?.clientY ?? -1;

    const target = e?.target;
    if (
      target instanceof Element &&
      target.closest?.(
        ".tool-dock-wrap, #tool-dock, #chrome-dock-peek, #dock-canvas-settings, #add-menu"
      )
    ) {
      return true;
    }
    // Open dock-tethered panels keep the dock expanded only while pointer is on them.
    if (
      target instanceof Element &&
      ((this._settingsOpen() && target.closest?.("#dock-canvas-settings")) ||
        (this._addMenuOpen() && target.closest?.("#add-menu")) ||
        (BoardHistoryPanel.isOpen?.() && target.closest?.("#board-history-shell, #board-history-drawer")))
    ) {
      return true;
    }

    const dock = document.getElementById("tool-dock");
    const wrap = document.querySelector(".tool-dock-wrap");
    const peek = document.getElementById("chrome-dock-peek");
    const settings = document.getElementById("dock-canvas-settings");
    const addMenu = document.getElementById("add-menu");
    const historyShell = document.getElementById("board-history-shell");

    if (this.revealed) {
      if (this._pointIn(this._hitRect(dock, 14), x, y)) return true;
      if (this._pointIn(this._hitRect(wrap, 14), x, y)) return true;
      if (this._settingsOpen() && this._pointIn(this._hitRect(settings, 10), x, y)) return true;
      if (this._addMenuOpen() && this._pointIn(this._hitRect(addMenu, 12), x, y)) return true;
      if (BoardHistoryPanel.isOpen() && this._pointIn(this._hitRect(historyShell, 8), x, y)) return true;
      return false;
    }

    // Collapsed: wake only on the peek / under the dock itself — not right-side chrome.
    if (this._pointIn(this._hitRect(peek, 24), x, y)) return true;
    return this._inDockWakeBand(x, y);
  },

  _nodeListOpen() {
    try {
      if (typeof NodeListPanel !== "undefined") return !!NodeListPanel.isOpen();
      return !!window.NodeListPanel?.isOpen?.();
    } catch {
      return false;
    }
  },

  _assetsOpen() {
    const root = document.getElementById("asset-picker");
    return !!(root && typeof isOverlayOpen === "function" && isOverlayOpen(root));
  },

  _settingsOpen() {
    const el = document.getElementById("dock-canvas-settings");
    return !!(el && !el.classList.contains("hidden"));
  },

  syncDockBtnStates() {
    const locate = document.getElementById("btn-dock-locate");
    const hist = document.getElementById("btn-dock-history");
    const assets = document.getElementById("btn-dock-assets");
    const settings = document.getElementById("btn-dock-canvas-settings");
    const listOpen = this._nodeListOpen();
    const histOpen = !!BoardHistoryPanel.isOpen?.();
    const assetsOpen = this._assetsOpen() && !!AssetPicker?.placeMode;
    const settingsOpen = this._settingsOpen();
    if (locate) {
      locate.classList.toggle("is-active", listOpen);
      locate.setAttribute("aria-expanded", listOpen ? "true" : "false");
    }
    if (hist) {
      hist.classList.toggle("is-active", histOpen);
      hist.setAttribute("aria-expanded", histOpen ? "true" : "false");
    }
    if (assets) {
      assets.classList.toggle("is-active", assetsOpen);
      assets.setAttribute("aria-expanded", assetsOpen ? "true" : "false");
    }
    if (settings) {
      settings.classList.toggle("is-active", settingsOpen);
      settings.setAttribute("aria-expanded", settingsOpen ? "true" : "false");
    }
  },

  /**
   * On dock auto-hide: only drop the + add menu (tethered to the dock).
   * Node list / assets / settings / history stay — closing them here made panels
   * flash shut when the unpinned dock collapsed after a click.
   */
  dismissAttachedChrome() {
    try {
      if (this._addMenuOpen() && typeof hideMenus === "function") hideMenus();
    } catch {
      /* ignore */
    }
    this.syncDockBtnStates();
  },

  syncSettingsChecks() {
    const map = {
      "dock-pref-snap-align": "snapAlign",
      "dock-pref-show-grid": "showGrid",
      "dock-pref-show-minimap": "showMinimap",
      "dock-pref-conn-flow": "connFlowAnim",
      "dock-pref-dock-pinned": "dockPinned",
    };
    Object.entries(map).forEach(([id, key]) => {
      const input = document.getElementById(id);
      if (input) input.checked = !!CanvasPrefs[key];
    });
  },

  syncPinUi() {
    const btn = document.getElementById("btn-dock-pin");
    const pinned = !!CanvasPrefs.dockPinned;
    if (btn) {
      btn.classList.toggle("is-active", pinned);
      btn.setAttribute("aria-pressed", pinned ? "true" : "false");
      btn.title = pinned ? "取消固定（离开底部自动收起）" : "固定工具栏";
    }
  },

  reveal() {
    clearTimeout(this._hideTimer);
    this._hideTimer = null;
    this.setCollapsed(false);
  },

  scheduleHide() {
    if (CanvasPrefs.dockPinned) return;
    if (this._hasAttachedChromeOpen()) return;
    // Do not reset on every mousemove — otherwise continuous canvas motion never hides.
    if (this._hideTimer) return;
    this._hideTimer = setTimeout(() => {
      this._hideTimer = null;
      if (CanvasPrefs.dockPinned) return;
      // Re-check: panel may have opened during the delay, or pointer re-entered chrome.
      if (this._hasAttachedChromeOpen()) return;
      if (this._lastPointer && this._shouldStayOpen(this._lastPointer)) return;
      this.dismissAttachedChrome();
      this.setCollapsed(true);
    }, this.HIDE_DELAY_MS);
  },

  setCollapsed(collapsed, { immediate = false } = {}) {
    const chrome = document.getElementById("chrome-bottom");
    const peek = document.getElementById("chrome-dock-peek");
    const hotzone = document.getElementById("chrome-dock-hotzone");
    if (!chrome) return;
    this.revealed = !collapsed;
    chrome.classList.toggle("is-dock-collapsed", !!collapsed);
    if (peek) {
      if (collapsed && !CanvasPrefs.dockPinned) peek.hidden = false;
      else peek.hidden = true;
    }
    if (hotzone) {
      hotzone.classList.toggle("is-active", !!collapsed && !CanvasPrefs.dockPinned);
    }
    if (immediate) chrome.classList.add("is-dock-ready");
  },

  toggleSettings() {
    if (this._settingsOpen()) this.closeSettings();
    else this.openSettings();
  },

  openSettings() {
    closeExclusiveChromePopovers("dock-settings");
    const el = document.getElementById("dock-canvas-settings");
    if (!el) return;
    this.syncSettingsChecks();
    el.classList.remove("hidden");
    el.setAttribute("aria-hidden", "false");
    if (typeof revealOverlay === "function") revealOverlay(el);
    document.getElementById("btn-dock-canvas-settings")?.setAttribute("aria-expanded", "true");
    document.getElementById("btn-dock-canvas-settings")?.classList.add("is-active");
  },

  closeSettings() {
    const el = document.getElementById("dock-canvas-settings");
    if (!el) return;
    if (typeof dismissOverlay === "function") dismissOverlay(el);
    el.classList.add("hidden");
    el.setAttribute("aria-hidden", "true");
    document.getElementById("btn-dock-canvas-settings")?.setAttribute("aria-expanded", "false");
    document.getElementById("btn-dock-canvas-settings")?.classList.remove("is-active");
  },
};
window.ChromeDock = ChromeDock;

const NodeHistory = {
  nodeId: null,
  selectedId: null,
  dockFilter: "success",

  open(nodeId, entryId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeSupportsHistory(node)) {
      showCanvasToast("当前节点没有生成历史");
      return;
    }
    FrameCapture.closeMenus();
    this.nodeId = nodeId;
    const list = Array.isArray(node.genHistory) ? node.genHistory : [];
    this.selectedId = entryId || node.activeHistoryId || list[0]?.id || null;
    const selected = list.find((h) => h.id === this.selectedId);
    this.dockFilter = selected?.status === "failed" ? "failed" : selected?.status === "generating" ? "generating" : "success";
    this.render();
    const drawer = document.getElementById("node-history-drawer");
    revealOverlay(drawer);
    drawer?.setAttribute("aria-hidden", "false");
  },

  close() {
    const drawer = document.getElementById("node-history-drawer");
    dismissOverlay(drawer);
    drawer?.setAttribute("aria-hidden", "true");
    this.nodeId = null;
    this.selectedId = null;
  },

  getNode() {
    return CanvasStore.activeBoard().nodes.find((n) => n.id === this.nodeId);
  },

  nodeRecords() {
    const node = this.getNode();
    if (!node) return [];
    const list = Array.isArray(node.genHistory) ? node.genHistory.slice() : [];
    if (["waiting", "pending", "generating"].includes(node.status) && (node.type === "image" || node.type === "video")) {
      list.unshift({
        id: `gen:${node.id}`,
        status: "generating",
        kind: node.type === "image" ? "image" : "video",
        typeLabel: node.type === "image" ? "图片生成" : "视频生成",
        prompt: node.prompt || "",
        model: node.model,
        ratio: node.ratio,
        duration: node.duration,
        createdAt: node.genStartedAt || Date.now(),
        taskId: node.taskId,
        videoUrl: null,
        imageUrl: null,
        coverUrl: null,
        references: node._lastRefs || null,
      });
    }
    return list;
  },

  filteredList() {
    return this.nodeRecords().filter((h) => h.status === this.dockFilter);
  },

  getSelected() {
    const all = this.nodeRecords();
    return all.find((h) => h.id === this.selectedId) || this.filteredList()[0] || all[0] || null;
  },

  select(entryId) {
    this.selectedId = entryId;
    const entry = this.nodeRecords().find((h) => h.id === entryId);
    if (entry) {
      this.dockFilter =
        entry.status === "failed" ? "failed" : entry.status === "generating" ? "generating" : "success";
    }
    this.render();
  },

  locate() {
    const nodeId = this.nodeId;
    this.close();
    if (nodeId) focusNodeOnCanvas(nodeId);
  },

  adopt() {
    const node = this.getNode();
    const entry = this.getSelected();
    if (!node || !entry) {
      showCanvasToast("没有可采纳的记录");
      return;
    }
    if (entry.status === "generating" || String(entry.id || "").startsWith("gen:")) {
      showCanvasToast("生成中的记录无法采纳");
      return;
    }
    const hasMedia = !!(entry.videoUrl || entry.imageUrl || entry.audioUrl);
    if (!hasMedia && !String(entry.prompt || "").trim()) {
      showCanvasToast("该记录没有可采纳的提示词");
      return;
    }
    CanvasHistory.push();
    const patch = {
      prompt: entry.prompt || node.prompt,
      ratio: entry.ratio || node.ratio,
      model: entry.model || node.model,
      duration: entry.duration ?? node.duration,
      style: entry.style ?? node.style,
    };
    if (hasMedia) {
      patch.videoUrl = entry.videoUrl || null;
      patch.imageUrl = entry.imageUrl || null;
      patch.audioUrl = entry.audioUrl || node.audioUrl || null;
      patch.coverUrl = entry.coverUrl || null;
      patch.thumbUrl = entry.thumbUrl || null;
      patch.mediaWidth = entry.mediaWidth || null;
      patch.mediaHeight = entry.mediaHeight || null;
      patch.status = "completed";
      patch.error = null;
      patch.taskId = entry.taskId || node.taskId;
      patch.activeHistoryId = entry.id;
      // Gen history never carries bake-in mark; drop flags so UI/API stay in sync.
      const nextImg = String(entry.imageUrl || "").trim();
      const curImg = String(node.imageUrl || "").trim();
      if (nextImg && nextImg !== curImg) {
        patch.aiMarked = false;
        patch.aiMarkBaseUrl = null;
      }
    }
    CanvasStore.updateNode(node.id, patch);
    this.close();
    renderNodes();
    scheduleRenderConnections(true);
    selectSingle(node.id);
    showCanvasToast(hasMedia ? "已采纳到节点" : "已采用该条提示词");
  },

  renderStageDock() {
    const records = this.nodeRecords();
    const ok = records.filter((r) => r.status === "success").length;
    const fail = records.filter((r) => r.status === "failed").length;
    const gen = records.filter((r) => r.status === "generating").length;
    const okEl = document.getElementById("nh-count-ok");
    const genEl = document.getElementById("nh-count-gen");
    const failEl = document.getElementById("nh-count-fail");
    if (okEl) okEl.textContent = String(ok);
    if (genEl) genEl.textContent = String(gen);
    if (failEl) failEl.textContent = String(fail);

    document.querySelectorAll("#history-stage-dock [data-nh-filter]").forEach((btn) => {
      btn.classList.toggle("active", btn.dataset.nhFilter === this.dockFilter);
    });

    const thumbs = document.getElementById("history-stage-thumbs");
    if (!thumbs) return;
    const filtered = this.filteredList().slice(0, 24);
    const entry = this.getSelected();
    if (!filtered.length) {
      thumbs.innerHTML = `<div class="history-dock-empty">暂无${this.dockFilter === "failed" ? "失败" : this.dockFilter === "generating" ? "进行中" : "完成"}记录</div>`;
      return;
    }
    thumbs.innerHTML = filtered
      .map((h) => {
        const src = resolveMediaUrl(h.coverUrl || h.imageUrl || "");
        const active = h.id === (entry?.id || this.selectedId);
        let media = `<span class="history-thumb-fallback">${h.status === "failed" ? "!" : h.status === "generating" ? "…" : "●"}</span>`;
        if (h.status === "success") {
          if (src) media = `<img data-src="${escapeAttr(src)}" alt="" decoding="async" class="media-thumb-lazy" />`;
          else if (h.videoUrl) media = `<video data-src="${escapeAttr(resolveMediaUrl(h.videoUrl))}" muted preload="none" class="media-thumb-lazy-vid" data-thumb-seek="1"></video>`;
          else if (h.audioUrl) media = `<span class="history-thumb-fallback">♪</span>`;
        }
        return `<button type="button" class="history-dock-thumb status-${escapeAttr(h.status)}${active ? " is-active" : ""}" data-history-id="${h.id}" title="${escapeAttr(formatHistoryTime(h.createdAt))}">
          ${media}
          <span class="history-dock-thumb-time">${escapeHtml(formatHistoryTime(h.createdAt))}</span>
        </button>`;
      })
      .join("");
    observePanelMediaLazy(thumbs);
    hydrateMediaThumbs(thumbs);
  },

  render() {
    const records = this.nodeRecords();
    const entry = records.length ? this.getSelected() : null;
    if (entry) this.selectedId = entry.id;
    const detail = document.getElementById("history-detail");
    const stage = document.getElementById("history-stage");
    const title = document.getElementById("history-drawer-title");
    const shellTitle = document.getElementById("history-shell-title");
    const adoptBtn = document.getElementById("btn-history-adopt");
    const shell = document.querySelector("#node-history-drawer .history-drawer-shell");
    const blank = !records.length;
    shell?.classList.toggle("is-blank", blank);
    if (shellTitle) shellTitle.textContent = "节点生成历史";
    if (title) title.textContent = "参数详情";

    if (stage) {
      if (blank) {
        stage.innerHTML = `<div class="history-blank">
          <p class="history-blank-title">此节点暂无历史生成记录</p>
          <p class="history-blank-sub">完成生成后，历史记录将在此处显示</p>
        </div>`;
      } else if (!entry) {
        stage.innerHTML = `<div class="history-stage-empty">选择记录查看预览</div>`;
      } else if (entry.status === "failed") {
        const fullErr = String(entry.error || "请稍后重试").trim();
        const shortErr =
          typeof formatNodeErrorDisplay === "function"
            ? formatNodeErrorDisplay(fullErr, "请稍后重试")
            : "请稍后重试";
        stage.innerHTML = `<div class="history-stage-fail" title="${escapeAttr(fullErr)}"><span>生成失败</span><small>${escapeHtml(shortErr)}</small></div>`;
      } else if (entry.status === "generating") {
        stage.innerHTML = `<div class="history-stage-empty">生成中…</div>`;
      } else if (entry.videoUrl) {
        stage.innerHTML = `<div class="history-stage-media">
          <video controls playsinline preload="metadata"></video>
        </div>`;
        void hydrateHistoryStageVideo(stage.querySelector("video"), entry.videoUrl);
      } else if (entry.audioUrl) {
        stage.innerHTML = `<div class="history-stage-media">
          <audio src="${escapeAttr(resolveMediaUrl(entry.audioUrl))}" controls preload="metadata"></audio>
        </div>`;
      } else if (entry.imageUrl || entry.coverUrl) {
        stage.innerHTML = `<div class="history-stage-media">
          <img src="${escapeAttr(resolveMediaUrl(entry.coverUrl || entry.imageUrl))}" alt="" />
        </div>`;
      } else {
        stage.innerHTML = `<div class="history-stage-empty">暂无预览</div>`;
      }
    }

    if (!blank) this.renderStageDock();

    if (detail) {
      if (blank) {
        detail.innerHTML = "";
      } else if (!entry) {
        detail.innerHTML = `<p class="history-empty">选择一条记录查看参数</p>`;
      } else {
        const modelLabel =
          entry.kind === "video" || entry.videoUrl
            ? getVideoModelLabel(entry.model)
            : entry.kind === "audio" || entry.audioUrl
              ? "音频"
              : getImageModelLabel(entry.model);
        const refs = Array.isArray(entry.references) ? entry.references : [];
        const refsHtml = refs.length
          ? `<div class="history-refs">${refs
              .map((r) => {
                const u = resolveMediaUrl(r.url || "");
                if (r.kind === "video") {
                  return `<div class="history-ref-item"><span class="history-ref-badge">VIDEO</span>${
                    u ? `<video src="${escapeAttr(u)}" muted preload="metadata"></video>` : `<span class="history-ref-chip">🎬</span>`
                  }</div>`;
                }
                if (r.kind === "audio") {
                  return `<div class="history-ref-item history-ref-audio"><span class="history-ref-badge">AUDIO</span><span class="history-ref-chip">♪</span></div>`;
                }
                return `<div class="history-ref-item">${
                  u ? `<img class="history-ref-img" src="${escapeAttr(u)}" alt="" />` : `<span class="history-ref-chip">🖼</span>`
                }</div>`;
              })
              .join("")}</div>`
          : `<span class="history-muted">无</span>`;
        const statusLabel = entry.status === "failed" ? "失败" : entry.status === "generating" ? "生成中" : "成功";
        const statusClass = entry.status === "failed" ? "is-fail" : entry.status === "success" ? "is-ok" : "";
        const resText =
          entry.resolution ||
          (entry.mediaWidth && entry.mediaHeight ? `${entry.mediaWidth}×${entry.mediaHeight}` : null);
        const method = historyMethodLabel(entry);
        detail.innerHTML = `
          <div class="history-kv"><span>工作编号</span><strong class="history-mono history-work-id">${escapeHtml(entry.taskId || "—")}</strong>${
            entry.taskId
              ? `<span class="history-work-actions"><button type="button" class="history-work-btn" data-action="copy-gen-id" data-task-id="${escapeAttr(entry.taskId)}" title="复制编号">复制</button>${
                  isCanvasAdmin()
                    ? `<button type="button" class="history-work-btn" data-action="view-gen-raw" data-task-id="${escapeAttr(entry.taskId)}" title="查看原始返回">原文</button>`
                    : ""
                }</span>`
              : ""
          }</div>
          <div class="history-kv"><span>状态</span><strong class="${statusClass}">${escapeHtml(statusLabel)}</strong></div>
          <div class="history-kv"><span>模型</span><strong>${escapeHtml(modelLabel || "—")}</strong></div>
          <div class="history-kv"><span>方式</span><strong>${escapeHtml(method)}</strong></div>
          <div class="history-kv"><span>比例</span><strong>${escapeHtml(entry.ratio || "自动")}</strong></div>
          ${resText ? `<div class="history-kv"><span>分辨率</span><strong>${escapeHtml(resText)}</strong></div>` : ""}
          ${
            entry.duration != null
              ? `<div class="history-kv"><span>时长</span><strong>${escapeHtml(String(entry.duration))}秒</strong></div>`
              : ""
          }
          <div class="history-kv"><span>时间</span><strong>${escapeHtml(formatHistoryTime(entry.createdAt))}</strong></div>
          <div class="history-kv"><span>类型</span><strong>${escapeHtml(entry.typeLabel || (entry.kind === "video" ? "视频生成" : entry.kind === "audio" ? "音频" : "图片生成"))}</strong></div>
          ${
            entry.status === "failed" && entry.error
              ? `<div class="history-block"><div class="history-block-label">错误信息</div><pre class="history-prompt history-error">${escapeHtml(entry.error)}</pre></div>`
              : ""
          }
          <div class="history-block">
            <div class="history-block-label">参考素材${refs.length ? ` (${refs.length})` : ""}</div>
            ${refsHtml}
          </div>
          <div class="history-block">
            <div class="history-block-label history-block-label-row">
              <span>提示词</span>
              ${
                String(entry.prompt || "").trim()
                  ? `<button type="button" class="history-work-btn" data-action="copy-history-prompt" title="复制提示词">复制</button>`
                  : ""
              }
            </div>
            <pre class="history-prompt">${escapeHtml(entry.prompt || "（空）")}</pre>
          </div>`;
      }
    }
    if (adoptBtn) {
      adoptBtn.disabled =
        blank ||
        !entry ||
        entry.status === "generating" ||
        String(entry.id || "").startsWith("gen:") ||
        !(
          entry.prompt ||
          entry.videoUrl ||
          entry.imageUrl ||
          entry.audioUrl ||
          entry.textContent != null
        );
    }
  },
};
window.NodeHistory = NodeHistory;

function initNodeHistoryDrawer() {
  HistoryDock.bind();
  HistoryDock.refresh();
  if (typeof ChromeDock !== "undefined") ChromeDock.init();
  document.getElementById("history-drawer-close")?.addEventListener("click", () => NodeHistory.close());
  document.getElementById("history-drawer-backdrop")?.addEventListener("click", () => NodeHistory.close());
  document.getElementById("btn-history-adopt")?.addEventListener("click", () => NodeHistory.adopt());
  document.getElementById("history-detail")?.addEventListener("click", (e) => {
    const copyPromptBtn = e.target.closest("[data-action='copy-history-prompt']");
    if (copyPromptBtn) {
      e.preventDefault();
      e.stopPropagation();
      const text = String(NodeHistory.getSelected?.()?.prompt || "");
      if (!text.trim()) {
        if (typeof showCanvasToast === "function") showCanvasToast("没有可复制的提示词");
        return;
      }
      void (async () => {
        const ok =
          typeof copyTextToSystemClipboard === "function"
            ? await copyTextToSystemClipboard(text)
            : false;
        if (typeof showCanvasToast === "function") showCanvasToast(ok ? "已复制提示词" : "复制失败");
      })();
      return;
    }
    const genBtn = e.target.closest("[data-action='copy-gen-id'], [data-action='view-gen-raw']");
    if (genBtn) {
      e.preventDefault();
      e.stopPropagation();
      const taskId = genBtn.dataset.taskId || "";
      if (genBtn.dataset.action === "copy-gen-id") void copyGenWorkId(taskId);
      else void openGenRecordDetail(taskId);
    }
  });
  document.getElementById("history-stage-dock")?.addEventListener("click", (e) => {
    const stat = e.target.closest("[data-nh-filter]");
    if (stat) {
      NodeHistory.dockFilter = stat.dataset.nhFilter;
      const list = NodeHistory.filteredList();
      if (list.length && !list.some((h) => h.id === NodeHistory.selectedId)) {
        NodeHistory.selectedId = list[0].id;
      }
      NodeHistory.render();
      return;
    }
    const btn = e.target.closest("[data-history-id]");
    if (btn) NodeHistory.select(btn.dataset.historyId);
  });
  window.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    if (!document.getElementById("node-history-drawer")?.classList.contains("hidden")) {
      NodeHistory.close();
    }
  });
}

const VideoLightbox = {
  nodeIds: [],
  index: 0,
  _nodesById: new Map(),
  _bound: false,
  _scrubbing: false,
  _scrubMoved: false,
  _loadSeq: 0,
  _loadAttempt: 0,
  _loadReady: false,
  _loadWatchdog: 0,
  _loadCleanup: null,
  _normalizeTried: false,
  _activeStableUrl: "",
  _activeResumeTime: 0,
  _mediaHold: false,
  _retainedReleaseTimer: 0,
  frameStep: 1 / 24,

  isOpen() {
    return !document.getElementById("video-lightbox")?.classList.contains("hidden");
  },

  open(nodeId) {
    const nodes = getBoardVideoNodes();
    if (!nodes.length) return;
    releaseCanvasInteractionState();
    this.setNodes(nodes, nodeId);
    this.bindOnce();
    this.show();
  },

  setNodes(nodes, selectedId) {
    const list = Array.isArray(nodes) ? nodes.filter((node) => node?.id) : [];
    this.nodeIds = list.map((node) => node.id);
    this._nodesById = new Map(list.map((node) => [node.id, node]));
    const idx = this.nodeIds.indexOf(selectedId);
    this.index = idx >= 0 ? idx : 0;
  },

  show() {
    const node = this.currentNode();
    if (!nodeHasCapturableVideo(node)) return;
    // Do NOT force-load the canvas/workbench preview here — that raced the lightbox
    // download after refresh and left the modal on black 00:00/00:00.
    const previewVideo = peekNodePreviewVideoEl(node.id);
    const resumeTime =
      previewVideo && previewVideo.readyState >= 1 ? previewVideo.currentTime || 0 : 0;
    const box = document.getElementById("video-lightbox");
    const video = document.getElementById("vl-video");
    const dl = document.getElementById("vl-download");
    if (!box || !video) return;

    revealOverlay(box);
    box.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";
    if (!this._mediaHold) {
      yieldMediaBandwidthForLightbox(node.id);
      this._mediaHold = true;
    }

    const seq = this.beginLoadCycle();
    this.applyShellAspect(node);
    this.setLoading(true);
    let url = resolveMediaUrl(node.videoUrl);
    // Prefer a URL the preview (or warmer) already buffered — same path, warm HTTP cache.
    const previewSrc = videoSrcKey(previewVideo);
    if (previewSrc && previewVideo.readyState >= 1) {
      const previewPath = uploadMediaPath(previewSrc) || previewSrc;
      const nodePath = uploadMediaPath(url) || url;
      if (previewPath === nodePath || previewSrc === url) url = previewSrc;
    } else if (_vlUrlWarmer?.dataset?.warmUrl && _vlUrlWarmer.readyState >= 1) {
      const warmUrl = _vlUrlWarmer.dataset.warmUrl;
      const warmPath = uploadMediaPath(warmUrl) || warmUrl;
      const nodePath = uploadMediaPath(url) || url;
      if (warmPath === nodePath) url = warmUrl;
    }
    const path = uploadMediaPath(url);
    const needsNormalize = path && needsVideoNormalizePath(url);
    const poster = nodeVideoPosterUrl(node);
    if (poster) video.setAttribute("poster", poster);
    else video.removeAttribute("poster");

    this._activeStableUrl = url;
    this._activeResumeTime = resumeTime;
    if (dl) {
      dl.href = url;
      dl.download = `video-${node.id}.mp4`;
    }
    this.updateUI();
    this.renderThumbs();
    this.syncPlayUi();
    this.syncTimeUi();
    syncAllNodeVideoPlayback();

    if (needsNormalize) {
      // Wait for playable URL before first paint — avoids black screen on non-mp4 paths.
      void (async () => {
        const normalized = await ensureBrowserPlayableVideoUrl(url, {
          force: needsVideoNormalizePath(url),
        });
        if (!this.isOpen() || seq !== this._loadSeq || this.currentNode()?.id !== node.id) return;
        this._normalizeTried = true;
        const afterPath = uploadMediaPath(normalized);
        if (path && afterPath && afterPath !== path) {
          upgradeNodeVideoUrl(node.id, path, afterPath);
          this._activeStableUrl = normalized;
          if (dl) dl.href = normalized;
        } else {
          this._activeStableUrl = normalized || url;
        }
        this.mountVideo(this._activeStableUrl, resumeTime, seq);
      })();
      return;
    }

    this.mountVideo(url, resumeTime, seq);
  },

  beginLoadCycle() {
    clearTimeout(this._retainedReleaseTimer);
    this._retainedReleaseTimer = 0;
    this._loadSeq += 1;
    this.clearLoadHooks();
    this._loadAttempt = 0;
    this._loadReady = false;
    this._normalizeTried = false;
    this._activeStableUrl = "";
    this._activeResumeTime = 0;
    return this._loadSeq;
  },

  applyShellAspect(node, videoEl) {
    const shell = document.getElementById("vl-video-shell");
    if (!shell) return;
    let ar = 16 / 9;
    const vw = Number(videoEl?.videoWidth) || 0;
    const vh = Number(videoEl?.videoHeight) || 0;
    const mw = Number(node?.mediaWidth) || 0;
    const mh = Number(node?.mediaHeight) || 0;
    if (vw > 0 && vh > 0) ar = vw / vh;
    else if (mw > 0 && mh > 0) ar = mw / mh;
    else {
      const ratio = String(node?.ratio || "").trim();
      const m = ratio.match(/^(\d+(?:\.\d+)?)\s*[:/]\s*(\d+(?:\.\d+)?)$/);
      if (m) {
        const a = Number(m[1]);
        const b = Number(m[2]);
        if (a > 0 && b > 0) ar = a / b;
      }
    }
    shell.style.setProperty("--vl-aspect", String(ar));
  },

  setLoading(on) {
    const shell = document.getElementById("vl-video-shell");
    const loading = document.getElementById("vl-loading");
    shell?.classList.toggle("is-loading", !!on);
    if (loading) loading.hidden = !on;
    if (on) document.getElementById("vl-play-big")?.classList.add("hidden");
  },

  clearLoadHooks() {
    if (this._loadWatchdog) clearTimeout(this._loadWatchdog);
    this._loadWatchdog = 0;
    if (typeof this._loadCleanup === "function") this._loadCleanup();
    this._loadCleanup = null;
  },

  cacheBustedUrl(url) {
    try {
      const out = new URL(url, window.location.origin);
      out.searchParams.set("_vl_retry", `${Date.now()}-${this._loadAttempt}`);
      return out.href;
    } catch {
      const join = String(url).includes("?") ? "&" : "?";
      return `${url}${join}_vl_retry=${Date.now()}-${this._loadAttempt}`;
    }
  },

  mountVideo(playUrl, resumeAt = 0, seq = this._loadSeq) {
    const video = this.video();
    if (!video || !this.isOpen() || seq !== this._loadSeq) return;
    this.clearLoadHooks();
    this._loadAttempt += 1;
    const attempt = this._loadAttempt;
    // Preserve HTTP range/cache reuse on the first retry. Only bypass a
    // repeatedly failing local asset; remote signed URLs must stay intact.
    const mountedUrl = attempt >= 3 && uploadMediaPath(playUrl) ? this.cacheBustedUrl(playUrl) : playUrl;
    const reuse = attempt === 1 && lightboxVideoMatchesUrl(video, mountedUrl);
    let settled = false;

    try {
      video.pause();
    } catch {
      /* ignore pause failures */
    }
    video.preload = "auto";

    const cleanup = () => {
      ["loadedmetadata", "loadeddata", "canplay"].forEach((type) => video.removeEventListener(type, onReady));
      video.removeEventListener("error", onFailure);
      video.removeEventListener("progress", onProgress);
      if (this._loadWatchdog) clearTimeout(this._loadWatchdog);
      this._loadWatchdog = 0;
      if (this._loadCleanup === cleanup) this._loadCleanup = null;
    };
    const isCurrent = () => this.isOpen() && seq === this._loadSeq && attempt === this._loadAttempt;
    const onReady = () => {
      if (settled || !isCurrent() || video.readyState < 1) return;
      settled = true;
      cleanup();
      this._loadReady = true;
      this.applyShellAspect(this.currentNode(), video);
      this.setLoading(false);
      this.syncMeta();
      this.syncPlayUi();
      this.syncTimeUi();
      void this.playOnShow(resumeAt, seq);
    };
    const onFailure = () => {
      if (settled || !isCurrent()) return;
      settled = true;
      const unsupported = Number(video.error?.code || 0) === 4;
      cleanup();
      void this.retryVideoLoad(seq, resumeAt, unsupported);
    };

    const startedAt = Date.now();
    const idleTimeout = attempt === 1 ? 12000 : 18000;
    const armWatchdog = () => {
      clearTimeout(this._loadWatchdog);
      // Keep slow but progressing transfers alive, with a bounded total wait.
      const remaining = Math.max(0, 60000 - (Date.now() - startedAt));
      this._loadWatchdog = setTimeout(onFailure, Math.min(idleTimeout, remaining));
    };
    const onProgress = () => {
      if (!settled && isCurrent()) armWatchdog();
    };

    this._loadCleanup = cleanup;
    ["loadedmetadata", "loadeddata", "canplay"].forEach((type) => video.addEventListener(type, onReady));
    video.addEventListener("error", onFailure);
    video.addEventListener("progress", onProgress);
    // Assign/load once. Resetting to an empty src first queues an abort event
    // that can be mistaken for a failure of the replacement request.
    if (!reuse) {
      video.src = mountedUrl;
      video.load();
    }
    armWatchdog();
    if (video.readyState >= 1) queueMicrotask(onReady);
  },

  async retryVideoLoad(seq, resumeAt = 0, normalizeFirst = false) {
    if (!this.isOpen() || seq !== this._loadSeq || this._loadReady) return;
    const node = this.currentNode();
    if (!node) return;
    const latestResume = this.video()?.currentTime || resumeAt || this._activeResumeTime || 0;
    if ((normalizeFirst || this._loadAttempt >= 2) && !this._normalizeTried) {
      await this.normalizeAndRetry(
        seq,
        node,
        this._activeStableUrl,
        uploadMediaPath(this._activeStableUrl),
        latestResume
      );
      return;
    }
    if (this._loadAttempt >= 4) {
      showCanvasToast("视频加载失败，请关闭预览后重试");
      this.setLoading(false);
      return;
    }
    setTimeout(() => {
      if (!this.isOpen() || seq !== this._loadSeq || this._loadReady) return;
      this.mountVideo(this._activeStableUrl, latestResume, seq);
    }, 300);
  },

  async normalizeAndRetry(seq, node, url, beforePath, resumeAt = 0, onlyIfChanged = false) {
    if (!url || this._normalizeTried || seq !== this._loadSeq) return;
    this._normalizeTried = true;
    const normalized = await ensureBrowserPlayableVideoUrl(url, {
      force: needsVideoNormalizePath(url),
    });
    if (!this.isOpen() || seq !== this._loadSeq || this.currentNode()?.id !== node?.id) return;
    const afterPath = uploadMediaPath(normalized);
    if (beforePath && afterPath && afterPath !== beforePath) {
      upgradeNodeVideoUrl(node.id, beforePath, afterPath);
      this._activeStableUrl = normalized;
      const dl = document.getElementById("vl-download");
      if (dl) dl.href = normalized;
    }
    if (this._loadReady) return;
    const changed = videoSrcKey(this.video()) !== normalized;
    if (onlyIfChanged && !changed) return;
    this.mountVideo(normalized || this._activeStableUrl, resumeAt, seq);
  },

  async playOnShow(resumeTime = 0, seq = this._loadSeq) {
    const video = this.video();
    if (!video || video.readyState < 1 || !this.isOpen() || seq !== this._loadSeq) return;
    if (resumeTime > 0 || video.currentTime > 0) {
      try {
        await seekVideoElement(video, resumeTime);
      } catch {
        /* ignore */
      }
    }
    if (!this.isOpen() || seq !== this._loadSeq) return;
    try {
      await video.play();
    } catch {
      try {
        video.muted = true;
        await video.play();
      } catch {
        /* autoplay may require a click */
      }
    }
    this.syncPlayUi();
    this.syncTimeUi();
  },

  close() {
    const box = document.getElementById("video-lightbox");
    const video = document.getElementById("vl-video");
    this._loadSeq += 1;
    this.clearLoadHooks();
    if (video) {
      video.pause();
      video.removeAttribute("poster");
      if (video.readyState < 1 || video.error) {
        video.removeAttribute("src");
        video.load();
      } else {
        video.preload = "metadata";
      }
    }
    dismissOverlay(box);
    box?.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
    this.nodeIds = [];
    this._nodesById = new Map();
    this.index = 0;
    this._activeStableUrl = "";
    this._loadReady = false;
    this.setLoading(false);
    this.retainVideoBriefly();
    if (this._mediaHold) {
      releaseMediaBandwidthAfterLightbox();
      this._mediaHold = false;
    }
    syncAllNodeVideoPlayback();
  },

  retainVideoBriefly() {
    clearTimeout(this._retainedReleaseTimer);
    // At most one player, for 30 seconds. Preserve quick reopen without keeping
    // large video buffers or background downloads alive for the whole session.
    this._retainedReleaseTimer = setTimeout(() => {
      this._retainedReleaseTimer = 0;
      if (this.isOpen()) return;
      const video = this.video();
      if (!video) return;
      video.pause();
      video.removeAttribute("src");
      delete video.dataset.warmUrl;
      video.load();
    }, 30000);
  },

  bindOnce() {
    if (this._bound) return;
    this._bound = true;
    const video = document.getElementById("vl-video");

    document.getElementById("vl-close")?.addEventListener("click", () => this.close());
    document.getElementById("vl-backdrop")?.addEventListener("click", () => this.close());
    document.getElementById("vl-prev")?.addEventListener("click", () => this.prev());
    document.getElementById("vl-next")?.addEventListener("click", () => this.next());
    document.getElementById("vl-side-prev")?.addEventListener("click", () => this.prev());
    document.getElementById("vl-side-next")?.addEventListener("click", () => this.next());
    document.getElementById("vl-locate")?.addEventListener("click", () => this.locateNode());
    document.getElementById("vl-capture")?.addEventListener("click", () => this.captureCurrentFrame());
    document.getElementById("vl-capture-chrome")?.addEventListener("click", () => this.captureCurrentFrame());
    document.getElementById("vl-toggle")?.addEventListener("click", () => this.togglePlay());
    document.getElementById("vl-play-big")?.addEventListener("click", () => this.togglePlay());
    document.getElementById("vl-frame-prev")?.addEventListener("click", () => this.nudge(-this.frameStep));
    document.getElementById("vl-frame-next")?.addEventListener("click", () => this.nudge(this.frameStep));
    const scrubBar = document.getElementById("vl-scrub");
    let vlScrubbing = false;
    const scrubFromPointer = (e) => {
      e.preventDefault();
      this._scrubMoved = true;
      this.scrubFromEvent(e);
    };
    const endScrub = (e) => {
      if (!vlScrubbing) return;
      vlScrubbing = false;
      this._scrubbing = false;
      if (scrubBar && e?.pointerId != null) {
        try {
          scrubBar.releasePointerCapture?.(e.pointerId);
        } catch {
          /* ignore */
        }
      }
      window.removeEventListener("pointermove", scrubFromPointer);
      window.removeEventListener("pointerup", endScrub);
      window.removeEventListener("pointercancel", endScrub);
    };
    scrubBar?.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      e.stopPropagation();
      vlScrubbing = true;
      this._scrubbing = true;
      this._scrubMoved = false;
      try {
        video?.pause();
      } catch {
        /* ignore */
      }
      scrubBar.setPointerCapture?.(e.pointerId);
      scrubFromPointer(e);
      window.addEventListener("pointermove", scrubFromPointer);
      window.addEventListener("pointerup", endScrub);
      window.addEventListener("pointercancel", endScrub);
    });
    document.getElementById("vl-thumbs")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-vl-idx]");
      if (!btn) return;
      this.index = Number(btn.dataset.vlIdx);
      this.show();
    });
    bindThumbStripWheel(document.getElementById("vl-thumbs"));
    video?.addEventListener("click", (e) => {
      if (this._scrubMoved) {
        this._scrubMoved = false;
        e.preventDefault();
        e.stopPropagation();
        return;
      }
      this.togglePlay();
    });
    video?.addEventListener("play", () => this.syncPlayUi());
    video?.addEventListener("pause", () => this.syncPlayUi());
    video?.addEventListener("timeupdate", () => {
      if (!this._scrubbing) this.syncTimeUi();
    });
    video?.addEventListener("seeked", () => this.syncTimeUi());

    window.addEventListener("keydown", (e) => {
      if (!this.isOpen()) return;
      if (e.key === "Escape") {
        e.preventDefault();
        this.close();
      } else if (e.key === "ArrowLeft" && !e.shiftKey) {
        e.preventDefault();
        this.prev();
      } else if (e.key === "ArrowRight" && !e.shiftKey) {
        e.preventDefault();
        this.next();
      } else if (e.key === " " || e.key === "Spacebar") {
        e.preventDefault();
        this.togglePlay();
      }
    });
  },

  currentNode() {
    const id = this.nodeIds[this.index];
    return this._nodesById.get(id) || CanvasStore.activeBoard().nodes.find((n) => n.id === id);
  },

  prev() {
    if (this.index <= 0) return;
    this.index--;
    this.show();
  },

  next() {
    if (this.index >= this.nodeIds.length - 1) return;
    this.index++;
    this.show();
  },

  locateNode() {
    const nodeId = this.nodeIds[this.index];
    const existsOnCanvas = CanvasStore.activeBoard().nodes.some((node) => node.id === nodeId);
    if (!existsOnCanvas) return;
    this.close();
    focusNodeOnCanvas(nodeId);
  },

  captureCurrentFrame() {
    const node = this.currentNode();
    if (!node?.id) {
      showCanvasToast("当前没有可截取的视频");
      return;
    }
    const v = this.video();
    try {
      v?.pause();
    } catch {
      /* ignore */
    }
    this.syncPlayUi();
    if (typeof FrameCapture?.run === "function") {
      FrameCapture.run(node.id, "current");
    } else {
      showCanvasToast("截帧功能不可用");
    }
  },

  video() {
    return document.getElementById("vl-video");
  },

  duration() {
    const v = this.video();
    return v && Number.isFinite(v.duration) ? v.duration : 0;
  },

  togglePlay() {
    const v = this.video();
    if (!v) return;
    if (v.paused || v.ended) v.play().catch(() => {});
    else v.pause();
    this.syncPlayUi();
  },

  async nudge(delta) {
    const v = this.video();
    if (!v) return;
    try {
      v.pause();
    } catch {
      /* ignore */
    }
    try {
      await seekVideoElement(v, (v.currentTime || 0) + delta);
    } catch {
      /* ignore */
    }
    this.syncTimeUi();
    this.syncPlayUi();
  },

  scrubFromEvent(e) {
    const bar = document.getElementById("vl-scrub");
    const v = this.video();
    if (!bar || !v) return;
    const rect = bar.getBoundingClientRect();
    if (!rect.width) return;
    const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    const dur = this.duration();
    if (!(dur > 0)) return;
    scrubVideoTime(v, ratio * dur);
    this.syncTimeUi();
  },

  syncMeta() {
    const node = this.currentNode();
    const v = this.video();
    const w = v?.videoWidth || node?.mediaWidth || 0;
    const h = v?.videoHeight || node?.mediaHeight || 0;
    const res = w && h ? `${w}×${h}` : "—";
    const el = document.getElementById("vl-meta");
    if (el) el.textContent = res;
  },

  syncPlayUi() {
    const v = this.video();
    const playing = Boolean(v && !v.paused && !v.ended);
    const loading = !this._loadReady;
    document.getElementById("vl-play-big")?.classList.toggle("hidden", playing || loading);
    const toggle = document.getElementById("vl-toggle");
    if (toggle) toggle.innerHTML = playing ? '<svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><rect x="3" y="3" width="3.5" height="10" rx="0.8"/><rect x="9.5" y="3" width="3.5" height="10" rx="0.8"/></svg>' : '<svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M5 3.2v9.6l8-4.8z"/></svg>';
  },

  syncTimeUi() {
    const v = this.video();
    const t = v?.currentTime || 0;
    const d = this.duration();
    const fill = document.getElementById("vl-scrub-fill");
    const time = document.getElementById("vl-time");
    if (fill) fill.style.width = `${d > 0 ? (t / d) * 100 : 0}%`;
    if (time) {
      const fmt = (s) => {
        const m = Math.floor(s / 60);
        const sec = Math.floor(s % 60);
        return `${String(m).padStart(2, "0")}:${String(sec).padStart(2, "0")}`;
      };
      time.textContent = `${fmt(t)} / ${fmt(d)}`;
    }
  },

  updateUI() {
    const total = this.nodeIds.length;
    const current = this.index + 1;
    const counter = document.getElementById("vl-counter");
    if (counter) counter.textContent = `相邻节点 ${current} / ${total}`;
    const atStart = this.index <= 0;
    const atEnd = this.index >= total - 1;
    ["vl-prev", "vl-side-prev"].forEach((id) => {
      const el = document.getElementById(id);
      if (el) el.disabled = atStart;
    });
    ["vl-next", "vl-side-next"].forEach((id) => {
      const el = document.getElementById(id);
      if (el) el.disabled = atEnd;
    });
    const showNav = total > 1;
    document.getElementById("vl-side-prev")?.style &&
      (document.getElementById("vl-side-prev").style.visibility = showNav ? "visible" : "hidden");
    document.getElementById("vl-side-next")?.style &&
      (document.getElementById("vl-side-next").style.visibility = showNav ? "visible" : "hidden");
    const locate = document.getElementById("vl-locate");
    if (locate) {
      const currentId = this.nodeIds[this.index];
      locate.classList.toggle("hidden", !CanvasStore.activeBoard().nodes.some((node) => node.id === currentId));
    }
  },

  renderThumbs() {
    const wrap = document.getElementById("vl-thumbs");
    if (!wrap) return;
    if (this.nodeIds.length <= 1) {
      wrap.innerHTML = "";
      return;
    }
    wrap.innerHTML = this.nodeIds
      .map((id, i) => {
        const node = this._nodesById.get(id) || CanvasStore.activeBoard().nodes.find((n) => n.id === id);
        const thumb = resolveVideoLightboxThumb(node);
        const name = escapeHtml(getNodeDisplayName(node, CanvasStore.activeBoard()) || "视频");
        const media = thumb
          ? `<img src="${escapeAttr(thumb)}" alt="" loading="lazy" decoding="async" />`
          : `<div class="vl-thumb-fallback"><span class="vl-thumb-icon">${nodeTypeIconSvg("video")}</span><span class="vl-thumb-label">${name.slice(0, 6)}</span></div>`;
        return `<button type="button" class="vl-thumb ${i === this.index ? "active" : ""}" data-vl-idx="${i}" title="${escapeAttr(name)}">${media}</button>`;
      })
      .join("");
    wrap.querySelectorAll("img").forEach((img) => {
      img.addEventListener(
        "error",
        () => {
          const btn = img.closest(".vl-thumb");
          if (!btn || btn.querySelector(".vl-thumb-fallback")) return;
          const id = this.nodeIds[Number(btn.dataset.vlIdx)];
          const node = this._nodesById.get(id) || CanvasStore.activeBoard().nodes.find((n) => n.id === id);
          const name = escapeHtml(getNodeDisplayName(node, CanvasStore.activeBoard()) || "视频");
          img.replaceWith(
            Object.assign(document.createElement("div"), {
              className: "vl-thumb-fallback",
              innerHTML: `<span class="vl-thumb-icon">${nodeTypeIconSvg("video")}</span><span class="vl-thumb-label">${name.slice(0, 6)}</span>`,
            })
          );
        },
        { once: true }
      );
    });
    const active = wrap.querySelector(".vl-thumb.active");
    active?.scrollIntoView({ block: "nearest", inline: "center", behavior: "smooth" });
  },
};
window.VideoLightbox = VideoLightbox;

function getBoardVideoNodes() {
  return CanvasStore.activeBoard()
    .nodes.filter((n) => nodeHasCapturableVideo(n))
    .slice()
    .sort((a, b) => a.x - b.x || a.y - b.y);
}

function resolveVideoLightboxThumb(node) {
  if (!node) return "";
  const poster = nodeVideoPosterUrl(node);
  if (poster) return poster;
  const pending = _pendingImportPreviews.get(node.id);
  if (pending?.url) return pending.url;
  return captureNodeVideoThumb(node.id) || "";
}

function captureNodeVideoThumb(nodeId) {
  const video = nodePreviewVideoEl(nodeId);
  if (!video || video.readyState < 2 || !video.videoWidth || !video.videoHeight) return "";
  try {
    const canvas = document.createElement("canvas");
    const scale = 96 / Math.max(video.videoWidth, 1);
    canvas.width = Math.max(1, Math.round(video.videoWidth * scale));
    canvas.height = Math.max(1, Math.round(video.videoHeight * scale));
    const ctx = canvas.getContext("2d");
    if (!ctx) return "";
    ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
    const data = canvas.toDataURL("image/jpeg", 0.6);
    return data && data.length > 1200 ? data : "";
  } catch {
    return "";
  }
}

function initVideoToolDialogs() {
  VideoTrimStudio.bind();
  VideoCompressModal.bind();
  VideoUpscaleModal.bind();
  VideoGifStudio.bind();
  VideoCropStudio.bind();
  ImageCropStudio.bind();
  ImageGridSplitStudio.bind();
  ImagePaintStudio.bind();
}

/** Lightbox / history / trim-crop studios / prompt clipboard — canvas + workbench. */
function initSharedOverlayUi() {
  if (window.__sharedOverlayUiBound) return;
  window.__sharedOverlayUiBound = true;
  if (typeof mountFloatingUiToBody === "function") mountFloatingUiToBody();
  initImageLightbox();
  initPromptClipboard();
  initVideoToolDialogs();
  initNodeHistoryDrawer();
}
window.initSharedOverlayUi = initSharedOverlayUi;

const CROP_RATIO_MAP = {
  "1:1": [1, 1],
  "16:9": [16, 9],
  "9:16": [9, 16],
  "4:3": [4, 3],
  "3:4": [3, 4],
};

const VideoCropStudio = {
  nodeId: null,
  ratio: "1:1",
  // crop box in video pixel coords
  x: 0,
  y: 0,
  w: 0,
  h: 0,
  vw: 0,
  vh: 0,
  _bound: false,
  _drag: null,

  isOpen() {
    return !document.getElementById("video-crop-studio")?.classList.contains("hidden");
  },

  open(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasCapturableVideo(node)) {
      showCanvasToast("当前节点没有可处理的视频");
      return;
    }
    this.bind();
    FrameCapture.closeMenus();
    this.nodeId = nodeId;
    this.ratio = "1:1";
    const studio = document.getElementById("video-crop-studio");
    const video = document.getElementById("vcrop-video");
    revealOverlay(studio);
    studio?.setAttribute("aria-hidden", "false");
    document.querySelectorAll("#vcrop-ratio-grid .vcrop-ratio-btn").forEach((b) => {
      b.classList.toggle("active", b.dataset.ratio === this.ratio);
    });
    if (video) {
      video.pause();
      video.src = resolveMediaUrl(node.videoUrl);
      video.load();
      const onMeta = () => {
        this.vw = video.videoWidth || node.mediaWidth || 0;
        this.vh = video.videoHeight || node.mediaHeight || 0;
        this.resetCropToRatio();
        this.syncUi();
        video.removeEventListener("loadedmetadata", onMeta);
      };
      video.addEventListener("loadedmetadata", onMeta);
      if (video.readyState >= 1) onMeta();
    }
    requestAnimationFrame(() => this.layoutBox());
  },

  close() {
    const studio = document.getElementById("video-crop-studio");
    const video = document.getElementById("vcrop-video");
    video?.pause();
    if (video) video.removeAttribute("src");
    dismissOverlay(studio);
    studio?.setAttribute("aria-hidden", "true");
    this.nodeId = null;
    this._drag = null;
  },

  resetCropToRatio() {
    const vw = this.vw;
    const vh = this.vh;
    if (!(vw > 0 && vh > 0)) return;
    if (this.ratio === "origin" || this.ratio === "free") {
      this.x = 0;
      this.y = 0;
      this.w = vw;
      this.h = vh;
      return;
    }
    const [rw, rh] = CROP_RATIO_MAP[this.ratio] || [1, 1];
    const target = rw / rh;
    const src = vw / vh;
    if (src > target) {
      this.h = vh;
      this.w = Math.max(2, Math.round((vh * rw) / rh));
      this.x = Math.max(0, Math.round((vw - this.w) / 2));
      this.y = 0;
    } else {
      this.w = vw;
      this.h = Math.max(2, Math.round((vw * rh) / rw));
      this.x = 0;
      this.y = Math.max(0, Math.round((vh - this.h) / 2));
    }
  },

  setRatio(ratio) {
    this.ratio = ratio;
    document.querySelectorAll("#vcrop-ratio-grid .vcrop-ratio-btn").forEach((b) => {
      b.classList.toggle("active", b.dataset.ratio === ratio);
    });
    this.resetCropToRatio();
    this.layoutBox();
    this.syncMeta();
  },

  clampCrop() {
    const vw = this.vw;
    const vh = this.vh;
    this.w = Math.max(2, Math.min(this.w, vw));
    this.h = Math.max(2, Math.min(this.h, vh));
    if (this.ratio !== "origin" && this.ratio !== "free" && CROP_RATIO_MAP[this.ratio]) {
      const [rw, rh] = CROP_RATIO_MAP[this.ratio];
      const target = rw / rh;
      // keep ratio: prefer adjusting height from width
      let w = this.w;
      let h = Math.round(w / target);
      if (h > vh) {
        h = vh;
        w = Math.round(h * target);
      }
      if (w > vw) {
        w = vw;
        h = Math.round(w / target);
      }
      this.w = Math.max(2, w);
      this.h = Math.max(2, h);
    }
    this.x = Math.max(0, Math.min(this.x, vw - this.w));
    this.y = Math.max(0, Math.min(this.y, vh - this.h));
  },

  getVideoDisplayRect() {
    const stage = document.getElementById("vcrop-stage");
    const video = document.getElementById("vcrop-video");
    if (!stage || !video || !(this.vw > 0 && this.vh > 0)) return null;
    const sr = stage.getBoundingClientRect();
    const scale = Math.min(sr.width / this.vw, sr.height / this.vh);
    const dw = this.vw * scale;
    const dh = this.vh * scale;
    const left = (sr.width - dw) / 2;
    const top = (sr.height - dh) / 2;
    return { left, top, dw, dh, scale, sr };
  },

  layoutBox() {
    const box = document.getElementById("vcrop-box");
    const disp = this.getVideoDisplayRect();
    if (!box || !disp) return;
    const { left, top, scale } = disp;
    const bx = left + this.x * scale;
    const by = top + this.y * scale;
    const bw = this.w * scale;
    const bh = this.h * scale;
    box.style.left = `${bx}px`;
    box.style.top = `${by}px`;
    box.style.width = `${bw}px`;
    box.style.height = `${bh}px`;
  },

  syncMeta() {
    const srcEl = document.getElementById("vcrop-src");
    const regionEl = document.getElementById("vcrop-region");
    const ratioEl = document.getElementById("vcrop-out-ratio");
    if (srcEl) srcEl.textContent = this.vw && this.vh ? `${this.vw}×${this.vh}` : "—";
    if (regionEl) {
      regionEl.textContent =
        this.w && this.h ? `${Math.round(this.w)}×${Math.round(this.h)} @${Math.round(this.x)},${Math.round(this.y)}` : "—";
    }
    if (ratioEl) {
      ratioEl.textContent =
        this.ratio === "origin" ? "原比例" : this.ratio === "free" ? "自由" : this.ratio;
    }
    const note = document.getElementById("vcrop-note");
    if (note) {
      note.textContent =
        this.ratio === "free"
          ? "拖动裁剪框移动位置；拖角可自由缩放（不锁定比例）。"
          : "拖动裁剪框移动位置；拖角可缩放（锁定比例）。";
    }
  },

  syncUi() {
    const video = document.getElementById("vcrop-video");
    const timeEl = document.getElementById("vcrop-time");
    const seek = document.getElementById("vcrop-seek");
    const dur = video?.duration || 0;
    const cur = video?.currentTime || 0;
    if (timeEl) timeEl.textContent = `${formatFcTime(cur)} / ${formatFcTime(dur)}`;
    if (seek && dur > 0) seek.value = String(Math.round((cur / dur) * 1000));
    this.layoutBox();
    this.syncMeta();
  },

  confirm() {
    const nodeId = this.nodeId;
    if (!nodeId) return;
    this.clampCrop();
    const crop_x = Math.max(0, Math.round(this.x));
    const crop_y = Math.max(0, Math.round(this.y));
    const crop_w = Math.max(2, Math.round(this.w / 2) * 2);
    const crop_h = Math.max(2, Math.round(this.h / 2) * 2);
    this.close();
    MediaTools.run(nodeId, "crop", {
      ratio: this.ratio === "origin" || this.ratio === "free" ? "origin" : this.ratio,
      crop_x,
      crop_y,
      crop_w,
      crop_h,
    });
  },

  bind() {
    if (this._bound) return;
    this._bound = true;
    const video = document.getElementById("vcrop-video");
    document.getElementById("vcrop-close")?.addEventListener("click", () => this.close());
    document.getElementById("vcrop-cancel")?.addEventListener("click", () => this.close());
    document.getElementById("vcrop-backdrop")?.addEventListener("click", () => this.close());
    document.getElementById("vcrop-confirm")?.addEventListener("click", () => this.confirm());
    document.getElementById("vcrop-ratio-grid")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-ratio]");
      if (btn) this.setRatio(btn.dataset.ratio);
    });
    document.getElementById("vcrop-play")?.addEventListener("click", () => {
      if (!video) return;
      if (video.paused) video.play().catch(() => {});
      else video.pause();
    });
    document.getElementById("vcrop-seek")?.addEventListener("input", (e) => {
      if (!video || !(video.duration > 0)) return;
      const t = (Number(e.target.value) / 1000) * video.duration;
      scrubVideoTime(video, t);
    });
    video?.addEventListener("timeupdate", () => {
      if (!this.isOpen()) return;
      this.syncUi();
    });
    video?.addEventListener("play", () => {
      const b = document.getElementById("vcrop-play");
      if (b) b.innerHTML = '<svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><rect x="3" y="3" width="3.5" height="10" rx="0.8"/><rect x="9.5" y="3" width="3.5" height="10" rx="0.8"/></svg>';
    });
    video?.addEventListener("pause", () => {
      const b = document.getElementById("vcrop-play");
      if (b) b.innerHTML = '<svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M5 3.2v9.6l8-4.8z"/></svg>';
    });
    window.addEventListener("resize", () => {
      if (this.isOpen()) this.layoutBox();
    });

    const box = document.getElementById("vcrop-box");
    box?.addEventListener("pointerdown", (e) => {
      if (!this.isOpen()) return;
      const corner = e.target.closest("[data-corner]")?.dataset.corner;
      const disp = this.getVideoDisplayRect();
      if (!disp) return;
      e.preventDefault();
      e.currentTarget.setPointerCapture?.(e.pointerId);
      this._drag = {
        mode: corner || "move",
        startX: e.clientX,
        startY: e.clientY,
        ox: this.x,
        oy: this.y,
        ow: this.w,
        oh: this.h,
        scale: disp.scale,
      };
    });
    window.addEventListener("pointermove", (e) => {
      if (!this._drag || !this.isOpen()) return;
      const dx = (e.clientX - this._drag.startX) / this._drag.scale;
      const dy = (e.clientY - this._drag.startY) / this._drag.scale;
      const mode = this._drag.mode;
      if (mode === "move") {
        this.x = this._drag.ox + dx;
        this.y = this._drag.oy + dy;
      } else {
        let x = this._drag.ox;
        let y = this._drag.oy;
        let w = this._drag.ow;
        let h = this._drag.oh;
        if (mode.includes("e")) w = this._drag.ow + dx;
        if (mode.includes("s")) h = this._drag.oh + dy;
        if (mode.includes("w")) {
          x = this._drag.ox + dx;
          w = this._drag.ow - dx;
        }
        if (mode.includes("n")) {
          y = this._drag.oy + dy;
          h = this._drag.oh - dy;
        }
        if (this.ratio !== "origin" && this.ratio !== "free" && CROP_RATIO_MAP[this.ratio]) {
          const [rw, rh] = CROP_RATIO_MAP[this.ratio];
          const target = rw / rh;
          if (Math.abs(dx) >= Math.abs(dy)) {
            h = w / target;
            if (mode.includes("n")) y = this._drag.oy + this._drag.oh - h;
          } else {
            w = h * target;
            if (mode.includes("w")) x = this._drag.ox + this._drag.ow - w;
          }
        }
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
      }
      this.clampCrop();
      this.layoutBox();
      this.syncMeta();
    });
    window.addEventListener("pointerup", () => {
      this._drag = null;
    });
    window.addEventListener("keydown", (e) => {
      if (!this.isOpen()) return;
      if (isTextInputTarget(e.target)) return;
      if (e.key === "Escape") {
        e.preventDefault();
        this.close();
      } else if (e.key === "Enter") {
        e.preventDefault();
        this.confirm();
      } else if (e.key === " ") {
        e.preventDefault();
        if (video?.paused) video.play().catch(() => {});
        else video?.pause();
      }
    });
  },
};
window.VideoCropStudio = VideoCropStudio;

const ImageCropStudio = {
  nodeId: null,
  ratio: "free",
  x: 0,
  y: 0,
  w: 0,
  h: 0,
  iw: 0,
  ih: 0,
  // pending transforms applied before crop on confirm
  rot: 0,
  flipH: false,
  flipV: false,
  _bound: false,
  _drag: null,
  _srcUrl: "",

  isOpen() {
    return !document.getElementById("image-crop-studio")?.classList.contains("hidden");
  },

  open(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasImage(node)) {
      showCanvasToast("当前节点没有可处理的图片");
      return;
    }
    this.bind();
    FrameCapture.closeMenus();
    this.nodeId = nodeId;
    this.ratio = "free";
    this.rot = 0;
    this.flipH = false;
    this.flipV = false;
    this._srcUrl = resolveMediaUrl(node.imageUrl);
    const studio = document.getElementById("image-crop-studio");
    const img = document.getElementById("icrop-image");
    revealOverlay(studio);
    studio?.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";
    document.querySelectorAll("#icrop-ratio-grid .icrop-ratio-btn").forEach((b) => {
      b.classList.toggle("active", b.dataset.ratio === this.ratio);
    });
    if (img) {
      img.style.transform = "";
      img.onload = () => {
        this.iw = img.naturalWidth || node.mediaWidth || 0;
        this.ih = img.naturalHeight || node.mediaHeight || 0;
        this.resetCropToRatio();
        this.layoutBox();
        this.syncMeta();
      };
      img.src = this._srcUrl;
      if (img.complete && img.naturalWidth) img.onload();
    }
    requestAnimationFrame(() => this.layoutBox());
  },

  close() {
    const studio = document.getElementById("image-crop-studio");
    const img = document.getElementById("icrop-image");
    if (img) {
      img.onload = null;
      img.removeAttribute("src");
      img.style.transform = "";
      img.style.width = "";
      img.style.height = "";
    }
    dismissOverlay(studio);
    studio?.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
    this.nodeId = null;
    this._drag = null;
  },

  logicalSize() {
    return { w: this.iw, h: this.ih };
  },

  resetCropToRatio() {
    const { w: vw, h: vh } = this.logicalSize();
    if (!(vw > 0 && vh > 0)) return;
    if (this.ratio === "origin" || this.ratio === "free") {
      this.x = 0;
      this.y = 0;
      this.w = vw;
      this.h = vh;
      return;
    }
    const [rw, rh] = CROP_RATIO_MAP[this.ratio] || [1, 1];
    const target = rw / rh;
    const src = vw / vh;
    if (src > target) {
      this.h = vh;
      this.w = Math.max(2, Math.round((vh * rw) / rh));
      this.x = Math.max(0, Math.round((vw - this.w) / 2));
      this.y = 0;
    } else {
      this.w = vw;
      this.h = Math.max(2, Math.round((vw * rh) / rw));
      this.x = 0;
      this.y = Math.max(0, Math.round((vh - this.h) / 2));
    }
  },

  setRatio(ratio) {
    this.ratio = ratio;
    document.querySelectorAll("#icrop-ratio-grid .icrop-ratio-btn").forEach((b) => {
      b.classList.toggle("active", b.dataset.ratio === ratio);
    });
    this.resetCropToRatio();
    this.layoutBox();
    this.syncMeta();
  },

  clampCrop() {
    const { w: vw, h: vh } = this.logicalSize();
    this.w = Math.max(2, Math.min(this.w, vw));
    this.h = Math.max(2, Math.min(this.h, vh));
    if (this.ratio !== "origin" && this.ratio !== "free" && CROP_RATIO_MAP[this.ratio]) {
      const [rw, rh] = CROP_RATIO_MAP[this.ratio];
      const target = rw / rh;
      let w = this.w;
      let h = Math.round(w / target);
      if (h > vh) {
        h = vh;
        w = Math.round(h * target);
      }
      if (w > vw) {
        w = vw;
        h = Math.round(w / target);
      }
      this.w = Math.max(2, w);
      this.h = Math.max(2, h);
    }
    this.x = Math.max(0, Math.min(this.x, vw - this.w));
    this.y = Math.max(0, Math.min(this.y, vh - this.h));
  },

  getImageDisplayRect() {
    const stage = document.getElementById("icrop-stage");
    const { w: vw, h: vh } = this.logicalSize();
    if (!stage || !(vw > 0 && vh > 0)) return null;
    const sr = stage.getBoundingClientRect();
    const scale = Math.min(sr.width / vw, sr.height / vh) * 0.92;
    const dw = vw * scale;
    const dh = vh * scale;
    const left = (sr.width - dw) / 2;
    const top = (sr.height - dh) / 2;
    return { left, top, dw, dh, scale, sr };
  },

  layoutBox() {
    const box = document.getElementById("icrop-box");
    const img = document.getElementById("icrop-image");
    const disp = this.getImageDisplayRect();
    if (!box || !disp || !img) return;
    const { left, top, dw, dh, scale } = disp;
    img.style.position = "absolute";
    img.style.left = `${left}px`;
    img.style.top = `${top}px`;
    img.style.width = `${dw}px`;
    img.style.height = `${dh}px`;
    img.style.maxWidth = "none";
    img.style.maxHeight = "none";
    img.style.objectFit = "fill";
    box.style.left = `${left + this.x * scale}px`;
    box.style.top = `${top + this.y * scale}px`;
    box.style.width = `${this.w * scale}px`;
    box.style.height = `${this.h * scale}px`;
  },

  syncMeta() {
    const { w: vw, h: vh } = this.logicalSize();
    const srcEl = document.getElementById("icrop-src");
    const regionEl = document.getElementById("icrop-region");
    const ratioEl = document.getElementById("icrop-out-ratio");
    if (srcEl) srcEl.textContent = vw && vh ? `${vw}×${vh}` : "—";
    if (regionEl) {
      regionEl.textContent =
        this.w && this.h
          ? `${Math.round(this.w)}×${Math.round(this.h)} @${Math.round(this.x)},${Math.round(this.y)}`
          : "—";
    }
    if (ratioEl) {
      ratioEl.textContent =
        this.ratio === "origin" ? "原图" : this.ratio === "free" ? "自由" : this.ratio;
    }
  },

  async confirm() {
    const nodeId = this.nodeId;
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeId || !node?.imageUrl) return;
    this.clampCrop();
    const crop_x = Math.max(0, Math.round(this.x));
    const crop_y = Math.max(0, Math.round(this.y));
    const crop_w = Math.max(1, Math.round(this.w));
    const crop_h = Math.max(1, Math.round(this.h));
    const ratioSaved = this.ratio;
    const ratioLabel =
      ratioSaved === "origin" ? "原图" : ratioSaved === "free" ? "自由裁剪" : `裁剪 ${ratioSaved}`;
    this.close();

    if (MediaTools.busy || FrameCapture.busy) return;
    MediaTools.busy = true;
    FrameCapture.closeMenus();
    let outId = null;
    try {
      CanvasHistory.push();
      outId = await createDerivedMediaNode(
        node,
        { kind: "image", width: crop_w, height: crop_h, op: "image_crop" },
        ratioLabel,
        { pending: true, skipHistory: true }
      );

      const blob = await bakeImageTransform(resolveMediaUrl(node.imageUrl), {
        crop_x,
        crop_y,
        crop_w,
        crop_h,
      });
      const fd = new FormData();
      fd.append("file", blob, `crop-${Date.now()}.png`);
      fd.append("width", String(crop_w));
      fd.append("height", String(crop_h));
      if (CanvasStore.activeBoardId) fd.append("board_id", CanvasStore.activeBoardId);
      const up = await fetch("/api/upload", { method: "POST", body: fd });
      if (!up.ok) throw new Error("上传裁剪结果失败");
      const uploaded = await up.json();

      CanvasStore.updateNode(outId, {
        status: "completed",
        imageUrl: uploaded.url,
        mediaWidth: uploaded.width || crop_w,
        mediaHeight: uploaded.height || crop_h,
        customName: ratioLabel,
        ratio: ratioSaved === "free" || ratioSaved === "origin" ? node.ratio || null : ratioSaved,
        ...mediaThumbPatchFromUpload(uploaded, "image"),
      });
      await CanvasStore.flushSave();
      renderNodes();
      scheduleRenderConnections(true);
      showCanvasToast(`${ratioLabel}完成`);
      if (outId) selectSingle(outId);
    } catch (err) {
      if (outId) {
        CanvasStore.updateNode(outId, { status: "failed", error: err.message || "裁剪失败" });
        await CanvasStore.flushSave();
        renderNodes();
      }
      showCanvasToast(err.message || "裁剪失败");
    } finally {
      MediaTools.busy = false;
    }
  },

  bind() {
    if (this._bound) return;
    this._bound = true;
    document.getElementById("icrop-close")?.addEventListener("click", () => this.close());
    document.getElementById("icrop-cancel")?.addEventListener("click", () => this.close());
    document.getElementById("icrop-backdrop")?.addEventListener("click", () => this.close());
    document.getElementById("icrop-confirm")?.addEventListener("click", () => this.confirm());
    document.getElementById("icrop-ratio-grid")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-ratio]");
      if (btn) this.setRatio(btn.dataset.ratio);
    });
    window.addEventListener("resize", () => {
      if (this.isOpen()) this.layoutBox();
    });

    const box = document.getElementById("icrop-box");
    box?.addEventListener("pointerdown", (e) => {
      if (!this.isOpen()) return;
      const corner = e.target.closest("[data-corner]")?.dataset.corner;
      const edge = e.target.closest("[data-edge]")?.dataset.edge;
      const mode = corner || edge || "move";
      const disp = this.getImageDisplayRect();
      if (!disp) return;
      e.preventDefault();
      e.currentTarget.setPointerCapture?.(e.pointerId);
      this._drag = {
        mode,
        startX: e.clientX,
        startY: e.clientY,
        ox: this.x,
        oy: this.y,
        ow: this.w,
        oh: this.h,
        scale: disp.scale,
      };
    });
    window.addEventListener("pointermove", (e) => {
      if (!this._drag || !this.isOpen()) return;
      const dx = (e.clientX - this._drag.startX) / this._drag.scale;
      const dy = (e.clientY - this._drag.startY) / this._drag.scale;
      const mode = this._drag.mode;
      if (mode === "move") {
        this.x = this._drag.ox + dx;
        this.y = this._drag.oy + dy;
      } else {
        let x = this._drag.ox;
        let y = this._drag.oy;
        let w = this._drag.ow;
        let h = this._drag.oh;
        if (mode.includes("e")) w = this._drag.ow + dx;
        if (mode.includes("s")) h = this._drag.oh + dy;
        if (mode.includes("w")) {
          x = this._drag.ox + dx;
          w = this._drag.ow - dx;
        }
        if (mode.includes("n")) {
          y = this._drag.oy + dy;
          h = this._drag.oh - dy;
        }
        if (this.ratio !== "origin" && this.ratio !== "free" && CROP_RATIO_MAP[this.ratio]) {
          const [rw, rh] = CROP_RATIO_MAP[this.ratio];
          const target = rw / rh;
          if (Math.abs(dx) >= Math.abs(dy)) {
            h = w / target;
            if (mode.includes("n")) y = this._drag.oy + this._drag.oh - h;
          } else {
            w = h * target;
            if (mode.includes("w")) x = this._drag.ox + this._drag.ow - w;
          }
        }
        this.x = x;
        this.y = y;
        this.w = w;
        this.h = h;
      }
      this.clampCrop();
      this.layoutBox();
      this.syncMeta();
    });
    window.addEventListener("pointerup", () => {
      this._drag = null;
    });
    window.addEventListener("keydown", (e) => {
      if (!this.isOpen()) return;
      if (isTextInputTarget(e.target)) return;
      if (e.key === "Escape") {
        e.preventDefault();
        this.close();
      } else if (e.key === "Enter") {
        e.preventDefault();
        this.confirm();
      }
    });
  },
};
window.ImageCropStudio = ImageCropStudio;

const GRID_SPLIT_MIN_CELL = 24;
const GRID_SPLIT_MAX_LINES = 4;

function smoothProfile1d(profile, radius) {
  const out = new Float32Array(profile.length);
  const r = Math.max(1, radius | 0);
  for (let i = 0; i < profile.length; i++) {
    let sum = 0;
    let n = 0;
    for (let j = i - r; j <= i + r; j++) {
      if (j < 0 || j >= profile.length) continue;
      sum += profile[j];
      n += 1;
    }
    out[i] = n ? sum / n : profile[i];
  }
  return out;
}

function horizontalSeparatorProfile(lum, w, h) {
  const prof = new Float32Array(h);
  for (let y = 1; y < h; y++) {
    let sum = 0;
    for (let x = 0; x < w; x++) {
      sum += Math.abs(lum[y * w + x] - lum[(y - 1) * w + x]);
    }
    prof[y] = sum / w;
  }
  return prof;
}

function verticalSeparatorProfile(lum, w, h) {
  const prof = new Float32Array(w);
  for (let x = 1; x < w; x++) {
    let sum = 0;
    for (let y = 0; y < h; y++) {
      sum += Math.abs(lum[y * w + x] - lum[y * w + (x - 1)]);
    }
    prof[x] = sum / h;
  }
  return prof;
}

/** Find strongest separator near expected equal-split position. */
function refineSplitIndex(profile, approx, searchRadius) {
  const len = profile.length;
  let best = Math.max(1, Math.min(len - 2, approx));
  let bestScore = -1;
  const r = Math.max(1, searchRadius | 0);
  for (let i = approx - r; i <= approx + r; i++) {
    if (i < 1 || i >= len) continue;
    const score = (profile[i - 1] || 0) + (profile[i] || 0) + (profile[i + 1] || 0);
    if (score > bestScore) {
      bestScore = score;
      best = i;
    }
  }
  return best;
}

function scoreBandUniformity(lum, w, h, axis, index) {
  const band = 2;
  let sum = 0;
  let sum2 = 0;
  let n = 0;
  if (axis === "h") {
    const y0 = Math.max(0, index - band);
    const y1 = Math.min(h - 1, index + band);
    for (let y = y0; y <= y1; y++) {
      for (let x = 0; x < w; x++) {
        const v = lum[y * w + x];
        sum += v;
        sum2 += v * v;
        n += 1;
      }
    }
  } else {
    const x0 = Math.max(0, index - band);
    const x1 = Math.min(w - 1, index + band);
    for (let x = x0; x <= x1; x++) {
      for (let y = 0; y < h; y++) {
        const v = lum[y * w + x];
        sum += v;
        sum2 += v * v;
        n += 1;
      }
    }
  }
  if (!n) return 0;
  const mean = sum / n;
  const variance = sum2 / n - mean * mean;
  return 1 / (1 + variance / 500);
}

/**
 * Prefer regular equal splits (2×2, 3×3 …): score full-span gutter strength at
 * each candidate line, with a mild penalty for overly fine grids.
 */
function detectGridByEqualSplits(lum, w, h, iw, ih) {
  const hProf = smoothProfile1d(horizontalSeparatorProfile(lum, w, h), Math.max(2, Math.floor(h * 0.006)));
  const vProf = smoothProfile1d(verticalSeparatorProfile(lum, w, h), Math.max(2, Math.floor(w * 0.006)));
  const searchH = Math.max(3, Math.floor(h * 0.04));
  const searchW = Math.max(3, Math.floor(w * 0.04));

  let best = { rows: 1, cols: 1, score: 0, hIdx: [], vIdx: [] };

  for (let rows = 1; rows <= 5; rows++) {
    for (let cols = 1; cols <= 5; cols++) {
      if (rows === 1 && cols === 1) continue;
      const hIdx = [];
      const vIdx = [];
      let score = 0;
      let parts = 0;

      for (let r = 1; r < rows; r++) {
        const approx = Math.round((r * h) / rows);
        const y = refineSplitIndex(hProf, approx, searchH);
        const edge = hProf[y] || 0;
        const uniform = scoreBandUniformity(lum, w, h, "h", y);
        score += edge * (0.65 + uniform * 0.35);
        hIdx.push(y);
        parts += 1;
      }
      for (let c = 1; c < cols; c++) {
        const approx = Math.round((c * w) / cols);
        const x = refineSplitIndex(vProf, approx, searchW);
        const edge = vProf[x] || 0;
        const uniform = scoreBandUniformity(lum, w, h, "v", x);
        score += edge * (0.65 + uniform * 0.35);
        vIdx.push(x);
        parts += 1;
      }

      const avg = score / Math.max(1, parts);
      const cells = rows * cols;
      const complexityPenalty = 1 + Math.max(0, cells - 4) * 0.12;
      const finalScore = avg / complexityPenalty;
      if (finalScore > best.score) {
        best = { rows, cols, score: finalScore, hIdx, vIdx };
      }
    }
  }

  if (best.score <= 0 || (best.rows === 1 && best.cols === 1)) {
    return { hLines: [], vLines: [], rows: 1, cols: 1 };
  }

  const maxH = Math.max(...hProf, 0);
  const maxV = Math.max(...vProf, 0);
  const floor = Math.min(maxH, maxV) * 0.22;
  if (best.score < floor) {
    return { hLines: [], vLines: [], rows: 1, cols: 1 };
  }

  return {
    hLines: best.hIdx.map((y) => Math.round((y / h) * ih)),
    vLines: best.vIdx.map((x) => Math.round((x / w) * iw)),
    rows: best.rows,
    cols: best.cols,
  };
}

/** Auto-detect horizontal / vertical grid split lines (image pixel coords). */
function detectImageGridLines(img, iw, ih) {
  const maxDim = 720;
  const sc = Math.min(1, maxDim / Math.max(iw, ih));
  const w = Math.max(16, Math.round(iw * sc));
  const h = Math.max(16, Math.round(ih * sc));
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  if (!ctx) return { hLines: [], vLines: [] };
  ctx.drawImage(img, 0, 0, w, h);
  const { data } = ctx.getImageData(0, 0, w, h);
  const lum = new Float32Array(w * h);
  for (let i = 0; i < w * h; i++) {
    const p = i * 4;
    lum[i] = 0.299 * data[p] + 0.587 * data[p + 1] + 0.114 * data[p + 2];
  }
  return detectGridByEqualSplits(lum, w, h, iw, ih);
}

function clampGridLines(lines, max, minGap) {
  const sorted = [...lines].sort((a, b) => a - b);
  const out = [];
  let prev = 0;
  for (const pos of sorted) {
    const p = Math.max(minGap, Math.min(max - minGap, Math.round(pos)));
    if (p - prev < minGap || max - p < minGap) continue;
    if (out.length && p - out[out.length - 1] < minGap) continue;
    out.push(p);
    prev = p;
  }
  return out;
}

function getGridOutputPosition(sourceNode, row, col, cellW, cellH) {
  const aspect = cellW > 0 && cellH > 0 ? cellW / cellH : 16 / 9;
  const { width: previewW, height: previewH } = getReferencePreviewSizeFromAspect(aspect);
  const wrapW = previewW;
  const base = getAlignedDerivedPosition(sourceNode, cellW, cellH);
  const gapX = wrapW + 40;
  const gapY = previewH + 56 + 36;
  return {
    x: base.x + col * gapX,
    y: base.y + row * gapY,
  };
}

function cropImageRegion(srcUrl, x, y, w, h) {
  return bakeImageTransform(srcUrl, {
    crop_x: x,
    crop_y: y,
    crop_w: w,
    crop_h: h,
  });
}

const ImageGridSplitStudio = {
  nodeId: null,
  iw: 0,
  ih: 0,
  hLines: [],
  vLines: [],
  _bound: false,
  _drag: null,
  _srcUrl: "",

  isOpen() {
    return !document.getElementById("image-grid-studio")?.classList.contains("hidden");
  },

  open(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasImage(node)) {
      showCanvasToast("当前节点没有可处理的图片");
      return;
    }
    this.bind();
    FrameCapture.closeMenus();
    this.nodeId = nodeId;
    this.hLines = [];
    this.vLines = [];
    this._srcUrl = resolveMediaUrl(node.imageUrl);
    const studio = document.getElementById("image-grid-studio");
    const img = document.getElementById("igrid-image");
    revealOverlay(studio);
    studio?.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";
    if (img) {
      img.onload = () => {
        this.iw = img.naturalWidth || node.mediaWidth || 0;
        this.ih = img.naturalHeight || node.mediaHeight || 0;
        this.autoDetect(img);
        this.layout();
        this.syncMeta();
      };
      img.src = this._srcUrl;
      if (img.complete && img.naturalWidth) img.onload();
    }
    requestAnimationFrame(() => this.layout());
  },

  close() {
    const studio = document.getElementById("image-grid-studio");
    const img = document.getElementById("igrid-image");
    if (img) {
      img.onload = null;
      img.removeAttribute("src");
      img.style.width = "";
      img.style.height = "";
      img.style.left = "";
      img.style.top = "";
    }
    const overlay = document.getElementById("igrid-overlay");
    if (overlay) overlay.innerHTML = "";
    dismissOverlay(studio);
    studio?.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
    this.nodeId = null;
    this._drag = null;
  },

  getImageDisplayRect() {
    const stage = document.getElementById("igrid-stage");
    const iw = this.iw;
    const ih = this.ih;
    if (!stage || !(iw > 0 && ih > 0)) return null;
    const sr = stage.getBoundingClientRect();
    const scale = Math.min(sr.width / iw, sr.height / ih) * 0.92;
    const dw = iw * scale;
    const dh = ih * scale;
    const left = (sr.width - dw) / 2;
    const top = (sr.height - dh) / 2;
    return { left, top, dw, dh, scale, sr };
  },

  autoDetect(imgEl) {
    const img = imgEl || document.getElementById("igrid-image");
    if (!img?.naturalWidth) return;
    const { hLines, vLines, rows, cols } = detectImageGridLines(img, this.iw, this.ih);
    this.hLines = clampGridLines(hLines, this.ih, GRID_SPLIT_MIN_CELL);
    this.vLines = clampGridLines(vLines, this.iw, GRID_SPLIT_MIN_CELL);
    this.layout();
    this.syncMeta();
    if (rows > 1 || cols > 1) {
      showCanvasToast(`识别为 ${rows}×${cols} 宫格`);
    } else if (!this.hLines.length && !this.vLines.length) {
      showCanvasToast("未识别到明显宫格，请手动添加分割线");
    }
  },

  addLine(axis) {
    if (axis === "h") {
      if (this.hLines.length >= GRID_SPLIT_MAX_LINES) {
        showCanvasToast(`最多 ${GRID_SPLIT_MAX_LINES} 条横线`);
        return;
      }
      const gaps = [0, ...this.hLines, this.ih];
      let best = this.ih / 2;
      let bestSize = 0;
      for (let i = 0; i < gaps.length - 1; i++) {
        const size = gaps[i + 1] - gaps[i];
        if (size > bestSize) {
          bestSize = size;
          best = Math.round((gaps[i] + gaps[i + 1]) / 2);
        }
      }
      this.hLines = clampGridLines([...this.hLines, best], this.ih, GRID_SPLIT_MIN_CELL);
    } else {
      if (this.vLines.length >= GRID_SPLIT_MAX_LINES) {
        showCanvasToast(`最多 ${GRID_SPLIT_MAX_LINES} 条竖线`);
        return;
      }
      const gaps = [0, ...this.vLines, this.iw];
      let best = this.iw / 2;
      let bestSize = 0;
      for (let i = 0; i < gaps.length - 1; i++) {
        const size = gaps[i + 1] - gaps[i];
        if (size > bestSize) {
          bestSize = size;
          best = Math.round((gaps[i] + gaps[i + 1]) / 2);
        }
      }
      this.vLines = clampGridLines([...this.vLines, best], this.iw, GRID_SPLIT_MIN_CELL);
    }
    this.layout();
    this.syncMeta();
  },

  removeLine(axis, index) {
    if (axis === "h") this.hLines = this.hLines.filter((_, i) => i !== index);
    else this.vLines = this.vLines.filter((_, i) => i !== index);
    this.layout();
    this.syncMeta();
  },

  clearLines() {
    this.hLines = [];
    this.vLines = [];
    this.layout();
    this.syncMeta();
  },

  buildCells() {
    const xs = [0, ...this.vLines, this.iw];
    const ys = [0, ...this.hLines, this.ih];
    const cells = [];
    for (let r = 0; r < ys.length - 1; r++) {
      for (let c = 0; c < xs.length - 1; c++) {
        const x = xs[c];
        const y = ys[r];
        const w = xs[c + 1] - x;
        const h = ys[r + 1] - y;
        if (w < 2 || h < 2) continue;
        cells.push({ row: r, col: c, x, y, w, h });
      }
    }
    return cells;
  },

  layout() {
    const img = document.getElementById("igrid-image");
    const overlay = document.getElementById("igrid-overlay");
    const disp = this.getImageDisplayRect();
    if (!img || !overlay || !disp) return;
    const { left, top, dw, dh, scale } = disp;
    img.style.position = "absolute";
    img.style.left = `${left}px`;
    img.style.top = `${top}px`;
    img.style.width = `${dw}px`;
    img.style.height = `${dh}px`;
    overlay.style.left = `${left}px`;
    overlay.style.top = `${top}px`;
    overlay.style.width = `${dw}px`;
    overlay.style.height = `${dh}px`;
    overlay.innerHTML = "";
    this.hLines.forEach((y, idx) => {
      const el = document.createElement("div");
      el.className = "igrid-line igrid-line-h";
      el.style.top = `${y * scale}px`;
      el.dataset.axis = "h";
      el.dataset.index = String(idx);
      overlay.appendChild(el);
    });
    this.vLines.forEach((x, idx) => {
      const el = document.createElement("div");
      el.className = "igrid-line igrid-line-v";
      el.style.left = `${x * scale}px`;
      el.dataset.axis = "v";
      el.dataset.index = String(idx);
      overlay.appendChild(el);
    });
  },

  syncMeta() {
    const rows = this.hLines.length + 1;
    const cols = this.vLines.length + 1;
    const count = rows * cols;
    const srcEl = document.getElementById("igrid-src");
    const gridEl = document.getElementById("igrid-grid-size");
    const outEl = document.getElementById("igrid-out-count");
    const listEl = document.getElementById("igrid-line-list");
    if (srcEl) srcEl.textContent = this.iw && this.ih ? `${this.iw}×${this.ih}` : "—";
    if (gridEl) gridEl.textContent = `${rows}×${cols}`;
    if (outEl) outEl.textContent = String(count);
    if (listEl) {
      const items = [
        ...this.hLines.map((y, i) => ({ axis: "h", i, label: `横线 ${i + 1} · Y=${y}` })),
        ...this.vLines.map((x, i) => ({ axis: "v", i, label: `竖线 ${i + 1} · X=${x}` })),
      ];
      listEl.innerHTML = items.length
        ? items
            .map(
              (it) =>
                `<div class="igrid-line-item"><span>${escapeHtml(it.label)}</span><button type="button" data-rm-axis="${it.axis}" data-rm-index="${it.i}" title="删除"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button></div>`
            )
            .join("")
        : `<div class="igrid-line-item" style="color:#666">暂无分割线，可点自动识别或手动添加</div>`;
    }
  },

  async confirm() {
    const nodeId = this.nodeId;
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeId || !node?.imageUrl) return;
    const cells = this.buildCells();
    if (!cells.length) {
      showCanvasToast("没有可输出的宫格");
      return;
    }
    if (cells.length > 25) {
      showCanvasToast("宫格过多，请减少分割线");
      return;
    }
    this.close();
    if (MediaTools.busy || FrameCapture.busy) return;
    MediaTools.busy = true;
    FrameCapture.closeMenus();
    const outIds = [];
    try {
      CanvasHistory.push();
      for (let i = 0; i < cells.length; i++) {
        const cell = cells[i];
        const label = `宫格 ${cell.row + 1}-${cell.col + 1}`;
        const pos = getGridOutputPosition(node, cell.row, cell.col, cell.w, cell.h);
        const outId = await createDerivedMediaNode(
          node,
          { kind: "image", width: cell.w, height: cell.h, op: "image_grid_split" },
          label,
          { pending: true, skipHistory: true, position: pos, deferSave: true }
        );
        outIds.push(outId);
        const blob = await cropImageRegion(resolveMediaUrl(node.imageUrl), cell.x, cell.y, cell.w, cell.h);
        const fd = new FormData();
        fd.append("file", blob, `grid-${cell.row + 1}-${cell.col + 1}-${Date.now()}.png`);
        fd.append("width", String(cell.w));
        fd.append("height", String(cell.h));
        if (CanvasStore.activeBoardId) fd.append("board_id", CanvasStore.activeBoardId);
        const up = await fetch("/api/upload", { method: "POST", body: fd });
        if (!up.ok) throw new Error(`上传第 ${i + 1} 张失败`);
        const uploaded = await up.json();
        CanvasStore.updateNode(outId, {
          status: "completed",
          imageUrl: uploaded.url,
          mediaWidth: uploaded.width || cell.w,
          mediaHeight: uploaded.height || cell.h,
          customName: label,
          ...mediaThumbPatchFromUpload(uploaded, "image"),
        });
      }
      await CanvasStore.flushSave();
      renderNodes();
      scheduleRenderConnections(true);
      showCanvasToast(`已分割为 ${cells.length} 张图片`);
      if (outIds.length === 1) selectSingle(outIds[0]);
      else if (outIds.length) setSelection(outIds, outIds[0]);
    } catch (err) {
      for (const id of outIds) {
        CanvasStore.updateNode(id, { status: "failed", error: err.message || "分割失败" });
      }
      await CanvasStore.flushSave();
      renderNodes();
      showCanvasToast(err.message || "宫格分割失败");
    } finally {
      MediaTools.busy = false;
    }
  },

  bind() {
    if (this._bound) return;
    this._bound = true;
    document.getElementById("igrid-close")?.addEventListener("click", () => this.close());
    document.getElementById("igrid-cancel")?.addEventListener("click", () => this.close());
    document.getElementById("igrid-backdrop")?.addEventListener("click", () => this.close());
    document.getElementById("igrid-confirm")?.addEventListener("click", () => this.confirm());
    document.getElementById("igrid-auto")?.addEventListener("click", () => this.autoDetect());
    document.getElementById("igrid-add-h")?.addEventListener("click", () => this.addLine("h"));
    document.getElementById("igrid-add-v")?.addEventListener("click", () => this.addLine("v"));
    document.getElementById("igrid-clear")?.addEventListener("click", () => this.clearLines());
    document.getElementById("igrid-line-list")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-rm-axis]");
      if (!btn) return;
      this.removeLine(btn.dataset.rmAxis, Number(btn.dataset.rmIndex));
    });
    window.addEventListener("resize", () => {
      if (this.isOpen()) this.layout();
    });

    const overlay = document.getElementById("igrid-overlay");
    overlay?.addEventListener("pointerdown", (e) => {
      if (!this.isOpen()) return;
      const line = e.target.closest(".igrid-line");
      if (!line) return;
      const axis = line.dataset.axis;
      const index = Number(line.dataset.index);
      if (!axis || Number.isNaN(index)) return;
      const disp = this.getImageDisplayRect();
      if (!disp) return;
      e.preventDefault();
      line.classList.add("is-dragging");
      line.setPointerCapture?.(e.pointerId);
      this._drag = { axis, index, pointerId: e.pointerId, lineEl: line };
    });
    window.addEventListener("pointermove", (e) => {
      if (!this._drag || !this.isOpen()) return;
      const disp = this.getImageDisplayRect();
      const stage = document.getElementById("igrid-stage");
      if (!disp || !stage) return;
      const stageRect = stage.getBoundingClientRect();
      const px = e.clientX - stageRect.left - disp.left;
      const py = e.clientY - stageRect.top - disp.top;
      const idx = this._drag.index;
      if (this._drag.axis === "h") {
        const y = Math.round(py / disp.scale);
        const lo = idx > 0 ? this.hLines[idx - 1] + GRID_SPLIT_MIN_CELL : GRID_SPLIT_MIN_CELL;
        const hi =
          idx < this.hLines.length - 1
            ? this.hLines[idx + 1] - GRID_SPLIT_MIN_CELL
            : this.ih - GRID_SPLIT_MIN_CELL;
        this.hLines[idx] = Math.max(lo, Math.min(hi, y));
      } else {
        const x = Math.round(px / disp.scale);
        const lo = idx > 0 ? this.vLines[idx - 1] + GRID_SPLIT_MIN_CELL : GRID_SPLIT_MIN_CELL;
        const hi =
          idx < this.vLines.length - 1
            ? this.vLines[idx + 1] - GRID_SPLIT_MIN_CELL
            : this.iw - GRID_SPLIT_MIN_CELL;
        this.vLines[idx] = Math.max(lo, Math.min(hi, x));
      }
      this.layout();
      this.syncMeta();
      const refreshed = document.querySelector(
        `.igrid-line[data-axis="${this._drag.axis}"][data-index="${idx}"]`
      );
      if (refreshed) {
        refreshed.classList.add("is-dragging");
        try {
          refreshed.setPointerCapture?.(this._drag.pointerId);
        } catch {
          /* ignore */
        }
        this._drag.lineEl = refreshed;
      }
    });
    window.addEventListener("pointerup", () => {
      if (!this._drag) return;
      this._drag.lineEl?.classList?.remove("is-dragging");
      this._drag = null;
    });
    window.addEventListener("keydown", (e) => {
      if (!this.isOpen()) return;
      if (e.key === "Escape") {
        e.preventDefault();
        this.close();
        return;
      }
      if (isTextInputTarget(e.target)) return;
      if (e.key === "Enter") {
        e.preventDefault();
        this.confirm();
      }
    });
  },
};
window.ImageGridSplitStudio = ImageGridSplitStudio;

const ImagePaintStudio = {
  nodeId: null,
  tool: "brush",
  color: "#ff4444",
  size: 24,
  fontSize: 24,
  iw: 0,
  ih: 0,
  layers: [],
  history: [[]],
  _img: null,
  _canvas: null,
  _ctx: null,
  _preview: null,
  _pointer: null,
  _textPos: null,
  _textDraft: "",
  _bound: false,
  _srcUrl: "",

  isOpen() {
    return !document.getElementById("image-paint-studio")?.classList.contains("hidden");
  },

  open(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasImage(node)) {
      showCanvasToast("当前节点没有可处理的图片");
      return;
    }
    this.bind();
    FrameCapture.closeMenus();
    this.nodeId = nodeId;
    this.tool = "brush";
    this.color = "#ff4444";
    this.size = 24;
    this.fontSize = 24;
    this.layers = [];
    this.history = [[]];
    this._preview = null;
    this._pointer = null;
    this._textPos = null;
    this._textDraft = "";
    this._srcUrl = resolveMediaUrl(node.imageUrl);
    this._canvas = document.getElementById("ipaint-canvas");
    this._ctx = this._canvas?.getContext("2d");
    this.syncToolUi();
    this.syncColorUi();
    this.syncSizeUi();
    this.hideTextInput();
    const studio = document.getElementById("image-paint-studio");
    revealOverlay(studio);
    studio?.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      this._img = img;
      this.iw = img.naturalWidth || node.mediaWidth || 0;
      this.ih = img.naturalHeight || node.mediaHeight || 0;
      this.layoutCanvas();
      this.syncMeta();
    };
    img.onerror = () => showCanvasToast("图片加载失败");
    img.src = this._srcUrl;
  },

  close() {
    this.hideTextInput();
    const studio = document.getElementById("image-paint-studio");
    if (this._canvas && this._ctx) {
      this._ctx.clearRect(0, 0, this._canvas.width, this._canvas.height);
      this._canvas.width = 0;
      this._canvas.height = 0;
      this._canvas.style.width = "";
      this._canvas.style.height = "";
      this._canvas.style.left = "";
      this._canvas.style.top = "";
    }
    dismissOverlay(studio);
    studio?.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
    this.nodeId = null;
    this._img = null;
    this._preview = null;
    this._pointer = null;
    this.layers = [];
    this.history = [[]];
  },

  setTool(tool) {
    this.commitTextInput();
    this.tool = tool;
    this._preview = null;
    this._pointer = null;
    this.syncToolUi();
    this.redraw();
  },

  setColor(color) {
    const c = String(color || "").trim();
    if (!c) return;
    this.color = c;
    this.syncColorUi();
  },

  setSize(n) {
    this.size = Math.max(1, Math.min(48, Number(n) || 24));
    this.syncSizeUi();
  },

  setFontSize(n) {
    this.fontSize = Math.max(12, Math.min(96, Number(n) || 24));
    const el = document.getElementById("ipaint-font-size-val");
    const slider = document.getElementById("ipaint-font-size");
    if (slider) slider.value = String(this.fontSize);
    if (el) el.textContent = `${this.fontSize}px`;
  },

  syncToolUi() {
    document.querySelectorAll("#ipaint-tools .ipaint-tool-btn").forEach((btn) => {
      btn.classList.toggle("active", btn.dataset.tool === this.tool);
    });
    if (this._canvas) {
      this._canvas.style.cursor = this.tool === "text" ? "var(--cursor-text)" : "var(--cursor-crosshair)";
    }
  },

  syncColorUi() {
    document.querySelectorAll("#ipaint-colors .ipaint-color-swatch").forEach((btn) => {
      btn.classList.toggle("active", btn.dataset.color === this.color);
    });
    const picker = document.getElementById("ipaint-color-picker");
    if (picker && /^#[0-9a-f]{6}$/i.test(this.color)) picker.value = this.color;
  },

  syncSizeUi() {
    const slider = document.getElementById("ipaint-size");
    const el = document.getElementById("ipaint-size-val");
    if (slider) slider.value = String(this.size);
    if (el) el.textContent = `${this.size}px`;
  },

  syncMeta() {
    const srcEl = document.getElementById("ipaint-src");
    const countEl = document.getElementById("ipaint-layer-count");
    if (srcEl) srcEl.textContent = this.iw && this.ih ? `${this.iw}×${this.ih}` : "—";
    if (countEl) countEl.textContent = String(this.layers.length);
  },

  layoutCanvas() {
    const canvas = this._canvas;
    const stage = document.getElementById("ipaint-stage");
    if (!canvas || !stage || !this._ctx || !(this.iw > 0 && this.ih > 0)) return;
    const sr = stage.getBoundingClientRect();
    const scale = Math.min(sr.width / this.iw, sr.height / this.ih, 1) * 0.94;
    const dw = Math.max(1, Math.round(this.iw * scale));
    const dh = Math.max(1, Math.round(this.ih * scale));
    canvas.width = this.iw;
    canvas.height = this.ih;
    canvas.style.position = "absolute";
    canvas.style.left = `${(sr.width - dw) / 2}px`;
    canvas.style.top = `${(sr.height - dh) / 2}px`;
    canvas.style.width = `${dw}px`;
    canvas.style.height = `${dh}px`;
    this.redraw();
  },

  pointerToImage(clientX, clientY) {
    const canvas = this._canvas;
    if (!canvas) return null;
    const r = canvas.getBoundingClientRect();
    if (!(r.width > 0 && r.height > 0)) return null;
    const x = ((clientX - r.left) / r.width) * this.iw;
    const y = ((clientY - r.top) / r.height) * this.ih;
    return {
      x: Math.max(0, Math.min(this.iw, x)),
      y: Math.max(0, Math.min(this.ih, y)),
    };
  },

  pushHistory() {
    this.history.push(JSON.parse(JSON.stringify(this.layers)));
    if (this.history.length > 60) this.history.shift();
    this.syncMeta();
  },

  undo() {
    this.commitTextInput();
    if (this.history.length <= 1) {
      this.layers = [];
      this.history = [[]];
    } else {
      this.history.pop();
      this.layers = JSON.parse(JSON.stringify(this.history[this.history.length - 1] || []));
    }
    this._preview = null;
    this.redraw();
    this.syncMeta();
  },

  clearLayers() {
    this.commitTextInput();
    if (!this.layers.length) return;
    this.layers = [];
    this.pushHistory();
    this._preview = null;
    this.redraw();
  },

  hideTextInput() {
    const input = document.getElementById("ipaint-text-input");
    if (!input) return;
    if (input._blurTimer) {
      clearTimeout(input._blurTimer);
      input._blurTimer = null;
    }
    input.classList.add("hidden");
    input.value = "";
    input.onblur = null;
    input.onkeydown = null;
    input.oninput = null;
    input._composing = false;
    this._textDraft = "";
    this._textPos = null;
    if (this._canvas) this._canvas.style.pointerEvents = "";
    this.redraw();
  },

  commitTextInput() {
    const input = document.getElementById("ipaint-text-input");
    if (!input || input.classList.contains("hidden") || !this._textPos) return;
    const text = String(input.value || "").trim();
    this.hideTextInput();
    if (!text) return;
    this.layers.push({
      type: "text",
      color: this.color,
      fontSize: this.fontSize,
      x: this._textPos.x,
      y: this._textPos.y,
      text,
    });
    this.pushHistory();
    this.redraw();
  },

  showTextInput(clientX, clientY) {
    const input = document.getElementById("ipaint-text-input");
    const stage = document.getElementById("ipaint-stage");
    const p = this.pointerToImage(clientX, clientY);
    if (!input || !stage || !p) return;
    this.commitTextInput();
    this._textPos = p;
    this._textDraft = "";
    const sr = stage.getBoundingClientRect();
    const cr = this._canvas.getBoundingClientRect();
    input.style.left = `${Math.max(0, Math.min(sr.width - 40, clientX - sr.left))}px`;
    input.style.top = `${Math.max(0, Math.min(sr.height - 28, clientY - sr.top))}px`;
    input.style.fontSize = `${Math.max(12, (this.fontSize * cr.height) / this.ih)}px`;
    input.style.color = this.color;
    input.classList.remove("hidden");
    input.value = "";
    if (this._canvas) this._canvas.style.pointerEvents = "none";
    const finish = () => this.commitTextInput();
    input.onblur = () => {
      input._blurTimer = setTimeout(() => {
        if (input._composing) return;
        if (document.activeElement === input) return;
        finish();
      }, 160);
    };
    input.onkeydown = (e) => {
      e.stopPropagation();
      if (e.key === "Enter" && !e.isComposing && !input._composing) {
        e.preventDefault();
        finish();
      } else if (e.key === "Escape") {
        e.preventDefault();
        this.hideTextInput();
      }
    };
    input.oninput = () => {
      this._textDraft = String(input.value || "");
      this.redraw();
    };
    if (!input._imeBound) {
      input._imeBound = true;
      input.addEventListener("compositionstart", () => {
        input._composing = true;
      });
      input.addEventListener("compositionend", () => {
        input._composing = false;
        this._textDraft = String(input.value || "");
        this.redraw();
      });
    }
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        try {
          input.focus({ preventScroll: true });
          input.select();
        } catch {
          input.focus();
        }
      });
    });
  },

  drawStroke(ctx, stroke) {
    if (!stroke) return;
    const type = stroke.type;
    if (type === "brush") {
      const pts = stroke.points || [];
      if (pts.length < 2) return;
      ctx.save();
      ctx.strokeStyle = stroke.color || "#ff4444";
      ctx.lineWidth = stroke.size || 4;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.beginPath();
      ctx.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
      ctx.stroke();
      ctx.restore();
      return;
    }
    if (type === "eraser") {
      const pts = stroke.points || [];
      if (pts.length < 2) return;
      ctx.save();
      ctx.globalCompositeOperation = "destination-out";
      ctx.strokeStyle = "rgba(0,0,0,1)";
      ctx.lineWidth = Math.max(4, stroke.size || 8);
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.beginPath();
      ctx.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
      ctx.stroke();
      ctx.restore();
      return;
    }
    if (type === "line" || type === "arrow") {
      ctx.save();
      ctx.strokeStyle = stroke.color || "#ff4444";
      ctx.lineWidth = stroke.size || 4;
      ctx.lineCap = "round";
      ctx.beginPath();
      ctx.moveTo(stroke.x1, stroke.y1);
      ctx.lineTo(stroke.x2, stroke.y2);
      ctx.stroke();
      if (type === "arrow") this.drawArrowHead(ctx, stroke.x1, stroke.y1, stroke.x2, stroke.y2, stroke.size || 4);
      ctx.restore();
      return;
    }
    if (type === "rect") {
      ctx.save();
      ctx.strokeStyle = stroke.color || "#ff4444";
      ctx.lineWidth = stroke.size || 4;
      ctx.strokeRect(stroke.x1, stroke.y1, stroke.x2 - stroke.x1, stroke.y2 - stroke.y1);
      ctx.restore();
      return;
    }
    if (type === "text") {
      ctx.save();
      ctx.fillStyle = stroke.color || "#ff4444";
      ctx.font = `600 ${stroke.fontSize || 28}px system-ui, sans-serif`;
      ctx.textBaseline = "top";
      ctx.fillText(stroke.text || "", stroke.x, stroke.y);
      ctx.restore();
    }
  },

  drawArrowHead(ctx, x1, y1, x2, y2, size) {
    const ang = Math.atan2(y2 - y1, x2 - x1);
    const len = Math.max(8, size * 2.4);
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - len * Math.cos(ang - 0.45), y2 - len * Math.sin(ang - 0.45));
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - len * Math.cos(ang + 0.45), y2 - len * Math.sin(ang + 0.45));
    ctx.stroke();
  },

  redraw() {
    const ctx = this._ctx;
    if (!ctx || !this._img || !(this.iw > 0 && this.ih > 0)) return;
    ctx.clearRect(0, 0, this.iw, this.ih);
    ctx.drawImage(this._img, 0, 0, this.iw, this.ih);
    for (const layer of this.layers) this.drawStroke(ctx, layer);
    if (this._preview) this.drawStroke(ctx, this._preview);
    if (this._textPos && this._textDraft) {
      this.drawStroke(ctx, {
        type: "text",
        color: this.color,
        fontSize: this.fontSize,
        x: this._textPos.x,
        y: this._textPos.y,
        text: this._textDraft,
      });
    }
  },

  onPointerDown(e) {
    if (!this.isOpen() || !this._canvas) return;
    if (e.target.closest("#ipaint-text-input")) return;
    const p = this.pointerToImage(e.clientX, e.clientY);
    if (!p) return;
    if (this.tool === "text") {
      this.showTextInput(e.clientX, e.clientY);
      return;
    }
    this.commitTextInput();
    e.preventDefault();
    this._canvas.setPointerCapture?.(e.pointerId);
    this._pointer = { id: e.pointerId, start: p, last: p };
    if (this.tool === "brush" || this.tool === "eraser") {
      this._preview = { type: this.tool, color: this.color, size: this.size, points: [p, p] };
    } else {
      this._preview = {
        type: this.tool,
        color: this.color,
        size: this.size,
        x1: p.x,
        y1: p.y,
        x2: p.x,
        y2: p.y,
      };
    }
    this.redraw();
  },

  onPointerMove(e) {
    if (!this._pointer || this._pointer.id !== e.pointerId || !this.isOpen()) return;
    const p = this.pointerToImage(e.clientX, e.clientY);
    if (!p || !this._preview) return;
    e.preventDefault();
    this._pointer.last = p;
    if (this.tool === "brush" || this.tool === "eraser") {
      this._preview.points.push(p);
    } else {
      this._preview.x2 = p.x;
      this._preview.y2 = p.y;
    }
    this.redraw();
  },

  onPointerUp(e) {
    if (!this._pointer || this._pointer.id !== e.pointerId) return;
    e.preventDefault();
    const preview = this._preview;
    this._pointer = null;
    this._preview = null;
    if (!preview) return;
    if (this.tool === "brush" || this.tool === "eraser") {
      const pts = preview.points || [];
      if (pts.length < 2 || (pts.length === 2 && pts[0].x === pts[1].x && pts[0].y === pts[1].y)) {
        this.redraw();
        return;
      }
      this.layers.push(preview);
      this.pushHistory();
      this.redraw();
      return;
    }
    const dx = Math.abs((preview.x2 || 0) - (preview.x1 || 0));
    const dy = Math.abs((preview.y2 || 0) - (preview.y1 || 0));
    if (dx < 2 && dy < 2) {
      this.redraw();
      return;
    }
    this.layers.push(preview);
    this.pushHistory();
    this.redraw();
  },

  async confirm() {
    const nodeId = this.nodeId;
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeId || !node?.imageUrl || !this._canvas) return;
    this.commitTextInput();
    const label = "画笔标注";
    let blob;
    try {
      blob = await new Promise((resolve, reject) => {
        this._canvas.toBlob((b) => (b ? resolve(b) : reject(new Error("导出失败"))), "image/png");
      });
    } catch (err) {
      showCanvasToast(err.message || "导出失败");
      return;
    }
    const outW = this.iw;
    const outH = this.ih;
    this.close();

    if (MediaTools.busy || FrameCapture.busy) return;
    MediaTools.busy = true;
    FrameCapture.closeMenus();
    let outId = null;
    try {
      CanvasHistory.push();
      outId = await createDerivedMediaNode(
        node,
        { kind: "image", width: outW, height: outH, op: "image_paint" },
        label,
        { pending: true, skipHistory: true }
      );
      const fd = new FormData();
      fd.append("file", blob, `paint-${Date.now()}.png`);
      fd.append("width", String(outW));
      fd.append("height", String(outH));
      if (CanvasStore.activeBoardId) fd.append("board_id", CanvasStore.activeBoardId);
      const up = await fetch("/api/upload", { method: "POST", body: fd });
      if (!up.ok) throw new Error("上传标注结果失败");
      const uploaded = await up.json();
      CanvasStore.updateNode(outId, {
        status: "completed",
        imageUrl: uploaded.url,
        mediaWidth: uploaded.width || outW,
        mediaHeight: uploaded.height || outH,
        customName: label,
        ...mediaThumbPatchFromUpload(uploaded, "image"),
      });
      await CanvasStore.flushSave();
      renderNodes();
      scheduleRenderConnections(true);
      showCanvasToast(`${label}完成`);
      if (outId) selectSingle(outId);
    } catch (err) {
      if (outId) {
        CanvasStore.updateNode(outId, { status: "failed", error: err.message || "标注失败" });
        await CanvasStore.flushSave();
        renderNodes();
      }
      showCanvasToast(err.message || "标注失败");
    } finally {
      MediaTools.busy = false;
    }
  },

  bind() {
    if (this._bound) return;
    this._bound = true;
    document.getElementById("ipaint-close")?.addEventListener("click", () => this.close());
    document.getElementById("ipaint-cancel")?.addEventListener("click", () => this.close());
    document.getElementById("ipaint-backdrop")?.addEventListener("click", () => this.close());
    document.getElementById("ipaint-confirm")?.addEventListener("click", () => this.confirm());
    document.getElementById("ipaint-undo")?.addEventListener("click", () => this.undo());
    document.getElementById("ipaint-clear")?.addEventListener("click", () => this.clearLayers());
    document.getElementById("ipaint-tools")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-tool]");
      if (btn) this.setTool(btn.dataset.tool);
    });
    document.getElementById("ipaint-colors")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-color]");
      if (btn) this.setColor(btn.dataset.color);
    });
    document.getElementById("ipaint-color-picker")?.addEventListener("input", (e) => {
      this.setColor(e.target.value);
    });
    document.getElementById("ipaint-size")?.addEventListener("input", (e) => {
      this.setSize(e.target.value);
    });
    document.getElementById("ipaint-font-size")?.addEventListener("input", (e) => {
      this.setFontSize(e.target.value);
    });
    window.addEventListener("resize", () => {
      if (this.isOpen()) this.layoutCanvas();
    });

    const canvas = document.getElementById("ipaint-canvas");
    canvas?.addEventListener("pointerdown", (e) => this.onPointerDown(e));
    canvas?.addEventListener("pointermove", (e) => this.onPointerMove(e));
    canvas?.addEventListener("pointerup", (e) => this.onPointerUp(e));
    canvas?.addEventListener("pointercancel", (e) => this.onPointerUp(e));

    window.addEventListener("keydown", (e) => {
      if (!this.isOpen()) return;
      if (isTextInputTarget(e.target) || e.target?.closest?.("#ipaint-text-input")) return;
      if (e.key === "Escape") {
        e.preventDefault();
        this.close();
      } else if (e.key === "Enter" && !e.target.closest("#ipaint-text-input")) {
        e.preventDefault();
        this.confirm();
      } else if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "z") {
        e.preventDefault();
        this.undo();
      } else if (!e.ctrlKey && !e.metaKey && !e.altKey) {
        const map = { b: "brush", e: "eraser", l: "line", a: "arrow", r: "rect", t: "text" };
        const tool = map[e.key.toLowerCase()];
        if (tool) {
          e.preventDefault();
          this.setTool(tool);
        }
      }
    });
  },
};
window.ImagePaintStudio = ImagePaintStudio;

/** Load image → rotate/flip → crop → PNG blob (browser-side, no AI). */
function bakeImageTransform(srcUrl, opts) {
  const { rot = 0, flipH = false, flipV = false, crop_x, crop_y, crop_w, crop_h } = opts;
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      try {
        const sw = img.naturalWidth;
        const sh = img.naturalHeight;
        const rad = ((rot % 360) + 360) % 360;
        const rotated = rad === 90 || rad === 270;
        const tw = rotated ? sh : sw;
        const th = rotated ? sw : sh;

        const canvas = document.createElement("canvas");
        canvas.width = tw;
        canvas.height = th;
        const ctx = canvas.getContext("2d");
        if (!ctx) throw new Error("无法创建画布");

        ctx.save();
        ctx.translate(tw / 2, th / 2);
        ctx.rotate((rad * Math.PI) / 180);
        ctx.scale(flipH ? -1 : 1, flipV ? -1 : 1);
        ctx.drawImage(img, -sw / 2, -sh / 2);
        ctx.restore();

        const x = Math.max(0, Math.min(crop_x, tw - 1));
        const y = Math.max(0, Math.min(crop_y, th - 1));
        const w = Math.max(1, Math.min(crop_w, tw - x));
        const h = Math.max(1, Math.min(crop_h, th - y));
        const out = document.createElement("canvas");
        out.width = w;
        out.height = h;
        const octx = out.getContext("2d");
        if (!octx) throw new Error("无法创建输出画布");
        octx.drawImage(canvas, x, y, w, h, 0, 0, w, h);
        out.toBlob(
          (blob) => {
            if (!blob) reject(new Error("导出失败"));
            else resolve(blob);
          },
          "image/png"
        );
      } catch (err) {
        reject(err);
      }
    };
    img.onerror = () => reject(new Error("图片加载失败"));
    img.src = srcUrl;
  });
}

function _toolEven(n) {
  return Math.max(2, Math.round(n / 2) * 2);
}

function _toolFitScale(sw, sh, maxH, maxPixels = 2088876) {
  let w = sw;
  let h = sh;
  if (maxH && h > maxH) {
    w = Math.round((w * maxH) / h);
    h = maxH;
  }
  if (w * h > maxPixels) {
    const s = Math.sqrt(maxPixels / (w * h));
    w = Math.round(w * s);
    h = Math.round(h * s);
  }
  return { w: _toolEven(w), h: _toolEven(h) };
}

function formatAudioPrecise(sec) {
  if (!Number.isFinite(sec) || sec < 0) return "0:00.0";
  const m = Math.floor(sec / 60);
  const s = sec - m * 60;
  return `${m}:${s.toFixed(1).padStart(4, "0")}`;
}

const AudioTrimStudio = {
  nodeId: null,
  inT: 0,
  outT: 0,
  dur: 0,
  _bound: false,
  _drag: null,
  _scrubTimer: null,

  isOpen() {
    return !document.getElementById("audio-trim-studio")?.classList.contains("hidden");
  },

  audioEl() {
    return document.getElementById("at-audio");
  },

  ensureAudible(audio = this.audioEl()) {
    if (!audio) return;
    try {
      audio.muted = false;
      audio.defaultMuted = false;
      audio.volume = 1;
    } catch {
      /* ignore */
    }
  },

  setPlayingUi(playing) {
    document.getElementById("at-play")?.classList.toggle("is-playing", !!playing);
  },

  open(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasAudio(node)) return;
    FrameCapture.closeMenus();
    this.nodeId = nodeId;
    const box = document.getElementById("audio-trim-studio");
    const audio = this.audioEl();
    const wave = document.getElementById("at-wave");
    if (!box || !audio) return;
    if (wave) {
      wave.innerHTML = Array.from({ length: 64 }, (_, i) => {
        const h = 18 + ((i * 41) % 70);
        return `<span style="height:${h}%"></span>`;
      }).join("");
    }
    audio.src = resolveMediaUrl(node.audioUrl);
    this.ensureAudible(audio);
    audio.load();
    revealOverlay(box);
    box.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";
    const onMeta = () => {
      this.dur = Number.isFinite(audio.duration) ? audio.duration : 0;
      this.inT = 0;
      this.outT = this.dur > 0 ? this.dur : 1;
      this.syncUi();
    };
    audio.addEventListener("loadedmetadata", onMeta, { once: true });
    if (audio.readyState >= 1) onMeta();
    this.bindOnce();
    this.setPlayingUi(false);
  },

  close() {
    const box = document.getElementById("audio-trim-studio");
    const audio = this.audioEl();
    clearTimeout(this._scrubTimer);
    this._scrubTimer = null;
    audio?.pause();
    this.setPlayingUi(false);
    dismissOverlay(box);
    box?.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
    this.nodeId = null;
    this._drag = null;
  },

  syncUi() {
    const range = document.getElementById("at-range");
    const label = document.getElementById("at-sel-label");
    const t0 = document.getElementById("at-t0");
    const t1 = document.getElementById("at-t1");
    const dur = Math.max(this.dur, 0.01);
    const left = (this.inT / dur) * 100;
    const right = 100 - (this.outT / dur) * 100;
    if (range) {
      range.style.left = `${Math.max(0, left)}%`;
      range.style.right = `${Math.max(0, right)}%`;
    }
    const sel = Math.max(0, this.outT - this.inT);
    if (label) label.textContent = `当前选择 ${formatAudioPrecise(sel)} / 总时长 ${formatAudioPrecise(this.dur)}`;
    if (t0) t0.textContent = formatAudioPrecise(0);
    if (t1) t1.textContent = formatAudioPrecise(this.dur);
  },

  reset() {
    this.inT = 0;
    this.outT = this.dur > 0 ? this.dur : 1;
    this.syncUi();
    const audio = this.audioEl();
    if (audio) {
      this.ensureAudible(audio);
      audio.currentTime = this.inT;
    }
  },

  /** Preview a short audible scrub at time t (for handle drag). */
  scrubTo(t) {
    const audio = this.audioEl();
    if (!audio || !this.dur) return;
    this.ensureAudible(audio);
    const clamped = Math.min(Math.max(0, t), Math.max(0, this.dur - 0.05));
    const now = performance.now();
    if (this._lastScrubAt && now - this._lastScrubAt < 80) {
      this._pendingScrub = clamped;
      return;
    }
    this._lastScrubAt = now;
    this._pendingScrub = null;
    try {
      audio.currentTime = clamped;
    } catch {
      /* ignore */
    }
    if (audio.paused) {
      audio.play().then(() => this.setPlayingUi(true)).catch(() => this.setPlayingUi(false));
    }
  },

  togglePlay() {
    const audio = this.audioEl();
    if (!audio) return;
    this.ensureAudible(audio);
    if (audio.paused) {
      if (audio.currentTime < this.inT || audio.currentTime >= this.outT - 0.02) {
        audio.currentTime = this.inT;
      }
      audio.play().then(() => this.setPlayingUi(true)).catch(() => {
        showCanvasToast("无法播放音频，请检查系统音量");
        this.setPlayingUi(false);
      });
    } else {
      audio.pause();
      this.setPlayingUi(false);
    }
  },

  confirm() {
    const nodeId = this.nodeId;
    const start = this.inT;
    const end = this.outT;
    this.close();
    if (!nodeId) return;
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    const fmt = audioFmtLabel(node?.audioUrl || "").toLowerCase();
    MediaTools.runAudio(nodeId, "trim_audio", {
      start,
      end,
      format: ["mp3", "wav", "m4a", "aac"].includes(fmt) ? fmt : "mp3",
    });
  },

  bindOnce() {
    if (this._bound) return;
    this._bound = true;
    document.getElementById("at-close")?.addEventListener("click", () => this.close());
    document.getElementById("at-cancel")?.addEventListener("click", () => this.close());
    document.querySelector('[data-at="close"]')?.addEventListener("click", () => this.close());
    document.getElementById("at-reset")?.addEventListener("click", () => this.reset());
    document.getElementById("at-confirm")?.addEventListener("click", () => this.confirm());
    document.getElementById("at-play")?.addEventListener("click", () => this.togglePlay());
    document.getElementById("at-wave")?.addEventListener("click", (e) => {
      if (e.target.closest("#at-play")) return;
      const track = document.getElementById("at-track");
      const wave = document.getElementById("at-wave-wrap") || document.querySelector(".at-wave-wrap");
      const el = wave || track;
      if (!el || !this.dur) return;
      const rect = el.getBoundingClientRect();
      const x = Math.min(1, Math.max(0, (e.clientX - rect.left) / rect.width));
      const t = Math.min(this.outT - 0.01, Math.max(this.inT, x * this.dur));
      const audio = this.audioEl();
      if (!audio) return;
      this.ensureAudible(audio);
      audio.currentTime = t;
      audio.play().then(() => this.setPlayingUi(true)).catch(() => {});
    });
    const audio = this.audioEl();
    audio?.addEventListener("timeupdate", () => {
      if (!this.isOpen()) return;
      if (audio.currentTime >= this.outT - 0.02) {
        audio.pause();
        audio.currentTime = this.inT;
        this.setPlayingUi(false);
      }
    });
    audio?.addEventListener("play", () => this.setPlayingUi(true));
    audio?.addEventListener("pause", () => this.setPlayingUi(false));
    const onDown = (which) => (e) => {
      e.preventDefault();
      this._drag = which;
      const move = (ev) => {
        const track = document.getElementById("at-track");
        if (!track || !this.dur) return;
        const rect = track.getBoundingClientRect();
        const x = Math.min(1, Math.max(0, (ev.clientX - rect.left) / rect.width));
        const t = x * this.dur;
        if (this._drag === "in") this.inT = Math.min(t, this.outT - 0.05);
        else this.outT = Math.max(t, this.inT + 0.05);
        this.syncUi();
        // Hear the edge being dragged so you know which segment you cut
        this.scrubTo(this._drag === "in" ? this.inT : Math.max(this.inT, this.outT - 0.35));
      };
      const up = () => {
        this._drag = null;
        window.removeEventListener("pointermove", move);
        window.removeEventListener("pointerup", up);
        // After setting range, play the selection so user can confirm
        const a = this.audioEl();
        if (a) {
          this.ensureAudible(a);
          a.currentTime = this.inT;
          a.play().then(() => this.setPlayingUi(true)).catch(() => {});
        }
      };
      window.addEventListener("pointermove", move);
      window.addEventListener("pointerup", up);
      move(e);
    };
    document.getElementById("at-handle-in")?.addEventListener("pointerdown", onDown("in"));
    document.getElementById("at-handle-out")?.addEventListener("pointerdown", onDown("out"));
    window.addEventListener("keydown", (e) => {
      if (!this.isOpen()) return;
      if (e.key === "Escape") this.close();
      if (e.key === " " || e.code === "Space") {
        e.preventDefault();
        this.togglePlay();
      }
    });
  },
};
window.AudioTrimStudio = AudioTrimStudio;

const VideoTrimStudio = {
  nodeId: null,
  inT: 0,
  outT: 0,
  dur: 0,
  _bound: false,
  _drag: null,
  frameStep: 1 / 24,

  isOpen() {
    return !document.getElementById("video-trim-studio")?.classList.contains("hidden");
  },

  open(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasCapturableVideo(node)) return;
    this.bind();
    FrameCapture.closeMenus();
    this.nodeId = nodeId;
    const box = document.getElementById("video-trim-studio");
    const video = document.getElementById("vt-video");
    if (!box || !video) return;
    video.src = resolveMediaUrl(node.videoUrl);
    video.load();
    revealOverlay(box);
    box.setAttribute("aria-hidden", "false");
    document.body.style.overflow = "hidden";
    const onMeta = () => {
      this.dur = Number.isFinite(video.duration) ? video.duration : 0;
      this.inT = 0;
      this.outT = this.dur > 0 ? this.dur : 1;
      const res = document.getElementById("vt-res");
      if (res) {
        const w = video.videoWidth || node.mediaWidth || 0;
        const h = video.videoHeight || node.mediaHeight || 0;
        res.textContent = w && h ? `${w} × ${h}` : "—";
      }
      document.getElementById("vt-dur").textContent = formatFcTime(this.dur);
      this.syncUi();
      this.buildFilm();
    };
    video.addEventListener("loadedmetadata", onMeta, { once: true });
    if (video.readyState >= 1) onMeta();
  },

  close() {
    const box = document.getElementById("video-trim-studio");
    const video = document.getElementById("vt-video");
    video?.pause();
    if (video) {
      video.removeAttribute("src");
      video.load();
    }
    dismissOverlay(box);
    box?.setAttribute("aria-hidden", "true");
    document.body.style.overflow = "";
    this.nodeId = null;
  },

  bind() {
    if (this._bound) return;
    this._bound = true;
    const video = document.getElementById("vt-video");
    document.getElementById("vt-close")?.addEventListener("click", () => this.close());
    document.getElementById("vt-cancel")?.addEventListener("click", () => this.close());
    document.getElementById("vt-confirm")?.addEventListener("click", () => this.confirm());
    document.getElementById("vt-set-in")?.addEventListener("click", () => {
      this.inT = Math.min(video?.currentTime || 0, this.outT - 0.05);
      this.syncUi();
    });
    document.getElementById("vt-set-out")?.addEventListener("click", () => {
      this.outT = Math.max(video?.currentTime || 0, this.inT + 0.05);
      this.syncUi();
    });
    document.getElementById("vt-in")?.addEventListener("change", () => {
      const t = parseFcTime(document.getElementById("vt-in").value);
      if (t == null) return;
      this.inT = Math.max(0, Math.min(t, this.outT - 0.05));
      this.syncUi();
      seekVideoElement(video, this.inT);
    });
    document.getElementById("vt-out")?.addEventListener("change", () => {
      const t = parseFcTime(document.getElementById("vt-out").value);
      if (t == null) return;
      this.outT = Math.min(this.dur || t, Math.max(t, this.inT + 0.05));
      this.syncUi();
      seekVideoElement(video, this.outT);
    });
    document.querySelector(".vt-transport")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-vt]");
      if (!btn || !video) return;
      const act = btn.dataset.vt;
      if (act === "toggle") {
        if (video.paused) video.play().catch(() => {});
        else video.pause();
      } else if (act === "prev-frame") seekVideoElement(video, (video.currentTime || 0) - this.frameStep);
      else if (act === "next-frame") seekVideoElement(video, (video.currentTime || 0) + this.frameStep);
      else if (act === "back-1") seekVideoElement(video, (video.currentTime || 0) - 1);
      else if (act === "fwd-1") seekVideoElement(video, (video.currentTime || 0) + 1);
    });
    video?.addEventListener("timeupdate", () => this.syncPlayhead());
    video?.addEventListener("play", () => {
      const b = document.getElementById("vt-play");
      if (b) b.innerHTML = '<svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><rect x="3" y="3" width="3.5" height="10" rx="0.8"/><rect x="9.5" y="3" width="3.5" height="10" rx="0.8"/></svg>';
    });
    video?.addEventListener("pause", () => {
      const b = document.getElementById("vt-play");
      if (b) b.innerHTML = '<svg width="12" height="12" viewBox="0 0 16 16" fill="currentColor" aria-hidden="true"><path d="M5 3.2v9.6l8-4.8z"/></svg>';
    });

    const film = document.getElementById("vt-film");
    const onPtr = (e) => {
      if (!this._drag || !film || !(this.dur > 0)) return;
      const rect = film.getBoundingClientRect();
      const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
      const t = ratio * this.dur;
      if (this._drag === "in") this.inT = Math.min(t, this.outT - 0.05);
      else if (this._drag === "out") this.outT = Math.max(t, this.inT + 0.05);
      else scrubVideoTime(video, Math.min(Math.max(t, this.inT), this.outT));
      this.syncUi();
    };
    document.getElementById("vt-handle-in")?.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      this._drag = "in";
      e.currentTarget.setPointerCapture?.(e.pointerId);
    });
    document.getElementById("vt-handle-out")?.addEventListener("pointerdown", (e) => {
      e.preventDefault();
      this._drag = "out";
      e.currentTarget.setPointerCapture?.(e.pointerId);
    });
    film?.addEventListener("pointerdown", (e) => {
      if (e.target.closest(".vt-handle")) return;
      e.preventDefault();
      e.stopPropagation();
      this._drag = "seek";
      try {
        video?.pause();
      } catch {
        /* ignore */
      }
      onPtr(e);
    });
    window.addEventListener("pointermove", onPtr);
    window.addEventListener("pointerup", () => {
      this._drag = null;
    });

    window.addEventListener("keydown", (e) => {
      if (!this.isOpen()) return;
      if (isTextInputTarget(e.target)) return;
      if (e.key === "Escape") {
        e.preventDefault();
        this.close();
      } else if (e.key === " ") {
        e.preventDefault();
        if (video.paused) video.play().catch(() => {});
        else video.pause();
      } else if (e.key === "ArrowLeft") {
        e.preventDefault();
        seekVideoElement(video, (video.currentTime || 0) - (e.shiftKey ? 1 : this.frameStep));
      } else if (e.key === "ArrowRight") {
        e.preventDefault();
        seekVideoElement(video, (video.currentTime || 0) + (e.shiftKey ? 1 : this.frameStep));
      } else if (e.key === "[") {
        e.preventDefault();
        this.inT = Math.min(video.currentTime || 0, this.outT - 0.05);
        this.syncUi();
      } else if (e.key === "]") {
        e.preventDefault();
        this.outT = Math.max(video.currentTime || 0, this.inT + 0.05);
        this.syncUi();
      } else if (e.key === "Enter") {
        e.preventDefault();
        this.confirm();
      }
    });
  },

  syncUi() {
    const keep = Math.max(0, this.outT - this.inT);
    document.getElementById("vt-in").value = formatFcTime(this.inT);
    document.getElementById("vt-out").value = formatFcTime(this.outT);
    document.getElementById("vt-keep").textContent = formatFcTime(keep);
    document.getElementById("vt-selected-label").textContent = `已选 ${formatFcTime(keep)}`;
    const range = document.getElementById("vt-range");
    if (range && this.dur > 0) {
      range.style.left = `${(this.inT / this.dur) * 100}%`;
      range.style.width = `${(keep / this.dur) * 100}%`;
    }
    this.syncPlayhead();
  },

  syncPlayhead() {
    const video = document.getElementById("vt-video");
    const t = video?.currentTime || 0;
    document.getElementById("vt-stamp").textContent = formatFcTime(t);
    document.getElementById("vt-time").textContent = `${formatFcTime(t)} / ${formatFcTime(this.dur)}`;
    const head = document.getElementById("vt-playhead");
    if (head && this.dur > 0) head.style.left = `${(t / this.dur) * 100}%`;
  },

  async buildFilm() {
    const track = document.getElementById("vt-film-track");
    const video = document.getElementById("vt-video");
    if (!track || !video?.src || !(this.dur > 0)) return;
    track.innerHTML = `<div class="fc-filmstrip-loading">生成时间轴…</div>`;
    const helper = document.createElement("video");
    helper.muted = true;
    helper.playsInline = true;
    helper.src = video.currentSrc || video.src;
    try {
      await new Promise((res, rej) => {
        helper.onloadedmetadata = () => res();
        helper.onerror = () => rej();
      });
      const count = Math.min(24, Math.max(10, Math.round(this.dur)));
      const thumbs = [];
      for (let i = 0; i < count; i++) {
        await seekVideoElement(helper, (this.dur * i) / Math.max(1, count - 1));
        const c = document.createElement("canvas");
        const scale = 100 / Math.max(helper.videoWidth || 1, 1);
        c.width = Math.max(1, Math.round((helper.videoWidth || 1) * scale));
        c.height = Math.max(1, Math.round((helper.videoHeight || 1) * scale));
        c.getContext("2d")?.drawImage(helper, 0, 0, c.width, c.height);
        thumbs.push(c.toDataURL("image/jpeg", 0.5));
      }
      track.innerHTML = thumbs.map((u) => `<img class="fc-filmstrip-thumb" src="${u}" alt="" />`).join("");
    } catch {
      track.innerHTML = "";
    } finally {
      helper.removeAttribute("src");
      helper.load();
    }
  },

  confirm() {
    const nodeId = this.nodeId;
    const start = this.inT;
    const end = this.outT;
    this.close();
    if (!nodeId || end <= start) {
      showCanvasToast("请选择有效区间");
      return;
    }
    MediaTools.run(nodeId, "trim", { start, end });
  },
};

const VideoCompressModal = {
  nodeId: null,
  sw: 0,
  sh: 0,
  scale: "smart",
  fps: 0,
  _bound: false,

  isOpen() {
    return !document.getElementById("video-compress-modal")?.classList.contains("hidden");
  },

  open(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasCapturableVideo(node)) return;
    this.bind();
    FrameCapture.closeMenus();
    this.nodeId = nodeId;
    this.scale = "smart";
    this.fps = 0;
    const box = document.getElementById("video-compress-modal");
    const video = document.getElementById("vc-video");
    video.src = resolveMediaUrl(node.videoUrl);
    video.load();
    revealOverlay(box);
    document.body.style.overflow = "hidden";
    const onMeta = () => {
      this.sw = video.videoWidth || node.mediaWidth || 0;
      this.sh = video.videoHeight || node.mediaHeight || 0;
      document.getElementById("vc-src").textContent =
        this.sw && this.sh ? `${this.sw} × ${this.sh} · ${Math.round((this.sw * this.sh) / 10000) / 10} 万像素` : "—";
      document.querySelectorAll("#vc-scale-grid .vc-scale-btn").forEach((b) => {
        b.classList.toggle("active", b.dataset.scale === "smart");
      });
      document.querySelectorAll("#vc-fps-grid .vc-fps-btn").forEach((b) => {
        b.classList.toggle("active", b.dataset.fps === "0");
      });
      this.updateOut();
    };
    video.addEventListener("loadedmetadata", onMeta, { once: true });
    if (video.readyState >= 1) onMeta();
  },

  close() {
    const box = document.getElementById("video-compress-modal");
    const video = document.getElementById("vc-video");
    video?.pause();
    if (video) {
      video.removeAttribute("src");
      video.load();
    }
    dismissOverlay(box);
    document.body.style.overflow = "";
    this.nodeId = null;
  },

  updateOut() {
    if (!this.sw || !this.sh) {
      document.getElementById("vc-out").textContent = "—";
      return;
    }
    const maxH = this.scale === "smart" ? null : Number(this.scale);
    const { w, h } = _toolFitScale(this.sw, this.sh, maxH);
    const fpsTxt = this.fps > 0 ? `${this.fps} fps` : "源帧率";
    document.getElementById("vc-out").textContent = `${w} × ${h} · 约 ${Math.round((w * h) / (this.sw * this.sh) * 100)}% · ${fpsTxt}`;
  },

  bind() {
    if (this._bound) return;
    this._bound = true;
    document.getElementById("vc-close")?.addEventListener("click", () => this.close());
    document.getElementById("vc-backdrop")?.addEventListener("click", () => this.close());
    document.getElementById("vc-confirm")?.addEventListener("click", () => this.confirm());
    document.getElementById("vc-scale-grid")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-scale]");
      if (!btn) return;
      this.scale = btn.dataset.scale;
      document.querySelectorAll("#vc-scale-grid .vc-scale-btn").forEach((b) => b.classList.toggle("active", b === btn));
      this.updateOut();
    });
    document.getElementById("vc-fps-grid")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-fps]");
      if (!btn) return;
      this.fps = Number(btn.dataset.fps) || 0;
      document.querySelectorAll("#vc-fps-grid .vc-fps-btn").forEach((b) => b.classList.toggle("active", b === btn));
      this.updateOut();
    });
    window.addEventListener("keydown", (e) => {
      if (!this.isOpen()) return;
      if (e.key === "Escape") this.close();
    });
  },

  confirm() {
    const nodeId = this.nodeId;
    const scale_mode = this.scale;
    const fps = this.fps > 0 ? this.fps : null;
    this.close();
    if (!nodeId) return;
    MediaTools.run(nodeId, "compress", { scale_mode, fps });
  },
};

const VideoUpscaleModal = {
  nodeId: null,
  batchNodeIds: null,
  mode: "ai", // ai | basic
  algo: "v3",
  engineTier: "pro",
  targetRes: "1080",
  fps: 0,
  sw: 0,
  sh: 0,
  engineOk: null,
  _bound: false,

  RES: { "720": 720, "1080": 1080, "2k": 1440, "4k": 2160 },

  isOpen() {
    return !document.getElementById("video-upscale-modal")?.classList.contains("hidden");
  },

  async open(nodeId, mode = "ai", opts = {}) {
    if (!isUpscaleEnabled()) {
      showCanvasToast("超分功能已关闭");
      return;
    }
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasCapturableVideo(node)) return;
    this.bind();
    releaseCanvasInteractionState();
    FrameCapture.closeMenus();
    if (!opts.keepBatch) this.batchNodeIds = null;
    this.nodeId = nodeId;
    this.mode = mode === "basic" ? "basic" : "ai";
    this.algo = "v3";
    this.engineTier = "pro";
    this.targetRes = "1080";
    this.fps = 0;
    const box = document.getElementById("video-upscale-modal");
    const video = document.getElementById("vu-video");
    const title = document.getElementById("vu-title");
    if (title) title.textContent = this.mode === "basic" ? "常规高清配置" : "视频超分配置";
    box?.classList.toggle("is-basic", this.mode === "basic");
    document.getElementById("vu-algo-block")?.classList.toggle("hidden", this.mode === "basic");
    document.getElementById("vu-engine-block")?.classList.toggle("hidden", this.mode === "basic");
    video.src = resolveMediaUrl(node.videoUrl);
    video.load();
    revealOverlay(box);
    document.body.style.overflow = "hidden";
    syncAllNodeVideoPlayback();
    document.getElementById("vu-engine").textContent =
      this.mode === "basic" ? "常规高清 · ffmpeg 缩放增强" : "检测引擎…";
    this.engineOk = null;
    this._syncChoices();
    const onMeta = () => {
      this.sw = video.videoWidth || node.mediaWidth || 0;
      this.sh = video.videoHeight || node.mediaHeight || 0;
      document.getElementById("vu-src").textContent =
        this.sw && this.sh ? `源 ${this.sw} × ${this.sh}` : "源 —";
      this.updateOut();
    };
    video.addEventListener("loadedmetadata", onMeta, { once: true });
    if (video.readyState >= 1) onMeta();
    if (this.mode === "ai") {
      try {
        const res = await fetch("/api/video/upscale/status");
        const st = await res.json();
        this.engineOk = Boolean(st.available);
        const workers = Number(st.workers_online || st.remote?.workers_online || 0);
        const pending = Number(st.remote?.queue_pending || 0);
        if (st.available) {
          document.getElementById("vu-engine").textContent = "引擎就绪 · Real-ESRGAN（本机）";
        } else if (workers > 0) {
          document.getElementById("vu-engine").textContent =
            `远程 GPU 在线（${workers} 台）${pending > 0 ? ` · 排队 ${pending}` : ""}`;
        } else {
          document.getElementById("vu-engine").textContent =
            "本机无 GPU 引擎 · 将排队等待本地 UpscaleWorker";
        }
      } catch {
        document.getElementById("vu-engine").textContent = "引擎状态未知";
      }
    }
  },

  async openBatch(nodeIds, mode = "ai") {
    if (!isUpscaleEnabled()) {
      showCanvasToast("超分功能已关闭");
      return;
    }
    if (!nodeIds?.length) return;
    this.batchNodeIds = nodeIds.slice();
    await this.open(nodeIds[0], mode, { keepBatch: true });
    const title = document.getElementById("vu-title");
    const n = nodeIds.length;
    if (title) {
      title.textContent =
        this.mode === "basic" ? `批量常规高清配置（${n} 个）` : `批量视频超分配置（${n} 个）`;
    }
  },

  close() {
    const box = document.getElementById("video-upscale-modal");
    const video = document.getElementById("vu-video");
    video?.pause();
    if (video) {
      video.removeAttribute("src");
      video.load();
    }
    dismissOverlay(box);
    document.body.style.overflow = "";
    this.nodeId = null;
    this.batchNodeIds = null;
    syncAllNodeVideoPlayback();
  },

  _targetSize() {
    const short = this.RES[this.targetRes] || 1080;
    if (!this.sw || !this.sh) return { w: 0, h: 0 };
    if (this.sh <= this.sw) {
      const h = short;
      const w = Math.max(2, Math.round((this.sw * h) / this.sh / 2) * 2);
      return { w, h: Math.max(2, Math.round(h / 2) * 2) };
    }
    const w = short;
    const h = Math.max(2, Math.round((this.sh * w) / this.sw / 2) * 2);
    return { w: Math.max(2, Math.round(w / 2) * 2), h };
  },

  updateOut() {
    const out = document.getElementById("vu-out");
    if (!out) return;
    if (!this.sw || !this.sh) {
      out.textContent = "—";
      return;
    }
    const { w, h } = this._targetSize();
    const fpsTxt = this.fps > 0 ? `${this.fps}fps` : "源帧率";
    const kind = this.mode === "basic" ? "常规高清" : this.algo === "v3" ? "V3 超分" : "V2 超分";
    const tier = this.mode === "basic" ? "" : this.engineTier === "pro" ? " · 专业版" : " · 标准版";
    out.textContent = `${w} × ${h} · ${fpsTxt} · ${kind}${tier}`;
    const note = document.getElementById("vu-algo-note");
    if (note) {
      note.textContent =
        this.algo === "v3"
          ? "效果超分：更强纹理与细节，处理更慢。"
          : "快速通用：速度优先，适合预览与批量。";
    }
  },

  _syncChoices() {
    document.querySelectorAll("#vu-algo-grid .vu-choice").forEach((b) => {
      b.classList.toggle("active", b.dataset.algo === this.algo);
    });
    document.querySelectorAll("#vu-engine-grid .vu-choice").forEach((b) => {
      b.classList.toggle("active", b.dataset.engine === this.engineTier);
    });
    document.querySelectorAll("#vu-res-grid .vc-scale-btn").forEach((b) => {
      b.classList.toggle("active", b.dataset.res === this.targetRes);
    });
    document.querySelectorAll("#vu-fps-grid .vc-fps-btn").forEach((b) => {
      b.classList.toggle("active", String(b.dataset.fps) === String(this.fps));
    });
    this.updateOut();
  },

  bind() {
    if (this._bound) return;
    this._bound = true;
    document.getElementById("vu-close")?.addEventListener("click", () => this.close());
    document.getElementById("vu-backdrop")?.addEventListener("click", () => this.close());
    document.getElementById("vu-confirm")?.addEventListener("click", () => this.confirm());
    document.getElementById("vu-algo-grid")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-algo]");
      if (!btn) return;
      this.algo = btn.dataset.algo || "v3";
      this._syncChoices();
    });
    document.getElementById("vu-engine-grid")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-engine]");
      if (!btn) return;
      this.engineTier = btn.dataset.engine || "pro";
      this._syncChoices();
    });
    document.getElementById("vu-res-grid")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-res]");
      if (!btn) return;
      this.targetRes = btn.dataset.res || "1080";
      this._syncChoices();
    });
    document.getElementById("vu-fps-grid")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-fps]");
      if (!btn) return;
      this.fps = Number(btn.dataset.fps) || 0;
      this._syncChoices();
    });
    window.addEventListener("keydown", (e) => {
      if (!this.isOpen()) return;
      if (e.key === "Escape") this.close();
    });
  },

  confirm() {
    const payload = {
      mode: this.mode,
      algo: this.algo,
      engine_tier: this.engineTier,
      target_res: this.targetRes,
      fps: this.fps > 0 ? this.fps : null,
    };
    const ids = this.batchNodeIds?.length
      ? this.batchNodeIds.slice()
      : this.nodeId
        ? [this.nodeId]
        : [];
    this.close();
    if (!ids.length) return;
    MediaTools.startBatchUpscale(ids, payload);
  },
};

const VideoGifStudio = {
  nodeId: null,
  inT: 0,
  outT: 5,
  dur: 0,
  sw: 0,
  sh: 0,
  _bound: false,
  _drag: null,

  isOpen() {
    return !document.getElementById("video-gif-studio")?.classList.contains("hidden");
  },

  open(nodeId) {
    const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
    if (!nodeHasCapturableVideo(node)) return;
    this.bind();
    FrameCapture.closeMenus();
    this.nodeId = nodeId;
    const box = document.getElementById("video-gif-studio");
    const video = document.getElementById("vg-video");
    video.src = resolveMediaUrl(node.videoUrl);
    video.load();
    revealOverlay(box);
    document.body.style.overflow = "hidden";
    document.getElementById("vg-format").value = "gif";
    document.getElementById("vg-fps").value = "10";
    document.getElementById("vg-width").value = "480";
    document.getElementById("vg-quality").value = "standard";
    this.updateConfirmLabel();
    const onMeta = () => {
      this.dur = Number.isFinite(video.duration) ? video.duration : 0;
      this.sw = video.videoWidth || node.mediaWidth || 0;
      this.sh = video.videoHeight || node.mediaHeight || 0;
      this.inT = 0;
      this.outT = Math.min(5, this.dur || 5);
      this.syncUi();
      this.buildFilm();
    };
    video.addEventListener("loadedmetadata", onMeta, { once: true });
    if (video.readyState >= 1) onMeta();
  },

  close() {
    const box = document.getElementById("video-gif-studio");
    const video = document.getElementById("vg-video");
    video?.pause();
    if (video) {
      video.removeAttribute("src");
      video.load();
    }
    dismissOverlay(box);
    document.body.style.overflow = "";
    this.nodeId = null;
  },

  updateConfirmLabel() {
    const fmt = document.getElementById("vg-format")?.value || "gif";
    const btn = document.getElementById("vg-confirm");
    if (btn) btn.textContent = fmt === "webp" ? "转换为 WebP" : "转换为 GIF";
  },

  syncUi() {
    const keep = Math.max(0.1, this.outT - this.inT);
    const fps = Number(document.getElementById("vg-fps")?.value || 10);
    const frames = Math.round(keep * fps);
    document.getElementById("vg-sel-label").textContent = `选择时长 ${keep.toFixed(1)}s · 约 ${frames} 帧`;
    document.getElementById("vg-t0").textContent = formatFcTime(this.inT).replace(/^0/, "").replace(/(\.\d)\d$/, "$1") || "0:00.0";
    // simpler labels
    document.getElementById("vg-t0").textContent = `${Math.floor(this.inT / 60)}:${String(Math.floor(this.inT % 60)).padStart(2, "0")}.${Math.floor((this.inT % 1) * 10)}`;
    document.getElementById("vg-t1").textContent = `${Math.floor(this.outT / 60)}:${String(Math.floor(this.outT % 60)).padStart(2, "0")}.${Math.floor((this.outT % 1) * 10)}`;
    const range = document.getElementById("vg-range");
    if (range && this.dur > 0) {
      range.style.left = `${(this.inT / this.dur) * 100}%`;
      range.style.width = `${(keep / this.dur) * 100}%`;
    }
    const w = Number(document.getElementById("vg-width")?.value || 480);
    const h = this.sw && this.sh ? Math.round((this.sh * w) / this.sw) : 0;
    document.getElementById("vg-dim").textContent =
      this.sw && this.sh ? `原始尺寸 ${this.sw}×${this.sh} · 输出 ${w}×${h}` : "原始尺寸 — · 输出 —";
  },

  async buildFilm() {
    const track = document.getElementById("vg-film-track");
    const video = document.getElementById("vg-video");
    if (!track || !video?.src || !(this.dur > 0)) return;
    track.innerHTML = `<div class="fc-filmstrip-loading">生成预览…</div>`;
    const helper = document.createElement("video");
    helper.muted = true;
    helper.playsInline = true;
    helper.src = video.currentSrc || video.src;
    try {
      await new Promise((res, rej) => {
        helper.onloadedmetadata = () => res();
        helper.onerror = () => rej();
      });
      const count = Math.min(20, Math.max(8, Math.round(this.dur)));
      const thumbs = [];
      for (let i = 0; i < count; i++) {
        await seekVideoElement(helper, (this.dur * i) / Math.max(1, count - 1));
        const c = document.createElement("canvas");
        const scale = 90 / Math.max(helper.videoWidth || 1, 1);
        c.width = Math.max(1, Math.round((helper.videoWidth || 1) * scale));
        c.height = Math.max(1, Math.round((helper.videoHeight || 1) * scale));
        c.getContext("2d")?.drawImage(helper, 0, 0, c.width, c.height);
        thumbs.push(c.toDataURL("image/jpeg", 0.5));
      }
      track.innerHTML = thumbs.map((u) => `<img class="fc-filmstrip-thumb" src="${u}" alt="" />`).join("");
    } catch {
      track.innerHTML = "";
    } finally {
      helper.removeAttribute("src");
      helper.load();
    }
  },

  bind() {
    if (this._bound) return;
    this._bound = true;
    const video = document.getElementById("vg-video");
    document.getElementById("vg-close")?.addEventListener("click", () => this.close());
    document.getElementById("vg-backdrop")?.addEventListener("click", () => this.close());
    document.getElementById("vg-cancel")?.addEventListener("click", () => this.close());
    document.getElementById("vg-confirm")?.addEventListener("click", () => this.confirm());
    document.getElementById("vg-reset")?.addEventListener("click", () => {
      this.inT = 0;
      this.outT = Math.min(5, this.dur || 5);
      document.getElementById("vg-format").value = "gif";
      document.getElementById("vg-fps").value = "10";
      document.getElementById("vg-width").value = "480";
      document.getElementById("vg-quality").value = "standard";
      this.updateConfirmLabel();
      this.syncUi();
    });
    document.getElementById("vg-play-overlay")?.addEventListener("click", () => {
      if (video.paused) video.play().catch(() => {});
      else video.pause();
    });
    video?.addEventListener("play", () => document.getElementById("vg-play-overlay")?.classList.add("hidden"));
    video?.addEventListener("pause", () => document.getElementById("vg-play-overlay")?.classList.remove("hidden"));
    ["vg-format", "vg-fps", "vg-width", "vg-quality"].forEach((id) => {
      document.getElementById(id)?.addEventListener("change", () => {
        this.updateConfirmLabel();
        this.syncUi();
      });
    });

    const film = document.getElementById("vg-film");
    const onPtr = (e) => {
      if (!this._drag || !film || !(this.dur > 0)) return;
      const rect = film.getBoundingClientRect();
      const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
      const t = ratio * this.dur;
      if (this._drag === "in") this.inT = Math.min(t, this.outT - 0.1);
      else this.outT = Math.max(t, this.inT + 0.1);
      this.syncUi();
    };
    document.getElementById("vg-handle-in")?.addEventListener("pointerdown", (e) => {
      this._drag = "in";
      e.currentTarget.setPointerCapture?.(e.pointerId);
    });
    document.getElementById("vg-handle-out")?.addEventListener("pointerdown", (e) => {
      this._drag = "out";
      e.currentTarget.setPointerCapture?.(e.pointerId);
    });
    window.addEventListener("pointermove", onPtr);
    window.addEventListener("pointerup", () => {
      this._drag = null;
    });
    window.addEventListener("keydown", (e) => {
      if (!this.isOpen()) return;
      if (e.key === "Escape") this.close();
    });
  },

  confirm() {
    const nodeId = this.nodeId;
    const start = this.inT;
    const end = this.outT;
    const format = document.getElementById("vg-format")?.value || "gif";
    const fps = Number(document.getElementById("vg-fps")?.value || 10);
    const width = Number(document.getElementById("vg-width")?.value || 480);
    const quality = document.getElementById("vg-quality")?.value || "standard";
    this.close();
    if (!nodeId) return;
    MediaTools.run(nodeId, "to_gif", { start, end, format, fps, width, quality });
  },
};

let nodeMediaLazyObserver = null;
let panelMediaLazyObserver = null;
let mediaLoadActive = 0;
let mediaLoadHoldDepth = 0;
const mediaLoadQueue = [];
// Browser ~6 connections/host. On LAN leave headroom for API/ping so Wi‑Fi
// media storms do not false-trigger「连接已断开」.
const _mediaHost = String(typeof location !== "undefined" ? location.hostname || "" : "");
const _mediaIsLoopback =
  _mediaHost === "127.0.0.1" || _mediaHost === "localhost" || _mediaHost === "::1";
const MEDIA_LOAD_MAX = _mediaIsLoopback ? 6 : 4;
const MEDIA_LOAD_SLOT_TIMEOUT_MS = _mediaIsLoopback ? 12000 : 20000;
const MEDIA_STUCK_RETRY_MS = _mediaIsLoopback ? 8000 : 16000;
const MEDIA_PRIO_HIGH = 0;
const MEDIA_PRIO_NORMAL = 1;
const MEDIA_PRIO_LOW = 2;
const _browserVideoEnsureCache = new Map();

function holdMediaLoadScheduler() {
  mediaLoadHoldDepth += 1;
}

function pumpMediaLoadQueue() {
  while (mediaLoadHoldDepth <= 0 && mediaLoadActive < MEDIA_LOAD_MAX && mediaLoadQueue.length) {
    const next = mediaLoadQueue.shift();
    if (next) next.fn();
  }
}

function getMediaLoadPressure() {
  return {
    active: mediaLoadActive,
    queued: mediaLoadQueue.length,
    hold: mediaLoadHoldDepth,
    max: MEDIA_LOAD_MAX,
  };
}
window.getMediaLoadPressure = getMediaLoadPressure;

function releaseMediaLoadScheduler() {
  if (mediaLoadHoldDepth <= 0) return;
  mediaLoadHoldDepth -= 1;
  if (mediaLoadHoldDepth <= 0) pumpMediaLoadQueue();
}

/** Pause background preview playback and hold the lazy-load queue for lightbox. */
function yieldMediaBandwidthForLightbox(_exceptNodeId) {
  holdMediaLoadScheduler();
  document.querySelectorAll(".node-preview.has-video video").forEach((video) => {
    try {
      video.pause();
    } catch {
      /* ignore */
    }
  });
}

function releaseMediaBandwidthAfterLightbox() {
  releaseMediaLoadScheduler();
  document.querySelectorAll(".node-preview.has-video").forEach((preview) => {
    if (!preview.isConnected) return;
    if (typeof elementNearViewport === "function" && !elementNearViewport(preview, 160)) return;
    if (typeof ensureNodeVideoLoaded === "function") ensureNodeVideoLoaded(preview);
  });
}

function uploadMediaPath(url) {
  if (!url) return "";
  const raw = String(url).replace(window.location.origin, "").split("?")[0];
  return raw.startsWith("/uploads/") ? raw : "";
}

function needsVideoNormalizePath(url) {
  const path = uploadMediaPath(url);
  return path ? !BROWSER_NATIVE_VIDEO_PATH_RE.test(path) : false;
}

async function hydrateHistoryStageVideo(video, rawUrl) {
  if (!video || !rawUrl) return;
  const normalized = await ensureBrowserPlayableVideoUrl(rawUrl, {
    force: needsVideoNormalizePath(rawUrl),
  });
  if (!video.isConnected) return;
  video.src = normalized;
  video.load();
}

async function ensureBrowserPlayableVideoUrl(url, { force = false } = {}) {
  const path = uploadMediaPath(url);
  if (!path) return resolveMediaUrl(url);
  if (force) _browserVideoEnsureCache.delete(path);
  const cached = _browserVideoEnsureCache.get(path);
  if (cached) return cached;

  const task = (async () => {
    try {
      const wbId =
        typeof WorkbenchStore !== "undefined" ? WorkbenchStore.activeWorkbench?.()?.id || null : null;
      const body = {
        url: path,
        board_id: CanvasStore.activeBoardId,
        force,
      };
      if (wbId && path.includes("/workbenches/")) body.workbench_id = wbId;
      const res = await fetch("/api/media/ensure-browser-video", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "same-origin",
        body: JSON.stringify(body),
      });
      if (!res.ok) return resolveMediaUrl(path);
      const data = await res.json();
      const out = data?.url || path;
      return resolveMediaUrl(out);
    } catch {
      return resolveMediaUrl(path);
    }
  })();

  _browserVideoEnsureCache.set(path, task);
  try {
    const resolved = await task;
    _browserVideoEnsureCache.set(path, Promise.resolve(resolved));
    return resolved;
  } catch {
    _browserVideoEnsureCache.delete(path);
    return resolveMediaUrl(path);
  }
}

function upgradeNodeVideoUrl(nodeId, oldPath, newPath, meta = {}) {
  if (!nodeId || !newPath || oldPath === newPath) return;

  if (typeof parseWbClipNodeId === "function" && nodeId.startsWith("wbclip-")) {
    const clipId = parseWbClipNodeId(nodeId);
    const hit = typeof findWbClipAnywhere === "function" ? findWbClipAnywhere(clipId) : null;
    const clip = hit?.clip || (typeof findWbClip === "function" ? findWbClip(clipId) : null);
    if (!clip) return;
    const cur = uploadMediaPath(clip.videoUrl || "");
    if (cur && cur !== oldPath && cur !== newPath) return;
    if (Array.isArray(clip.genHistory)) {
      clip.genHistory.forEach((h) => {
        if (uploadMediaPath(h.videoUrl || "") === oldPath) h.videoUrl = newPath;
      });
    }
    clip.videoUrl = newPath;
    if (meta.coverUrl) clip.coverUrl = meta.coverUrl;
    if (meta.thumbUrl) clip.thumbUrl = meta.thumbUrl;
    if (meta.mediaWidth) clip.mediaWidth = meta.mediaWidth;
    if (meta.mediaHeight) clip.mediaHeight = meta.mediaHeight;
    WorkbenchStore?.save?.();
    return;
  }

  if (typeof parseWbAssetNodeId === "function" && nodeId.startsWith("wbasset-")) {
    const assetId = parseWbAssetNodeId(nodeId);
    const wb = WorkbenchStore?.activeWorkbench?.();
    const asset =
      wb?.assets?.find((a) => a.id === assetId) ||
      wb?.episodes?.flatMap((ep) => ep.assets || []).find((a) => a.id === assetId);
    if (!asset) return;
    const cur = uploadMediaPath(asset.videoUrl || "");
    if (cur && cur !== oldPath && cur !== newPath) return;
    asset.videoUrl = newPath;
    WorkbenchStore?.save?.();
    return;
  }

  for (const board of CanvasStore.boards) {
    const node = board.nodes.find((n) => n.id === nodeId);
    if (!node) continue;
    const cur = uploadMediaPath(node.videoUrl || "");
    if (cur && cur !== oldPath && cur !== newPath) return;
    if (Array.isArray(node.genHistory)) {
      let histChanged = false;
      node.genHistory.forEach((h) => {
        if (uploadMediaPath(h.videoUrl || "") === oldPath) {
          h.videoUrl = newPath;
          histChanged = true;
        }
      });
      if (histChanged) CanvasStore.save();
    }
    CanvasStore.updateNode(nodeId, { videoUrl: newPath, ...meta });
    return;
  }
}

function mediaLoadPriorityForEl(el) {
  if (!el) return MEDIA_PRIO_NORMAL;
  if (el.classList?.contains("ws-cover-media")) return MEDIA_PRIO_LOW;
  // Open prompt expand / chip menus are what the user is looking at — don't starve them.
  if (
    el.closest?.(
      "#prompt-expand:not(.hidden), #prompt-expand:not(.hidden) .prompt-expand-box, #prompt-expand-editor, #prompt-expand-refs, #workbench-prompt-expand-refs, .workbench-clip-refs, .wb-studio-refs, .mention-menu, .mention-preview, .mention-chip-tooltip"
    )
  ) {
    return MEDIA_PRIO_HIGH;
  }
  // Workbench is outside the canvas viewport — still prioritize visible clip videos.
  if (el.closest?.("#workbench-view, .workbench-clip-preview, .wb-studio-preview")) {
    return MEDIA_PRIO_HIGH;
  }
  const wrap = el.closest?.(".node-wrap");
  if (wrap?.classList.contains("is-selected") || wrap?.classList.contains("is-picked")) {
    return MEDIA_PRIO_HIGH;
  }
  if (wrap?.classList.contains("is-offscreen")) return MEDIA_PRIO_LOW;
  const nodeId = wrap?.dataset?.id || el.dataset?.node;
  if (nodeId) {
    const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
    if (node && isNodeInViewport(node, VIEWPORT_CULL_MARGIN)) return MEDIA_PRIO_HIGH;
    if (node && isNodeInViewport(node, VIEWPORT_PRELOAD_MARGIN)) return MEDIA_PRIO_NORMAL;
  }
  return MEDIA_PRIO_NORMAL;
}

/** Chip thumbs: boost when the user is looking at expand/selected panel; else keep low. */
function mediaThumbLoadPriority(img) {
  if (!img) return MEDIA_PRIO_LOW;
  if (
    img.closest(
      "#prompt-expand:not(.hidden), #prompt-expand:not(.hidden) .prompt-expand-box, #prompt-expand-editor, #prompt-expand-refs, #workbench-prompt-expand-refs, .workbench-clip-refs, .wb-studio-refs, .mention-menu, .mention-preview"
    )
  ) {
    return MEDIA_PRIO_HIGH;
  }
  const wrap = img.closest(".node-wrap");
  // Selected / expanded panel chips are what the user is staring at — same urgency as posters.
  if (
    wrap?.classList.contains("is-selected") ||
    wrap?.classList.contains("expanded") ||
    wrap?.classList.contains("is-picked")
  ) {
    return MEDIA_PRIO_HIGH;
  }
  if (
    img.closest(
      ".ref-chip, .ref-inputs, .panel-qm-records-host, .quick-mention-chip, .panel-refs, .panel-prompt-wrap, .mention-chip"
    )
  ) {
    return MEDIA_PRIO_LOW;
  }
  return mediaLoadPriorityForEl(img);
}

/** True when the browser already has this URL decoded in memory (disk/memory cache). */
function isLikelyCachedImageUrl(src) {
  if (!src || (typeof isMediaMissingUrl === "function" && isMediaMissingUrl(src))) return false;
  try {
    const probe = new Image();
    probe.src = src;
    return !!(probe.complete && probe.naturalWidth > 0);
  } catch {
    return false;
  }
}

function enqueueMediaLoad(item) {
  const idx = mediaLoadQueue.findIndex((x) => x.priority > item.priority);
  if (idx === -1) mediaLoadQueue.push(item);
  else mediaLoadQueue.splice(idx, 0, item);
}

function scheduleMediaLoad(run, priority = MEDIA_PRIO_NORMAL) {
  const start = () => {
    mediaLoadActive += 1;
    let finished = false;
    const finish = () => {
      if (finished) return;
      finished = true;
      mediaLoadActive = Math.max(0, mediaLoadActive - 1);
      pumpMediaLoadQueue();
    };
    try {
      // Caller must invoke finish() when the load settles OR times out.
      run(finish);
    } catch {
      finish();
    }
  };
  if (mediaLoadHoldDepth > 0 || mediaLoadActive >= MEDIA_LOAD_MAX) {
    enqueueMediaLoad({ priority, fn: start });
    return;
  }
  start();
}

/**
 * Run a media load with a hard ceiling. If load/error never fires, clear the
 * early `dataset.loaded` claim so hydrate can retry — otherwise cards spin forever.
 */
function runMediaLoadWithTimeout(runLoad, onTimeout, onRelease) {
  let settled = false;
  let released = false;
  const release = (timedOut = false) => {
    if (released) return;
    released = true;
    if (timedOut && !settled) {
      try {
        onTimeout?.();
      } catch {
        /* ignore */
      }
    }
    try {
      onRelease?.();
    } catch {
      /* ignore */
    }
  };
  const localTimer = setTimeout(() => release(true), MEDIA_LOAD_SLOT_TIMEOUT_MS);
  try {
    runLoad(() => {
      settled = true;
      clearTimeout(localTimer);
      release(false);
    });
  } catch {
    clearTimeout(localTimer);
    release(true);
  }
}

function markWorkspaceCoverState(el, ok) {
  const cover = el?.closest?.(".workspace-board-cover");
  if (!cover) return;
  cover.classList.remove("is-cover-loading");
  cover.classList.toggle("is-cover-ready", !!ok);
  cover.classList.toggle("is-cover-empty", !ok);
}

function ensureLazyImage(img, priority) {
  if (!img) return;
  // Stale queue claim: never started (hold / starvation) — free so hydrate can retry.
  if (
    img.dataset.mediaQueued === "1" &&
    !img.dataset.mediaLoadStartedAt &&
    img.dataset.loaded !== "1"
  ) {
    const queuedAt = Number(img.dataset.mediaLoadQueuedAt || 0);
    if (queuedAt && Date.now() - queuedAt > MEDIA_LOAD_SLOT_TIMEOUT_MS) {
      delete img.dataset.mediaQueued;
      delete img.dataset.mediaLoadQueuedAt;
      // Keep the sequence monotonic so an older queued job cannot own this retry.
    }
  }
  if (img.dataset.loaded === "1" || img.dataset.mediaQueued === "1") return;
  const src = img.dataset.src || "";
  if (!src) {
    if (img.src) img.dataset.loaded = "1";
    return;
  }
  const isWsCover = img.classList.contains("ws-cover-media");
  // Workspace covers: never re-request URLs that already 404'd this session.
  if (isWsCover && isKnownMediaUrl404(src)) {
    img.dataset.loaded = "1";
    markWorkspaceCoverState(img, false);
    const wrap = img.closest(".workspace-board-cover");
    img.remove();
    if (wrap && !wrap.querySelector(".workspace-board-cover-empty, .ws-cover-media")) {
      wrap.insertAdjacentHTML(
        "beforeend",
        `<span class="workspace-board-cover-empty">${wrap.classList.contains("workbench-cover") ? "工作台" : "暂无封面"}</span>`
      );
    }
    return;
  }
  const isNodePreview = img.classList.contains("node-preview-img");
  const isVideoPoster = img.classList.contains("node-video-poster-img");
  const isThumb = img.classList.contains("media-thumb-lazy");
  const fullSrc = img.dataset.fullSrc || "";
  const attempt = String((Number(img.dataset.mediaLoadAttempt) || 0) + 1);
  img.dataset.mediaLoadAttempt = attempt;
  img.dataset.mediaLoadQueuedAt = String(Date.now());
  // Queue claim only — set loaded when the network request actually starts.
  img.dataset.mediaQueued = "1";
  const prio = priority ?? mediaLoadPriorityForEl(img);
  if (isNodePreview) setPreviewMediaLoading(img, true);
  let removeLoadListeners = () => {};
  const clearClaim = () => {
    removeLoadListeners();
    if (img.dataset.mediaLoadAttempt !== attempt) return;
    if (img.classList.contains("is-media-loaded")) return;
    img.dataset.loaded = "";
    delete img.dataset.mediaQueued;
    delete img.dataset.mediaLoadQueuedAt;
    delete img.dataset.mediaLoadStartedAt;
    if (isNodePreview) setPreviewMediaLoading(img, false);
  };
  const runLoad = (done) => {
    // Chip thumbs stay painted across cull — don't abort just because the host
    // card scrolled cold (that previously left hollow chips).
    if (img.dataset.mediaLoadAttempt !== attempt) {
      done();
      return;
    }
    if (img.dataset.src !== src) {
      clearClaim();
      done();
      if (img.isConnected) ensureLazyImage(img, prio);
      return;
    }
    if (!img.isConnected || (!isThumb && img.closest(".node-wrap")?.classList.contains("is-offscreen"))) {
      clearClaim();
      done();
      return;
    }
    img.dataset.loaded = "1";
    delete img.dataset.mediaQueued;
    img.dataset.mediaLoadStartedAt = String(Date.now());
    let finished = false;
    const onDone = (ok = true) => {
      if (finished) return;
      finished = true;
      removeLoadListeners();
      if (img.dataset.mediaLoadAttempt !== attempt) {
        done();
        return;
      }
      delete img.dataset.mediaLoadQueuedAt;
      delete img.dataset.mediaLoadStartedAt;
      if (ok) {
        img.classList.add("is-media-loaded");
        if (isThumb) noteChipThumbPainted(img.currentSrc || img.src || src);
        if (isVideoPoster) {
          const preview = img.closest(".node-preview");
          if (preview?._posterFallbackTimer) {
            clearTimeout(preview._posterFallbackTimer);
            preview._posterFallbackTimer = null;
          }
          preview?.classList.remove("is-frame-preview", "is-paused-frame", "is-poster-loading");
          delete preview?.dataset?.framePreview;
          preview.dataset.posterReady = "1";
          const video = preview?.querySelector("video");
          const okSrc = img.currentSrc || img.src || "";
          if (video && okSrc && !isMediaMissingUrl(okSrc)) {
            video.setAttribute("poster", okSrc);
          }
          syncVideoPreviewPendingState(preview);
        }
        if (isNodePreview && fullSrc) {
          const loaded = img.currentSrc || img.src || "";
          img.dataset.usingFull = loaded === fullSrc || img.dataset.forceFull === "1" ? "1" : "0";
          if (img.naturalWidth) img.dataset.thumbWidth = String(img.naturalWidth);
          const preview = img.closest(".node-preview");
          preview?.classList.remove("is-preview-upgrading", "is-media-pending");
          if (shouldUpgradeNodePreviewToFull(img)) upgradeNodePreviewToFull(img);
          else setPreviewMediaLoading(img, false);
        } else if (isNodePreview) {
          setPreviewMediaLoading(img, false);
        }
        if (isNodePreview && img.naturalWidth > 0 && img.naturalHeight > 0) {
          const nodeId = img.dataset.node;
          if (nodeId) tryApplyNodeMediaDimensions(nodeId, img.naturalWidth, img.naturalHeight);
        }
        if (isVideoPoster && img.naturalWidth > 0 && img.naturalHeight > 0) {
          const nodeId = img.closest(".node-preview")?.dataset?.videoNode;
          if (nodeId) tryApplyNodeMediaDimensions(nodeId, img.naturalWidth, img.naturalHeight);
        }
        if (isWsCover) markWorkspaceCoverState(img, true);
      } else if (isWsCover) {
        noteMediaUrl404(src);
        markWorkspaceCoverState(img, false);
        const wrap = img.closest(".workspace-board-cover");
        img.remove();
        if (wrap && !wrap.querySelector(".workspace-board-cover-empty, .ws-cover-media")) {
          wrap.insertAdjacentHTML(
            "beforeend",
            `<span class="workspace-board-cover-empty">${wrap.classList.contains("workbench-cover") ? "工作台" : "暂无封面"}</span>`
          );
        }
      } else if (isNodePreview && fullSrc && src !== fullSrc && img.dataset.forceFull !== "1") {
        img.dataset.loaded = "";
        img.dataset.src = fullSrc;
        img.dataset.forceFull = "1";
        ensureLazyImage(img, MEDIA_PRIO_HIGH);
      } else if (img.dataset.loadRetry !== "1" && src && !isMediaMissingUrl(src) && !isKnownMediaUrl404(src)) {
        // Retry the original URL. Appending a cache-buster invalidates signed
        // remote URLs and turns a transient network failure into a permanent one.
        img.dataset.loaded = "";
        img.classList.remove("is-media-loaded");
        if (isNodePreview) setPreviewMediaLoading(img, false);
        img.dataset.loadRetry = "1";
        img.dataset.src = src;
        setTimeout(() => {
          if (img.isConnected && img.dataset.loaded !== "1") ensureLazyImage(img, MEDIA_PRIO_HIGH);
        }, 500);
      } else {
        noteMediaUrl404(src);
        img.dataset.loaded = "1";
        if (isNodePreview) setPreviewMediaLoading(img, false);
        if (isVideoPoster) {
          const preview = img.closest(".node-preview");
          if (!showVideoFirstFrameInsteadOfMissingPoster(preview, src)) {
            // Still no video src — hide broken poster; never show「文件不存在」on video nodes.
            img.classList.remove("is-media-loaded", "is-media-missing");
            img.hidden = true;
            img.removeAttribute("src");
            delete img.dataset.src;
            preview?.classList.remove("is-poster-loading");
          }
          syncVideoPreviewPendingState(preview);
        } else {
          applyMediaMissingFallback(img, { markChip: !isNodePreview });
        }
      }
      done();
    };
    const onLoad = () => onDone(true);
    const onError = () => {
      if (isVideoPoster && !isMediaMissingUrl(img.dataset.src || img.src)) {
        const preview = img.closest(".node-preview");
        if (preview?._posterFallbackTimer) {
          clearTimeout(preview._posterFallbackTimer);
          preview._posterFallbackTimer = null;
        }
        const failedSrc = img.dataset.src || img.src || "";
        // When the video file exists, show its first frame — never the「文件不存在」placeholder.
        if (showVideoFirstFrameInsteadOfMissingPoster(preview, failedSrc)) {
          onDone(true);
          return;
        }
        // Never stamp「文件不存在」onto a video poster — hide and wait for frame.
        img.classList.remove("is-media-loaded", "is-media-missing");
        img.hidden = true;
        img.removeAttribute("src");
        delete img.dataset.src;
        preview?.classList.remove("is-poster-loading");
        onDone(true);
        return;
      }
      onDone(false);
    };
    removeLoadListeners = () => {
      img.removeEventListener("load", onLoad);
      img.removeEventListener("error", onError);
    };
    img.addEventListener("load", onLoad, { once: true });
    img.addEventListener("error", onError, { once: true });
    img.src = src;
    // Do not race decode() against load — a premature reject was marking images "loaded" while blank.
    if (img.complete && img.naturalWidth > 0) onDone(true);
  };
  // Chip thumbs are tiny (~32px) — never queue them behind canvas videos.
  // Focused posters also bypass so selected cards stay snappy.
  if (isThumb || (isVideoPoster && prio <= MEDIA_PRIO_HIGH)) {
    runMediaLoadWithTimeout(runLoad, clearClaim);
  } else {
    scheduleMediaLoad((slotDone) => {
      runMediaLoadWithTimeout(runLoad, clearClaim, slotDone);
    }, prio);
  }
}

function shouldShowNodePreviewVideoEl(preview) {
  if (!preview) return false;
  // Workbench clip preview: always show the video layer (normal player first-frame).
  if (preview.dataset?.wbPreview === "1" || preview.closest?.("#workbench-view, .workbench-clip-preview")) {
    return true;
  }
  if (
    preview.classList.contains("is-playing") ||
    preview.classList.contains("is-frame-preview") ||
    preview.classList.contains("is-paused-frame")
  ) {
    return true;
  }
  if (preview.classList.contains("is-hovering") && preview.dataset.userPaused !== "1") return true;
  const wrap = preview.closest(".node-wrap");
  return Boolean(wrap?.classList.contains("is-selected") && !wrap.classList.contains("is-picked"));
}

function markLazyVideoVisible(video, opts = {}) {
  if (!video) return;
  const preview = video.closest(".node-preview.has-video");
  const isNodeVid = video.classList.contains("node-preview-vid-el");
  const force = opts.force === true;
  const show = force || !isNodeVid || shouldShowNodePreviewVideoEl(preview);
  video.dataset.mediaReady = "1";
  if (show) video.classList.add("is-media-loaded");
  else video.classList.remove("is-media-loaded");
  // Keep data-src until metadata actually arrives — otherwise workbench hydrate/retry
  // cannot recover when Chromium stays at readyState 0 (black 0:00/0:00).
  const playable = video.readyState >= 1 || video.videoWidth > 0;
  if (playable && (video.getAttribute("src") || video.currentSrc)) {
    video.removeAttribute("data-src");
    delete video.dataset.src;
  }
}

const previewVideoTransfers = new WeakMap();
function beginPreviewVideoTransfer(video, src) {
  const previous = previewVideoTransfers.get(video);
  previous?.cleanup?.();
  const failures = previous?.src === src && video.readyState < 1 ? Math.min(previous.failures + 1, 3) : 0;
  const now = Date.now();
  const state = {src, failures, started: now, progress: now};
  const onProgress = () => { state.progress = Date.now(); };
  const onReady = () => { state.failures = 0; };
  video.addEventListener("progress", onProgress);
  video.addEventListener("loadedmetadata", onReady);
  state.cleanup = () => {
    video.removeEventListener("progress", onProgress);
    video.removeEventListener("loadedmetadata", onReady);
  };
  previewVideoTransfers.set(video, state);
}

function previewVideoTransferPending(video, src) {
  const state = previewVideoTransfers.get(video);
  if (!state || state.src !== src || video.readyState >= 1) return false;
  // An explicit offscreen release/source change must still be able to reload.
  if (video.getAttribute("src") !== state.src) return false;
  const now = Date.now();
  const idle = Math.min(120000, 30000 * 2 ** state.failures);
  return now - state.progress < idle && now - state.started < 180000;
}

/**
 * Keep the scheduler slot occupied while the browser is still downloading.
 * Slot timeouts used to free the seat early; later videos then opened extra
 * connections on top of unfinished Range GETs and starved /api/* on LAN.
 */
function releaseMediaSlotWhenTransferSettles(video, src, slotDone) {
  if (typeof slotDone !== "function") return;
  let polls = 0;
  const tick = () => {
    polls += 1;
    if (!video?.isConnected || polls > 180 || !previewVideoTransferPending(video, src)) {
      slotDone();
      return;
    }
    setTimeout(tick, 1000);
  };
  tick();
}

function ensureLazyVideoEl(video, priority) {
  if (!video) return;
  // Hydration, hover and recovery can all visit the same video before metadata
  // arrives. Keep the current request (or queue slot) instead of restarting it.
  const requestedSrc = video.dataset.src || video.getAttribute("src") || video.currentSrc || "";
  if (previewVideoTransferPending(video, requestedSrc)) return;
  const claimAt = Number(video.dataset.mediaLoadStartedAt || video.dataset.mediaLoadQueuedAt || 0);
  if (
    video.dataset.loaded === "1" &&
    video.dataset.loadedSrc === requestedSrc &&
    claimAt && Date.now() - claimAt < MEDIA_LOAD_SLOT_TIMEOUT_MS
  ) return;
  let src = video.dataset.src || "";
  if (!src) {
    const attrSrc = video.getAttribute("src") || video.currentSrc || "";
    // Stuck: src was applied but never became playable (and data-src already cleared).
    if (attrSrc && video.readyState < 1 && video.videoWidth <= 0) {
      src = attrSrc;
      video.dataset.src = attrSrc;
      video.dataset.loaded = "";
      delete video.dataset.loadedSrc;
      video.classList.remove("is-media-loaded");
      try {
        video.removeAttribute("src");
        video.load();
      } catch {
        /* ignore */
      }
    } else if (attrSrc) {
      video.dataset.loaded = "1";
      const preview = video.closest(".node-preview.has-video");
      const isNodeVid = video.classList.contains("node-preview-vid-el");
      const show = !isNodeVid || shouldShowNodePreviewVideoEl(preview) || shouldNodeVideoAutoplay(preview);
      markLazyVideoVisible(video, { force: show });
      return;
    } else {
      return;
    }
  }
  const prevSrc = video.dataset.loadedSrc || "";
  if (video.dataset.loaded === "1") {
    if (prevSrc === src) {
      // Same URL marked loaded but still no metadata — force a real reload.
      if (video.readyState < 1 && video.videoWidth <= 0) {
        video.dataset.loaded = "";
        delete video.dataset.loadedSrc;
        video.classList.remove("is-media-loaded");
        try {
          video.removeAttribute("src");
          video.load();
        } catch {
          /* ignore */
        }
      } else {
        if (!video.classList.contains("is-media-loaded") && video.readyState >= 2) {
          const preview = video.closest(".node-preview.has-video");
          const show =
            !video.classList.contains("node-preview-vid-el") ||
            shouldShowNodePreviewVideoEl(preview) ||
            shouldNodeVideoAutoplay(preview);
          markLazyVideoVisible(video, { force: show });
        }
        return;
      }
    } else {
      video.dataset.loaded = "";
      video.classList.remove("is-media-loaded");
      try {
        video.removeAttribute("src");
        video.load();
      } catch {
        /* ignore */
      }
    }
  }
  video.dataset.loaded = "1";
  video.dataset.loadedSrc = src;
  const attempt = String((Number(video.dataset.mediaLoadAttempt) || 0) + 1);
  video.dataset.mediaLoadAttempt = attempt;
  video.dataset.mediaLoadQueuedAt = String(Date.now());
  const isWsCover = video.classList.contains("ws-cover-media");
  const isNodeVid = video.classList.contains("node-preview-vid-el");
  const isThumbVid = video.classList.contains("media-thumb-lazy-vid");
  const framePreview = isNodeVid && video.closest(".node-preview")?.classList.contains("is-frame-preview");
  const prio = priority ?? (isThumbVid ? mediaThumbLoadPriority(video) : mediaLoadPriorityForEl(video));
  let removeLoadListeners = () => {};
  const clearClaim = () => {
    removeLoadListeners();
    if (video.dataset.mediaLoadAttempt !== attempt) return;
    if (video.classList.contains("is-media-loaded") && (video.readyState >= 1 || video.videoWidth > 0)) return;
    video.dataset.loaded = "";
    delete video.dataset.loadedSrc;
    delete video.dataset.mediaLoadQueuedAt;
    delete video.dataset.mediaLoadStartedAt;
    const preview = video.closest(".node-preview.has-video");
    if (preview) syncVideoPreviewPendingState(preview);
  };
  const runLoad = (done) => {
    // A timed-out queued job may have been replaced before it gets a slot.
    if (video.dataset.mediaLoadAttempt !== attempt) {
      done();
      return;
    }
    if (!video.isConnected || (!isThumbVid && video.closest(".node-wrap")?.classList.contains("is-offscreen"))) {
      clearClaim();
      done();
      return;
    }
    video.dataset.mediaLoadStartedAt = String(Date.now());
    let finished = false;
    const onDone = (ok = true) => {
      if (finished) return;
      finished = true;
      removeLoadListeners();
      if (video.dataset.mediaLoadAttempt !== attempt) {
        done();
        return;
      }
      delete video.dataset.mediaLoadQueuedAt;
      delete video.dataset.mediaLoadStartedAt;
      const preview = video.closest(".node-preview.has-video");
      if (ok) {
        const show =
          isWsCover ||
          !isNodeVid ||
          framePreview ||
          shouldShowNodePreviewVideoEl(preview) ||
          shouldNodeVideoAutoplay(preview);
        markLazyVideoVisible(video, { force: show });
        if (isWsCover) markWorkspaceCoverState(video, true);
        // Only drop pending when something is actually visible — otherwise hollow black.
        syncVideoPreviewPendingState(preview);
      } else if (isWsCover) {
        markWorkspaceCoverState(video, false);
        video.remove();
      } else {
        markLazyVideoVisible(video, { force: false });
        syncVideoPreviewPendingState(preview);
      }
      done();
    };
    const tryReady = () => {
      const ready = framePreview ? video.readyState >= 1 || video.videoWidth > 0 : video.readyState >= 2 || video.videoWidth > 0;
      if (ready) {
        probeNodeVideoDimensions(video);
        onDone(true);
      }
    };
    const retryAfterNormalize = async () => {
      if (finished || video.dataset.mediaLoadAttempt !== attempt) return;
      if (video.dataset.normalizeRetry === "1") {
        onDone(false);
        return;
      }
      const path = uploadMediaPath(src);
      if (!path) {
        onDone(false);
        return;
      }
      video.dataset.normalizeRetry = "1";
      try {
        // Never force re-encode: force used to wipe an already-playable file.
        const normalized = await ensureBrowserPlayableVideoUrl(src, {
          force: needsVideoNormalizePath(src),
        });
        if (!video.isConnected || video.dataset.mediaLoadAttempt !== attempt) {
          onDone(false);
          return;
        }
        const preview = video.closest(".node-preview.has-video");
        const nodeId = preview?.dataset?.videoNode;
        const nextPath = uploadMediaPath(normalized);
        if (nodeId && nextPath && nextPath !== path) {
          upgradeNodeVideoUrl(nodeId, path, nextPath);
        }
        video.dataset.loaded = "";
        delete video.dataset.loadedSrc;
        video.classList.remove("is-media-loaded");
        video.dataset.src = normalized;
        video.dataset.browserReady = "1";
        ensureLazyVideoEl(video);
        // The replacement load owns a new attempt. Always finish this failed
        // attempt so it cannot permanently occupy a media scheduler slot.
        onDone(false);
      } catch {
        onDone(false);
      }
    };
    video.addEventListener("loadeddata", tryReady, { once: true });
    video.addEventListener("loadedmetadata", tryReady, { once: true });
    video.addEventListener("canplay", tryReady, { once: true });
    video.addEventListener("playing", tryReady, { once: true });
    const onError = () => {
      void retryAfterNormalize();
    };
    video.addEventListener("error", onError, { once: true });
    removeLoadListeners = () => {
      for (const event of ["loadeddata", "loadedmetadata", "canplay", "playing"]) {
        video.removeEventListener(event, tryReady);
      }
      video.removeEventListener("error", onError);
    };
    video.preload = isWsCover ? "auto" : isNodeVid ? "metadata" : "auto";
    beginPreviewVideoTransfer(video, src);
    video.src = src;
    // Keep dataset.src until we know load succeeded — allows hydrate/retry to re-run.
    try {
      video.load();
    } catch {
      onDone();
    }
    if (video.readyState >= (framePreview ? 1 : 2)) tryReady();
  };
  // Every <video> load counts against MEDIA_LOAD_MAX. Frame-preview / chip
  // thumbs used to bypass the queue and could open dozens of concurrent GETs
  // on multi-clip boards (especially without posters), saturating the host.
  scheduleMediaLoad((slotDone) => {
    runMediaLoadWithTimeout(runLoad, clearClaim, () => {
      releaseMediaSlotWhenTransferSettles(video, src, slotDone);
    });
  }, prio);
}

function getNodeMediaLazyObserver() {
  if (nodeMediaLazyObserver) return nodeMediaLazyObserver;
  const root = document.getElementById("viewport") || null;
  nodeMediaLazyObserver = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        const target = entry.target;
        if (entry.isIntersecting) {
          if (target.matches?.("img.node-preview-img[data-src]")) ensureLazyImage(target);
          else if (target.classList?.contains("has-video")) hydrateNodeVideoPoster(target);
          return;
        }
        const video = target.classList?.contains("has-video")
          ? target.querySelector("video")
          : target.tagName === "VIDEO"
            ? target
            : null;
        if (video) {
          try {
            video.pause();
          } catch {
            /* ignore */
          }
        }
      });
    },
    { root, rootMargin: "220px", threshold: 0.02 }
  );
  return nodeMediaLazyObserver;
}

/** @deprecated use getNodeMediaLazyObserver */
function getNodeVideoLazyObserver() {
  return getNodeMediaLazyObserver();
}

function ensureNodeVideoLoaded(preview) {
  const video = preview?.querySelector("video");
  if (!video) return;

  const rawSrc = video.dataset.src || video.getAttribute("src") || "";
  if (!rawSrc) return;

  if (video.dataset.browserReady === "1") {
    if (video.dataset.src) ensureLazyVideoEl(video);
    return;
  }

  const uploadPath = uploadMediaPath(rawSrc);
  // mp4/webm/mov: load directly — skip server probe/transcode round-trip
  if (uploadPath && !needsVideoNormalizePath(rawSrc)) {
    video.dataset.browserReady = "1";
    if (video.dataset.src) ensureLazyVideoEl(video);
    return;
  }

  if (uploadPath && video.dataset.browserNormalize !== "pending") {
    video.dataset.browserNormalize = "pending";
    preview?.classList.add("is-video-buffering");
    void (async () => {
      try {
        const beforePath = uploadPath;
        const normalized = await ensureBrowserPlayableVideoUrl(rawSrc, {
          force: needsVideoNormalizePath(rawSrc),
        });
        if (!video.isConnected || !preview.isConnected) return;
        const afterPath = uploadMediaPath(normalized);
        if (afterPath && afterPath !== beforePath) {
          const nodeId = preview.dataset.videoNode;
          upgradeNodeVideoUrl(nodeId, beforePath, afterPath);
          _browserVideoEnsureCache.set(beforePath, Promise.resolve(normalized));
          _browserVideoEnsureCache.set(afterPath, Promise.resolve(normalized));
          video.dataset.src = normalized;
          video.dataset.loaded = "";
          delete video.dataset.loadedSrc;
          video.classList.remove("is-media-loaded");
        } else if (normalized) {
          // Same path after normalize — still restore lazy src so load can proceed.
          video.dataset.src = normalized;
        }
        video.dataset.browserReady = "1";
        if (video.dataset.src) ensureLazyVideoEl(video);
        else if (video.src && !video.classList.contains("is-media-loaded")) {
          const show = shouldShowNodePreviewVideoEl(preview) || shouldNodeVideoAutoplay(preview);
          markLazyVideoVisible(video, { force: show });
        }
      } finally {
        video.dataset.browserNormalize = "done";
        preview?.classList.remove("is-video-buffering");
      }
    })();
    return;
  }

  if (video.dataset.src) ensureLazyVideoEl(video);
}

function elementNearViewport(el, margin = 100) {
  if (!el?.getBoundingClientRect) return false;
  const root = document.getElementById("viewport");
  const r = el.getBoundingClientRect();
  const v = root?.getBoundingClientRect?.() || { left: 0, top: 0, right: innerWidth, bottom: innerHeight };
  return r.right >= v.left - margin && r.left <= v.right + margin && r.bottom >= v.top - margin && r.top <= v.bottom + margin;
}

function resetStuckNodeImage(img, opts = {}) {
  if (!img || img.naturalWidth > 0 || !elementNearViewport(img)) return false;
  const isFallback = img.dataset.missingFallback === "1" || img.classList.contains("is-media-missing");
  if (isFallback && !opts.retryFallback) return false;
  const since = Number(img.dataset.mediaLoadStartedAt || img.dataset.mediaLoadQueuedAt || 0);
  if (!isFallback && img.dataset.loaded === "1" && since && Date.now() - since < MEDIA_STUCK_RETRY_MS) return false;
  if (isFallback) {
    const retries = Number(img.dataset.resumeRetry || 0);
    if (retries >= 2) return false;
    img.dataset.resumeRetry = String(retries + 1);
  }
  const wrap = img.closest(".node-wrap");
  const nodeId = img.dataset.node || wrap?.dataset?.id;
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  if (!node?.imageUrl) return false;
  const sources = nodeImagePreviewSources(node);
  const src = pickNodePreviewImageSrc(node, img) || sources.thumb || sources.full;
  if (!src) return false;
  _media404UrlKeys.delete(mediaUrlCacheKey(src));
  _media404UrlKeys.delete(mediaUrlCacheKey(sources.full));
  nodeMediaLazyObserver?.unobserve?.(img);
  img.dataset.loaded = "";
  img.dataset.lazyObserved = "";
  img.dataset.loadRetry = "";
  img.dataset.src = src;
  if (sources.full) img.dataset.fullSrc = sources.full;
  delete img.dataset.missingFallback;
  delete img.dataset.mediaLoadQueuedAt;
  delete img.dataset.mediaLoadStartedAt;
  img.classList.remove("is-media-loaded", "is-media-missing", "is-broken-media");
  img.removeAttribute("src");
  setPreviewMediaLoading(img, false);
  return true;
}

function resetStuckNodeVideo(preview) {
  const video = preview?.querySelector("video");
  if (!video || !elementNearViewport(preview)) return false;
  if (previewVideoTransferPending(video, video.dataset.src || video.getAttribute("src") || "")) return false;
  if (nodeVideoPreviewIsPainted(preview)) return false;
  const since = Number(video.dataset.mediaLoadStartedAt || video.dataset.mediaLoadQueuedAt || 0);
  // Don't wait the full stuck timeout when the card is visibly empty after a cull.
  const hollow =
    !video.getAttribute("src") &&
    !video.currentSrc &&
    !nodeVideoPosterIsReady(preview);
  if (!hollow && video.dataset.loaded === "1" && since && Date.now() - since < MEDIA_STUCK_RETRY_MS) {
    return false;
  }
  const nodeId = preview.dataset.videoNode;
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  const src = node?.videoUrl ? resolveMediaUrl(node.videoUrl) : video.dataset.src || video.getAttribute("src") || "";
  if (!src) return false;
  nodeMediaLazyObserver?.unobserve?.(preview);
  preview.dataset.videoHydrated = "";
  preview.dataset.lazyObserved = "";
  const poster = node ? nodeVideoPosterUrl(node) : "";
  if (!poster) {
    preview.dataset.framePreview = "1";
    preview.classList.add("is-frame-preview");
  } else {
    delete preview.dataset.framePreview;
  }
  video.dataset.loaded = "";
  video.dataset.src = src;
  delete video.dataset.loadedSrc;
  delete video.dataset.browserReady;
  delete video.dataset.mediaLoadQueuedAt;
  delete video.dataset.mediaLoadStartedAt;
  video.classList.remove("is-media-loaded");
  try {
    video.removeAttribute("src");
    video.load();
  } catch {
    /* ignore */
  }
  return true;
}

function hydrateVisibleNodeMedia(root = document.getElementById("nodes-layer"), opts = {}) {
  if (isCanvasInteractionActive()) { scheduleCanvasBackgroundWork(); return; }
  if (!root) return;
  syncNodeViewportCull();
  root.querySelectorAll(".node-wrap:not(.is-offscreen)[data-media-needs-hydrate='1']").forEach((wrap) => {
    rehydrateNodeWrapMedia(wrap);
  });
  root.querySelectorAll(".node-wrap:not(.is-offscreen) img.node-preview-img[data-src]:not(.is-media-loaded)").forEach((img) => {
    resetStuckNodeImage(img, opts);
    observeNodeImageLazy(img);
  });
  if (opts.retryFallback) {
    root.querySelectorAll(".node-wrap:not(.is-offscreen) img.node-preview-img.is-media-missing").forEach((img) => {
      if (resetStuckNodeImage(img, opts)) observeNodeImageLazy(img);
    });
  }
  root.querySelectorAll(".node-wrap:not(.is-offscreen) img.node-preview-img[src]:not([data-src])").forEach((img) => {
    const probeImg = () => {
      if (img.naturalWidth > 0 && img.naturalHeight > 0) {
        const nodeId = img.dataset.node || img.closest(".node-wrap")?.dataset?.id;
        if (nodeId) tryApplyNodeMediaDimensions(nodeId, img.naturalWidth, img.naturalHeight);
      }
    };
    if (img.complete) probeImg();
    else img.addEventListener("load", probeImg, { once: true });
  });
  root.querySelectorAll(".node-wrap:not(.is-offscreen) .node-preview.has-video").forEach((preview) => {
    resetStuckNodeVideo(preview);
    // Stuck「文件不存在」poster must not block recovery.
    const posterImg = preview.querySelector(".node-video-poster-img.is-media-loaded");
    const posterSrc = posterImg?.currentSrc || posterImg?.src || posterImg?.dataset?.src || "";
    if (posterImg && (posterImg.classList.contains("is-media-missing") || isMediaMissingUrl(posterSrc))) {
      delete preview.dataset.videoHydrated;
      showVideoFirstFrameInsteadOfMissingPoster(preview, posterSrc);
      syncVideoPreviewPendingState(preview);
      return;
    }
    if (!videoPreviewLooksHollow(preview)) {
      preview.dataset.videoHydrated = "1";
      syncVideoPreviewPendingState(preview);
      // Long-idle Chromium can keep readyState but paint black — nudge a still.
      if (opts.nudgeFrames !== false) nudgePausedVideoFrame(preview);
      return;
    }
    delete preview.dataset.videoHydrated;
    preview.dataset.lazyObserved = "";
    const wrap = preview.closest(".node-wrap");
    if (wrap) delete wrap.dataset.mediaNeedsHydrate;
    ensureVideoFirstFrameVisible(preview);
    observeNodeVideoLazy(preview);
    syncVideoPreviewPendingState(preview);
    preview.dataset.videoHydrated = nodeVideoPreviewIsPainted(preview) ? "1" : "";
  });
}

function recoverVisibleCanvasMedia(opts = {}) {
  if (document.visibilityState === "hidden") return;
  if (_viewportInteracting || CanvasStore.isDragging) return;
  if (document.getElementById("app-root")?.classList.contains("is-workspace")) return;
  hydrateVisibleNodeMedia(document.getElementById("nodes-layer"), opts);
}
window.recoverVisibleCanvasMedia = recoverVisibleCanvasMedia;

function initCanvasMediaRecovery() {
  if (window.__canvasMediaRecoveryBound) return;
  window.__canvasMediaRecoveryBound = true;
  let resumeRaf = 0;
  const resume = () => {
    if (resumeRaf) return;
    resumeRaf = requestAnimationFrame(() => {
      resumeRaf = 0;
      recoverVisibleCanvasMedia({ retryFallback: true });
      syncAllNodeVideoPlayback();
    });
  };
  window.addEventListener("focus", resume);
  window.addEventListener("pageshow", resume);
  document.addEventListener("visibilitychange", () => {
    if (document.visibilityState === "visible") resume();
    else {
      document.querySelectorAll("video, audio").forEach((media) => media.pause());
      document.querySelectorAll(".node-preview.has-video.is-hovering").forEach((preview) => {
        preview.classList.remove("is-hovering");
      });
    }
  });
  // Hollow video first-frames need faster repair than the old 12s tick.
  window.setInterval(() => recoverVisibleCanvasMedia({ nudgeFrames: true }), 4000);
}

function observeNodeImageLazy(img) {
  if (!img || img.dataset.lazyObserved === "1") return;
  img.dataset.lazyObserved = "1";
  const wrap = img.closest(".node-wrap");
  const nodeId = img.dataset.node || wrap?.dataset?.id;
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  if (node) {
    const preferred = pickNodePreviewImageSrc(node, img);
    if (preferred && preferred !== img.dataset.src) {
      img.dataset.src = preferred;
      if (preferred === nodeImagePreviewSources(node).full) img.dataset.forceFull = "1";
    }
    if (node.imageUrl && !node.thumbUrl && uploadMediaPath(node.imageUrl) && !viewportWantsFullPreview()) {
      void ensureMediaThumbRemote(node.imageUrl, "image").then((meta) => applyMediaThumbMetaToNode(nodeId, meta));
    }
  }
  if (wrap?.classList.contains("is-selected") || wrap?.classList.contains("is-picked")) {
    if (shouldUpgradeNodePreviewToFull(img)) upgradeNodePreviewToFull(img);
    else ensureLazyImage(img, MEDIA_PRIO_HIGH);
    return;
  }
  // IntersectionObserver can miss a transformed canvas target after a fast
  // pan/zoom or DOM replacement. A DOM-visible node should load immediately.
  if (elementNearViewport(img)) {
    ensureLazyImage(img, MEDIA_PRIO_HIGH);
    return;
  }
  getNodeMediaLazyObserver().observe(img);
}

function observeNodeVideoLazy(preview) {
  if (!preview || preview.dataset.lazyObserved === "1") return;
  preview.dataset.lazyObserved = "1";
  hydrateNodeVideoPoster(preview);
  const wrap = preview.closest(".node-wrap");
  if (wrap?.classList.contains("is-selected") || wrap?.classList.contains("is-picked")) {
    if (shouldNodeVideoAutoplay(preview)) ensureNodeVideoLoaded(preview);
    return;
  }
  getNodeMediaLazyObserver().observe(preview);
}

/** Reuse the loaded covers and keyboard focus when a background refresh is unchanged. */
function updateWorkspaceGrid(root, html) {
  if (root._workspaceHtml === html) return false;
  root._workspaceCoverObserver?.disconnect();
  root.querySelectorAll("video.ws-cover-media").forEach((video) => {
    video.pause();
    video.removeAttribute("src");
    video.load();
  });
  root.innerHTML = html;
  root._workspaceHtml = html;
  return true;
}

function observeWorkspaceCovers(root = document.getElementById("workspace-board-grid")) {
  if (!root) return;
  const load = (el) => {
    if (!el.isConnected) return;
    if (el.tagName === "IMG") ensureLazyImage(el);
    else if (el.tagName === "VIDEO") ensureLazyVideoEl(el);
  };
  if (!root._workspaceCoverObserver && typeof IntersectionObserver !== "undefined") {
    root._workspaceCoverObserver = new IntersectionObserver((entries, observer) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        observer.unobserve(entry.target);
        load(entry.target);
      });
    }, { root: null, rootMargin: "240px", threshold: 0 });
  }
  root.querySelectorAll(".ws-cover-media[data-src]").forEach((el) => {
    if (el.dataset.coverObserved === "1") return;
    el.dataset.coverObserved = "1";
    el.closest(".workspace-board-cover")?.classList.add("is-cover-loading");
    if (root._workspaceCoverObserver) root._workspaceCoverObserver.observe(el);
    else load(el);
  });
}

function getPanelMediaLazyObserver() {
  if (panelMediaLazyObserver) return panelMediaLazyObserver;
  panelMediaLazyObserver = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        const el = entry.target;
        panelMediaLazyObserver.unobserve(el);
        if (el.tagName === "IMG") ensureLazyImage(el);
        else if (el.tagName === "VIDEO") ensureLazyVideoEl(el);
      });
    },
    { root: null, rootMargin: "100px", threshold: 0.02 }
  );
  return panelMediaLazyObserver;
}

function observePanelMediaLazy(root) {
  if (!root?.querySelectorAll) return;
  const obs = getPanelMediaLazyObserver();
  root.querySelectorAll("img[data-src], video[data-src]").forEach((el) => {
    if (el.dataset.panelLazyObserved === "1") return;
    el.dataset.panelLazyObserved = "1";
    obs.observe(el);
  });
}

function bindNodeVideos(root = document) {
  root.querySelectorAll(".node-preview.has-video").forEach((preview) => {
    if (preview.dataset.wbPreview === "1") return;
    if (preview.dataset.vidBound === "1") return;
    preview.dataset.vidBound = "1";
    const video = preview.querySelector("video");
    const fill = preview.querySelector(".node-vid-scrub-fill");
    const thumb = preview.querySelector(".node-vid-scrub-thumb");
    const timeEl = preview.querySelector(".node-vid-time");
    const playBtn = preview.querySelector('[data-action="node-video-toggle"]');
    const muteBtn = preview.querySelector('[data-action="node-video-mute"]');
    if (!video) return;
    const cur = timeEl?.querySelector(".nv-cur");
    const durEl = timeEl?.querySelector(".nv-dur");
    const scrub = preview.querySelector(".node-vid-scrub");

    video.muted = true;
    video.defaultMuted = true;
    video.loop = true;

    const fmt = (s) => {
      const t = Math.max(0, Number(s) || 0);
      const m = Math.floor(t / 60);
      const sec = Math.floor(t % 60);
      return `${m}:${String(sec).padStart(2, "0")}`;
    };

    const sync = () => {
      let dur = Number.isFinite(video.duration) && video.duration > 0 ? video.duration : 0;
      if (!dur) {
        try {
          if (video.seekable && video.seekable.length > 0) {
            const end = video.seekable.end(video.seekable.length - 1);
            if (Number.isFinite(end) && end > 0) dur = end;
          }
        } catch {
          /* ignore */
        }
      }
      const pct = dur ? (video.currentTime / dur) * 100 : 0;
      if (fill) fill.style.width = `${pct}%`;
      if (thumb) thumb.style.left = `${pct}%`;
      if (timeEl) {
        const currentText = fmt(video.currentTime);
        const durationText = fmt(dur);
        if (cur && cur.textContent !== currentText) cur.textContent = currentText;
        if (durEl) {
          if (durEl.textContent !== durationText) durEl.textContent = durationText;
        } else if (!cur) timeEl.textContent = `${currentText} / ${durationText}`;
      }
      const playing = !video.paused && !video.ended;
      preview.classList.toggle("is-playing", playing);
      playBtn?.querySelector(".nv-icon-play")?.classList.toggle("hidden", playing);
      playBtn?.querySelector(".nv-icon-pause")?.classList.toggle("hidden", !playing);
      playBtn?.setAttribute("aria-label", playing ? "暂停视频" : "播放视频");
      const muted = video.muted || video.volume === 0;
      muteBtn?.querySelector(".nv-icon-muted")?.classList.toggle("hidden", !muted);
      muteBtn?.querySelector(".nv-icon-unmuted")?.classList.toggle("hidden", muted);
      preview.classList.toggle("is-unmuted", !muted);
      muteBtn?.setAttribute("aria-label", muted ? "开启声音" : "静音");
      if (scrub) {
        scrub.setAttribute("aria-valuemax", String(Math.round(dur)));
        scrub.setAttribute("aria-valuenow", String(Math.round(video.currentTime || 0)));
        scrub.setAttribute("aria-valuetext", `${fmt(video.currentTime)} / ${fmt(dur)}`);
      }
    };

    let syncRaf = 0;
    const scheduleSync = () => {
      if (syncRaf) return;
      syncRaf = requestAnimationFrame(() => {
        syncRaf = 0;
        sync();
      });
    };

    video.addEventListener("timeupdate", scheduleSync);
    video.addEventListener("play", sync);
    video.addEventListener("pause", sync);
    video.addEventListener("ended", sync);
    video.addEventListener("volumechange", sync);
    video.addEventListener("durationchange", scheduleSync);
    video.addEventListener("seeked", scheduleSync);
    video.addEventListener("loadedmetadata", () => {
      probeNodeVideoDimensions(video);
      sync();
    });
    video.addEventListener("canplay", () => {
      preview.classList.remove("is-video-buffering");
      if (shouldShowNodePreviewVideoEl(preview) || shouldNodeVideoAutoplay(preview)) {
        markLazyVideoVisible(video, { force: true });
      }
      syncNodeVideoPlayback(preview);
    });
    video.addEventListener("playing", () => {
      if (!shouldNodeVideoAutoplay(preview) || preview.dataset.userPaused === "1") {
        video.pause();
        return;
      }
      preview.classList.remove("is-video-buffering");
      markLazyVideoVisible(video, { force: true });
      sync();
    });
    video.addEventListener("waiting", () => {
      if (shouldNodeVideoAutoplay(preview) && preview.dataset.userPaused !== "1") {
        preview.classList.add("is-video-buffering");
      }
    });
    video.addEventListener("error", () => {
      preview.classList.remove("is-video-buffering", "is-playing");
      sync();
    });

    preview.addEventListener("mouseenter", () => {
      preview.classList.add("is-hovering");
      if (preview._hoverLoadTimer) clearTimeout(preview._hoverLoadTimer);
      preview._hoverLoadTimer = setTimeout(() => {
        preview._hoverLoadTimer = null;
        if (!preview.classList.contains("is-hovering")) return;
        if (nodeVideoPlaybackBlocked(preview) || preview.dataset.userPaused === "1") return;
        ensureNodeVideoLoaded(preview);
        syncNodeVideoPlayback(preview);
      }, NODE_VIDEO_HOVER_MS);
    });
    preview.addEventListener("mouseleave", () => {
      if (preview._hoverLoadTimer) {
        clearTimeout(preview._hoverLoadTimer);
        preview._hoverLoadTimer = null;
      }
      preview.classList.remove("is-hovering");
      syncNodeVideoPlayback(preview);
      sync();
    });

    observeNodeVideoLazy(preview);
    sync();

    if (scrub) {
      let scrubbing = false;
      let scrubRaf = 0;
      let scrubX = 0;
      const applyScrub = () => {
        if (scrubRaf) cancelAnimationFrame(scrubRaf);
        scrubRaf = 0;
        const nodeId = preview.dataset.videoNode;
        if (nodeId) scrubNodeVideo(nodeId, scrubX, scrub);
        sync();
      };
      const scrubFromPointer = (e) => {
        scrubX = e.clientX;
        if (!scrubRaf) scrubRaf = requestAnimationFrame(applyScrub);
      };
      const endScrub = (e) => {
        if (!scrubbing) return;
        if (e.type === "pointerup") scrubX = e.clientX;
        applyScrub();
        scrubbing = false;
        try {
          scrub.releasePointerCapture?.(e.pointerId);
        } catch {
          /* ignore */
        }
        window.removeEventListener("pointermove", scrubFromPointer);
        window.removeEventListener("pointerup", endScrub);
        window.removeEventListener("pointercancel", endScrub);
        window.removeEventListener("blur", endScrub);
      };
      scrub.addEventListener("keydown", (e) => {
        if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(e.key)) return;
        e.preventDefault();
        e.stopPropagation();
        preview.dataset.userPaused = "1";
        ensureNodeVideoLoaded(preview);
        const dur = Number.isFinite(video.duration) ? video.duration : videoSeekableEnd(video);
        if (!(dur > 0)) return;
        const time = e.key === "Home" ? 0 : e.key === "End" ? dur :
          video.currentTime + (e.key === "ArrowRight" ? 5 : -5);
        scrubVideoTime(video, time);
        sync();
      });
      scrub.addEventListener("pointerdown", (e) => {
        if (e.button !== 0) return;
        e.preventDefault();
        e.stopPropagation();
        scrubbing = true;
        preview.dataset.userPaused = "1";
        ensureNodeVideoLoaded(preview);
        try {
          video.pause();
        } catch {
          /* ignore */
        }
        scrub.setPointerCapture?.(e.pointerId);
        scrubFromPointer(e);
        window.addEventListener("pointermove", scrubFromPointer);
        window.addEventListener("pointerup", endScrub);
        window.addEventListener("pointercancel", endScrub);
        window.addEventListener("blur", endScrub);
      });
    }
  });
  syncAllNodeVideoPlayback(root);
}

function nodeVideoPlaybackBlocked(preview) {
  return !preview?.isConnected || document.visibilityState === "hidden" ||
    _viewportInteracting || CanvasStore.isDragging ||
    !!preview.closest(".node-wrap.is-offscreen, #canvas-view.hidden");
}

function shouldNodeVideoAutoplay(preview) {
  if (nodeVideoPlaybackBlocked(preview)) return false;
  if (VideoLightbox?.isOpen?.()) return false;
  if (VideoUpscaleModal?.isOpen?.()) return false;
  const wrap = preview.closest(".node-wrap");
  // Multi-select: never autoplay (toolbar also hidden)
  if (wrap?.classList.contains("is-picked") && !wrap.classList.contains("is-selected")) {
    return false;
  }
  const intended = preview.classList.contains("is-hovering") ||
    preview.dataset.keepPlaying === "1" || wrap?.classList.contains("is-selected");
  return !!intended && elementNearViewport(preview, 0);
}

function requestNodeVideoPlay(preview, video) {
  if (!video.paused || preview._playRequest) return;
  const attempt = {};
  preview._playRequest = attempt;
  let result;
  try {
    result = video.play();
  } catch {
    preview._playRequest = null;
    preview.classList.remove("is-playing", "is-video-buffering");
    return;
  }
  Promise.resolve(result).then(() => {
    if (!shouldNodeVideoAutoplay(preview) || preview.dataset.userPaused === "1") video.pause();
    preview.classList.toggle("is-playing", !video.paused && !video.ended);
  }).catch(() => {
    preview.classList.remove("is-playing", "is-video-buffering");
  }).finally(() => {
    if (preview._playRequest === attempt) preview._playRequest = null;
  });
}

function syncNodeVideoPlayback(preview) {
  if (preview?.dataset?.wbPreview === "1") return;
  const video = preview?.querySelector("video");
  if (!video) return;
  if (nodeVideoPlaybackBlocked(preview)) {
    video.pause();
    preview.classList.remove("is-playing", "is-video-buffering");
    return;
  }
  const wantPlay = shouldNodeVideoAutoplay(preview) && preview.dataset.userPaused !== "1";
  if (wantPlay) {
    ensureNodeVideoLoaded(preview);
    const frameReady =
      preview.classList.contains("is-frame-preview") &&
      video.classList.contains("is-media-loaded") &&
      video.readyState >= 1;
    const posterReady = nodeVideoPosterIsReady(preview);
    if (!frameReady && (video.readyState < 2 || !video.dataset.loaded)) {
      // Poster still is enough UI — avoid dark spinner overlay while video buffers.
      if (!posterReady) preview.classList.add("is-video-buffering");
      else preview.classList.remove("is-video-buffering");
      try {
        video.pause();
      } catch {
        /* ignore */
      }
      preview.classList.remove("is-playing");
      return;
    }
    preview.classList.remove("is-video-buffering", "is-paused-frame");
    if (preview.dataset.userUnmuted !== "1") video.muted = true;
    video.loop = true;
    requestNodeVideoPlay(preview, video);
  } else {
    preview.classList.remove("is-video-buffering");
    try {
      video.pause();
    } catch {
      /* ignore */
    }
    if (video.classList.contains("is-media-loaded") && (video.readyState >= 1 || video.videoWidth > 0)) {
      preview.classList.add("is-frame-preview", "is-paused-frame");
      markLazyVideoVisible(video, { force: true });
      try {
        if (!Number.isFinite(video.currentTime) || video.currentTime < 0.001) {
          video.currentTime = 0.08;
        }
      } catch {
        /* ignore */
      }
    } else if (!nodeVideoPosterIsReady(preview)) {
      // Idle with no poster and no decoded frame — pull first frame.
      ensureVideoFirstFrameVisible(preview);
    }
    preview.classList.remove("is-playing");
  }
}

function syncAllNodeVideoPlayback(root = document) {
  const scope = root?.querySelectorAll ? root : document;
  scope.querySelectorAll(".node-preview.has-video").forEach((preview) => {
    syncNodeVideoPlayback(preview);
  });
}

function toggleNodeVideo(nodeId) {
  const preview = document.querySelector(`.node-preview.has-video[data-video-node="${nodeId}"]`);
  const video = preview?.querySelector("video");
  if (!video) return;
  if (video.paused || video.ended) {
    ensureNodeVideoLoaded(preview);
    if (preview.dataset.userUnmuted !== "1") video.muted = true;
    preview.dataset.userPaused = "";
    preview.dataset.keepPlaying = "1";
    preview.classList.remove("is-paused-frame");
    requestNodeVideoPlay(preview, video);
  } else {
    preview.dataset.keepPlaying = "";
    preview.dataset.userPaused = "1";
    video.pause();
    if (video.classList.contains("is-media-loaded") && (video.readyState >= 1 || video.videoWidth > 0)) {
      preview.classList.add("is-frame-preview", "is-paused-frame");
      preview.querySelectorAll(".node-video-poster-img").forEach((img) => {
        const src = img.currentSrc || img.src || img.dataset.src || "";
        if (isMediaMissingUrl(src)) {
          img.classList.remove("is-media-loaded");
          img.hidden = true;
        }
      });
    }
    preview.classList.remove("is-playing");
  }
}

function toggleNodeVideoMute(nodeId) {
  const preview = document.querySelector(`.node-preview.has-video[data-video-node="${nodeId}"]`);
  const video = preview?.querySelector("video");
  if (!video) return;
  if (video.muted || video.volume === 0) {
    video.muted = false;
    video.volume = 1;
    preview.dataset.userUnmuted = "1";
  } else {
    video.muted = true;
    preview.dataset.userUnmuted = "";
  }
}

function scrubNodeVideo(nodeId, clientX, barEl) {
  const preview = document.querySelector(`.node-preview.has-video[data-video-node="${nodeId}"]`);
  const video = nodePreviewVideoEl(nodeId);
  if (!video || !barEl) return;
  if (preview) ensureNodeVideoLoaded(preview);
  const track = barEl.querySelector(".node-vid-scrub-track") || barEl;
  const rect = track.getBoundingClientRect();
  if (!rect.width) return;
  const ratio = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
  const dur =
    Number.isFinite(video.duration) && video.duration > 0 ? video.duration : videoSeekableEnd(video);
  if (!(dur > 0)) return;
  scrubVideoTime(video, ratio * dur);
}

function isOverlayBlockingCanvas(el) {
  if (!el) return false;
  if (typeof isOverlayOpen === "function") return isOverlayOpen(el);
  return !el.classList.contains("hidden");
}

function isCanvasActive() {
  if (document.querySelector("dialog[open]")) return false;
  if (document.querySelector(".app-dialog[open]")) return false;
  if (isLightboxOpen()) return false;
  if (!document.getElementById("video-lightbox")?.classList.contains("hidden")) return false;
  if (!document.getElementById("frame-capture-studio")?.classList.contains("hidden")) return false;
  if (!document.getElementById("video-trim-studio")?.classList.contains("hidden")) return false;
  if (!document.getElementById("video-compress-modal")?.classList.contains("hidden")) return false;
  if (!document.getElementById("video-upscale-modal")?.classList.contains("hidden")) return false;
  if (!document.getElementById("video-gif-studio")?.classList.contains("hidden")) return false;
  if (!document.getElementById("video-crop-studio")?.classList.contains("hidden")) return false;
  if (!document.getElementById("image-paint-studio")?.classList.contains("hidden")) return false;
  if (!document.getElementById("node-history-drawer")?.classList.contains("hidden")) return false;
  if (document.getElementById("prompt-expand") && !document.getElementById("prompt-expand").classList.contains("hidden")) {
    return false;
  }
  for (const id of ["asset-picker", "text-result-expand"]) {
    if (isOverlayBlockingCanvas(document.getElementById(id))) return false;
  }
  return true;
}

function canUseCanvasShortcuts() {
  if (!isCanvasActive()) return false;
  if (isEditingPromptContext()) return false;
  if (isTextInputTarget(document.activeElement)) return false;
  if (isFocusInCanvasChrome(document.activeElement)) return false;
  if (isFloatingCanvasUiOpen()) return false;
  return true;
}

function layoutImportGridSlots(count, anchorX, anchorY, opts = {}) {
  const n = Math.max(1, Number(count) || 1);
  const cellW = opts.cellW ?? 300;
  const cellH = opts.cellH ?? 220;
  const gap = opts.gap ?? 28;
  const maxCols = opts.maxCols ?? 6;
  const cols = Math.min(n, maxCols, Math.max(1, Math.ceil(Math.sqrt(n))));
  const rows = Math.ceil(n / cols);
  const totalW = cols * cellW + Math.max(0, cols - 1) * gap;
  const totalH = rows * cellH + Math.max(0, rows - 1) * gap;
  const slots = [];
  for (let i = 0; i < n; i++) {
    const col = i % cols;
    const row = Math.floor(i / cols);
    slots.push({
      x: anchorX - totalW / 2 + col * (cellW + gap) + cellW / 2,
      y: anchorY - totalH / 2 + row * (cellH + gap) + cellH / 2,
    });
  }
  return slots;
}
window.layoutImportGridSlots = layoutImportGridSlots;

/** Arrange selected nodes into a grid / row / column / along links. */
function arrangeSelectedNodes(mode = "auto-grid", opts = {}) {
  const ids = getSelectedIds();
  if (ids.length < 2) return;
  const board = CanvasStore.activeBoard();
  if (!board) return;
  const nodes = ids
    .map((id) => board.nodes.find((n) => n.id === id))
    .filter(Boolean);
  if (nodes.length < 2) return;

  const gapX = opts.gapX ?? 40;
  const gapY = opts.gapY ?? 28;
  const boxes = nodes.map((n) => ({
    node: n,
    w: getNodeWidth(n),
    h: getNodeFrameHeight(n),
  }));

  let ordered = boxes;
  if (mode === "by-links") {
    const conn = board.connections || [];
    const indeg = new Map(boxes.map((b) => [b.node.id, 0]));
    const outs = new Map(boxes.map((b) => [b.node.id, []]));
    const idSet = new Set(boxes.map((b) => b.node.id));
    for (const c of conn) {
      if (!idSet.has(c.from) || !idSet.has(c.to)) continue;
      outs.get(c.from)?.push(c.to);
      indeg.set(c.to, (indeg.get(c.to) || 0) + 1);
    }
    const queue = boxes
      .filter((b) => (indeg.get(b.node.id) || 0) === 0)
      .sort((a, b) => a.node.y - b.node.y || a.node.x - b.node.x);
    const seen = new Set();
    const topo = [];
    while (queue.length) {
      const cur = queue.shift();
      if (seen.has(cur.node.id)) continue;
      seen.add(cur.node.id);
      topo.push(cur);
      for (const to of outs.get(cur.node.id) || []) {
        indeg.set(to, (indeg.get(to) || 0) - 1);
        if ((indeg.get(to) || 0) <= 0) {
          const next = boxes.find((b) => b.node.id === to);
          if (next && !seen.has(to)) queue.push(next);
        }
      }
    }
    for (const b of boxes) if (!seen.has(b.node.id)) topo.push(b);
    ordered = topo;
  } else {
    ordered = [...boxes].sort((a, b) => a.node.y - b.node.y || a.node.x - b.node.x);
  }

  const n = ordered.length;
  let cols = 1;
  if (mode === "row") cols = n;
  else if (mode === "col" || mode === "by-links") cols = 1;
  else if (mode === "grid-2") cols = Math.min(2, n);
  else cols = Math.min(n, Math.max(1, Math.ceil(Math.sqrt(n)))); // auto-grid

  const colW = [];
  const rowH = [];
  for (let i = 0; i < n; i++) {
    const c = i % cols;
    const r = Math.floor(i / cols);
    colW[c] = Math.max(colW[c] || 0, ordered[i].w);
    rowH[r] = Math.max(rowH[r] || 0, ordered[i].h);
  }
  const colX = [];
  let xAcc = 0;
  for (let c = 0; c < cols; c++) {
    colX[c] = xAcc;
    xAcc += (colW[c] || 0) + gapX;
  }
  const rowY = [];
  let yAcc = 0;
  const rows = Math.ceil(n / cols);
  for (let r = 0; r < rows; r++) {
    rowY[r] = yAcc;
    yAcc += (rowH[r] || 0) + gapY;
  }

  const minX = Math.min(...ordered.map((b) => b.node.x));
  const minY = Math.min(...ordered.map((b) => b.node.y));
  CanvasHistory?.push?.();
  ordered.forEach((b, i) => {
    const c = i % cols;
    const r = Math.floor(i / cols);
    b.node.x = Math.round(minX + colX[c]);
    b.node.y = Math.round(minY + rowY[r]);
  });
  CanvasStore.save();
  renderNodes({ immediate: true });
  connStaticDirty = true;
  scheduleRenderConnections(true);
  if (!opts.silent) showCanvasToast?.("已整理布局");
}

const MULTI_SELECT_BAR_GAP = 12;

function getSelectedNodesBounds() {
  const ids = getSelectedIds();
  if (ids.length < 2) return null;
  const board = CanvasStore.activeBoard();
  if (!board) return null;
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  let count = 0;
  for (const id of ids) {
    const n = board.nodes.find((node) => node.id === id);
    if (!n) continue;
    count += 1;
    minX = Math.min(minX, n.x);
    minY = Math.min(minY, n.y);
    maxX = Math.max(maxX, n.x + getNodeWidth(n));
    maxY = Math.max(maxY, n.y + getNodeFrameHeight(n));
  }
  if (count < 2) return null;
  return { minX, minY, maxX, maxY };
}

function positionMultiSelectBar() {
  if (_viewportInteracting) return;
  const bar = document.getElementById("multi-select-bar");
  if (!bar || bar.classList.contains("hidden")) return;
  const bounds = getSelectedNodesBounds();
  if (!bounds) return;

  const centerX = (bounds.minX + bounds.maxX) / 2;
  const anchor = worldToScreen(centerX, bounds.minY);
  const gap = MULTI_SELECT_BAR_GAP;
  const margin = 8;

  bar.style.transform = "translate(-50%, -100%)";
  bar.style.left = `${anchor.x}px`;
  bar.style.top = `${anchor.y - gap}px`;

  let rect = bar.getBoundingClientRect();
  let left = anchor.x;
  let top = anchor.y - gap;

  const halfW = rect.width / 2;
  left = Math.min(Math.max(left, margin + halfW), window.innerWidth - margin - halfW);

  if (rect.top < margin) {
    bar.style.transform = "translate(-50%, 0)";
    top = anchor.y + gap;
  }

  bar.style.left = `${left}px`;
  bar.style.top = `${top}px`;

  rect = bar.getBoundingClientRect();
  if (rect.bottom > window.innerHeight - margin) {
    top -= rect.bottom - (window.innerHeight - margin);
    bar.style.top = `${top}px`;
  }
}

const MultiSelectBar = {
  _bound: false,

  el() {
    return document.getElementById("multi-select-bar");
  },

  reposition() {
    positionMultiSelectBar();
  },

  sync() {
    const bar = this.el();
    if (!bar) return;
    const inWorkspace = document.getElementById("app-root")?.classList.contains("is-workspace");
    const ids = getSelectedIds();
    const show = !inWorkspace && ids.length >= 2 && !CanvasStore.isDragging;
    bar.classList.toggle("hidden", !show);
    if (!show) {
      this.closeMenu();
      return;
    }
    const countEl = document.getElementById("msb-count");
    if (countEl) countEl.textContent = `${ids.length} 个节点`;
    this.bind();
    this.reposition();
    requestAnimationFrame(() => {
      if (!bar.classList.contains("hidden")) positionMultiSelectBar();
    });
  },

  closeMenu() {
    const menu = document.getElementById("msb-layout-menu");
    if (menu) {
      menu.classList.remove("is-open");
      menu.classList.add("hidden");
    }
    document.getElementById("msb-layout")?.classList.remove("is-open");
    document.getElementById("msb-layout")?.setAttribute("aria-expanded", "false");
  },

  toggleMenu() {
    const menu = document.getElementById("msb-layout-menu");
    const btn = document.getElementById("msb-layout");
    if (!menu || !btn) return;
    const willOpen = menu.classList.contains("hidden") || !menu.classList.contains("is-open");
    if (willOpen) {
      menu.classList.remove("hidden");
      void menu.offsetWidth;
      menu.classList.add("is-open");
      btn.classList.add("is-open");
      btn.setAttribute("aria-expanded", "true");
    } else {
      this.closeMenu();
    }
  },

  bind() {
    if (this._bound) return;
    this._bound = true;
    document.getElementById("msb-layout")?.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.toggleMenu();
    });
    document.getElementById("msb-layout-menu")?.addEventListener("click", (e) => {
      const btn = e.target.closest("[data-layout]");
      if (!btn) return;
      e.preventDefault();
      e.stopPropagation();
      this.closeMenu();
      arrangeSelectedNodes(btn.dataset.layout || "auto-grid");
    });
    document.getElementById("msb-download")?.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      void downloadSelectedMedia(getSelectedIds());
    });
    document.getElementById("msb-delete")?.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      void deleteSelectedNodes(false, getSelectedIds());
    });
    document.addEventListener(
      "pointerdown",
      (e) => {
        if (e.target.closest?.("#multi-select-bar")) return;
        this.closeMenu();
      },
      true
    );
  },
};

function syncMultiSelectBar() {
  MultiSelectBar.sync();
}
window.arrangeSelectedNodes = arrangeSelectedNodes;
window.focusNodesOnCanvasSmooth = focusNodesOnCanvasSmooth;
window.focusNodeOnCanvasSmooth = focusNodeOnCanvasSmooth;
window.animateViewportTo = animateViewportTo;
window.getNodeWidth = getNodeWidth;
window.getNodeFrameHeight = getNodeFrameHeight;
window.MultiSelectBar = MultiSelectBar;

function getPasteWorldPos(opts = {}) {
  const { useContextPos = false } = opts;
  if (useContextPos && CanvasStore._ctxPos) return { ...CanvasStore._ctxPos };
  return getAddNodeWorldPosFromHover();
}

/**
 * Last mouse hover on canvas content (screen→world).
 * Packaged build used `_pointerX/_pointerY` directly as node top-left — no centering offset.
 */
function getAddNodeWorldPosFromHover() {
  const px = CanvasStore._placeX ?? CanvasStore._pointerX;
  const py = CanvasStore._placeY ?? CanvasStore._pointerY;
  if (typeof px === "number" && typeof py === "number") {
    return screenToWorld(px, py);
  }
  const rect = getViewportEl()?.getBoundingClientRect();
  const cx = rect ? rect.left + rect.width / 2 : window.innerWidth / 2;
  const cy = rect ? rect.top + rect.height / 2 : window.innerHeight / 2;
  return screenToWorld(cx, cy);
}

/** Freeze hover at add-menu open so choosing a type still uses the stay position. */
function captureAddNodePlacement() {
  CanvasStore._addPlaceWorld = getAddNodeWorldPosFromHover();
}

function clearAddNodePlacement() {
  CanvasStore._addPlaceWorld = null;
}

function getAddNodeWorldPos() {
  if (CanvasStore._addPlaceWorld) {
    return { x: CanvasStore._addPlaceWorld.x, y: CanvasStore._addPlaceWorld.y };
  }
  return getAddNodeWorldPosFromHover();
}

/** True when the event target is over canvas content (nodes/empty), not chrome or floating menus. */
function isCanvasPlacementPointerTarget(target) {
  if (!target || typeof target.closest !== "function") return false;
  if (
    target.closest(
      [
        ".add-menu",
        ".ctx-menu-canvas",
        ".ctx-menu-node",
        ".tool-dock",
        ".tool-dock-wrap",
        ".topbar",
        ".topbar-cluster",
        ".bottom-bar",
        ".bottom-chrome",
        ".nav-panel",
        ".multi-select-bar",
        ".zoom-controls-wrap",
        ".zoom-hud",
        ".canvas-toast",
        ".connect-hint",
        ".overlay-popover",
        ".prompt-expand",
        "dialog",
        "#chrome-bottom",
        "#chrome-top",
      ].join(", ")
    )
  ) {
    return false;
  }
  const vp = getViewportEl();
  if (!vp) return false;
  return target === vp || vp.contains(target);
}

function cloneBoardSnapshot() {
  return JSON.stringify({
    boards: CanvasStore.boards,
    activeBoardId: CanvasStore.activeBoardId,
    selectedIds: CanvasStore.selectedIds,
    primaryId: CanvasStore.primaryId,
  });
}

function restoreBoardSnapshot(raw) {
  const data = JSON.parse(raw);
  const keepViewport = { ...CanvasStore.viewport };
  CanvasStore.boards = data.boards || [];
  CanvasStore.activeBoardId = data.activeBoardId;
  CanvasStore.viewport = keepViewport;
  CanvasStore.selectedIds = data.selectedIds || [];
  CanvasStore.primaryId = data.primaryId || null;
  if ((CanvasStore.selectedIds || []).length !== 1) {
    CanvasStore.primaryId = null;
  } else if (!CanvasStore.primaryId) {
    CanvasStore.primaryId = CanvasStore.selectedIds[0];
  }
  CanvasStore.selectedNodeId = CanvasStore.primaryId;
  CanvasStore.boards.forEach((b) => CanvasStore.ensureBoardMeta(b));
  if (!CanvasStore.boards.find((b) => b.id === CanvasStore.activeBoardId)) {
    CanvasStore.activeBoardId = CanvasStore.boards[0]?.id || null;
  }
  renderBoardDropdown();
  renderNodes({ immediate: true });
  updateNodeCount();
  updateCanvasHint();
  applyViewport();
  connStaticDirty = true;
  scheduleRenderConnections(true);
}

const CanvasHistory = {
  stack: [],
  index: -1,
  maxSize: 60,

  reset() {
    this.stack = [cloneBoardSnapshot()];
    this.index = 0;
  },

  /** Snapshot current board AFTER a mutation (undo = previous, redo/恢复 = next). */
  push() {
    const snap = cloneBoardSnapshot();
    if (this.index >= 0 && this.stack[this.index] === snap) return;
    this.stack = this.stack.slice(0, this.index + 1);
    this.stack.push(snap);
    if (this.stack.length > this.maxSize) {
      this.stack.shift();
      this.index = this.stack.length - 1;
    } else {
      this.index += 1;
    }
    updateContextMenuStates();
  },

  canUndo() {
    return this.index > 0;
  },

  canRedo() {
    return this.index >= 0 && this.index < this.stack.length - 1;
  },

  undo() {
    if (!this.canUndo()) return false;
    this.index -= 1;
    restoreBoardSnapshot(this.stack[this.index]);
    CanvasStore.save();
    updateContextMenuStates();
    showCanvasToast("已撤销");
    return true;
  },

  redo() {
    if (!this.canRedo()) return false;
    this.index += 1;
    restoreBoardSnapshot(this.stack[this.index]);
    CanvasStore.save();
    updateContextMenuStates();
    showCanvasToast("已恢复");
    return true;
  },
};

/** Process queued node-delete media (3-day grace). Does not scan unrelated orphans. */
async function purgeBoardFolderOrphans(boardId, { silent = true, flush = false, trustClient = false } = {}) {
  const board = CanvasStore.boards.find((b) => b.id === boardId) || CanvasStore.activeBoard();
  if (!board?.id || board.isOwned === false) return null;
  if (!window.CanvasAuth?.isLoggedIn?.()) return null;
  try {
    if (flush) await CanvasStore.flushSave?.();
  } catch {
    /* ignore */
  }
  try {
    const fresh = CanvasStore.boards.find((b) => b.id === board.id) || board;
    const res = await fetch(`/api/canvas/boards/${encodeURIComponent(fresh.id)}/purge-orphans`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "same-origin",
      body: JSON.stringify({ board: fresh }),
    });
    if (!res.ok) {
      const err = await res.json().catch(() => ({}));
      if (!silent) console.warn("[pending-deletes]", res.status, err?.detail || res.statusText);
      return null;
    }
    const data = await res.json().catch(() => null);
    const n = Number(data?.deleted) || 0;
    if (n > 0) console.info("[pending-deletes] trashed", n);
    if (data?.pending_changed) {
      if (Array.isArray(data.pendingAssetDeletes) && data.pendingAssetDeletes.length) {
        fresh.pendingAssetDeletes = data.pendingAssetDeletes;
      } else {
        delete fresh.pendingAssetDeletes;
      }
    }
    return data;
  } catch (err) {
    if (!silent) console.warn("[pending-deletes]", err);
    return null;
  }
}

let _purgeBoardTimer = 0;
function schedulePurgeBoardFolderOrphans(boardId, opts = {}) {
  clearTimeout(_purgeBoardTimer);
  _purgeBoardTimer = setTimeout(() => {
    _purgeBoardTimer = 0;
    void purgeBoardFolderOrphans(boardId, opts);
  }, 800);
}

function isNodeBusyForDelete(node) {
  if (!node) return false;
  return ["waiting", "pending", "generating", "uploading"].includes(node.status);
}

/** Cancel in-flight generation without the pause confirm dialog. */
async function abortBusyNodeTasks(nodes) {
  const list = (nodes || []).filter(isNodeBusyForDelete);
  for (const node of list) {
    try {
      if (typeof window.cancelQueuedGeneration === "function") {
        window.cancelQueuedGeneration(node.id);
      }
      if (node.taskId) {
        await fetch(`/api/tasks/${encodeURIComponent(node.taskId)}/cancel`, {
          method: "POST",
          credentials: "same-origin",
        }).catch(() => null);
      }
    } catch (_) {
      /* best-effort */
    }
  }
  if (list.length && typeof window.pumpGenQueue === "function") window.pumpGenQueue();
}

function isNodeActivelyGenerating(node) {
  return Boolean(node && ["waiting", "pending", "generating"].includes(node.status));
}

/** Last successful media on node (current fields or genHistory). */
function resolveNodeClipboardMedia(node) {
  if (!node) return null;
  if (node.videoUrl || node.imageUrl || (isTextGenNode(node) && String(node.resultText || "").trim())) {
    return {
      videoUrl: node.videoUrl || null,
      imageUrl: node.imageUrl || null,
      coverUrl: node.coverUrl || null,
      thumbUrl: node.thumbUrl || null,
      resultText: node.resultText || null,
      mediaWidth: node.mediaWidth || null,
      mediaHeight: node.mediaHeight || null,
    };
  }
  const hist = Array.isArray(node.genHistory) ? node.genHistory : [];
  const last = hist.find((h) => h && h.status === "success" && (h.videoUrl || h.imageUrl));
  if (!last) return null;
  return {
    videoUrl: last.videoUrl || null,
    imageUrl: last.imageUrl || null,
    coverUrl: last.coverUrl || null,
    thumbUrl: last.thumbUrl || null,
    resultText: null,
    mediaWidth: last.mediaWidth || null,
    mediaHeight: last.mediaHeight || null,
  };
}

function applyClipboardMedia(copy, media) {
  if (!media) return false;
  Object.assign(copy, media);
  copy.status = "completed";
  copy.error = null;
  copy.isError = false;
  copy.isNew = false;
  return true;
}

/** Best-effort still from an already-painted source video card (for clone/paste). */
function captureLiveVideoPosterUrl(nodeId) {
  const id = String(nodeId || "").trim();
  if (!id) return "";
  const preview = document.querySelector(`.node-preview.has-video[data-video-node="${CSS.escape(id)}"]`);
  if (!preview) return "";
  const img = preview.querySelector(".node-video-poster-img.is-media-loaded");
  const fromImg = img?.currentSrc || img?.src || img?.dataset?.src || "";
  if (fromImg && !(typeof isMediaMissingUrl === "function" && isMediaMissingUrl(fromImg))) {
    return fromImg;
  }
  return "";
}

function ensureCloneVideoPoster(copy, sourceNode) {
  if (!copy?.videoUrl || nodeVideoPosterUrl(copy)) return copy;
  const live = captureLiveVideoPosterUrl(sourceNode?.id);
  if (live) {
    copy.coverUrl = live;
    return copy;
  }
  // Kick background poster generation so the next paint can pick it up.
  if (typeof ensureMediaThumbRemote === "function") {
    void ensureMediaThumbRemote(copy.videoUrl, "video").then((meta) => {
      if (!meta?.cover_url || !copy.id) return;
      const board = CanvasStore.activeBoard?.();
      const liveNode = board?.nodes?.find((n) => n.id === copy.id);
      if (!liveNode || liveNode.coverUrl) return;
      applyMediaThumbMetaToNode(copy.id, meta);
      const wrap = document.querySelector(`.node-wrap[data-id="${CSS.escape(copy.id)}"]`);
      const preview = wrap?.querySelector(".node-preview.has-video");
      if (preview) {
        syncNodeVideoPosterDom(preview, resolveMediaUrl(meta.cover_url), { silent: true });
        preview.classList.remove("is-frame-preview", "is-video-buffering");
      }
    });
  }
  return copy;
}

/** Copy/duplicate: keep prompt/settings/media; drop task queue, errors, and in-flight state. */
function collectNodeSoftRefsForClipboard(node) {
  if (!node) return [];
  const board = CanvasStore.activeBoard();
  const seen = new Set();
  const out = [];
  for (const id of [...getSoftRefIds(node), ...getWiredReferableNodes(node.id).map((n) => n.id)]) {
    if (!id || id === node.id || seen.has(id)) continue;
    const ref = board?.nodes?.find((n) => n.id === id);
    if (ref && isReferableNode(ref)) {
      seen.add(id);
      out.push(id);
    }
  }
  return out;
}

/** Remap softRefIds when cloning; keep outside refs, drop missing/self. */
function remapSoftRefIdsOnClone(softRefIds, idMap, newId) {
  const seen = new Set();
  const out = [];
  for (const id of softRefIds || []) {
    if (!id) continue;
    const mapped = idMap.has(id) ? idMap.get(id) : id;
    if (!mapped || mapped === newId || seen.has(mapped)) continue;
    seen.add(mapped);
    out.push(mapped);
  }
  return out;
}

/**
 * Remap @ref:oldId / @oldId inside prompt when nodes are pasted/cloned.
 * softRefIds are remapped separately — without this, chips show but submit keeps raw @codes.
 */
function remapPromptMentionsOnClone(prompt, idMap) {
  if (!prompt || !idMap?.size) return prompt || "";
  const byId = new Map();
  for (const id of idMap.keys()) byId.set(id, { id });
  const byName = new Map();
  let out = "";
  let last = 0;
  const src = String(prompt);
  forEachMention(src, byId, byName, (hit) => {
    out += src.slice(last, hit.index);
    const mapped = idMap.get(hit.id);
    if (mapped) {
      const raw = src.slice(hit.index, hit.end);
      out += /^@ref:/i.test(raw) ? `@ref:${mapped}` : `@${mapped}`;
    } else {
      out += src.slice(hit.index, hit.end);
    }
    last = hit.end;
  });
  out += src.slice(last);
  return collapsePromptChipWhitespace(out);
}
window.remapPromptMentionsOnClone = remapPromptMentionsOnClone;

function sanitizeNodeForClipboard(node, opts = {}) {
  const keepGenHistory = opts.keepGenHistory === true;
  const copy = { ...node };
  // Paste has no wires → bake wired refs into softRefIds.
  // Duplicate copies wires separately → keep soft-only (see cloneNodes).
  if (opts.bakeWiresIntoSoftRefs === false) {
    copy.softRefIds = [...getSoftRefIds(node)];
  } else {
    copy.softRefIds = collectNodeSoftRefsForClipboard(node);
  }
  copy.taskId = null;
  delete copy.generationStopped;
  delete copy.stoppedTaskId;
  copy.genStartedAt = null;
  copy.autoRetryCount = 0;
  delete copy._genPayload;
  delete copy._retryPayload;
  delete copy._lastRefs;
  delete copy._lastPaintedImageUrl;
  delete copy._lastPaintedVideoUrl;
  delete copy._accountBusyRetries;
  // Clipboard copy/paste: current node only. genHistory stays on Ctrl+D duplicate.
  if (!keepGenHistory) {
    delete copy.genHistory;
    delete copy.activeHistoryId;
  } else if (Array.isArray(copy.genHistory)) {
    copy.genHistory = copy.genHistory.filter((h) => h.status !== "generating");
  }
  // Keep cover/thumb so duplicate/paste can paint a still immediately instead of
  // buffering the whole video (and competing with every ref-chip thumb load).

  if (isNodeActivelyGenerating(node)) {
    if (applyClipboardMedia(copy, resolveNodeClipboardMedia(node))) {
      return copy;
    }
    copy.status = "idle";
    copy.error = null;
    copy.isError = false;
    copy.lastGenMs = null;
    return copy;
  }

  const media = resolveNodeClipboardMedia(node);
  if (media) {
    applyClipboardMedia(copy, media);
    return copy;
  }

  if (node.status === "failed" || isPausedGenerationError(node.error)) {
    copy.status = "idle";
    copy.error = null;
    copy.isError = false;
    copy.lastGenMs = null;
    return copy;
  }

  if (node.status === "completed") {
    copy.status = "completed";
    copy.error = null;
    copy.isError = false;
    return copy;
  }

  copy.error = null;
  copy.isError = false;
  return copy;
}

const CANVAS_NODES_CLIP_FORMAT = "qingzi-canvas-nodes";
const CANVAS_NODES_CLIP_VERSION = 1;
const CANVAS_NODES_CLIP_LS_KEY = "qingzi-canvas-nodes-clipboard";

function buildCanvasNodesClipboardPayload(nodes, connections) {
  return {
    format: CANVAS_NODES_CLIP_FORMAT,
    version: CANVAS_NODES_CLIP_VERSION,
    nodes: Array.isArray(nodes) ? nodes : [],
    connections: Array.isArray(connections) ? connections : [],
  };
}

function parseCanvasNodesClipboardPayload(text) {
  const raw = String(text || "").trim();
  if (!raw || raw[0] !== "{") return null;
  try {
    const data = JSON.parse(raw);
    if (!data || data.format !== CANVAS_NODES_CLIP_FORMAT) return null;
    if (!Array.isArray(data.nodes) || !data.nodes.length) return null;
    return {
      format: CANVAS_NODES_CLIP_FORMAT,
      version: Number(data.version) || 1,
      nodes: data.nodes,
      connections: Array.isArray(data.connections) ? data.connections : [],
    };
  } catch {
    return null;
  }
}

function persistCanvasNodesClipboardText(text) {
  try {
    localStorage.setItem(CANVAS_NODES_CLIP_LS_KEY, text);
  } catch {
    /* quota / private mode */
  }
}

function readPersistedCanvasNodesClipboardText() {
  try {
    return localStorage.getItem(CANVAS_NODES_CLIP_LS_KEY) || "";
  } catch {
    return "";
  }
}

function getCanvasNodesClipboardText(nodes, connections) {
  return JSON.stringify(buildCanvasNodesClipboardPayload(nodes, connections));
}

/**
 * Write plain text into the OS clipboard (call inside a user gesture).
 * Tries Clipboard API, then execCommand + copy event, then a focused textarea.
 * Does not touch canvas-node localStorage — use copyPlainTextToSystemClipboard for that.
 */
async function copyTextToSystemClipboard(text) {
  if (!text) return false;

  if (window.isSecureContext && navigator.clipboard?.writeText) {
    try {
      await navigator.clipboard.writeText(text);
      return true;
    } catch (err) {
      console.warn("copyTextToSystemClipboard writeText", err);
    }
  }

  let copied = false;
  const onCopy = (e) => {
    e.preventDefault();
    e.clipboardData.setData("text/plain", text);
    copied = true;
  };
  document.addEventListener("copy", onCopy, true);
  try {
    document.execCommand("copy");
  } catch (err) {
    console.warn("copyTextToSystemClipboard execCommand", err);
  }
  document.removeEventListener("copy", onCopy, true);
  if (copied) return true;

  try {
    const ta = document.createElement("textarea");
    ta.value = text;
    ta.setAttribute("readonly", "");
    ta.style.cssText =
      "position:fixed;top:0;left:0;width:2px;height:2px;padding:0;border:none;outline:none;box-shadow:none;background:transparent;opacity:0;";
    document.body.appendChild(ta);
    ta.focus();
    ta.select();
    ta.setSelectionRange(0, text.length);
    const ok = document.execCommand("copy");
    document.body.removeChild(ta);
    if (ok) return true;
  } catch (err) {
    console.warn("copyTextToSystemClipboard textarea", err);
  }
  return false;
}

/** Write canvas-node clipboard text to OS + persist same-tab fallback. */
async function copyPlainTextToSystemClipboard(text) {
  if (!text) return false;
  persistCanvasNodesClipboardText(text);
  return copyTextToSystemClipboard(text);
}

async function requestCanvasNodeCopyToSystemClipboard(nodes, connections) {
  const text = getCanvasNodesClipboardText(nodes, connections);
  return copyPlainTextToSystemClipboard(text);
}

function applyCanvasNodesClipboardPayload(data) {
  if (!data?.nodes?.length) return false;
  CanvasClipboard.nodes = data.nodes.map((n) => ({ ...n }));
  CanvasClipboard.connections = (data.connections || []).map((c) => ({ ...c }));
  updateContextMenuStates();
  return true;
}

/** Load node payload from system clipboard; allowMemory = same-tab copy fallback only. */
async function ensureCanvasClipboardLoaded(plainText = "", { allowMemory = false } = {}) {
  const tryApply = (raw) => {
    const parsed = parseCanvasNodesClipboardPayload(String(raw || "").trim());
    return parsed ? applyCanvasNodesClipboardPayload(parsed) : false;
  };

  if (tryApply(plainText)) return true;

  // Context-menu paste — no ClipboardEvent payload; read OS clipboard once.
  if (!plainText && navigator.clipboard?.readText) {
    try {
      if (tryApply(await navigator.clipboard.readText())) return true;
    } catch {
      /* permission / insecure */
    }
  }

  // Same-tab copy when OS clipboard write/read failed (WeChat / Ctrl+V still use OS when available).
  if (allowMemory && CanvasClipboard.hasNodes()) return true;
  return false;
}

const CanvasClipboard = {
  nodes: [],
  connections: [],

  hasNodes() {
    return this.nodes.length > 0;
  },

  async copyNodeIds(ids) {
    const board = CanvasStore.activeBoard();
    const idSet = new Set(ids);
    this.nodes = board.nodes.filter((n) => idSet.has(n.id)).map((n) => sanitizeNodeForClipboard(n));
    this.connections = board.connections
      .filter((c) => idSet.has(c.from) && idSet.has(c.to))
      .map((c) => ({ ...c }));
    const ok = await requestCanvasNodeCopyToSystemClipboard(this.nodes, this.connections);
    updateContextMenuStates();
    return ok;
  },

  cloneNodes(ids, dx, dy) {
    const board = CanvasStore.activeBoard();
    const idSet = new Set(ids);
    const sourceNodes = board.nodes.filter((n) => idSet.has(n.id));
    if (!sourceNodes.length) return [];

    const idMap = new Map();
    sourceNodes.forEach((n) => {
      idMap.set(n.id, uid());
    });
    const newIds = [];
    sourceNodes.forEach((n) => {
      const newId = idMap.get(n.id);
      // 副本只复制真实牵线作为素材来源，不把 softRefIds（含历史「牵线写入 soft」残留）带过去。
      // 否则会出现：删掉牵线后输入框缩略图仍在。
      const base = sanitizeNodeForClipboard(n, { bakeWiresIntoSoftRefs: false, keepGenHistory: true });
      base.softRefIds = [];
      if (base.prompt) base.prompt = remapPromptMentionsOnClone(base.prompt, idMap);
      if (Array.isArray(base.quickMentionRecords) && base.quickMentionRecords.length) {
        base.quickMentionRecords = remapQuickMentionRecordsOnClone(base.quickMentionRecords, idMap);
      }
      const next = { ...base, id: newId, x: n.x + dx, y: n.y + dy };
      ensureCloneVideoPoster(next, n);
      board.nodes.push(next);
      newIds.push(newId);
    });

    // 1) Wires between selected nodes → copy both ends
    // 2) Wires between selected ↔ outside → keep outside, remap selected
    //    (so Ctrl+D on a video still keeps links from the same image refs)
    const seen = new Set();
    board.connections.forEach((c) => {
      const fromSel = idSet.has(c.from);
      const toSel = idSet.has(c.to);
      if (!fromSel && !toSel) return;
      const from = fromSel ? idMap.get(c.from) : c.from;
      const to = toSel ? idMap.get(c.to) : c.to;
      if (!from || !to || from === to) return;
      const key = `${from}->${to}`;
      if (seen.has(key)) return;
      if (board.connections.some((x) => x.from === from && x.to === to)) return;
      seen.add(key);
      board.connections.push({ id: uid(), from, to });
    });

    CanvasStore.save();
    renderNodes();
    setSelection(newIds, newIds.length === 1 ? newIds[0] : null);
    updateNodeCount();
    updateCanvasHint();
    connStaticDirty = true;
    scheduleRenderConnections(true);
    return newIds;
  },

  pasteAt(worldX, worldY) {
    if (!this.nodes.length) return [];
    let minX = Infinity;
    let minY = Infinity;
    let maxX = -Infinity;
    let maxY = -Infinity;
    this.nodes.forEach((n) => {
      minX = Math.min(minX, n.x);
      minY = Math.min(minY, n.y);
      maxX = Math.max(maxX, n.x + getNodeWidth(n));
      maxY = Math.max(maxY, n.y + getNodeFrameHeight(n));
    });
    const cx = (minX + maxX) / 2;
    const cy = (minY + maxY) / 2;
    const dx = worldX - cx;
    const dy = worldY - cy;

    const board = CanvasStore.activeBoard();
    if (!board) return [];
    if (!Array.isArray(board.connections)) board.connections = [];
    const idMap = new Map();
    const newIds = [];
    this.nodes.forEach((n) => {
      const newId = uid();
      idMap.set(n.id, newId);
    });
    this.nodes.forEach((n) => {
      const newId = idMap.get(n.id);
      const base = sanitizeNodeForClipboard(n);
      base.softRefIds = remapSoftRefIdsOnClone(base.softRefIds, idMap, newId);
      if (base.prompt) base.prompt = remapPromptMentionsOnClone(base.prompt, idMap);
      if (Array.isArray(base.quickMentionRecords) && base.quickMentionRecords.length) {
        base.quickMentionRecords = remapQuickMentionRecordsOnClone(base.quickMentionRecords, idMap);
      }
      const next = { ...base, id: newId, x: n.x + dx, y: n.y + dy };
      ensureCloneVideoPoster(next, n);
      board.nodes.push(next);
      newIds.push(newId);
    });
    // Restore wires that were entirely inside the copied set (cross-board safe).
    const seen = new Set();
    for (const c of this.connections || []) {
      const from = idMap.get(c.from);
      const to = idMap.get(c.to);
      if (!from || !to || from === to) continue;
      const key = `${from}->${to}`;
      if (seen.has(key)) continue;
      if (board.connections.some((x) => x.from === from && x.to === to)) continue;
      seen.add(key);
      board.connections.push({ id: uid(), from, to });
    }

    CanvasStore.save();
    renderNodes();
    setSelection(newIds, newIds.length === 1 ? newIds[0] : null);
    updateNodeCount();
    updateCanvasHint();
    connStaticDirty = true;
    scheduleRenderConnections(true);
    return newIds;
  },
};

async function copySelectedNodes(idsOverride = null) {
  const ids = idsOverride?.length ? idsOverride : getSelectedIds();
  if (!ids.length) return false;
  const ok = await CanvasClipboard.copyNodeIds(ids);
  showCanvasToast(
    ok ? `已复制 ${ids.length} 个节点` : "复制失败：无法写入剪贴板（需 HTTPS 或 localhost）"
  );
  return ok;
}

async function cutSelectedNodes(idsOverride = null) {
  const ids = idsOverride?.length ? idsOverride : getSelectedIds();
  if (!ids.length) return false;
  await CanvasClipboard.copyNodeIds(ids);
  await deleteSelectedNodes(true);
  showCanvasToast(`已剪切 ${ids.length} 个节点`);
  return true;
}

async function blobToPngClipboardBlob(blob) {
  if (blob && blob.type === "image/png") return blob;
  const bitmap = await createImageBitmap(blob);
  try {
    const canvas = document.createElement("canvas");
    canvas.width = bitmap.width;
    canvas.height = bitmap.height;
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("no 2d context");
    ctx.drawImage(bitmap, 0, 0);
    return await new Promise((resolve, reject) => {
      canvas.toBlob((b) => (b ? resolve(b) : reject(new Error("toBlob failed"))), "image/png");
    });
  } finally {
    bitmap.close?.();
  }
}

async function imageUrlToPngClipboardBlob(src) {
  const url = new URL(String(src || ""), location.href).href;
  const img = new Image();
  // Same-origin uploads work without CORS; external URLs need anonymous.
  if (!url.startsWith("blob:") && !url.startsWith("data:") && !url.startsWith(location.origin)) {
    img.crossOrigin = "anonymous";
  }
  await new Promise((resolve, reject) => {
    img.onload = () => resolve();
    img.onerror = () => reject(new Error("图片加载失败"));
    img.src = url;
  });
  const canvas = document.createElement("canvas");
  canvas.width = img.naturalWidth || img.width;
  canvas.height = img.naturalHeight || img.height;
  if (!canvas.width || !canvas.height) throw new Error("empty image");
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("no 2d context");
  ctx.drawImage(img, 0, 0);
  return await new Promise((resolve, reject) => {
    canvas.toBlob((b) => (b ? resolve(b) : reject(new Error("toBlob failed"))), "image/png");
  });
}

async function writePngBlobToClipboard(pngBlob) {
  if (!window.isSecureContext || !navigator.clipboard?.write || typeof ClipboardItem === "undefined") {
    throw new Error("clipboard unsupported");
  }
  // Browsers generally only accept image/png in ClipboardItem.
  await navigator.clipboard.write([new ClipboardItem({ "image/png": pngBlob })]);
}

async function copyNodeImage(nodeId) {
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  if (!node?.imageUrl) {
    showCanvasToast("没有可复制的图片");
    return false;
  }
  if (!window.isSecureContext || !navigator.clipboard?.write) {
    showCanvasToast("当前环境不支持复制图片（请用本机或 HTTPS 打开）");
    return false;
  }
  try {
    const abs = new URL(node.imageUrl, location.href).href;
    let png = null;
    try {
      const res = await fetch(abs, { credentials: "same-origin" });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      png = await blobToPngClipboardBlob(await res.blob());
    } catch {
      png = await imageUrlToPngClipboardBlob(node.imageUrl);
    }
    await writePngBlobToClipboard(png);
    showCanvasToast("图片已复制到剪贴板");
    return true;
  } catch (err) {
    console.warn("copyNodeImage failed", err);
    showCanvasToast("复制图片失败");
    return false;
  }
}

function duplicateSelectedNodes(idsOverride = null) {
  const ids = idsOverride?.length ? idsOverride : getSelectedIds();
  if (!ids.length) return false;
  CanvasClipboard.cloneNodes(ids, 40, 40);
  CanvasHistory.push();
  showCanvasToast(`已创建 ${ids.length} 个副本（含牵线）`);
  return true;
}

function pasteCanvasNodes(opts = {}) {
  if (!CanvasClipboard.hasNodes()) return false;
  const pos = getPasteWorldPos(opts);
  const ids = CanvasClipboard.pasteAt(pos.x, pos.y);
  if (ids.length) {
    CanvasHistory.push();
    showCanvasToast(`已粘贴 ${ids.length} 个节点`);
  }
  return ids.length > 0;
}

function filesFromHtmlString(html, namePrefix = "pasted-image") {
  const raw = String(html || "");
  if (!raw) return [];
  const files = [];
  const seen = new Set();
  const re = /\bsrc=["'](data:image\/[^"']+)["']/gi;
  let match;
  let idx = 0;
  while ((match = re.exec(raw))) {
    const file = dataUrlToFile(match[1], `${namePrefix}-${idx + 1}.png`);
    idx += 1;
    if (!file) continue;
    const key = `${file.size}|${file.type}|${idx}`;
    if (seen.has(key)) continue;
    seen.add(key);
    files.push(file);
  }
  return files;
}

function extForClipboardMime(mime) {
  const m = String(mime || "").toLowerCase();
  if (m === "image/jpeg" || m === "image/jpg") return "jpg";
  if (m === "image/webp") return "webp";
  if (m === "image/gif") return "gif";
  if (m === "image/bmp") return "bmp";
  if (m.startsWith("video/")) return "mp4";
  if (m.startsWith("audio/")) return "mp3";
  return "png";
}

/**
 * Read image/video/audio blobs from the OS clipboard (context-menu paste has no ClipboardEvent).
 * Always returns File[]. Side-channel: CanvasStore._clipboardReadMeta.
 */
async function readSystemClipboardMediaFiles() {
  const meta = { ok: false, unavailable: false, errorName: "", errorMessage: "" };
  CanvasStore._clipboardReadMeta = meta;

  if (!navigator.clipboard?.read) {
    meta.unavailable = true;
    meta.errorMessage = "clipboard.read unavailable";
    return [];
  }
  // http://LAN-IP is not a secure context — API may exist but always fail.
  if (!window.isSecureContext) {
    meta.unavailable = true;
    meta.errorMessage = "insecure context";
    return [];
  }

  let items;
  try {
    items = await navigator.clipboard.read();
    meta.ok = true;
  } catch (err) {
    meta.errorName = String(err?.name || "");
    meta.errorMessage = String(err?.message || err || "");
    return [];
  }

  const files = [];
  let idx = 0;
  for (const item of items || []) {
    const types = Array.isArray(item.types) ? item.types : [];
    for (const type of types) {
      const mime = String(type || "").toLowerCase();
      if (mime === "text/html" || mime === "text/plain") {
        try {
          const blob = await item.getType(type);
          const text = await blob.text();
          for (const file of filesFromHtmlString(text, `clipboard-html-${Date.now()}`)) {
            if (typeof isMediaFile === "function" ? isMediaFile(file) : true) files.push(file);
          }
        } catch {
          /* ignore */
        }
        continue;
      }
      if (!mime.startsWith("image/") && !mime.startsWith("video/") && !mime.startsWith("audio/")) {
        continue;
      }
      try {
        const blob = await item.getType(type);
        if (!blob || !blob.size) continue;
        const ext = extForClipboardMime(mime);
        const file = new File([blob], `pasted-${Date.now()}-${idx}.${ext}`, {
          type: blob.type || mime,
        });
        idx += 1;
        if (typeof isMediaFile === "function" ? isMediaFile(file) : true) files.push(file);
      } catch {
        /* type may be present but unreadable */
      }
    }
  }
  return files;
}

/** Start clipboard.read under the paste-button pointerdown gesture. */
function prefetchContextClipboardMedia() {
  CanvasStore._ctxClipboardMediaPromise = readSystemClipboardMediaFiles().catch(() => []);
  CanvasStore._ctxClipboardMediaAt = Date.now();
}

async function pastePlainTextAsCanvasNode(plain, opts = {}) {
  const text = String(plain || "").trim();
  if (!text || text.length < 8) return false;
  if (parseCanvasNodesClipboardPayload(text)) return false;
  const pos = getPasteWorldPos(opts);
  if (window.tryImportNeowowClipboard) {
    const handled = await window.tryImportNeowowClipboard(text, pos);
    if (handled) return true;
  }
  CanvasHistory.push();
  const node = CanvasStore.addNode("text", pos.x - 140, pos.y - 90);
  const title = text.length > 24 ? `${text.slice(0, 24)}…` : text.slice(0, 24);
  CanvasStore.updateNode(node.id, {
    customName: title.replace(/\s+/g, " "),
    prompt: text,
    resultText: text,
    status: "completed",
  });
  renderNodes();
  selectSingle(node.id);
  updateNodeCount();
  updateCanvasHint();
  showCanvasToast("已粘贴为文本节点");
  return true;
}

/**
 * Context-menu paste: try OS clipboard images via clipboard.read, then canvas nodes / text.
 * System images are most reliable with Ctrl+V (browser paste event).
 */
async function pasteFromSystemOrCanvasClipboard(opts = {}) {
  let mediaFiles = [];
  const pref = CanvasStore._ctxClipboardMediaPromise;
  CanvasStore._ctxClipboardMediaPromise = null;
  if (pref) {
    try {
      mediaFiles = await pref;
    } catch {
      mediaFiles = [];
    }
  }
  if (!mediaFiles.length) {
    mediaFiles = await readSystemClipboardMediaFiles();
  }

  if (isWorkbenchViewActive()) {
    if (mediaFiles.length && typeof wbImportExternalFiles === "function") {
      await wbImportExternalFiles(mediaFiles);
      return true;
    }
    showCanvasToast("请按 Ctrl+V 粘贴素材");
    return false;
  }

  const pos = getPasteWorldPos(opts);

  if (mediaFiles.length) {
    await importMediaFilesAt(mediaFiles, pos.x, pos.y);
    return true;
  }

  const ok = await ensureCanvasClipboardLoaded("", { allowMemory: true });
  if (ok && pasteCanvasNodes(opts)) return true;

  if (navigator.clipboard?.readText) {
    try {
      const plain = String((await navigator.clipboard.readText()) || "").trim();
      if (plain && (await pastePlainTextAsCanvasNode(plain, opts))) return true;
    } catch {
      /* permission / insecure */
    }
  }

  showCanvasToast("系统图片请直接按 Ctrl+V 粘贴");
  return false;
}

async function pasteCanvasNodesFromAnyClipboard(opts = {}, plainText = "", loadOpts = {}) {
  const ok = await ensureCanvasClipboardLoaded(plainText, loadOpts);
  if (!ok) {
    showCanvasToast("剪贴板没有可粘贴的节点");
    return false;
  }
  return pasteCanvasNodes(opts);
}

/** Copy/cut/paste nodes on canvas — never while focus is in a prompt editor. */
function tryNodeClipboardShortcut(e) {
  if (!isCanvasActive()) return false;
  if (isEditingPromptContext(e.target)) return false;
  if (isFocusInCanvasChrome(e.target)) return false;
  if (isFloatingCanvasUiOpen()) return false;
  const mod = e.ctrlKey || e.metaKey;
  if (!mod) return false;

  const key = e.key.toLowerCase();
  if (key === "c") {
    if (hasPageTextSelectionOutsideCanvas()) return false;
    if (!getSelectedIds().length) return false;
    e.preventDefault();
    void copySelectedNodes();
    return true;
  }
  if (key === "x") {
    if (!getSelectedIds().length) return false;
    e.preventDefault();
    void cutSelectedNodes();
    return true;
  }
  if (key === "v") {
    // Do not preventDefault — let the document "paste" handler see e.clipboardData
    // so external Ctrl+C (text/image) is not overridden by stale CanvasClipboard nodes.
    // Context-menu paste still goes through pasteCanvasNodesFromAnyClipboard.
    return false;
  }
  return false;
}

async function deleteSelectedNodes(skipConfirm = false, idsOverride = null) {
  const ids = [...(idsOverride || getSelectedIds())];
  if (!ids.length) return false;
  const board = CanvasStore.activeBoard();
  const nodes = ids.map((id) => board?.nodes?.find((n) => n.id === id)).filter(Boolean);
  const busyNodes = nodes.filter(isNodeBusyForDelete);
  const busyCount = busyNodes.length;

  // Generating / uploading nodes always need an explicit confirm (even for Del / context menu).
  if (busyCount > 0) {
    const ok = await AppDialog.confirm(
      busyCount === 1
        ? "该节点正在生成或处理中。删除后当前任务会取消，已产生的结果不会回到画布，是否仍要删除？"
        : `选中的节点中有 ${busyCount} 个正在生成或处理中。删除后这些任务会取消且结果不会返回画布，是否仍要删除？`,
      {
        title: "节点进行中",
        okText: "仍要删除",
        danger: true,
      }
    );
    if (!ok) return false;
  } else if (!skipConfirm) {
    const message =
      ids.length > 1 ? `删除选中的 ${ids.length} 个节点？` : "删除此节点？";
    const ok = await AppDialog.confirm(message, {
      title: "删除确认",
      okText: "删除",
      danger: true,
    });
    if (!ok) return false;
  }

  if (busyCount > 0) await abortBusyNodeTasks(busyNodes);

  // Queue only media unique to the deleted nodes — not a full orphan scan.
  // Files stay on disk 3 days; undo restores nodes + clears this queue entry via history.
  const exclusiveUrls = collectExclusiveMediaUrlsForNodes(board, ids);
  ids.forEach((id) => CanvasStore.deleteNode(id, false));
  if (exclusiveUrls.length) {
    queuePendingAssetDeletes(board, exclusiveUrls);
  }
  CanvasHistory.push();
  CanvasStore.save();
  clearSelection();
  ConnectionUI.cancel();
  renderNodes();
  updateNodeCount();
  updateCanvasHint();
  showCanvasToast(
    busyCount > 0
      ? `已删除 ${ids.length} 个节点（进行中的任务已取消）`
      : `已删除 ${ids.length} 个节点`
  );
  return true;
}

/** Media URL fields mirrored from backend board_assets._MEDIA_KEYS. */
const NODE_MEDIA_URL_KEYS = ["imageUrl", "videoUrl", "audioUrl", "coverUrl", "thumbUrl", "aiMarkBaseUrl"];

function normalizeUploadUrlKey(url) {
  let raw = String(url || "").trim();
  if (!raw) return "";
  raw = raw.split("?")[0].split("#")[0];
  try {
    if (/^https?:\/\//i.test(raw)) raw = new URL(raw).pathname || raw;
  } catch {
    /* ignore */
  }
  if (!raw.startsWith("/")) raw = `/${raw.replace(/^\/+/, "")}`;
  return raw;
}

/** Identity keys so shared copies match across boards / thumb derivatives / flat paths. */
function uploadUrlIdentityKeys(url) {
  const keys = new Set();
  const key = normalizeUploadUrlKey(url);
  if (!key || !key.includes("/uploads/")) return keys;
  keys.add(key);
  const name = key.split("/").pop() || "";
  if (!name) return keys;
  keys.add(name);
  keys.add(`/uploads/${name}`);
  let stem = name.replace(/\.[^.]+$/, "");
  if (!stem) return keys;
  keys.add(stem);
  for (let i = 0; i < 3; i++) {
    if (stem.endsWith("_poster_thumb")) stem = stem.slice(0, -"_poster_thumb".length);
    else if (stem.endsWith("_poster")) stem = stem.slice(0, -"_poster".length);
    else if (stem.endsWith("_thumb")) stem = stem.slice(0, -"_thumb".length);
    else break;
    if (stem) keys.add(stem);
  }
  return keys;
}

/** True when cover/thumb looks like a derivative of this video (same upload stem).
 *  Returns null when either side is not a recognizable /uploads path (e.g. blob poster). */
function videoStillCoverMatches(videoUrl, coverUrl) {
  const vk = uploadUrlIdentityKeys(videoUrl);
  const ck = uploadUrlIdentityKeys(coverUrl);
  if (!vk.size || !ck.size) return null;
  for (const k of ck) {
    if (vk.has(k)) return true;
  }
  return false;
}

function collectNodeMediaUrls(node) {
  const urls = new Set();
  if (!node || typeof node !== "object") return urls;
  for (const key of NODE_MEDIA_URL_KEYS) {
    const u = String(node[key] || "").trim();
    if (u.includes("/uploads/")) urls.add(u);
  }
  for (const entry of node.genHistory || []) {
    if (!entry || typeof entry !== "object") continue;
    for (const key of NODE_MEDIA_URL_KEYS) {
      const u = String(entry[key] || "").trim();
      if (u.includes("/uploads/")) urls.add(u);
    }
    for (const ref of entry.references || []) {
      const u = String(ref?.url || "").trim();
      if (u.includes("/uploads/")) urls.add(u);
    }
  }
  return urls;
}

/** Build usage key set across boards; optionally ignore nodes being deleted on one board. */
function buildMediaUsageKeySet(boards, { excludeBoardId = null, excludeNodeIds = null } = {}) {
  const keys = new Set();
  const skipIds = excludeNodeIds ? new Set(excludeNodeIds) : null;
  for (const board of boards || []) {
    if (!board || !Array.isArray(board.nodes)) continue;
    const skipOnThis = excludeBoardId && board.id === excludeBoardId ? skipIds : null;
    for (const node of board.nodes) {
      if (skipOnThis?.has(node.id)) continue;
      for (const u of collectNodeMediaUrls(node)) {
        for (const k of uploadUrlIdentityKeys(u)) keys.add(k);
      }
    }
  }
  return keys;
}

function mediaUrlStillReferenced(url, usageKeys) {
  if (!usageKeys?.size) return false;
  for (const k of uploadUrlIdentityKeys(url)) {
    if (usageKeys.has(k)) return true;
  }
  return false;
}

/** URLs used by deleted nodes and not by any remaining node on any loaded board. */
function collectExclusiveMediaUrlsForNodes(board, nodeIds) {
  if (!board || !nodeIds?.length) return [];
  const idSet = new Set(nodeIds);
  const fromDeleted = new Set();
  for (const node of board.nodes || []) {
    if (!idSet.has(node.id)) continue;
    for (const u of collectNodeMediaUrls(node)) fromDeleted.add(u);
  }
  if (!fromDeleted.size) return [];
  // Cross-board + same-board copies (Ctrl+D / paste) share filenames — never queue those.
  const usageKeys = buildMediaUsageKeySet(CanvasStore.boards || [board], {
    excludeBoardId: board.id,
    excludeNodeIds: nodeIds,
  });
  return [...fromDeleted].filter((u) => !mediaUrlStillReferenced(u, usageKeys));
}

function queuePendingAssetDeletes(board, urls) {
  if (!board || !urls?.length) return;
  const cleaned = [...new Set(urls.map((u) => String(u || "").trim()).filter(Boolean))];
  if (!cleaned.length) return;
  if (!Array.isArray(board.pendingAssetDeletes)) board.pendingAssetDeletes = [];
  board.pendingAssetDeletes.push({
    at: new Date().toISOString(),
    refs: cleaned,
  });
  // Bound growth if someone deletes heavily without waiting for server prune.
  if (board.pendingAssetDeletes.length > 200) {
    board.pendingAssetDeletes = board.pendingAssetDeletes.slice(-200);
  }
}

function setBoardCover(nodeId) {
  const board = CanvasStore.activeBoard();
  board.coverNodeId = nodeId;
  CanvasStore.save();
  updateTopAvatarCover();
  showCanvasToast("已设为画布封面");
}

async function refreshCanvasView(options = {}) {
  if (CanvasEnterTransition._busy) {
    showCanvasToast("正在刷新…");
    return;
  }
  hideContextMenus({ immediate: true });
  try {
    const ok = await CanvasEnterTransition.runTransition(
      async () => {
        await CanvasStore.syncFromServer({ force: true });
        if (typeof window.syncAllNodesFromTasks === "function") {
          await window.syncAllNodesFromTasks();
        }
        connStaticDirty = true;
        scheduleRenderConnections(true);
        renderNodes();
        bindNodeInteractions();
        stripCanvasTitles();
        initConnectionInteractions();
        updateNodeCount();
        updateCanvasHint();
        renderBoardDropdown();
        updateTopAvatarCover();
        applyViewport();
      },
      { minMs: 360 }
    );
    if (ok) {
      showCanvasToast(options.fromStaleGuard ? "已更新为最新画板" : "画布已刷新");
    }
  } catch (err) {
    showCanvasToast(err?.message || "刷新失败");
  }
}
window.refreshCanvasView = refreshCanvasView;

const FLOATING_MENU_ANIM_MS = 160;

function isFloatingMenuOpen(menu) {
  return !!menu && menu.classList.contains("is-floating-open") && !menu.classList.contains("hidden");
}

function hideFloatingMenu(menu, { immediate = false } = {}) {
  if (!menu) return;
  clearTimeout(menu._hideTimer);
  if (menu._openRaf) {
    cancelAnimationFrame(menu._openRaf);
    menu._openRaf = null;
  }
  menu.classList.remove("is-floating-open");
  if (immediate || menu.classList.contains("hidden")) {
    menu.classList.add("hidden");
    return;
  }
  menu._hideTimer = setTimeout(() => {
    menu.classList.add("hidden");
    menu._hideTimer = null;
  }, FLOATING_MENU_ANIM_MS);
}

function revealFloatingMenu(menu, sx, sy, opts = {}) {
  if (!menu) return;
  clearTimeout(menu._hideTimer);
  if (menu._openRaf) {
    cancelAnimationFrame(menu._openRaf);
    menu._openRaf = null;
  }
  menu.classList.remove("hidden", "is-floating-open");
  positionContextMenu(menu, sx, sy, opts);
  void menu.offsetWidth;
  menu._openRaf = requestAnimationFrame(() => {
    menu._openRaf = null;
    if (menu.classList.contains("hidden")) return;
    menu.classList.add("is-floating-open");
  });
}

function positionContextMenu(menu, sx, sy, opts = {}) {
  const { anchor = "topleft" } = opts;
  menu.classList.remove("hidden");
  const w = menu.offsetWidth || 180;
  const h = menu.offsetHeight || 120;
  let x = sx;
  let y = sy;
  if (anchor === "center-above") {
    x = sx - w / 2;
    y = sy - h - 16;
  }
  if (y + h > window.innerHeight - 8) y = Math.max(8, sy - h - 16);
  if (y < 8 && sy + 16 + h < window.innerHeight) y = sy + 16;
  x = Math.min(Math.max(8, x), window.innerWidth - w - 8);
  y = Math.min(Math.max(8, y), window.innerHeight - h - 8);
  menu.style.left = x + "px";
  menu.style.top = y + "px";
}

function updateContextMenuStates() {
  // Paste may come from memory, system clipboard JSON, or localStorage — try on click.
  const canPaste = true;
  const canUndo = CanvasHistory.canUndo();
  const canRedo = CanvasHistory.canRedo();
  document.querySelectorAll("#ctx-menu-canvas [data-action='paste'], #ctx-menu-node [data-action='paste']").forEach((btn) => {
    btn.disabled = !canPaste;
  });
  document.querySelectorAll("#ctx-menu-canvas [data-action='undo']").forEach((btn) => {
    btn.disabled = !canUndo;
  });
  document.querySelectorAll("#ctx-menu-canvas [data-action='redo']").forEach((btn) => {
    btn.disabled = !canRedo;
  });
}

function hideContextMenus({ immediate = false } = {}) {
  const addMenu = document.getElementById("add-menu");
  const addWasOpen = isFloatingMenuOpen(addMenu);
  hideFloatingMenu(document.getElementById("ctx-menu-canvas"), { immediate });
  hideFloatingMenu(document.getElementById("ctx-menu-node"), { immediate });
  hideFloatingMenu(addMenu, { immediate });
  if (addWasOpen) clearAddNodePlacement();
}

function showAddMenuAt(sx, sy) {
  const menu = document.getElementById("add-menu");
  if (!menu) return;
  closeExclusiveChromePopovers("menu");
  hideFloatingMenu(document.getElementById("ctx-menu-canvas"), { immediate: true });
  hideFloatingMenu(document.getElementById("ctx-menu-node"), { immediate: true });
  revealFloatingMenu(menu, sx, sy);
}

function openAddMenuAtScreen(cx, cy, opts = {}) {
  // Dblclick: stay position = click. Context "添加节点": keep last hover (do not use right-click).
  if (opts.setPlace) {
    CanvasStore._placeX = cx;
    CanvasStore._placeY = cy;
  }
  showAddMenuAt(cx, cy);
  captureAddNodePlacement();
}

function showCanvasContextMenu(sx, sy, worldPos) {
  // Keep _placeX/_placeY = last canvas hover. Right-click only stores paste target.
  CanvasStore._ctxPos = worldPos;
  CanvasStore._ctxNodeId = null;
  CanvasStore._ctxTargetIds = null;
  updateContextMenuStates();
  const menu = document.getElementById("ctx-menu-canvas");
  closeExclusiveChromePopovers("menu");
  hideContextMenus({ immediate: true });
  revealFloatingMenu(menu, sx, sy);
}

function showNodeContextMenu(sx, sy, nodeId) {
  const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
  if (!node) return;
  CanvasStore._ctxNodeId = nodeId;
  CanvasStore._ctxPos = {
    x: node.x + getNodeWidth(node) / 2,
    y: node.y + getNodeFrameHeight(node) / 2,
  };
  updateContextMenuStates();
  const menu = document.getElementById("ctx-menu-node");
  const selected = getSelectedIds();
  const targetIds = selected.length ? selected : [nodeId];
  CanvasStore._ctxTargetIds = [...targetIds];
  const downloadable = countDownloadableNodes(targetIds);
  const upscalable = countUpscalableVideoNodes(targetIds);
  const copyImageBtn = menu.querySelector("[data-action='copy-image']");
  if (copyImageBtn) copyImageBtn.disabled = targetIds.length > 1 || !node.imageUrl;
  const downloadBtn = menu.querySelector("[data-action='download']");
  if (downloadBtn) downloadBtn.disabled = downloadable === 0;
  const downloadLabel = menu.querySelector("[data-ctx-label='download']");
  if (downloadLabel) {
    downloadLabel.textContent = targetIds.length > 1 ? `下载选中（${downloadable} 个文件）` : "下载";
  }
  menu.querySelectorAll("[data-ctx-section='upscale']").forEach((el) => {
    el.classList.add("hidden");
  });
  menu.querySelectorAll("[data-action='upscale-ai'], [data-action='upscale-basic']").forEach((btn) => {
    btn.disabled = upscalable === 0;
  });
  const upscaleAiLabel = menu.querySelector("[data-ctx-label='upscale-ai']");
  if (upscaleAiLabel) {
    upscaleAiLabel.textContent = "";
  }
  const upscaleBasicLabel = menu.querySelector("[data-ctx-label='upscale-basic']");
  if (upscaleBasicLabel) {
    upscaleBasicLabel.textContent = "";
  }
  const groupLabel = menu.querySelector("[data-ctx-label='group']");
  if (groupLabel) {
    groupLabel.textContent = targetIds.length > 1 ? `打组（${targetIds.length} 个节点）` : "打组（单节点）";
  }
  const deleteLabel = menu.querySelector("[data-ctx-label='delete']");
  if (deleteLabel) {
    deleteLabel.textContent = targetIds.length > 1 ? `删除（${targetIds.length} 个节点）` : "删除";
  }
  closeExclusiveChromePopovers("menu");
  hideContextMenus({ immediate: true });
  revealFloatingMenu(menu, sx, sy);
}

function handleContextMenuAction(action, source) {
  hideContextMenus();
  releaseCanvasInteractionState();
  const nodeId = CanvasStore._ctxNodeId || getSelectedIds()[0] || null;
  const contextIds = () => {
    const snapped = CanvasStore._ctxTargetIds;
    if (Array.isArray(snapped) && snapped.length) return [...snapped];
    const selected = getSelectedIds();
    if (selected.length) return selected;
    return nodeId ? [nodeId] : [];
  };

  switch (action) {
    case "add-node":
      // Menu can open at the right-click point; node placement still uses last hover.
      openAddMenuAtScreen(
        CanvasStore._menuX || window.innerWidth / 2,
        CanvasStore._menuY || window.innerHeight / 2
      );
      return;
    case "add-asset":
      document.getElementById("asset-file-input")?.click();
      return;
    case "paste": {
      // Snapshot paste target before menu teardown.
      const pasteOpts = { useContextPos: true };
      void pasteFromSystemOrCanvasClipboard(pasteOpts);
      return;
    }
    case "undo":
      if (tryPromptHistoryUndo()) return;
      CanvasHistory.undo();
      return;
    case "redo":
      if (tryPromptHistoryRedo()) return;
      CanvasHistory.redo();
      return;
    case "refresh":
      void refreshCanvasView();
      return;
    case "rename":
      if (nodeId) NodeRename.open(nodeId);
      return;
    case "copy-image":
      if (nodeId) copyNodeImage(nodeId);
      return;
    case "copy":
      void copySelectedNodes(contextIds());
      return;
    case "cut":
      void cutSelectedNodes(contextIds());
      return;
    case "duplicate":
      duplicateSelectedNodes(contextIds());
      return;
    case "download":
      downloadSelectedMedia(contextIds());
      return;
    case "upscale-ai":
      batchUpscaleSelected(contextIds(), "ai");
      return;
    case "upscale-basic":
      batchUpscaleSelected(contextIds(), "basic");
      return;
    case "set-cover":
      if (nodeId) setBoardCover(nodeId);
      return;
    case "delete": {
      const ids = contextIds();
      CanvasStore._ctxTargetIds = null;
      if (!ids.length) return;
      // Keep multi-selection: never collapse to the right-clicked node alone
      if (ids.length === 1) setSelection(ids, ids[0]);
      else setSelection(ids, null);
      void deleteSelectedNodes(true, ids);
      return;
    }
    default:
      break;
  }
}

function initCanvasContextMenus() {
  updateContextMenuLabels();
  updateContextMenuStates();

  document.querySelectorAll("#ctx-menu-canvas .ctx-item[data-action], #ctx-menu-node .ctx-item[data-action]").forEach((btn) => {
    // Start clipboard.read under pointerdown (stronger user activation than pointerup).
    btn.addEventListener("pointerdown", (e) => {
      if (e.button !== 0) return;
      if (btn.dataset.action !== "paste" || btn.disabled) return;
      prefetchContextClipboardMedia();
    });
    // Use pointerup so action still fires if a drag race clears selection before click
    btn.addEventListener("pointerup", (e) => {
      if (e.button !== 0) return;
      e.preventDefault();
      e.stopPropagation();
      if (btn.disabled) return;
      handleContextMenuAction(btn.dataset.action, btn.closest(".ctx-menu")?.id);
    });
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
    });
  });

  document.querySelectorAll("#add-menu .ctx-item[data-type]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const type = btn.dataset.type;
      // Same as packaged: node top-left = stay/hover world pos (no centering offset).
      const pos = getAddNodeWorldPos();
      addNodeAt(type, pos.x, pos.y);
      CanvasHistory.push();
      hideContextMenus();
    });
  });

  document.getElementById("asset-file-input")?.addEventListener("change", async (e) => {
    const files = collectImportableFiles(e.target.files);
    e.target.value = "";
    if (!files.length) {
      showCanvasToast("未识别到可导入的文件（图片/视频/音频/文本）");
      return;
    }
    const pos = getPasteWorldPos();
    await importMediaFilesAt(files, pos.x, pos.y);
  });
}

function initCanvasShortcuts() {
  window.addEventListener("keydown", (e) => {
    if (tryDeleteNodeFromPromptShortcut(e)) return;
    if (tryNodeClipboardShortcut(e)) return;
    // Prompt editing owns clipboard + undo/redo while caret is in the editor
    if (isEditingPromptContext(e.target)) {
      const mod = e.ctrlKey || e.metaKey;
      if (mod) {
        const k = e.key.toLowerCase();
        const editor =
          e.target?.closest?.(".prompt-editor") ||
          document.activeElement?.closest?.(".prompt-editor");
        if (editor && (k === "z" || k === "y")) {
          e.preventDefault();
          e.stopPropagation();
          if (k === "y" || (k === "z" && e.shiftKey)) PromptHistory.redo(editor);
          else PromptHistory.undo(editor);
        } else if (editor && (k === "c" || k === "x" || k === "v")) {
          // Let browser + initPromptClipboard handle editor text copy/cut/paste
          e.stopPropagation();
        }
      }
      return;
    }

    if (!canUseCanvasShortcuts()) return;

    const mod = e.ctrlKey || e.metaKey;

    if (e.key === "F2") {
      const id = CanvasStore.primaryId || CanvasStore.selectedIds[0];
      if (id) {
        e.preventDefault();
        NodeRename.open(id);
      }
      return;
    }

    if (e.key === "Tab" && !mod) {
      e.preventDefault();
      const addMenu = document.getElementById("add-menu");
      if (isFloatingMenuOpen(addMenu)) {
        hideContextMenus();
        return;
      }
      const cx = CanvasStore._placeX ?? CanvasStore._pointerX ?? CanvasStore._menuX ?? window.innerWidth / 2;
      const cy = CanvasStore._placeY ?? CanvasStore._pointerY ?? CanvasStore._menuY ?? window.innerHeight / 2;
      openAddMenuAtScreen(cx, cy);
      return;
    }

    if (mod && e.key.toLowerCase() === "d") {
      if (duplicateSelectedNodes()) e.preventDefault();
      return;
    }

    if (mod && e.key.toLowerCase() === "z") {
      e.preventDefault();
      if (e.shiftKey) {
        if (!tryPromptHistoryRedo()) CanvasHistory.redo();
      } else if (!tryPromptHistoryUndo()) {
        CanvasHistory.undo();
      }
      return;
    }

    if (mod && e.key.toLowerCase() === "y") {
      e.preventDefault();
      if (!tryPromptHistoryRedo()) CanvasHistory.redo();
      return;
    }

    if ((e.key === "Delete" || e.key === "Backspace") && getSelectedIds().length) {
      e.preventDefault();
      deleteSelectedNodes(true);
    }
  });
}

function showContextMenu(sx, sy, worldPos) {
  CanvasStore._menuX = sx;
  CanvasStore._menuY = sy;
  showCanvasContextMenu(sx, sy, worldPos);
}

function toggleAddMenu() {
  const btn = document.getElementById("btn-add-node");
  if (!btn) return;
  const menu = document.getElementById("add-menu");
  if (isFloatingMenuOpen(menu)) {
    hideContextMenus();
    return;
  }
  const rect = btn.getBoundingClientRect();
  const cx = rect.left + rect.width / 2;
  const cy = rect.top;
  // Packaged froze `_ctxPos` at the + button — freeze last canvas hover instead.
  captureAddNodePlacement();
  hideFloatingMenu(document.getElementById("ctx-menu-canvas"), { immediate: true });
  hideFloatingMenu(document.getElementById("ctx-menu-node"), { immediate: true });
  revealFloatingMenu(menu, cx, cy, { anchor: "center-above" });
}

function hideMenus() {
  hideContextMenus();
}

function addNodeAt(type, x, y) {
  // Adding/selecting near the screen edge must never pan/zoom the canvas.
  const vpSnap = snapshotCanvasViewport();
  let wx = x;
  let wy = y;
  if (wx == null || wy == null) {
    const pos = getAddNodeWorldPos();
    wx = pos.x;
    wy = pos.y;
  }
  // Packaged: exact top-left at stay position — do not center-offset.
  const node = CanvasStore.addNode(type, wx, wy);
  if (node && typeof ensureMyApiNodeModels === "function") ensureMyApiNodeModels({ persist: true });
  renderNodes();
  selectNode(node.id, { focusPrompt: true });
  if (node && typeof updateGenCostBadge === "function") updateGenCostBadge(node.id);
  updateNodeCount();
  updateCanvasHint();
  restoreCanvasViewport(vpSnap);
  // Focus runs on a delay — keep viewport locked through that tick too.
  setTimeout(() => restoreCanvasViewport(vpSnap), 320);
}

function canvasAuthLoggedIn() {
  return Boolean(window.CanvasAuth?.isLoggedIn?.());
}

function canEditBoard(board) {
  return Boolean(board) && board.isOwned !== false;
}

async function showNoPermission(message) {
  const msg = message || "您没有权限操作此画板。";
  if (typeof AppDialog !== "undefined" && AppDialog.alert) {
    await AppDialog.alert(msg, { title: "无权限" });
  } else {
    window.alert(msg);
  }
}

async function guardBoardEnter(boardId, { promptLogin = true } = {}) {
  const board = CanvasStore.boards.find((b) => b.id === boardId);
  if (!board) return false;
  if (!canvasAuthLoggedIn()) {
    if (!promptLogin) return false;
    try {
      await window.CanvasAuth.ensureLogin();
      await Promise.race([
        CanvasStore.loadFromServer(),
        new Promise((r) => setTimeout(r, 3000)),
      ]);
    } catch {
      return false;
    }
  }
  const current = CanvasStore.boards.find((b) => b.id === boardId);
  if (!current) return false;
  // Allow entering owned and shared boards; edit gates stay in canEditBoard callers.
  return true;
}

async function createNewBoard(opts = {}) {
  if (window.CanvasAuth) {
    try {
      await window.CanvasAuth.ensureLogin();
    } catch {
      return null;
    }
    // Prefer local boards; only refresh from server if empty (avoid hang on slow /api/canvas).
    if (!CanvasStore.boards?.length) {
      try {
        await Promise.race([
          CanvasStore.loadFromServer(),
          new Promise((r) => setTimeout(r, 3000)),
        ]);
      } catch {
        /* ignore */
      }
      if (typeof WorkspaceHome !== "undefined" && document.getElementById("app-root")?.classList.contains("is-workspace")) {
        WorkspaceHome.render();
      }
    }
  }
  const openCanvas = opts.openCanvas !== false;
  const name = "画板 " + (CanvasStore.boards.length + 1);
  const board = CanvasStore.createBoard(name);
  CanvasStore.activeBoardId = board.id;
  renderBoardDropdown();
  renderPinnedBoards();
  if (openCanvas) {
    await enterCanvasWithLoader(board.id, {
      skipReload: true,
      afterPrepare() {
        CanvasStore.viewport = defaultBoardViewport();
        const b = CanvasStore.activeBoard();
        if (b) b.viewport = { ...CanvasStore.viewport };
        applyViewport();
      },
    });
  } else {
    WorkspaceHome.render();
  }
  return board;
}

const WorkspaceEnterTransition = {
  _startedAt: 0,
  MIN_MS: 380,
  REVEAL_MS: 480,
  LOADER_FADE_MS: 300,

  isWorkspaceBootRoute() {
    if (window.isAppCanvasPage || window.isAppWorkbenchPage) return false;
    return window.isAppHomePage !== false;
  },

  beginBoot() {
    if (!this.isWorkspaceBootRoute()) return;
    this._startedAt = window.__workspaceBootAt || Date.now();
    document.documentElement.classList.add("is-workspace-booting");
    document.body.classList.add("workspace-enter-loading");
    document.getElementById("canvas-enter-loader")?.setAttribute("aria-busy", "true");
  },

  /** Always restore workspace interactivity (boot CSS uses pointer-events: none). */
  forceClearBoot() {
    document.documentElement.classList.remove("is-workspace-booting", "is-workspace-reveal-active");
    document.body.classList.remove("workspace-enter-loading");
    document.getElementById("app-root")?.classList.remove("is-workspace-reveal");
    const loader = document.getElementById("canvas-enter-loader");
    loader?.classList.add("hidden");
    loader?.classList.remove("is-active", "is-hiding");
    loader?.setAttribute("aria-busy", "false");
    this._startedAt = 0;
  },

  cancelBoot() {
    this.forceClearBoot();
  },

  async revealBoot() {
    if (!document.documentElement.classList.contains("is-workspace-booting")) {
      this.forceClearBoot();
      return;
    }
    const root = document.getElementById("app-root");
    const wait = Math.max(0, this.MIN_MS - (Date.now() - (this._startedAt || Date.now())));
    if (wait) await new Promise((r) => setTimeout(r, wait));
    await waitNextPaint();
    document.documentElement.classList.add("is-workspace-reveal-active");
    root?.classList.add("is-workspace-reveal");
    document.documentElement.classList.remove("is-workspace-booting");
    document.body.classList.remove("workspace-enter-loading");
    const loader = document.getElementById("canvas-enter-loader");
    loader?.classList.add("is-hiding");
    loader?.setAttribute("aria-busy", "false");
    await new Promise((r) => setTimeout(r, this.LOADER_FADE_MS));
    loader?.classList.add("hidden");
    loader?.classList.remove("is-hiding", "is-active");
    await new Promise((r) => setTimeout(r, this.REVEAL_MS));
    root?.classList.remove("is-workspace-reveal");
    document.documentElement.classList.remove("is-workspace-reveal-active");
    this._startedAt = 0;
  },
};

const CanvasEnterTransition = {
  _busy: false,
  _busySince: 0,
  _startedAt: 0,
  MIN_MS: 480,
  REVEAL_MS: 560,
  LOADER_FADE_MS: 300,

  _root() {
    return document.getElementById("app-root");
  },

  _loader() {
    return document.getElementById("canvas-enter-loader");
  },

  _showLoader() {
    const loader = this._loader();
    if (!loader) return;
    loader.classList.remove("hidden", "is-hiding");
    loader.setAttribute("aria-busy", "true");
    if (document.documentElement.classList.contains("is-canvas-booting")) {
      loader.classList.add("is-active");
      return;
    }
    loader.classList.remove("is-active");
    void loader.offsetWidth;
    requestAnimationFrame(() => loader.classList.add("is-active"));
  },

  _hideLoader() {
    const loader = this._loader();
    if (!loader || loader.classList.contains("hidden")) return;
    loader.classList.remove("is-active");
    loader.classList.add("is-hiding");
    loader.setAttribute("aria-busy", "false");
  },

  begin() {
    const root = this._root();
    root?.classList.remove("is-canvas-reveal");
    root?.classList.add("is-canvas-entering");
    document.body.classList.add("canvas-enter-loading");
    this._startedAt = Date.now();
    this._showLoader();
  },

  async reveal() {
    const root = this._root();
    if (!root) return;
    const wait = Math.max(0, this.MIN_MS - (Date.now() - this._startedAt));
    if (wait) await new Promise((r) => setTimeout(r, wait));
    document.documentElement.classList.remove("is-canvas-booting");
    this._hideLoader();
    await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));
    root.classList.add("is-canvas-reveal");
    void root.offsetWidth;
    root.classList.remove("is-canvas-entering");
    await new Promise((r) => setTimeout(r, this.REVEAL_MS));
    root.classList.remove("is-canvas-reveal");
    document.body.classList.remove("canvas-enter-loading");
    await new Promise((r) => setTimeout(r, this.LOADER_FADE_MS));
    const loader = this._loader();
    loader?.classList.add("hidden");
    loader?.classList.remove("is-hiding");
  },

  cancel() {
    const root = this._root();
    document.documentElement.classList.remove("is-canvas-booting");
    root?.classList.remove("is-canvas-entering", "is-canvas-reveal");
    document.body.classList.remove("canvas-enter-loading");
    const loader = this._loader();
    loader?.classList.add("hidden");
    loader?.classList.remove("is-active", "is-hiding");
    loader?.setAttribute("aria-busy", "false");
  },

  async runTransition(task, { minMs } = {}) {
    if (this._busy) return false;
    this._busy = true;
    const prevMin = this.MIN_MS;
    if (typeof minMs === "number") this.MIN_MS = minMs;
    try {
      this.begin();
      await task();
      await waitNextPaint();
      await this.reveal();
      return true;
    } catch (err) {
      this.cancel();
      throw err;
    } finally {
      this.MIN_MS = prevMin;
      this._busy = false;
    }
  },
};

function waitNextPaint() {
  return new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
}

async function prepareCanvasBoard(boardId, { skipReload = false } = {}) {
  if (!skipReload) {
    await CanvasStore.loadFromServer();
  }
  const board = CanvasStore.boards.find((b) => b.id === boardId);
  if (!board) throw new Error("画板不存在");
  CanvasStore.activeBoardId = boardId;

  // Task recovery runs after reveal; an offline worker must not gate first paint.
  await waitNextPaint();
  return board;
}

async function enterCanvasWithLoader(boardId, opts = {}) {
  if (!boardId) return false;
  if (window.isAppHomePage) {
    const { skipGuard = false, promptLogin = true } = opts;
    if (!skipGuard) {
      const ok = await guardBoardEnter(boardId, { promptLogin });
      if (!ok) return false;
    }
    try {
      await CanvasStore.flushSave?.();
    } catch {
      /* ignore */
    }
    window.goAppPage?.("canvas", { id: boardId });
    return true;
  }
  // Dedicated canvas page keeps is-canvas-booting until reveal; do not
  // tear down that overlay here or the empty board flashes first.
  if (!window.isAppCanvasPage) {
    WorkspaceEnterTransition.forceClearBoot();
  }

  // Safety: a previous hung enter must not block forever.
  if (CanvasEnterTransition._busy) {
    const started = Number(CanvasEnterTransition._busySince || 0);
    if (started && Date.now() - started < 8000) {
      console.warn("[enterCanvas] busy, ignore click", boardId);
      if (typeof showCanvasToast === "function") {
        showCanvasToast("正在打开画板，请稍候…");
      }
      return false;
    }
    console.warn("[enterCanvas] clearing stale busy lock");
    CanvasEnterTransition.cancel();
    CanvasEnterTransition._busy = false;
    CanvasEnterTransition._busySince = 0;
  }
  const {
    skipReload = false,
    skipGuard = false,
    promptLogin = true,
    afterPrepare = null,
  } = opts;

  if (!skipGuard) {
    const ok = await guardBoardEnter(boardId, { promptLogin });
    if (!ok) {
      showWorkspaceHome();
      return false;
    }
  }

  const board = CanvasStore.boards.find((b) => b.id === boardId);
  if (!board) {
    showWorkspaceHome();
    return false;
  }

  if (CanvasStore.activeBoardId && CanvasStore.activeBoardId !== boardId) {
    captureActiveBoardViewport();
  }

  CanvasEnterTransition._busy = true;
  CanvasEnterTransition._busySince = Date.now();
  try {
    CanvasEnterTransition.begin();
    // Show canvas chrome immediately so enter never feels stuck on workspace.
    syncAppShellMode("canvas");
    await prepareCanvasBoard(boardId, { skipReload });
    restoreBoardViewport(boardId);
    if (typeof afterPrepare === "function") afterPrepare();

    enterCanvasMode(boardId);
    applyViewport();
    // Saved viewport may point at empty space (stale sync / default). Snap back to nodes.
    const boardNow = CanvasStore.boards.find((b) => b.id === boardId);
    if (
      boardNow?.nodes?.length &&
      typeof isAnyNodeVisibleInViewport === "function" &&
      !isAnyNodeVisibleInViewport() &&
      typeof zoomFit === "function"
    ) {
      await zoomFit(true, { instant: true });
    }
    await waitNextPaint();
    await CanvasEnterTransition.reveal();

    if (boardNow?.nodes?.length && typeof window.syncAllNodesFromTasks === "function") {
      void window.syncAllNodesFromTasks().catch((err) => console.warn("[enterCanvas] task recovery", err));
    }

    // Persist after UI is interactive. Only process queued node-delete media
    // older than 3 days — never a full orphan scan.
    void (async () => {
      try {
        CanvasStore.save();
        await CanvasStore.flushSave?.();
        await purgeBoardFolderOrphans(boardId, { silent: true, flush: false, trustClient: false });
      } catch (err) {
        console.warn("[enterCanvas] post-enter save", err);
      }
      if (typeof window.refreshMyApiModels === "function") {
        void window.refreshMyApiModels();
      }
    })();
    return true;
  } catch (err) {
    console.error("[enterCanvas] failed", boardId, err);
    window.__lastEnterError = String(err && (err.stack || err.message || err));
    try {
      if (typeof showCanvasToast === "function") {
        showCanvasToast(`无法打开画板：${err?.message || err || "未知错误"}`);
      }
    } catch {
      /* ignore */
    }
    CanvasEnterTransition.cancel();
    showWorkspaceHome();
    return false;
  } finally {
    CanvasEnterTransition._busy = false;
    CanvasEnterTransition._busySince = 0;
  }
}
window.enterCanvasWithLoader = enterCanvasWithLoader;

async function switchBoard(boardId) {
  if (!boardId || !CanvasStore.boards.some((b) => b.id === boardId)) return;
  // Board already in memory — skip full canvas reload so enter stays instant.
  await enterCanvasWithLoader(boardId, { skipReload: true });
}

function updateCanvasTopChrome() {
  const inCanvas = !document.getElementById("app-root")?.classList.contains("is-workspace");
  const userWrap = document.getElementById("canvas-user-wrap");
  const pointsBadge = document.getElementById("canvas-points-badge");
  const internalBtn = document.getElementById("btn-canvas-internal");
  userWrap?.classList.toggle("hidden", !inCanvas);
  if (pointsBadge) {
    const loggedIn = canvasAuthLoggedIn();
    const pointsOn = window.AppConfig?.points_enabled !== false;
    pointsBadge.classList.toggle("hidden", !inCanvas || !loggedIn || !pointsOn);
  }
  if (internalBtn) {
    const role = String(window.__canvasUser?.role || "").toLowerCase();
    const isStaff = canvasAuthLoggedIn() && (role === "admin" || role === "internal");
    internalBtn.classList.toggle("hidden", !inCanvas || !isStaff);
  }
}
window.updateCanvasTopChrome = updateCanvasTopChrome;

function syncAppShellMode(mode) {
  const isWorkspace = mode === "workspace";
  const app = document.getElementById("app-root");
  const home = document.getElementById("workspace-home");
  document.documentElement.classList.toggle("route-workspace", isWorkspace);
  app?.classList.toggle("is-workspace", isWorkspace);
  if (home) home.classList.toggle("hidden", !isWorkspace);
  if (!isWorkspace) closeBoardMenus();
  // Hidden workbench/canvas views keep <video> playing; stop audio when landing on home.
  if (isWorkspace) {
    clearAllScheduledMediaReleases();
    pauseAllAppMediaPlayback();
  }
  updateCanvasTopChrome();
  window.updateVersionBadge?.();
}
window.syncAppShellMode = syncAppShellMode;

function enterCanvasMode(boardId) {
  if (boardId) CanvasStore.activeBoardId = boardId;
  const board = CanvasStore.activeBoard();
  if (!board) {
    showWorkspaceHome();
    return;
  }
  if (!canEditBoard(board)) {
    // Shared boards are viewable; edit actions stay gated elsewhere.
    console.info("[enterCanvas] opening shared board read-only", board.id);
  }
  syncAppShellMode("canvas");
  const nameEl = document.getElementById("board-name");
  if (nameEl) nameEl.textContent = board.name;
  closeBoardMenus();
  updateTopAvatarCover();
  updateCanvasTopChrome();
  window.resetLogPanelForBoard?.(board.id);
  window.AgentPanel?.onBoardChange?.(board.id);
  renderPinnedBoards();
  resetMediaThumbStagger();
  renderNodes({ immediate: true });
  bindNodeInteractions();
  stripCanvasTitles();
  initConnectionInteractions();
  updateNodeCount();
  updateCanvasHint();
  try {
    history.replaceState(null, "", window.appPageUrl?.("canvas", { id: board.id }) || `/canvas?id=${encodeURIComponent(board.id)}`);
  } catch {
    /* ignore */
  }
  updateWindowTitle("canvas");
  window.CanvasStaleGuard?.onEnterCanvas?.();
}

function showWorkspaceHome() {
  if (window.isAppCanvasPage || window.isAppWorkbenchPage) {
    window.goAppPage?.("home");
    return;
  }
  window.CanvasStaleGuard?.onLeaveCanvas?.();
  MultiSelectBar?.closeMenu?.();
  document.getElementById("multi-select-bar")?.classList.add("hidden");
  captureActiveBoardViewport();
  // Flush immediately so re-enter / refresh does not load a stale empty viewport.
  void CanvasStore.flushSave?.();
  syncAppShellMode("workspace");
  syncWorkbenchShellMode?.(false);
  closeBoardMenus();
  if (typeof hideMenus === "function") hideMenus();
  WorkspaceHome.render();
  WorkbenchHome?.render?.();
  updateWindowTitle("workspace");
  try {
    history.replaceState(null, "", "#/");
  } catch {
    /* ignore */
  }
}
window.showWorkspaceHome = showWorkspaceHome;

/** Thread records panel: API hard timeout / network retries / poll interval. */
const WorkspaceApiPolicy = {
  _bound: false,
  _saveTimer: 0,

  values() {
    const prefs = typeof CanvasPrefs !== "undefined" ? CanvasPrefs : null;
    return {
      timeoutHours: Math.min(24, Math.max(1, Math.round(Number(prefs?.apiTimeoutHours) || 4))),
      retries: Math.min(30, Math.max(0, Math.round(Number(prefs?.apiRetryCount) || 10))),
      pollSec: Math.min(60, Math.max(1, Math.round(Number(prefs?.apiPollIntervalSec) || 10))),
    };
  },

  applyRuntime() {
    const v = this.values();
    window.AUTO_RETRY_MAX = v.retries;
    window.API_POLL_INTERVAL_SEC = v.pollSec;
    window.API_HARD_TIMEOUT_HOURS = v.timeoutHours;
    if (typeof window.applyApiPolicyToRuntime === "function") {
      window.applyApiPolicyToRuntime(v);
    }
  },

  syncUi() {
    const v = this.values();
    const timeoutEl = document.getElementById("thread-api-timeout");
    const retryEl = document.getElementById("thread-api-retries");
    const pollEl = document.getElementById("thread-api-poll");
    if (timeoutEl && document.activeElement !== timeoutEl) timeoutEl.value = String(v.timeoutHours);
    if (retryEl && document.activeElement !== retryEl) retryEl.value = String(v.retries);
    if (pollEl && document.activeElement !== pollEl) pollEl.value = String(v.pollSec);
    this.applyRuntime();
    this.ensureBound();
  },

  readFromUi() {
    const timeoutEl = document.getElementById("thread-api-timeout");
    const retryEl = document.getElementById("thread-api-retries");
    const pollEl = document.getElementById("thread-api-poll");
    return {
      timeoutHours: Math.min(24, Math.max(1, Math.round(Number(timeoutEl?.value) || 4))),
      retries: Math.min(30, Math.max(0, Math.round(Number(retryEl?.value) || 0))),
      pollSec: Math.min(60, Math.max(1, Math.round(Number(pollEl?.value) || 10))),
    };
  },

  persist(next) {
    if (typeof CanvasPrefs === "undefined") return;
    CanvasPrefs.apiTimeoutHours = next.timeoutHours;
    CanvasPrefs.apiRetryCount = next.retries;
    CanvasPrefs.apiPollIntervalSec = next.pollSec;
    CanvasPrefs.save();
    this.applyRuntime();
    this.syncUi();
    void this.syncServer(next);
  },

  schedulePersist() {
    clearTimeout(this._saveTimer);
    this._saveTimer = setTimeout(() => {
      this.persist(this.readFromUi());
    }, 280);
  },

  async syncServer(next) {
    const apiFn = typeof window.api === "function" ? window.api : null;
    if (!apiFn) return;
    try {
      await apiFn("/api/http-policy", {
        method: "PUT",
        body: JSON.stringify({
          hard_timeout_hours: next.timeoutHours,
          network_retries: next.retries,
          poll_interval_sec: next.pollSec,
        }),
        retries: 1,
        priority: "low",
      });
    } catch (err) {
      console.warn("sync http policy failed", err);
    }
  },

  async loadFromServer() {
    const apiFn = typeof window.api === "function" ? window.api : null;
    if (!apiFn) {
      this.syncUi();
      return;
    }
    try {
      const data = await apiFn("/api/http-policy", { retries: 1, priority: "low" });
      if (data && typeof data === "object" && typeof CanvasPrefs !== "undefined") {
        if (data.hard_timeout_hours != null) {
          CanvasPrefs.apiTimeoutHours = Math.min(
            24,
            Math.max(1, Math.round(Number(data.hard_timeout_hours) || 4))
          );
        }
        if (data.network_retries != null) {
          CanvasPrefs.apiRetryCount = Math.min(
            30,
            Math.max(0, Math.round(Number(data.network_retries) || 0))
          );
        }
        if (data.poll_interval_sec != null) {
          CanvasPrefs.apiPollIntervalSec = Math.min(
            60,
            Math.max(1, Math.round(Number(data.poll_interval_sec) || 10))
          );
        }
        CanvasPrefs.save();
      }
    } catch {
      /* keep local prefs */
    }
    this.syncUi();
  },

  ensureBound() {
    if (this._bound) return;
    this._bound = true;
    const onChange = () => this.schedulePersist();
    ["thread-api-timeout", "thread-api-retries", "thread-api-poll"].forEach((id) => {
      const el = document.getElementById(id);
      if (!el) return;
      el.addEventListener("change", onChange);
      el.addEventListener("input", onChange);
    });
  },
};

window.WorkspaceApiPolicy = WorkspaceApiPolicy;

const WorkspaceHome = {
  render() {
    const grid = document.getElementById("workspace-board-grid");
    if (!grid) return;
    const boards = CanvasStore.sortedBoards();
    const guestHint = "";
    const cards = boards
      .filter((b) => b && b.isOwned !== false)
      .map((b) => {
        const cover = this._coverHtml(b);
        const shortId = String(b.id || "").slice(0, 8);
        return `
        <button type="button" class="workspace-board-card" data-id="${escapeAttr(b.id)}">
          <div class="workspace-board-cover">${cover}</div>
          <div class="workspace-board-meta">
            <h3>${b.pinned ? "📌 " : ""}${escapeHtml(b.name || "未命名画板")}</h3>
            <p>
              <span>${b.nodes?.length || 0} 节点</span>
              <span class="workspace-board-id" title="${escapeAttr(b.id)}">ID ${escapeHtml(shortId)}</span>
            </p>
          </div>
        </button>`;
      })
      .join("");
    const html =
      guestHint +
      `<button type="button" class="workspace-board-card is-new" id="workspace-card-new" title="新建画板">
        <span class="workspace-new-cover" aria-hidden="true"><span class="workspace-new-plus">+</span></span>
        <span class="workspace-new-label">新建画板</span>
      </button>` +
      cards;
    const emptyBoards = boards.filter((b) => !(b.nodes?.length));
    const hint = document.getElementById("workspace-recovery-hint");
    if (hint) {
      const showRecovery = CanvasStore._cacheRestoredCount > 0 && emptyBoards.length > 0;
      hint.hidden = !showRecovery;
      if (!hint.hidden) {
        hint.textContent = `已从浏览器缓存恢复 ${CanvasStore._cacheRestoredCount} 个画板。若节点仍为空，请刷新页面；素材文件若已删除需重新生成。`;
      }
    }
    if (!updateWorkspaceGrid(grid, html)) return;
    grid.querySelectorAll(".workspace-board-card[data-id]").forEach((btn) => {
      btn.addEventListener("click", () => {
        void switchBoard(btn.dataset.id);
      });
      btn.addEventListener("pointerenter", () => window.prefetchAppPage?.("canvas"), { once: true });
      btn.addEventListener("contextmenu", (e) => {
        e.preventDefault();
        e.stopPropagation();
        WorkspaceBoardMenu.open(e, btn.dataset.id);
      });
    });
    grid.querySelector("#workspace-card-new")?.addEventListener("click", () => createNewBoard());
    observeWorkspaceCovers(grid);
  },
  _coverHtml(board) {
    const coverId = board.coverNodeId;
    const node =
      (coverId && board.nodes?.find((n) => n.id === coverId)) ||
      board.nodes?.find((n) => n.imageUrl || n.videoUrl || n.coverUrl);
    if (!node) return `<span class="workspace-board-cover-empty">暂无封面</span>`;
    const thumb = nodeThumbMedia(node);
    // Only one cover thumb per card — never hydrate the whole board's media on the home grid.
    if (thumb.kind === "image" && thumb.src) {
      if (typeof isKnownMediaUrl404 === "function" && isKnownMediaUrl404(thumb.src)) {
        return `<span class="workspace-board-cover-empty">暂无封面</span>`;
      }
      return `<img class="ws-cover-media" data-src="${escapeAttr(thumb.src)}" alt="" decoding="async" />`;
    }
    if (thumb.kind === "video" && thumb.src) {
      if (typeof isKnownMediaUrl404 === "function" && isKnownMediaUrl404(thumb.src)) {
        return `<span class="workspace-board-cover-empty">暂无封面</span>`;
      }
      return `<video class="ws-cover-media" data-src="${escapeAttr(thumb.src)}" muted playsinline preload="none"></video>`;
    }
    return `<span class="workspace-board-cover-empty">暂无封面</span>`;
  },
};

function initWorkspaceHome() {
  window.addEventListener("hashchange", () => applyRouteFromHash());
  WorkspaceBoardMenu.init();
}

const WorkspaceBoardMenu = {
  boardId: null,
  init() {
    const menu = document.getElementById("ctx-menu-workspace-board");
    if (!menu) return;
    menu.querySelectorAll(".ctx-item[data-action]").forEach((btn) => {
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        const action = btn.dataset.action;
        const boardId = this.boardId;
        this.close();
        if (!boardId) return;
        const board = CanvasStore.boards.find((b) => b.id === boardId);
        if (!board) return;
        if (action === "rename") BoardRename.open(boardId);
        else if (action === "share") void window.WorkspaceTransfer?.share("canvas", boardId);
        else if (action === "delete") confirmDeleteBoard(boardId);
      });
    });
    document.addEventListener("click", (e) => {
      if (!e.target.closest("#ctx-menu-workspace-board")) this.close();
    });
    document.addEventListener("contextmenu", (e) => {
      if (e.target.closest("#ctx-menu-workspace-board")) return;
      if (e.target.closest("#workspace-board-grid .workspace-board-card[data-id]")) return;
      this.close();
    });
    document.addEventListener("keydown", (e) => {
      if (e.key === "Escape") this.close();
    });
  },
  open(e, boardId) {
    if (typeof WorkbenchBoardMenu !== "undefined") WorkbenchBoardMenu.close();
    const board = CanvasStore.boards.find((b) => b.id === boardId);
    if (!board || board.isOwned === false) return;
    this.boardId = boardId;
    const menu = document.getElementById("ctx-menu-workspace-board");
    if (!menu) return;
    revealFloatingMenu(menu, e.clientX, e.clientY);
  },
  close() {
    this.boardId = null;
    hideFloatingMenu(document.getElementById("ctx-menu-workspace-board"));
  },
};

function applyRouteFromHash() {
  const route = window.parseAppRoute?.() || {};
  if (window.isAppHomePage) {
    if (route.kind === "canvas" && route.id) {
      window.goAppPage?.("canvas", route);
      return;
    }
    if (route.kind === "workbench") {
      showWorkspaceHome();
      return;
    }
    showWorkspaceHome();
    return;
  }
  if (route.kind === "workbench") {
    window.goAppPage?.("home");
    return;
  }
  if (route.share) {
    showWorkspaceHome();
    showCanvasToast("共享画板已停用，请使用导入/导出");
    return;
  }
  if (route.id && (route.kind === "canvas" || window.isAppCanvasPage)) {
    if (window.isAppWorkbenchPage) {
      window.goAppPage?.("canvas", route);
      return;
    }
    if (CanvasStore.boards.some((b) => b.id === route.id)) {
      void enterCanvasWithLoader(route.id, { promptLogin: false });
      return;
    }
  }
  showWorkspaceHome();
}

async function bootAppView() {
  if (window.isAppHomePage) {
    showWorkspaceHome();
    return false;
  }
  const route = window.parseAppRoute?.() || {};
  if (route.kind === "workbench") {
    window.goAppPage?.("home");
    return false;
  }
  if (route.share) {
    showWorkspaceHome();
    showCanvasToast("共享画板已停用，请使用导入/导出");
    return false;
  }
  const id = route.id;
  if (id) {
    if (!CanvasStore.boards.some((b) => b.id === id)) {
      await CanvasStore.loadFromServer();
    }
    if (CanvasStore.boards.some((b) => b.id === id)) {
      return !!(await enterCanvasWithLoader(id, { promptLogin: false, skipReload: true }));
    }
  }
  showWorkspaceHome();
  return false;
}

const BoardRename = {
  boardId: null,
  open(boardId) {
    const board = CanvasStore.boards.find((b) => b.id === boardId);
    if (!board) return;
    this.boardId = boardId;
    const dialog = document.getElementById("modal-rename-board");
    const input = document.getElementById("input-rename-board");
    if (!dialog || !input) return;
    input.value = board.name || "";
    input.setAttribute("autocomplete", "off");
    input.setAttribute("spellcheck", "false");
    input.readOnly = true;
    revealOverlay(dialog);
    requestAnimationFrame(() => {
      input.readOnly = false;
      input.focus();
      input.select();
    });
  },
  close() {
    this.boardId = null;
    dismissOverlay(document.getElementById("modal-rename-board"));
  },
  save(name) {
    if (!this.boardId) return;
    if (CanvasStore.renameBoard(this.boardId, name)) {
      renderBoardDropdown();
      renderPinnedBoards();
      if (document.getElementById("app-root")?.classList.contains("is-workspace")) {
        WorkspaceHome.render();
      }
    }
    this.close();
  },
};

function initBoardRename() {
  const dialog = document.getElementById("modal-rename-board");
  const form = document.getElementById("form-rename-board");
  const input = document.getElementById("input-rename-board");
  if (!dialog || !form || !input) return;
  form.addEventListener("submit", (e) => {
    e.preventDefault();
    BoardRename.save(input.value);
  });
  document.getElementById("btn-cancel-rename-board")?.addEventListener("click", () => BoardRename.close());
  dialog.addEventListener("cancel", (e) => {
    e.preventDefault();
    BoardRename.close();
  });
}

const BoardDelete = {
  boardId: null,
  open(boardId) {
    const board = CanvasStore.boards.find((b) => b.id === boardId);
    if (!board) return;
    this.boardId = boardId;
    const msg = document.getElementById("delete-board-message");
    if (msg) {
      const name = escapeHtml(board.name || "未命名");
      msg.innerHTML = `将永久删除「<span class="board-delete-name">${name}</span>」及其中的全部节点与素材。`;
    }
    revealOverlay(document.getElementById("modal-delete-board"));
  },
  close() {
    this.boardId = null;
    dismissOverlay(document.getElementById("modal-delete-board"));
  },
  async confirm() {
    const boardId = this.boardId;
    if (!boardId) return;
    this.close();
    try {
      const res = await CanvasStore.deleteBoardRemote(boardId);
      if (!res.ok) {
        await AppDialog.alert(res.reason || "删除失败", { title: "删除失败" });
        return;
      }
    } catch (err) {
      await AppDialog.alert(err.message || "删除失败", { title: "删除失败" });
      return;
    }
    if (typeof window.cancelQueuedGenerationsForBoard === "function") {
      window.cancelQueuedGenerationsForBoard(boardId);
    }
    dismissOverlay(document.getElementById("board-dropdown"), { immediate: true });
    showWorkspaceHome();
  },
};

function initBoardDelete() {
  const dialog = document.getElementById("modal-delete-board");
  if (!dialog) return;
  document.getElementById("btn-confirm-delete-board")?.addEventListener("click", () => BoardDelete.confirm());
  document.getElementById("btn-cancel-delete-board")?.addEventListener("click", () => BoardDelete.close());
  document.getElementById("btn-close-delete-board")?.addEventListener("click", () => BoardDelete.close());
  dialog.addEventListener("cancel", (e) => {
    e.preventDefault();
    BoardDelete.close();
  });
}

async function confirmDeleteBoard(boardId) {
  BoardDelete.open(boardId);
}

function closeBoardMenus({ immediate = false } = {}) {
  dismissOverlay(document.getElementById("board-dropdown"), { immediate });
  dismissOverlay(document.getElementById("board-more-menu"), { immediate });
  document.getElementById("btn-board-switcher")?.classList.remove("is-open");
  document.getElementById("btn-board-switcher")?.setAttribute("aria-expanded", "false");
  document.getElementById("btn-top-avatar")?.classList.remove("is-open");
  document.getElementById("btn-top-avatar")?.setAttribute("aria-expanded", "false");
}

function toggleAvatarMenu() {
  const menu = document.getElementById("board-more-menu");
  const btn = document.getElementById("btn-top-avatar");
  if (!menu || !btn) return;
  dismissOverlay(document.getElementById("board-dropdown"), { immediate: true });
  document.getElementById("btn-board-switcher")?.classList.remove("is-open");
  document.getElementById("btn-board-switcher")?.setAttribute("aria-expanded", "false");
  const opening = !isOverlayOpen(menu);
  if (opening) {
    closeExclusiveChromePopovers("avatar");
    const rect = btn.getBoundingClientRect();
    menu.style.top = `${Math.round(rect.bottom + 8)}px`;
    menu.style.left = `${Math.round(rect.left)}px`;
    const board = CanvasStore.activeBoard();
    const owned = board && board.isOwned !== false;
    menu.querySelector('[data-action="share"]')?.classList.toggle("hidden", !owned);
    menu.querySelector('[data-action="rename"]')?.classList.toggle("hidden", !owned);
    menu.querySelector('[data-action="delete"]')?.classList.toggle("hidden", !owned);
    revealOverlay(menu);
    btn.classList.add("is-open");
    btn.setAttribute("aria-expanded", "true");
  } else {
    dismissOverlay(menu);
    btn.classList.remove("is-open");
    btn.setAttribute("aria-expanded", "false");
  }
}

const TOP_AVATAR_FALLBACK = `<svg width="16" height="16" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="9" r="3.2" stroke="currentColor" stroke-width="1.6"/><path d="M5.5 19c1.2-3 3.5-4.5 6.5-4.5s5.3 1.5 6.5 4.5" stroke="currentColor" stroke-width="1.6" stroke-linecap="round"/></svg>`;

function boardCoverSrc(board) {
  if (!board) return "";
  const coverId = board.coverNodeId;
  const node =
    (coverId && board.nodes?.find((n) => n.id === coverId)) ||
    board.nodes?.find((n) => n.imageUrl || n.coverUrl || n.videoUrl);
  if (!node) return "";
  const thumb = nodeThumbMedia(node);
  return thumb.src || "";
}

function updateTopAvatarCover() {
  const face = document.querySelector("#btn-top-avatar .top-avatar-face");
  if (!face) return;
  const board = CanvasStore.activeBoard();
  const src = boardCoverSrc(board);
  if (!src) {
    face.innerHTML = TOP_AVATAR_FALLBACK;
    return;
  }
  const isVideo = /\.(mp4|webm|mov)(\?|$)/i.test(src) || (board?.nodes || []).some(
    (n) => n.videoUrl && resolveMediaUrl(n.videoUrl) === src && !n.imageUrl && !n.coverUrl
  );
  if (isVideo) {
    face.innerHTML = `<video src="${escapeAttr(src)}" muted playsinline></video>`;
  } else {
    face.innerHTML = `<img src="${escapeAttr(src)}" alt="" />`;
  }
}

let boardDropdownKeepOpen = false;

function toggleBoardDropdown() {
  const dd = document.getElementById("board-dropdown");
  const btn = document.getElementById("btn-board-switcher");
  if (!dd) return;
  dismissOverlay(document.getElementById("board-more-menu"), { immediate: true });
  document.getElementById("btn-top-avatar")?.classList.remove("is-open");
  document.getElementById("btn-top-avatar")?.setAttribute("aria-expanded", "false");
  const opening = !isOverlayOpen(dd);
  if (opening) {
    closeExclusiveChromePopovers("board");
    BoardPicker.query = "";
    BoardPicker.tab = "all";
    boardDropdownKeepOpen = true;
    renderBoardDropdown({ keepOpen: true });
    boardDropdownKeepOpen = false;
    revealOverlay(dd);
    btn?.classList.add("is-open");
    btn?.setAttribute("aria-expanded", "true");
    requestAnimationFrame(() => {
      document.getElementById("board-dd-search-input")?.focus();
    });
  } else {
    closeBoardMenus();
  }
}

const BoardPicker = {
  query: "",
  tab: "all", // all | pinned
};

function boardThumbHtml(board) {
  const coverId = board.coverNodeId;
  const node =
    (coverId && board.nodes?.find((n) => n.id === coverId)) ||
    board.nodes?.find((n) => n.imageUrl || n.videoUrl || n.coverUrl);
  if (!node) {
    return `<span class="board-dd-thumb-empty" aria-hidden="true">
      <svg width="16" height="16" viewBox="0 0 16 16" fill="none"><rect x="2" y="3" width="12" height="10" rx="1.5" stroke="currentColor"/><path d="M4 11l3-3 2 2 3-3.5" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"/></svg>
    </span>`;
  }
  const thumb = nodeThumbMedia(node);
  if (thumb.kind === "image" && thumb.src) {
    return `<img data-src="${escapeAttr(thumb.src)}" alt="" decoding="async" class="media-thumb-lazy" />`;
  }
  if (thumb.kind === "video" && thumb.src) {
    return `<video data-src="${escapeAttr(thumb.src)}" muted playsinline preload="none" class="media-thumb-lazy-vid" data-thumb-seek="1"></video>`;
  }
  return `<span class="board-dd-thumb-empty" aria-hidden="true"></span>`;
}

function filteredBoardsForPicker() {
  const q = (BoardPicker.query || "").trim().toLowerCase();
  let boards = CanvasStore.sortedBoards();
  if (BoardPicker.tab === "pinned") {
    boards = boards.filter((b) => b.pinned);
  }
  if (q) {
    boards = boards.filter(
      (b) =>
        String(b.name || "").toLowerCase().includes(q) ||
        String(b.id || "").toLowerCase().includes(q)
    );
  }
  return boards;
}

function renderPinnedBoards() {
  /* Topbar no longer shows pinned chips (redundant with board name / picker). */
}

function renderBoardDropdown(opts = {}) {
  const board = CanvasStore.activeBoard();
  const nameEl = document.getElementById("board-name");
  if (nameEl) nameEl.textContent = board?.name || "工作区";
  updateTopAvatarCover();
  const dd = document.getElementById("board-dropdown");
  if (!dd) return;
  const keepOpen = Boolean(opts.keepOpen || boardDropdownKeepOpen || isOverlayOpen(dd));

  const list = filteredBoardsForPicker();
  const itemsHtml = list.length
    ? list
        .map((b) => {
          const active = b.id === CanvasStore.activeBoardId;
          return `
        <button type="button" class="board-dd-item${active ? " active" : ""}" data-id="${escapeAttr(b.id)}">
          <span class="board-dd-thumb">${boardThumbHtml(b)}</span>
          <span class="board-dd-item-body">
            <span class="board-dd-item-name">${b.pinned ? "📌 " : ""}${escapeHtml(b.name || "未命名")}</span>
            <span class="board-dd-item-meta">${b.nodes?.length || 0} 节点</span>
          </span>
          <svg class="board-dd-check" width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <path d="M6.5 12.5l3.5 3.5 7.5-7.5" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>
          </svg>
        </button>`;
        })
        .join("")
    : `<div class="board-dd-empty">没有匹配的画板</div>`;

  dd.innerHTML = `
    <div class="board-dd-search">
      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" aria-hidden="true">
        <circle cx="11" cy="11" r="6.5" stroke="currentColor" stroke-width="1.8"/>
        <path d="M16 16l4 4" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>
      </svg>
      <input id="board-dd-search-input" type="search" placeholder="搜索画布" value="${escapeAttr(BoardPicker.query)}" autocomplete="off" />
    </div>
    <div class="board-dd-tabs">
      <button type="button" class="board-dd-tab${BoardPicker.tab === "all" ? " active" : ""}" data-tab="all">全部</button>
      <button type="button" class="board-dd-tab${BoardPicker.tab === "pinned" ? " active" : ""}" data-tab="pinned">置顶</button>
    </div>
    <div class="board-dd-list">${itemsHtml}</div>
    <div class="board-dd-foot">
      <button type="button" class="board-dd-new" id="board-dd-new">
        <span class="board-dd-new-icon">+</span>
        <span>新建画布</span>
      </button>
    </div>`;

  observePanelMediaLazy(dd);
  hydrateMediaThumbs(dd);

  const searchInput = dd.querySelector("#board-dd-search-input");
  searchInput?.addEventListener("input", () => {
    BoardPicker.query = searchInput.value || "";
    boardDropdownKeepOpen = true;
    renderBoardDropdown({ keepOpen: true });
    boardDropdownKeepOpen = false;
    const next = document.getElementById("board-dd-search-input");
    if (next) {
      next.focus();
      const len = next.value.length;
      next.setSelectionRange(len, len);
    }
  });
  searchInput?.addEventListener("click", (e) => e.stopPropagation());
  searchInput?.addEventListener("keydown", (e) => e.stopPropagation());

  dd.querySelectorAll(".board-dd-tab").forEach((tab) => {
    tab.addEventListener("click", (e) => {
      e.stopPropagation();
      BoardPicker.tab = tab.dataset.tab || "all";
      boardDropdownKeepOpen = true;
      renderBoardDropdown({ keepOpen: true });
      boardDropdownKeepOpen = false;
    });
  });
  dd.querySelectorAll(".board-dd-item[data-id]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      closeBoardMenus();
      switchBoard(btn.dataset.id);
    });
  });
  dd.querySelector("#board-dd-new")?.addEventListener("click", (e) => {
    e.stopPropagation();
    closeBoardMenus();
    createNewBoard();
  });
  renderPinnedBoards();
  if (!keepOpen) dismissOverlay(dd);
}

function formatGenDuration(ms) {
  const n = Number(ms);
  if (!Number.isFinite(n) || n < 0) return "";
  if (n < 1000) return `${Math.round(n)}ms`;
  const sec = n / 1000;
  if (sec < 60) return `${sec < 10 ? sec.toFixed(1) : Math.round(sec)}s`;
  const m = Math.floor(sec / 60);
  const s = Math.round(sec % 60);
  return `${m}:${String(s).padStart(2, "0")}`;
}

function ensureNodeGenClock(node) {
  if (!node || !["waiting", "pending", "generating"].includes(node.status)) return false;
  const existing = Number(node.genStartedAt);
  if (Number.isFinite(existing) && existing > 0) {
    // Clamp absurd future clocks from bad cache
    if (existing > Date.now() + 5000) {
      node.genStartedAt = Date.now();
      return true;
    }
    return false;
  }
  node.genStartedAt = Date.now();
  return true;
}

function genElapsedMsForNode(node) {
  if (!node) return null;
  if (["waiting", "pending", "generating"].includes(node.status)) {
    ensureNodeGenClock(node);
    if (node.genStartedAt) return Math.max(0, Date.now() - Number(node.genStartedAt));
  }
  if (node.lastGenMs != null && Number.isFinite(Number(node.lastGenMs))) {
    return Number(node.lastGenMs);
  }
  return null;
}

function renderGenTimeBadge(node) {
  const ms = genElapsedMsForNode(node);
  if (ms == null) return "";
  const live = ["waiting", "pending", "generating"].includes(node.status);
  const title = live ? "已用时" : "生成耗时";
  return `<span class="node-gen-time${live ? " is-live" : ""}" data-gen-elapsed="${node.id}" title="${title}">${formatGenDuration(ms)}</span>`;
}

function ensureGenTimeBadgeEl(wrap, node) {
  if (!wrap || !node?.id) return null;
  let timeEl = wrap.querySelector(`[data-gen-elapsed="${node.id}"]`);
  const ms = genElapsedMsForNode(node);
  if (ms == null) {
    timeEl?.remove();
    return null;
  }
  const live = ["waiting", "pending", "generating"].includes(node.status);
  const title = live ? "已用时" : "生成耗时";
  const text = formatGenDuration(ms);
  if (!timeEl) {
    const label = wrap.querySelector(".node-label");
    if (!label) return null;
    timeEl = document.createElement("span");
    timeEl.className = `node-gen-time${live ? " is-live" : ""}`;
    timeEl.dataset.genElapsed = node.id;
    timeEl.title = title;
    timeEl.textContent = text;
    const ratio = label.querySelector(".node-ratio");
    if (ratio?.nextSibling) label.insertBefore(timeEl, ratio.nextSibling);
    else label.appendChild(timeEl);
    return timeEl;
  }
  timeEl.classList.toggle("is-live", live);
  timeEl.title = title;
  timeEl.textContent = text;
  return timeEl;
}

function isBusyGenStatus(status) {
  return status === "waiting" || status === "pending" || status === "generating";
}

function patchGenActionBtnsUI(node) {
  if (!node?.id) return;
  const wrap = document.querySelector(`.node-wrap[data-id="${node.id}"]`);
  if (!wrap) return;
  const btn = wrap.querySelector(".gen-auto-retry");
  if (btn) {
    const maxRetry = window.AUTO_RETRY_MAX ?? 3;
    const on = !!node.autoRetry;
    const used = Number(node.autoRetryCount) || 0;
    btn.classList.toggle("is-on", on);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    btn.title = on
      ? `API 生成失败后自动重试，最多 ${maxRetry} 次${used ? `（已重试 ${used}/${maxRetry}）` : ""}`
      : `API 生成失败后自动重试，最多 ${maxRetry} 次`;
    let badge = btn.querySelector(".gen-auto-retry-badge");
    if (on && used > 0) {
      if (!badge) {
        badge = document.createElement("span");
        badge.className = "gen-auto-retry-badge";
        btn.appendChild(badge);
      }
      badge.textContent = `${used}/${maxRetry}`;
    } else if (badge) {
      badge.remove();
    }
  }
  ensureGenTimeBadgeEl(wrap, node);
}


/** If channel/model pill text drifted from store (e.g. soft-patch path), refresh toolbar in place. */
function syncChannelToolbarIfStale(wrap, node) {
  if (!wrap || !node) return;
  const labelEl = wrap.querySelector(".channel-btn-label");
  if (!labelEl) return;
  const want = typeof getChannelLabel === "function"
    ? getChannelLabel(typeof resolveNodeChannel === "function" ? resolveNodeChannel(node) : node.channel)
    : String(node.channel || "");
  if (labelEl.textContent !== want) {
    refreshNodeMediaToolbar(node);
    return;
  }
  const modelEl = wrap.querySelector(".video-model-btn-label");
  if (modelEl && typeof getNodeModelLabel === "function") {
    const modelWant = getNodeModelLabel(node, node.model);
    if (modelEl.textContent !== modelWant) refreshNodeMediaToolbar(node);
  }
}

/** Soft-update preview + action row without remounting the prompt editor. */
function softPatchNodeGenUi(wrap, node) {
  if (!wrap || !node) return false;
  const body = wrap.querySelector(".node-body");
  if (!body) return false;
  const oldPreview = body.querySelector(":scope > .node-preview");
  if (!oldPreview) return false;
  const html = (isTextGenNode(node) ? renderTextPreview(node) : renderPreviewContent(node) || "").trim();
  if (!html) return false;
  const tmp = document.createElement("div");
  tmp.innerHTML = html;
  const next = tmp.firstElementChild;
  if (!next) return false;
  oldPreview.replaceWith(next);
  // Results / status swap while @ 列表仍开着会留下悬浮菜单，生成完成时一并关掉。
  if (
    typeof MentionUI !== "undefined" &&
    MentionUI.isOpen?.() &&
    (!MentionUI.hostNodeId || MentionUI.hostNodeId === node.id) &&
    (node.status === "completed" || node.status === "failed" || isBusyGenStatus(node.status))
  ) {
    hideMediaHoverPreviews();
  }
  const actions = wrap.querySelector(".gen-action-btns");
  if (actions) {
    const atmp = document.createElement("div");
    atmp.innerHTML = renderGenActionBtns(node, node.type);
    const anext = atmp.firstElementChild;
    if (anext) actions.replaceWith(anext);
  }
  ensureGenTimeBadgeEl(wrap, node);
  // Label「错」/「新」badges — soft completion used to skip「新」, so it only
  // appeared after a full remount / page refresh.
  const label = wrap.querySelector(".node-label");
  if (label) {
    const wantErr = shouldShowNodeErrorBadge(node);
    let errBadge = label.querySelector(".node-error-badge");
    if (wantErr && !errBadge) {
      const tmp = document.createElement("div");
      tmp.innerHTML = renderNodeErrorBadgeHtml(node.id);
      errBadge = tmp.firstElementChild;
      const newBadge = label.querySelector(".node-new-badge");
      if (errBadge) {
        if (newBadge) label.insertBefore(errBadge, newBadge);
        else label.appendChild(errBadge);
      }
    } else if (!wantErr && errBadge) {
      errBadge.remove();
    }
    const wantNew = shouldShowNodeNewBadge(node);
    let newBadge = label.querySelector(".node-new-badge");
    if (wantNew && !newBadge) {
      const tmp = document.createElement("div");
      tmp.innerHTML = renderNodeNewBadgeHtml();
      newBadge = tmp.firstElementChild;
      if (newBadge) label.appendChild(newBadge);
    } else if (!wantNew && newBadge) {
      newBadge.remove();
    }
  }
  // Panel / sticky error under the prompt (keep media; do not wipe preview)
  const panel = wrap.querySelector(".node-panel");
  if (panel) {
    const toolbar = panel.querySelector(".panel-toolbar");
    const stickyHtml =
      node.status === "failed" &&
      String(node.error || "").trim() &&
      typeof recHasKeepablePreview === "function" &&
      recHasKeepablePreview(node) &&
      typeof renderStickyGenErrorLine === "function"
        ? renderStickyGenErrorLine(node)
        : "";
    let stickyEl = panel.querySelector(".wb-inline-fail");
    let statusEl = panel.querySelector(".node-status");
    if (stickyHtml) {
      statusEl?.remove();
      const tmp = document.createElement("div");
      tmp.innerHTML = stickyHtml;
      const next = tmp.firstElementChild;
      if (next) {
        if (stickyEl) stickyEl.replaceWith(next);
        else if (toolbar) panel.insertBefore(next, toolbar);
        else panel.appendChild(next);
      }
    } else {
      stickyEl?.remove();
      const statusText = node.status === "failed" ? node.error || "生成失败" : "";
      if (statusText) {
        if (!statusEl) {
          statusEl = document.createElement("div");
          statusEl.className = "node-status node-status-error";
          if (toolbar) panel.insertBefore(statusEl, toolbar);
          else panel.appendChild(statusEl);
        }
        statusEl.textContent =
          typeof formatNodeErrorDisplay === "function"
            ? formatNodeErrorDisplay(node.error || statusText, statusText)
            : statusText;
      } else if (statusEl) {
        statusEl.remove();
      }
    }
  }
  // Reference nodes: sticky fail sits under preview-col body
  if (isReferenceNode(node)) {
    const col = wrap.querySelector(".node-preview-col");
    const stickyHtml =
      node.status === "failed" &&
      String(node.error || "").trim() &&
      typeof recHasKeepablePreview === "function" &&
      recHasKeepablePreview(node) &&
      typeof renderStickyGenErrorLine === "function"
        ? renderStickyGenErrorLine(node)
        : "";
    let stickyEl = col?.querySelector(":scope > .wb-inline-fail");
    if (stickyHtml && col) {
      const tmp = document.createElement("div");
      tmp.innerHTML = stickyHtml;
      const next = tmp.firstElementChild;
      if (next) {
        if (stickyEl) stickyEl.replaceWith(next);
        else col.appendChild(next);
      }
    } else {
      stickyEl?.remove();
    }
  }
  scheduleSyncConnectionFlowState();
  return true;
}

/** Swap @mention chip thumbs for one ref without remounting editors. */
function patchMentionChipThumbsForRef(refNodeId) {
  const id = String(refNodeId || "").trim();
  if (!id) return;
  const board = CanvasStore.activeBoard();
  const refNode = board?.nodes?.find((n) => n.id === id);
  if (!refNode || typeof renderMentionChipHtml !== "function") return;
  const safe = typeof CSS !== "undefined" && typeof CSS.escape === "function" ? CSS.escape(id) : id;
  document.querySelectorAll(`.mention-chip[data-ref-id="${safe}"]`).forEach((chip) => {
    if (!chip?.isConnected) return;
    const hostId = chip.closest(".prompt-editor")?.dataset?.node || "";
    const tmp = document.createElement("div");
    tmp.innerHTML = renderMentionChipHtml(refNode, board, hostId, 0);
    const next = tmp.firstElementChild;
    if (!next) return;
    const oldThumb = chip.querySelector(".mention-chip-thumb");
    const newThumb = next.querySelector(".mention-chip-thumb");
    if (oldThumb && newThumb) {
      oldThumb.replaceWith(newThumb);
      hydrateMediaThumbs(chip);
    } else if (!oldThumb && newThumb) {
      chip.insertBefore(newThumb, chip.firstChild);
      hydrateMediaThumbs(chip);
    } else if (oldThumb && !newThumb) {
      oldThumb.remove();
    }
    const label = next.querySelector(".mention-chip-label");
    const curLabel = chip.querySelector(".mention-chip-label");
    if (label && curLabel && curLabel.textContent !== label.textContent) {
      curLabel.textContent = label.textContent;
    }
    chip.classList.toggle("is-unlinked", next.classList.contains("is-unlinked"));
    const aria = next.getAttribute("aria-label");
    if (aria) chip.setAttribute("aria-label", aria);
  });
}

/**
 * Keep history pill ↔ media toolbar in sync without remounting the card.
 * Generation completion used to soft-patch preview only and skip inserting
 * `.media-toolbar` when it did not exist yet (history pill stayed visible).
 */
function syncNodeMediaChrome(wrap, node) {
  if (!wrap || !node) return;
  const col = wrap.querySelector(".node-preview-col") || wrap;
  const hasMediaTools =
    typeof nodeHasCapturableVideo === "function" &&
    (nodeHasCapturableVideo(node) || nodeHasAudio(node) || nodeHasImage(node));
  wrap.classList.toggle("has-media-tools", !!hasMediaTools);

  const insertBeforeChrome = (el) => {
    if (!el || !col) return;
    const anchor =
      col.querySelector(":scope > .node-label-row") ||
      col.querySelector(":scope > .node-body") ||
      col.firstElementChild;
    if (anchor) col.insertBefore(el, anchor);
    else col.appendChild(el);
  };

  const parseFirst = (html) => {
    const text = String(html || "").trim();
    if (!text) return null;
    const tmp = document.createElement("div");
    tmp.innerHTML = text;
    return tmp.firstElementChild;
  };

  // Full media toolbar takes precedence; otherwise lite chrome (copy @ref ± history).
  const tbHtml = (
    (typeof renderMediaToolbar === "function" ? renderMediaToolbar(node) : "") ||
    (typeof renderNodeLiteChrome === "function" ? renderNodeLiteChrome(node) : "") ||
    ""
  ).trim();
  const oldTb = col.querySelector(":scope > .media-toolbar");
  if (tbHtml) {
    const nextTb = parseFirst(tbHtml);
    if (nextTb) {
      if (oldTb) oldTb.replaceWith(nextTb);
      else insertBeforeChrome(nextTb);
    }
  } else if (oldTb) {
    oldTb.remove();
  }

  // Legacy standalone history pill — remove if still present.
  col.querySelectorAll(":scope > .node-history").forEach((el) => el.remove());
}

/**
 * After an in-place media URL change (AI mark, legacy bake, etc.):
 * refresh only this node's preview + hosts that cite it — never remount the whole canvas.
 */
function softRefreshNodeMedia(nodeId, opts = {}) {
  const refreshHosts = opts.refreshHosts !== false;
  const id = String(nodeId || "").trim();
  if (!id) return false;
  const board = CanvasStore.activeBoard();
  const node = board?.nodes?.find((n) => n.id === id);
  const wrap = document.querySelector(`.node-wrap[data-id="${CSS.escape(id)}"]`);
  if (!node) {
    if (refreshHosts) refreshHostsUsingRef(id);
    return false;
  }
  if (!wrap) {
    patchMentionChipThumbsForRef(id);
    if (refreshHosts) refreshHostsUsingRef(id);
    return false;
  }

  const patched = softPatchNodeGenUi(wrap, node);
  if (!patched) {
    // Remount only this card: clear fp so renderNodes rebuilds it; skipFullSideEffects
    // avoids re-hydrating every other video/wire on the board.
    delete wrap.dataset.fp;
    delete wrap.dataset.structFp;
    renderNodes({ immediate: true, skipFullSideEffects: true });
    patchMentionChipThumbsForRef(id);
    if (refreshHosts) refreshHostsUsingRef(id);
    scheduleRenderConnections(true);
    return true;
  }

  const preview = wrap.querySelector(".node-body > .node-preview");
  if (preview) {
    hydrateMediaThumbs(preview);
    preview.querySelectorAll("img.node-preview-img[data-src]").forEach(observeNodeImageLazy);
    if (preview.classList.contains("has-video")) {
      delete preview.dataset.videoHydrated;
      hydrateNodeVideoPoster(preview);
      repairVideoMissingPosterPreviews(preview);
    }
  }

  syncNodeMediaChrome(wrap, node);

  wrap.dataset.fp = nodeDomFingerprint(node);
  wrap.dataset.structFp = nodeStructuralFingerprint(node);
  patchMentionChipThumbsForRef(id);
  if (refreshHosts) refreshHostsUsingRef(id);
  return true;
}

window.softRefreshNodeMedia = softRefreshNodeMedia;
window.patchMentionChipThumbsForRef = patchMentionChipThumbsForRef;

/** Keep waiting ↔ generating preview in sync when fingerprint treats them as the same 「busy」. */
function syncBusyPreviewIfNeeded(wrap, node) {
  if (!wrap || !node || !isBusyGenStatus(node.status)) return;
  const preview = wrap.querySelector(".node-body > .node-preview");
  if (!preview) return;
  const wantPaid = node.userPromptKind === "paid_quota_confirm";
  const isPaid = preview.classList.contains("paid-quota-confirm");
  if (wantPaid !== isPaid) {
    softPatchNodeGenUi(wrap, node);
    return;
  }
  const wantWaiting = node.status === "waiting";
  const isWaiting = preview.classList.contains("waiting");
  const isGenerating = preview.classList.contains("generating");
  if (wantWaiting && isWaiting) return;
  if (!wantWaiting && isGenerating && !isWaiting) return;
  softPatchNodeGenUi(wrap, node);
}

function buildIncomingConnectionKeys(board) {
  const incoming = new Map();
  for (const c of board?.connections || []) {
    if (!incoming.has(c.to)) incoming.set(c.to, []);
    incoming.get(c.to).push(`${c.from}:${c.id}`);
  }
  for (const [id, keys] of incoming) incoming.set(id, keys.join(","));
  return incoming;
}

function nodeStructuralFingerprint(node, incomingKeys) {
  /** Fields that require a full card rebuild (not status/error/timer alone). */
  const board = CanvasStore.activeBoard();
  const incoming = incomingKeys ? (incomingKeys.get(node.id) || "") : (board?.connections || [])
    .filter((c) => c.to === node.id)
    .map((c) => `${c.from}:${c.id}`)
    .join(",");
  const hist = node.genHistory || [];
  return [
    "struct-v1",
    node.type,
    node.ratio || "",
    // Toolbar fields: keep in fingerprint so renderNodes rebuilds when channel/model
    // changes if a caller still uses full render. Prefer refreshNodeMediaToolbar to avoid flash.
    node.model || "",
    node.duration ?? "",
    node.style || "",
    node.accountId || "",
    node.customName || "",
    node.videoUrl || "",
    node.imageUrl || "",
    node.thumbUrl || "",
    node.audioUrl || "",
    node.coverUrl || "",
    node.aiMarked ? "1" : "0",
    node.aiMarkBaseUrl || "",
    nodeAiPassCount(node),
    node.mediaWidth || "",
    node.mediaHeight || "",
    node.activeHistoryId || "",
    node.resultText || "",
    hist.length,
    hist.map((h) => h.id).join(","),
    incoming,
    // softRefIds / quickMentionRecords: refreshed via refreshNodeInputRefs — omit so
    // adding one asset does not remount the whole card (and flash every thumb).
    isTextGenNode(node) ? node.prompt || "" : "",
    nodeHasCapturableVideo(node) || nodeHasAudio(node) || nodeHasImage(node) ? "1" : "0",
    node.autoRetry ? "1" : "0",
    node.autoRetryCount ?? 0,
    node.channel || "",
    node.resolution || "",
    node.useUpgrade ? "1" : "0",
    node.type === "video" ? getNodeVideoGenMode(node) : "",
    node.type === "voice" ? getNodeAudioAppMode(node) : "",
    node.type === "voice" ? String(node.lyrics || "").slice(0, 80) : "",
    node.type === "voice" && node._recording ? `rec${node._recordElapsedSec || 0}` : "",
    // Do NOT include MYAPI_MODELS_VERSION — catalog refresh uses refreshMyApiNodeToolbars.
    isUpscaleEnabled() ? "up1" : "up0",
  ].join("\x1f");
}

function nodeDomFingerprint(node, structuralKey) {
  /** Content that affects node HTML (excludes x/y/selection — those patch via syncSelectionDOM). */
  // waiting/pending/generating share 「busy」 so slot promotion does not rebuild the card.
  const statusKey = isBusyGenStatus(node.status) ? "busy" : node.status;
  return [
    "dom-v7",
    structuralKey ?? nodeStructuralFingerprint(node),
    statusKey,
    node.error || "",
    node.lastGenMs ?? "",
    node.genStartedAt ? "1" : "0",
  ].join("\x1f");
}

function hydrateNodeWrap(wrap) {
  if (!wrap) return;
  if (wrap.dataset?.deferredNode === "1") return;
  // Fresh editors schedule their size after mount. Measuring the still-empty
  // editor here forced the whole canvas to lay out midway through pointerup.
  // Always fill freshly created editors from store (soft skip only after peMounted)
  PromptEditor.mountAll(wrap);
  bindAudioCard(wrap);
  bindNodeVideos(wrap);
  hydrateMediaThumbs(wrap);
  stripCanvasTitles(wrap);
  wrap.querySelectorAll("img.node-preview-img[data-src]").forEach(observeNodeImageLazy);
  wrap.querySelectorAll(".node-preview.has-video").forEach((preview) => {
    repairVideoMissingPosterPreviews(preview);
    if (wrap.classList.contains("is-offscreen")) return;
    ensureVideoFirstFrameVisible(preview);
    if (shouldNodeVideoAutoplay(preview)) {
      ensureNodeVideoLoaded(preview);
      observeNodeVideoLazy(preview);
    }
  });
  const nodeId = wrap.dataset?.id;
  const node = nodeId
    ? CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId)
    : null;
  if (node) {
    const box = wrap.querySelector(".ref-inputs");
    if (box && !box.dataset.mediaRefsKey) {
      box.dataset.mediaRefsKey = getInputRefsRenderKey(node);
    }
    const qm = wrap.querySelector(".panel-qm-records-host");
    if (qm && !qm.dataset.refsKey) {
      qm.dataset.refsKey = getQuickMentionRecordsRenderKey(node);
    }
    const wires = wrap.querySelector(".panel-text-wires-host");
    if (wires && !wires.dataset.refsKey) {
      wires.dataset.refsKey = getWiredTextRefsRenderKey(node);
    }
  }
}

/** Canvas uses icons/labels — no browser title tooltips (they block the view). */
const CANVAS_TOOLTIP_SKIP = ".topbar, .nav-panel, .bottom-bar, dialog, .modal-dialog, .log-panel, .log-fab, .agent-fab, .agent-panel, .node-list-panel, .status-bar-wrap, .workspace-home";

function stripCanvasTitles(root) {
  const scope = root?.querySelectorAll ? root : document.getElementById("viewport");
  if (scope) {
    scope.querySelectorAll("[title]").forEach((el) => {
      if (el.closest(CANVAS_TOOLTIP_SKIP)) return;
      el.removeAttribute("title");
    });
  }
  ["mention-menu", "mention-preview", "mention-chip-tooltip", "prompt-expand", "connect-hint"].forEach((id) => {
    const panel = document.getElementById(id);
    if (!panel) return;
    panel.querySelectorAll("[title]").forEach((el) => el.removeAttribute("title"));
  });
}

// Keep a lightweight geometry shell for distant nodes. Selection/viewport entry
// mounts the card in place, preserving node identity, connections and hit testing.
function mountDeferredNode(wrap, node, incomingKeys) {
  if (wrap.dataset.deferredNode !== "1") return;
  const tmp = document.createElement("div");
  tmp.innerHTML = renderNodeCard(node).trim();
  const card = tmp.firstElementChild;
  wrap.className = card.className;
  wrap.style.cssText = card.style.cssText;
  wrap.replaceChildren(...card.childNodes);
  delete wrap.dataset.deferredNode;
  wrap.dataset.structFp = nodeStructuralFingerprint(node, incomingKeys);
  wrap.dataset.fp = nodeDomFingerprint(node, wrap.dataset.structFp);
  hydrateNodeWrap(wrap);
}

function renderNodesImpl(opts = {}) {
  if (isCanvasInteractionActive()) {
    _canvasPendingRender = { force: !!(_canvasPendingRender?.force || opts.force) };
    scheduleCanvasBackgroundWork();
    return;
  }
  _interactCullCache = null;
  const force = !!opts.force;
  const layer = document.getElementById("nodes-layer");
  const board = CanvasStore.activeBoard();
  if (!layer) return;
  if (!board) {
    clearAllScheduledMediaReleases();
    layer.innerHTML = "";
    updateNodeCount();
    updateCanvasHint();
    return;
  }

  const keepIds = new Set(board.nodes.map((n) => n.id));
  const existing = new Map();
  layer.querySelectorAll(":scope > .node-wrap[data-id]").forEach((el) => {
    existing.set(el.dataset.id, el);
  });

  let removed = 0;
  existing.forEach((el, id) => {
    if (!keepIds.has(id)) {
      cancelScheduledMediaRelease(id);
      el.remove();
      existing.delete(id);
      removed += 1;
    }
  });

  const touched = [];
  const softTouched = [];
  let addedShells = 0;
  const incomingKeys = buildIncomingConnectionKeys(board);
  const viewport = getViewportWorldRect();
  const mountStarted = performance.now();
  for (const node of board.nodes) {
    let wrap = existing.get(node.id);
    const defer = board.nodes.length > 40 && !isNodeExpanded(node)
      && (touched.length >= 24 || performance.now() - mountStarted > 12 || !isNodeRectInViewport(
        { x: node.x, y: node.y, w: getNodeWidth(node), h: getNodeFrameHeight(node) }, VIEWPORT_CULL_MARGIN, viewport));
    if (defer && (!wrap || wrap.dataset.deferredNode === "1")) {
      if (!wrap) {
        wrap = document.createElement("div");
        wrap.className = "node-wrap compact is-offscreen";
        wrap.dataset.id = node.id;
        wrap.dataset.type = node.type;
        wrap.dataset.deferredNode = "1";
        layer.appendChild(wrap);
        existing.set(node.id, wrap);
        addedShells += 1;
      }
      wrap.style.cssText = `left:${node.x}px;top:${node.y}px;width:${getNodeWidth(node)}px;height:${getNodeFrameHeight(node)}px`;
      continue;
    }
    if (wrap?.dataset.deferredNode === "1") mountDeferredNode(wrap, node, incomingKeys);
    const structFp = nodeStructuralFingerprint(node, incomingKeys);
    const fp = nodeDomFingerprint(node, structFp);
    if (!force && wrap && wrap.dataset.fp === fp) {
      // Cheap position sync (selection/expand handled below)
      wrap.style.top = `${node.y}px`;
      wrap.dataset.structFp = structFp;
      syncBusyPreviewIfNeeded(wrap, node);
      syncChannelToolbarIfStale(wrap, node);
      continue;
    }

    // Status / error / timer-only changes: swap preview in place (keeps prompt editor alive).
    // Media URL / history changes still remount here; paintTaskResultNow uses softRefreshNodeMedia.
    if (
      !force &&
      wrap &&
      wrap.dataset.structFp === structFp &&
      softPatchNodeGenUi(wrap, node)
    ) {
      wrap.dataset.fp = fp;
      wrap.dataset.structFp = structFp;
      wrap.style.top = `${node.y}px`;
      syncChannelToolbarIfStale(wrap, node);
      softTouched.push(wrap);
      continue;
    }

    const html = renderNodeCard(node).trim();
    const tmp = document.createElement("div");
    tmp.innerHTML = html;
    const next = tmp.firstElementChild;
    if (!next) continue;
    next.dataset.fp = fp;
    next.dataset.structFp = structFp;

    // Preserve in-progress prompt edit when this card is rebuilt
    const focused = document.activeElement?.closest?.(".prompt-editor");
    const keepEditor = !!(focused && wrap && wrap.contains(focused) && focused.dataset.node === node.id);
    let savedHtml = null;
    if (keepEditor) {
      savedHtml = focused.innerHTML;
      PromptEditor.rememberSelection?.(focused);
    }

    if (wrap) {
      wrap.replaceWith(next);
    } else {
      layer.appendChild(next);
    }
    wrap = next;
    existing.set(node.id, wrap);

    if (keepEditor && savedHtml != null) {
      const ed = wrap.querySelector(`.prompt-editor[data-node="${node.id}"]`);
      if (ed) {
        ed.innerHTML = savedHtml;
        ed.dataset.peMounted = "1";
        try {
          ed.focus({ preventScroll: true });
          PromptEditor.restoreSelection?.(ed);
        } catch {
          /* ignore */
        }
      }
    }

    touched.push(wrap);
  }

  updateNodeCount();
  updateCanvasHint();
  syncSelectionDOM(existing);
  if ((touched.length || addedShells || removed || softTouched.length) && typeof HistoryDock !== "undefined") {
    HistoryDock.refresh();
  }

  // Mount prompts immediately (not only in rAF) so expand/blur never see empty editors
  if (force && !touched.length) {
    hydrateNodeWrap(layer);
  } else {
    touched.forEach((w) => hydrateNodeWrap(w));
    // Soft-patched previews need media hydrate, but not full PromptEditor remount.
    softTouched.forEach((w) => {
      const preview = w.querySelector(".node-body > .node-preview");
      if (!preview) return;
      hydrateMediaThumbs(preview);
      preview.querySelectorAll("img.node-preview-img[data-src]").forEach(observeNodeImageLazy);
      if (preview.classList.contains("has-video")) {
        delete preview.dataset.videoHydrated;
        hydrateNodeVideoPoster(preview);
        repairVideoMissingPosterPreviews(preview);
      }
    });
  }

  const hadRemount = !!(force || touched.length || addedShells || removed);
  const skipFull = !!opts.skipFullSideEffects && !force;
  if (hadRemount && !skipFull) {
    requestAnimationFrame(() => {
      FrameCapture.restoreAfterRender();
      // Only repair remounted cards — never rescrape every video on the board.
      touched.forEach((w) => repairVideoMissingPosterPreviews(w));
    });
    connStaticDirty = true;
    scheduleRenderConnections(true);
    stripCanvasTitles(document.getElementById("canvas-world"));
    syncNodeViewportCull();
    syncCanvasLayerBounds();
    CanvasMinimap.scheduleRender();
    scheduleBoardLegacyAiMarkBakes(board);
  } else if (softTouched.length || removed) {
    // Preview / error-line height may change — refresh wires once, skip full media rescrape.
    scheduleRenderConnections(true);
    syncCanvasLayerBounds();
    CanvasMinimap.scheduleRender();
  }
}

let _renderNodesRaf = 0;
let _renderNodesPending = { force: false, skipFullSideEffects: false };

function flushScheduledRenderNodes() {
  if (!_renderNodesRaf) return;
  cancelAnimationFrame(_renderNodesRaf);
  _renderNodesRaf = 0;
}

function renderNodes(opts = {}) {
  if (opts.immediate) {
    flushScheduledRenderNodes();
    const o = { ..._renderNodesPending, ...opts };
    // A non-skip caller wins over a coalesced skip.
    if (!opts.skipFullSideEffects) o.skipFullSideEffects = false;
    _renderNodesPending = { force: false, skipFullSideEffects: false };
    renderNodesImpl(o);
    return;
  }
  if (opts.force) _renderNodesPending.force = true;
  if (!opts.skipFullSideEffects) _renderNodesPending.skipFullSideEffects = false;
  if (_renderNodesRaf) return;
  _renderNodesRaf = requestAnimationFrame(() => {
    _renderNodesRaf = 0;
    const o = _renderNodesPending;
    _renderNodesPending = { force: false, skipFullSideEffects: false };
    renderNodesImpl(o);
  });
}

function isNodePreviewMediaTarget(el) {
  if (!el?.closest) return false;
  if (el.closest(".node-vid-chrome, .node-vid-btn, .node-vid-scrub, .node-vid-capture, .audio-play-btn")) {
    return false;
  }
  return Boolean(
    el.closest(
      ".node-preview-img, .node-preview.has-video, .node-preview.text-result, .node-preview[data-text-node]"
    )
  );
}

function isNodeDragBlockedTarget(el) {
  if (!el?.closest) return false;
  return Boolean(
    el.closest(
      ".node-delete, .node-port, .node-port-zone, .media-toolbar, .frame-capture-current-bar, " +
        ".btn-capture-current, .node-history, .audio-play-btn, .audio-card-dl, .node-vid-btn, " +
        ".node-vid-scrub, .node-vid-capture, .video-duration-slider, .image-style-picker, " +
        ".video-model-picker, .video-settings-picker, .channel-picker, .channel-btn, .channel-option, .channel-menu, .mention-chip, .ref-chip, " +
        ".text-wire-chip, .quick-mention-float, .qm-pick-menu, .btn-generate-inline, .gen-action-btns, " +
        ".btn-quick-mention, .btn-text-shortcuts, .btn-expand-prompt, .panel-refs, .ref-inputs, .panel-video-modes, .video-mode-tab, .audio-mode-tab, .audio-record-panel, .audio-music-block, .audio-lyrics-input, " +
        ".panel-prompt-tools, .panel-prompt-wrap, .panel-toolbar, .panel-text-wires-host, " +
        ".prompt-editor, .node-prompt, button, input, select, textarea, a, .node-error-badge, .wb-inline-fail"
    )
  );
}

function bindNodeInteractions() {
  const layer = document.getElementById("nodes-layer");
  if (layer.dataset.bound) return;
  layer.dataset.bound = "1";

  layer.addEventListener(canvasPointerType("down"), (e) => {
    // Right / middle click must not start long-press drag (breaks context menu actions)
    if (!isPrimaryCanvasButton(e)) return;
    const wrap = e.target.closest(".node-wrap");
    if (!wrap) return;
    if (isNodeDragBlockedTarget(e.target)) return;
    // 单选展开时让原生 audio 控件可点；多选/未选中时关掉，避免误触
    if (
      e.target.closest("audio") &&
      wrap.classList.contains("is-selected") &&
      !e.altKey
    ) {
      return;
    }

    const id = wrap.dataset.id;
    const mod = isMultiSelectModifier(e);
    const dragHandle = isNodeDragHandleTarget(e.target);
    const onPreview = isNodePreviewMediaTarget(e.target);
    // Label sits inside preview-col; treat like soft drag so dblclick rename still fires.
    const onLabel = Boolean(e.target.closest(".node-label-row, .node-label, .node-label-text"));

    if (!dragHandle) {
      if (mod) {
        e.stopPropagation();
        const board = CanvasStore.activeBoard();
        const node = board.nodes.find((n) => n.id === id);
        if (!node) return;
        const pos = screenToWorld(e.clientX, e.clientY);
        beginLongPress("node", e, {
          nodeId: id,
          selectOnly: true,
          modifier: mod,
          offsetX: pos.x - node.x,
          offsetY: pos.y - node.y,
        });
      }
      return;
    }

    // preventDefault on mousedown suppresses dblclick — skip for title rename target
    if (!onPreview && !onLabel) e.preventDefault();
    e.stopPropagation();

    const board = CanvasStore.activeBoard();
    const node = board.nodes.find((n) => n.id === id);
    if (!node) return;
    const pos = screenToWorld(e.clientX, e.clientY);
    beginLongPress("node", e, {
      nodeId: id,
      modifier: mod,
      fromPreview: onPreview || onLabel,
      offsetX: pos.x - node.x,
      offsetY: pos.y - node.y,
    });
  });

  layer.addEventListener("dblclick", (e) => {
    const label = e.target.closest(".node-label-text, .node-label, .node-label-row");
    if (!label) return;
    const wrap = label.closest(".node-wrap");
    if (!wrap) return;
    e.preventDefault();
    e.stopPropagation();
    NodeRename.open(wrap.dataset.id);
  });

  layer.addEventListener("mouseleave", () => {
    if (!ConnectionUI.dragging) ConnectionUI.clearPreview();
  });
}

function isAnyNodeVisibleInViewport() {
  const board = CanvasStore.activeBoard();
  if (!board?.nodes?.length) return true;
  const vp = getViewportWorldRect();
  const pad = 24;
  return board.nodes.some((n) => {
    const b = nodeBounds(n);
    return !(
      b.x + b.w < vp.x - pad ||
      b.x > vp.x + vp.w + pad ||
      b.y + b.h < vp.y - pad ||
      b.y > vp.y + vp.h + pad
    );
  });
}

function updateOffviewBar() {
  const bar = document.getElementById("canvas-offview-bar");
  if (!bar) return;
  if (document.getElementById("app-root")?.classList.contains("is-workspace")) {
    bar.classList.add("hidden");
    bar.classList.remove("is-visible");
    return;
  }
  const board = CanvasStore.activeBoard();
  const hasNodes = (board?.nodes?.length || 0) > 0;
  const offscreen = hasNodes && !isAnyNodeVisibleInViewport();
  if (!offscreen) CanvasStore._offviewBarDismissed = false;
  const show = offscreen && !CanvasStore._offviewBarDismissed;
  bar.classList.toggle("hidden", !show);
  bar.classList.toggle("is-visible", show);
}

function initOffviewBar() {
  document.getElementById("btn-canvas-offview-go")?.addEventListener("click", (e) => {
    e.stopPropagation();
    zoomFit();
    CanvasStore._offviewBarDismissed = false;
    updateOffviewBar();
  });
  document.getElementById("btn-canvas-offview-close")?.addEventListener("click", (e) => {
    e.stopPropagation();
    CanvasStore._offviewBarDismissed = true;
    updateOffviewBar();
  });
  if (!window.__canvasViewportPersistBound) {
    window.__canvasViewportPersistBound = true;
    const persistVp = () => {
      try {
        if (document.getElementById("app-root")?.classList.contains("is-workspace")) return;
        if (!CanvasStore.activeBoardId) return;
        captureActiveBoardViewport();
        void CanvasStore.flushSave?.();
      } catch {
        /* ignore */
      }
    };
    window.addEventListener("pagehide", persistVp);
    document.addEventListener("visibilitychange", () => {
      if (document.visibilityState === "hidden") persistVp();
    });
  }
}

function updateCanvasHint() {
  const hint = document.getElementById("canvas-hint");
  if (!hint) return;
  const board = CanvasStore.activeBoard();
  const empty = !board || !board.nodes.length;
  hint.classList.toggle("hidden", !empty);
  updateOffviewBar();
}

function getChannelLabel(channel) {
  const defaults = {
    myapi: "MyApi",
    bendi: "BenDi",
    volcengine: "火山引擎",
    doubao_s: "Seed S",
    dola: "Seed",
    dola_s: "Seed",
    doubao: "Seed",
  };
  const key = channel === "dola" || channel === "dola_s" ? channel : channel || "doubao";
  const base = defaults[key] || defaults.doubao;
  const ov = String(window.AppConfig?.ui_display?.channels?.[key]?.label || "").trim();
  return ov || base;
}

/** Apply admin display overrides to built-in models only (never MyApi / public). */
function applyModelUiDisplay(m) {
  if (!m?.id) return m;
  const id = String(m.id);
  if (m.myapi || m.public || id.startsWith("myapi_") || id.startsWith("public_")) return m;
  const ov = window.AppConfig?.ui_display?.models?.[id];
  if (!ov || typeof ov !== "object") return m;
  const label = String(ov.label || "").trim();
  const desc = String(ov.desc || "").trim();
  if (!label && !desc) return m;
  return {
    ...m,
    label: label || m.label,
    desc: desc || m.desc,
  };
}

function withModelUiDisplay(list) {
  return (Array.isArray(list) ? list : []).map(applyModelUiDisplay);
}

function hasMyApiModelsForType(nodeType) {
  if (nodeType === "video") return MYAPI_VIDEO_MODELS.length > 0;
  if (nodeType === "text" || nodeType === "voice-text") return MYAPI_TEXT_MODELS.length > 0;
  if (nodeType === "voice") return MYAPI_VOICE_MODELS.length > 0;
  return MYAPI_IMAGE_MODELS.length > 0;
}

function myApiModelsForType(nodeType) {
  if (nodeType === "video") return MYAPI_VIDEO_MODELS;
  if (nodeType === "text" || nodeType === "voice-text") return MYAPI_TEXT_MODELS;
  if (nodeType === "voice") return MYAPI_VOICE_MODELS;
  return MYAPI_IMAGE_MODELS;
}

/** True when user set a custom MyApi model as default for this node kind. */
function hasMyApiDefaultForType(nodeType) {
  return myApiModelsForType(nodeType).some((m) => m?.is_default && !m?.public);
}

function defaultMyApiModelIdForType(nodeType) {
  const list = myApiModelsForType(nodeType);
  const hit = list.find((m) => m?.is_default && !m?.public);
  return hit?.id || list[0]?.id || "";
}

window.hasMyApiDefaultForType = hasMyApiDefaultForType;
window.defaultMyApiModelIdForType = defaultMyApiModelIdForType;

function resolveNodeChannel(node, { allowGpt = true } = {}) {
  let channel = normalizeChannel(node?.channel, node?.model);
  const nodeType = node?.type || "image";
  void allowGpt;
  if (channel === "volcengine" && !isVolcengineChannelAvailable(nodeType)) {
    channel = preferredChannelForType(nodeType);
  }
  if (channel === "bendi" && !isBendiChannelEnabled()) {
    channel = preferredChannelForType(nodeType);
  }
  if (
    channel === "bendi" &&
    (nodeType === "text" || nodeType === "voice-text") &&
    !(typeof isBendiTextAllowed === "function" && isBendiTextAllowed())
  ) {
    channel = preferredChannelForType(nodeType);
  }
  if (!isBrowserChannelEnabled() && isBytedanceFamilyChannel(channel)) {
    channel =
      isBendiChannelEnabled() &&
      (nodeType === "text" || nodeType === "voice-text"
        ? typeof isBendiTextAllowed === "function" && isBendiTextAllowed()
        : true)
        ? preferredChannelForType(nodeType)
        : "myapi";
  }
  if (!isDoubaoChannelEnabled() && isBytedanceFamilyChannel(channel)) {
    channel = preferredChannelForType(nodeType);
  }
  if (channel === "myapi" && !hasMyApiModelsForType(nodeType)) {
    // Keep MyApi selected when browser channels are off — UI shows「模型无」.
    if (isBrowserChannelEnabled()) {
      channel = preferredChannelForType(nodeType);
    }
  }
  return channel;
}

function migrateDoubaoDisabledNodes() {
  if (isDoubaoChannelEnabled() || typeof CanvasStore === "undefined") return;
  let changed = false;
  CanvasStore.boards.forEach((board) => {
    (board.nodes || []).forEach((node) => {
      const ch0 = normalizeChannel(node.channel, node.model);
      if (ch0 !== "doubao" && ch0 !== "doubao_s" && ch0 !== "dola") return;
      const ch = preferredChannelForType(node.type);
      node.channel = ch;
      node.model = defaultModelForChannel(ch, node.type) || null;
      if (node.type === "video" && !node.model) {
        node.duration = null;
        node.resolution = null;
      }
      if (node.type === "image" && !isBytedanceFamilyChannel(ch)) node.style = null;
      changed = true;
    });
  });
  if (changed) CanvasStore.save();
}
window.migrateDoubaoDisabledNodes = migrateDoubaoDisabledNodes;

/** 历史 Dola 节点统一迁到 DouBao（Dola 渠道已下线）。 */
function migrateDolaSNodes() {
  if (typeof CanvasStore === "undefined") return;
  let changed = false;
  CanvasStore.boards.forEach((board) => {
    (board.nodes || []).forEach((node) => {
      if (!node) return;
      if (
        node.channel === "dola" ||
        node.channel === "dola_s" ||
        node.channel === "Dola" ||
        node.channel === "Dola S"
      ) {
        node.channel = "doubao";
        node.useUpgrade = false;
        changed = true;
      }
    });
  });
  if (changed) CanvasStore.save();
}
window.migrateDolaSNodes = migrateDolaSNodes;

/** 历史浏览器 OpenAI 节点迁到 BenDi（gpt_* → gpt-image / chatgpt）。 */
function migrateGptChannelNodes() {
  if (typeof CanvasStore === "undefined") return;
  let changed = false;
  const mapModel = (node) => {
    const m = String(node.model || "").trim();
    if (m === "gpt_chat" || m === "gpt" || m === "openai") return "chatgpt";
    if (m === "gpt_images" || m === "gpt_chat_images" || m.startsWith("gpt_")) return "gpt-image";
    return null;
  };
  CanvasStore.boards.forEach((board) => {
    (board.nodes || []).forEach((node) => {
      if (!node) return;
      const ch = String(node.channel || "").trim().toLowerCase();
      const isGptCh = ch === "gpt" || ch === "openai";
      const legacyModel = isLegacyBrowserGptModel(node.model);
      if (!isGptCh && !legacyModel) return;
      node.channel = "bendi";
      const mapped = mapModel(node);
      if (mapped) {
        node.model = mapped;
      } else if (node.type === "text" || node.type === "voice-text") {
        node.model = "chatgpt";
      } else if (node.type === "image") {
        node.model = "gpt-image";
      }
      if (node.type === "image") node.style = null;
      changed = true;
    });
  });
  if (changed) CanvasStore.save();
}
window.migrateGptChannelNodes = migrateGptChannelNodes;

function getAccountOptionsHtml(selectedChannel, nodeType = "image") {
  const textLike = nodeType === "text" || nodeType === "voice-text";
  const bendiOk =
    isBendiChannelEnabled() && (!textLike || (typeof isBendiTextAllowed === "function" && isBendiTextAllowed()));
  const volcOk = isVolcengineChannelAvailable(nodeType);
  if (!isBrowserChannelEnabled()) {
    const opts = [];
    if (volcOk) {
      opts.push(
        `<option value="volcengine" ${selectedChannel === "volcengine" ? "selected" : ""}>${escapeHtml(getChannelLabel("volcengine"))}</option>`
      );
    }
    if (bendiOk) {
      opts.push(
        `<option value="bendi" ${selectedChannel === "bendi" ? "selected" : ""}>${escapeHtml(getChannelLabel("bendi"))}</option>`
      );
    }
    if (isMyApiChannelAvailable(nodeType)) {
      const selected =
        selectedChannel === "myapi" || (!selectedChannel && !bendiOk && !volcOk) ? "selected" : "";
      opts.push(`<option value="myapi" ${selected}>${escapeHtml(getChannelLabel("myapi"))}</option>`);
    }
    return opts.join("");
  }
  const channel = resolveNodeChannel({ channel: selectedChannel, type: nodeType, model: null }, {
    allowGpt: false,
  });
  const appChannels = Array.isArray(window.AppConfig?.channels) ? window.AppConfig.channels : null;
  const canUse = (id) => {
    if (id === "bendi") return bendiOk;
    if (id === "volcengine") return volcOk;
    if (!appChannels) return id !== "dola" && id !== "gpt";
    return appChannels.includes(id);
  };
  const browserOn = isBrowserChannelEnabled();
  const opts = [];
  if (browserOn && canUse("doubao") && isDoubaoChannelEnabled()) {
    opts.push(`<option value="doubao" ${channel === "doubao" ? "selected" : ""}>${escapeHtml(getChannelLabel("doubao"))}</option>`);
    opts.push(`<option value="doubao_s" ${channel === "doubao_s" ? "selected" : ""}>${escapeHtml(getChannelLabel("doubao_s"))}</option>`);
  }
  if (canUse("volcengine")) {
    opts.push(`<option value="volcengine" ${channel === "volcengine" ? "selected" : ""}>${escapeHtml(getChannelLabel("volcengine"))}</option>`);
  }
  if (canUse("bendi")) {
    opts.push(`<option value="bendi" ${channel === "bendi" ? "selected" : ""}>${escapeHtml(getChannelLabel("bendi"))}</option>`);
  }
  if (canUse("myapi") && isMyApiChannelAvailable(nodeType)) {
    opts.push(`<option value="myapi" ${channel === "myapi" ? "selected" : ""}>${escapeHtml(getChannelLabel("myapi"))}</option>`);
  }
  return opts.join("");
}

function isMyApiChannelAvailable(nodeType) {
  // Canvas-only pack always exposes MyApi (model list may be empty →「模型无」).
  if (!isBrowserChannelEnabled()) return true;
  const channels = window.AppConfig?.channels;
  if (Array.isArray(channels) && channels.includes("myapi")) return true;
  return hasMyApiModelsForType(nodeType);
}

function getChannelOptions(node, { allowGpt = true } = {}) {
  void allowGpt;
  const textLike = node?.type === "text" || node?.type === "voice-text";
  const voiceLike = node?.type === "voice";
  const volcOk = isVolcengineChannelAvailable(node?.type);
  // Voice: Volcengine and/or MyApi.
  if (voiceLike) {
    const options = [];
    if (volcOk) options.push({ id: "volcengine", label: getChannelLabel("volcengine") });
    if (isMyApiChannelAvailable("voice")) options.push({ id: "myapi", label: getChannelLabel("myapi") });
    return options;
  }
  const bendiOk =
    isBendiChannelEnabled() && (!textLike || (typeof isBendiTextAllowed === "function" && isBendiTextAllowed()));
  // Pure API pack: Volcengine / BenDi / MyApi — never list DouBao browser channels.
  if (!isBrowserChannelEnabled()) {
    const options = [];
    if (volcOk) options.push({ id: "volcengine", label: getChannelLabel("volcengine") });
    if (bendiOk) {
      options.push({ id: "bendi", label: getChannelLabel("bendi") });
    }
    if (isMyApiChannelAvailable(node?.type)) options.push({ id: "myapi", label: getChannelLabel("myapi") });
    return options;
  }
  const appChannels = Array.isArray(window.AppConfig?.channels) ? window.AppConfig.channels : null;
  const canUse = (id) => {
    if (id === "bendi") return bendiOk;
    if (id === "volcengine") return volcOk;
    if (!appChannels) return id !== "dola" && id !== "gpt";
    return appChannels.includes(id);
  };
  const browserOn = isBrowserChannelEnabled();
  const options = [];
  if (browserOn && canUse("doubao") && isDoubaoChannelEnabled()) {
    options.push({ id: "doubao", label: getChannelLabel("doubao") });
    options.push({ id: "doubao_s", label: getChannelLabel("doubao_s") });
  }
  if (canUse("volcengine")) {
    options.push({ id: "volcengine", label: getChannelLabel("volcengine") });
  }
  if (canUse("bendi")) {
    options.push({ id: "bendi", label: getChannelLabel("bendi") });
  }
  if (canUse("myapi") && isMyApiChannelAvailable(node.type)) options.push({ id: "myapi", label: getChannelLabel("myapi") });
  return options;
}

function hasActiveModelsForNode(node) {
  const channel = resolveNodeChannel(node, { allowGpt: node.type !== "video" });
  if (node.type === "image") return imageModelsForChannel(channel).length > 0;
  if (node.type === "video") return videoModelsForNode(node).length > 0;
  if (node.type === "voice") return voiceModelsForChannel(channel).length > 0;
  if (isTextGenNode(node)) {
    if (channel === "myapi" || channel === "bendi" || channel === "volcengine") {
      return textModelsForChannel(channel).length > 0;
    }
    return true;
  }
  return true;
}

function renderMediaEmptyPill() {
  return `<span class="pill-select is-disabled media-pill-empty">模型无</span>`;
}

function renderChannelPicker(node, { allowGpt = true } = {}) {
  const options = getChannelOptions(node, { allowGpt });
  if (!options.length) return "";
  const channel = resolveNodeChannel(node, { allowGpt });
  const single = options.length === 1;
  const items = options
    .map(
      (o) => `
    <button type="button" class="channel-option${o.id === channel ? " active" : ""}" data-node="${node.id}" data-channel="${o.id}">
      <span class="channel-option-label">${escapeHtml(o.label)}</span>
      ${o.id === channel ? '<span class="video-model-check">✓</span>' : ""}
    </button>`
    )
    .join("");
  return `
    <div class="channel-picker${single ? " is-single" : ""}" data-node="${node.id}">
      <button type="button" class="channel-btn pill-select${single ? " is-static" : ""}" data-node="${node.id}" title="渠道"${single ? ' tabindex="-1"' : ""}>
        <span class="channel-btn-label">${escapeHtml(getChannelLabel(channel))}</span>
        ${single ? "" : '<span class="video-model-btn-caret">▾</span>'}
      </button>
      ${single ? "" : `<div class="channel-menu hidden" data-node="${node.id}">${items}</div>`}
    </div>`;
}

function imageModelsForChannel(channel) {
  if (channel === "volcengine") return withModelUiDisplay(VOLCENGINE_IMAGE_MODELS);
  if (!isBrowserChannelEnabled()) {
    if (channel === "bendi") return withModelUiDisplay(BENDI_IMAGE_MODELS);
    return channel === "myapi" ? MYAPI_IMAGE_MODELS.slice() : [];
  }
  if (channel === "bendi") return withModelUiDisplay(BENDI_IMAGE_MODELS);
  if (channel === "myapi") return MYAPI_IMAGE_MODELS.slice();
  const seedream = IMAGE_MODELS.slice();
  const key = bytedanceModelCatalogKey(channel);
  // Ordinary DouBao/Dola: no Seedream 5.0 Pro (requires S).
  if (key === "doubao") return withModelUiDisplay(seedream.filter((m) => !m.upgrade));
  // S channels: full Seedream catalog.
  if (key === "doubao_s") return withModelUiDisplay(seedream);
  return withModelUiDisplay(seedream);
}

function videoModelsForChannel(channel) {
  if (channel === "volcengine") return withModelUiDisplay(VOLCENGINE_VIDEO_MODELS);
  if (!isBrowserChannelEnabled()) {
    if (channel === "bendi") return withModelUiDisplay(BENDI_VIDEO_MODELS);
    return channel === "myapi" ? MYAPI_VIDEO_MODELS.slice() : [];
  }
  if (channel === "bendi") return withModelUiDisplay(BENDI_VIDEO_MODELS);
  if (channel === "myapi") return MYAPI_VIDEO_MODELS.slice();
  // Dola：独立模型表（2.5 / 2.0 Fast / 1.0），普通与 S 渠道同一套
  if (isDolaFamilyChannel(channel)) return withModelUiDisplay(DOLA_VIDEO_MODELS);
  const key = bytedanceModelCatalogKey(channel);
  // Ordinary DouBao: no Seedance 2.0 / 2.5 (those require S).
  if (key === "doubao") return withModelUiDisplay(VIDEO_MODELS.filter((m) => !m.upgrade));
  // S: full Seedance catalog.
  if (key === "doubao_s") return withModelUiDisplay(VIDEO_MODELS);
  return withModelUiDisplay(VIDEO_MODELS);
}

/** Channel models further filtered by videoMode (edit/extend → ref-video only). */
function videoModelsForNode(node) {
  const channel =
    typeof resolveNodeChannel === "function"
      ? resolveNodeChannel(node, { allowGpt: false })
      : normalizeChannel(node?.channel, node?.model);
  let models = videoModelsForChannel(channel);
  if (videoModeRequiresRefVideo(getNodeVideoGenMode(node))) {
    models = models.filter((m) => modelSupportsReferenceVideo(m.id));
  }
  return models;
}

function textModelsForChannel(channel) {
  if (channel === "volcengine") return withModelUiDisplay(VOLCENGINE_TEXT_MODELS);
  if (channel === "bendi") {
    return withModelUiDisplay(BENDI_TEXT_MODELS.length ? BENDI_TEXT_MODELS : BENDI_LOCAL_TEXT_MODELS);
  }
  if (channel === "myapi") return MYAPI_TEXT_MODELS.slice();
  return [];
}

function voiceModelsForChannel(channel) {
  if (channel === "volcengine") {
    return withModelUiDisplay(VOLCENGINE_VOICE_MODELS.filter((m) => m.canvas !== false));
  }
  if (channel === "myapi") return MYAPI_VOICE_MODELS.slice();
  return [];
}

function defaultModelForChannel(channel, type = "image") {
  if (channel === "volcengine") {
    if (type === "video") return DEFAULT_VOLCENGINE_VIDEO_MODEL;
    if (type === "text" || type === "voice-text") return DEFAULT_VOLCENGINE_TEXT_MODEL;
    if (type === "voice") return DEFAULT_VOLCENGINE_VOICE_MODEL;
    return DEFAULT_VOLCENGINE_IMAGE_MODEL;
  }
  if (channel === "bendi") {
    const local = typeof getBendiMode === "function" && getBendiMode() === "local";
    if (type === "video") {
      const preferred = local ? DEFAULT_BENDI_LOCAL_VIDEO_MODEL : DEFAULT_BENDI_VIDEO_MODEL;
      const models =
        typeof videoModelsForChannel === "function" ? videoModelsForChannel("bendi") : BENDI_VIDEO_MODELS;
      if (models.some((m) => m.id === preferred)) return preferred;
      const hit25 = models.find((m) => /2\.5|2_5/.test(String(m.id || "")));
      return hit25?.id || models[0]?.id || preferred;
    }
    if (type === "text" || type === "voice-text") {
      return local ? DEFAULT_BENDI_LOCAL_TEXT_MODEL : "";
    }
    return local
      ? DEFAULT_BENDI_LOCAL_IMAGE_MODEL
      : BENDI_IMAGE_MODELS[0]?.id || "bendi_image";
  }
  if (channel === "myapi") {
    return defaultMyApiModelIdForType(type);
  }
  if (type === "video") {
    if (channel === "dola" || channel === "dola_s") return DEFAULT_DOLA_VIDEO_MODEL;
    if (channel === "doubao_s") {
      return VIDEO_MODELS.find((m) => m.id === "seedance_v2.0")?.id || DEFAULT_VIDEO_MODEL;
    }
    return DEFAULT_VIDEO_MODEL;
  }
  if (type === "text" || type === "voice-text") return "doubao_chat";
  return DEFAULT_IMAGE_MODEL;
}

function isNodeExpanded(node) {
  if (!node || isReferenceNode(node)) return false;
  // 仅单选展开编辑面板；多选只有描边高亮（is-picked），不弹窗
  if (!CanvasStore.primaryId || CanvasStore.isDragging) return false;
  if ((CanvasStore.selectedIds || []).length !== 1) return false;
  return node.id === CanvasStore.primaryId;
}

function isPausedGenerationError(error) {
  return String(error || "").includes("已手动暂停");
}

function formatNodeErrorDisplay(error, fallback = "请稍后重试") {
  let msg = (error || fallback).trim();
  // Strip legacy channel brand prefixes from older stored errors.
  msg = msg
    .replace(/^MyApi\s*(图片|视频|文本)?(失败)?[：:]\s*/i, "")
    .replace(/^MyApi\s+/i, "")
    .trim();
  // Unwrap exception class prefixes / caused-by chains so real Doubao text can show.
  msg = msg.split(/\n\s*↳\s*caused by:\s*/i)[0].trim();
  msg = msg.replace(/^(?:RuntimeError|GenerationPollError):\s*/gi, "").trim();
  // Our force-prompt copyright disclaimer is not a failure reason — drop it.
  msg = msg
    .replace(/本内容图像视频均为本人个人制作[^。\n]*(?:。|$)/g, " ")
    .replace(/不存在版权侵权风险[^。\n]*(?:。|$)/g, " ")
    .replace(/著作权归本人所有[^。\n]*(?:。|$)/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (
    msg.includes("710022004") ||
    /rate limited/i.test(msg) ||
    msg.includes("shark_admin") ||
    msg.includes('"code":"10000"') ||
    msg.includes('"type":"verify"')
  ) {
    return "Seed 触发限流/安全验证，请等待约 10 分钟后再试";
  }
  // Real Doubao policy / copyright rejects (not our disclaimer text).
  if (
    /版权相关限制|版权限制|疑似包含侵权|侵权内容|侵权\s*\/|内容违规|审核未通过|未通过审核|无法生成该内容|暂时无法创作|无法创作对应的内容|换其他主题试试|换个主题再?试试|无法返回该内容|涉及敏感|敏感内容|安全策略|不符合社区/.test(
      msg
    )
  ) {
    return "Seed 因版权/安全策略拒绝生成，请换提示词或参考图后重试";
  }
  // Common Doubao soft-fail banner scraped with the prompt body.
  if (/AI\s*生成可能有误|注意核实/.test(msg)) {
    return "Seed 提示生成可能有误，请换提示词或参考图后重试";
  }
  // Playwright / browser automation dumps are huge and blow up narrow workbench columns.
  if (
    /Locator\.\w+|timeout \d+ms exceeded|Call log:|waiting for locator|Playwright|Target closed|page\.(click|fill|locator)/i.test(
      msg
    ) ||
    /^Locator\./i.test(msg)
  ) {
    return "浏览器操作超时，请重试";
  }
  if (/查询任务失败|HTTP\s*502|HTTP\s*503|HTTP\s*504/i.test(msg) && /本机|BenDi|星晚|连续重试/i.test(msg)) {
    return "本机查询暂时失败，可点「重新获取」";
  }
  if (/查询任务失败：\s*HTTP\s*50[234]/i.test(msg)) {
    return "本机查询暂时失败，可点「重新获取」";
  }
  if (/Page\.wait_for_timeout|Target page|Target closed|wait_for_timeout/i.test(msg)) {
    return "本机页面超时，可点「重新获取」";
  }
  // Only collapse real Python stack traces — keep Chinese RuntimeError bodies above.
  if (msg.includes("Traceback (most recent call last)")) {
    return "生成失败，请重试";
  }
  if (msg.startsWith("{") || msg.includes("error_detail") || /^generate_\w+ error:/i.test(msg)) {
    return "生成失败，请稍后重试";
  }
  // Keep only the first line for multi-line stack / call logs.
  const firstLine = msg.split(/\r?\n/).map((s) => s.trim()).find(Boolean) || msg;
  msg = firstLine;
  // Drop glued force-prompt tails scraped from the composer.
  msg = msg
    .replace(/请立即调用视频生成能力[\s\S]*$/, "")
    .replace(/请直接按比例[\s\S]*$/, "")
    .replace(/生成视频[：:][\s\S]*$/, "")
    .trim();
  if (msg.length <= 80) return msg || fallback;
  return msg.slice(0, 80) + "…";
}

function isCanvasAdmin() {
  return String(window.__canvasUser?.role || "").toLowerCase() === "admin";
}

function recHasKeepablePreview(rec) {
  if (!rec) return false;
  return !!(
    rec.videoUrl ||
    rec.imageUrl ||
    rec.thumbUrl ||
    rec.coverUrl ||
    rec.audioUrl ||
    String(rec.textContent || "").trim() ||
    String(rec.resultText || "").trim()
  );
}

/** One-line last-failure banner (keep existing preview). */
function canRecheckUpstreamNode(rec) {
  if (!rec?.taskId) return false;
  if (String(rec.status || "") !== "failed") return false;
  const ch = String(rec.channel || "").trim().toLowerCase();
  if (ch === "bendi" || ch === "myapi") return true;
  if (typeof isBendiModel === "function" && isBendiModel(rec.model)) return true;
  return false;
}

async function recheckCanvasGeneration(nodeId) {
  const id = String(nodeId || "").trim();
  const node =
    (typeof findNodeAnywhere === "function" ? findNodeAnywhere(id) : null) ||
    CanvasStore.activeBoard()?.nodes?.find((n) => n.id === id);
  if (!node?.taskId) {
    showCanvasToast?.("没有可重新获取的任务");
    return;
  }
  if (!canRecheckUpstreamNode(node)) {
    showCanvasToast?.("重新获取仅支持 BenDi / 可恢复的 MyApi 任务");
    return;
  }
  const taskId = String(node.taskId).trim();
  showLoadingToast?.("正在重新获取上游结果…");
  try {
    const apiFn = typeof api === "function" ? api : window.api;
    await apiFn(`/api/tasks/${encodeURIComponent(taskId)}/recheck`, { method: "POST" });
    CanvasStore.updateNode(id, {
      status: "generating",
      error: null,
      isError: false,
      promptSent: true,
      genStartedAt: node.genStartedAt || Date.now(),
    });
    void CanvasStore.flushSave?.();
    renderNodes?.({ immediate: true });
    window.updateThreadBadge?.();
    window.ensureProgressTicker?.();
    window.startPolling?.();
    hideLoadingToast?.();
    showCanvasToast?.("已重新接入，继续查询中…");
  } catch (err) {
    hideLoadingToast?.();
    showCanvasToast?.(err?.message || "重新获取失败");
  }
}
window.canRecheckUpstreamNode = canRecheckUpstreamNode;
window.recheckCanvasGeneration = recheckCanvasGeneration;

function renderStickyGenErrorLine(rec) {
  if (!rec) return "";
  const busy = ["generating", "pending", "waiting"].includes(rec.status);
  if (busy) return "";
  const err = String(rec.error || "").trim();
  if (!err) return "";
  if (!recHasKeepablePreview(rec)) return "";
  const msg =
    typeof formatNodeErrorDisplay === "function" ? formatNodeErrorDisplay(err, "生成失败") : err;
  const taskId = String(rec.taskId || "").trim();
  const recId = String(rec.id || "").trim();
  const recheckBtn =
    canRecheckUpstreamNode(rec)
      ? `<button type="button" class="wb-inline-fail-ico wb-inline-fail-recheck" data-action="recheck-gen" data-node="${escapeAttr(recId)}" data-task-id="${escapeAttr(taskId)}" title="重新获取上游结果（不重新提交）" aria-label="重新获取">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M13.2 8A5.2 5.2 0 1 1 11.4 3.6" stroke="currentColor" stroke-width="1.3" stroke-linecap="round"/><path d="M11.2 1.6v2.6H13.8" stroke="currentColor" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/></svg>
        </button>`
      : "";
  const rawBtn =
    taskId && isCanvasAdmin()
      ? `<button type="button" class="wb-inline-fail-ico" data-action="view-gen-raw" data-task-id="${escapeAttr(taskId)}" title="查看客户提示与原始返回" aria-label="查看原文">
          <svg width="13" height="13" viewBox="0 0 16 16" fill="none" aria-hidden="true"><circle cx="7" cy="7" r="4" stroke="currentColor" stroke-width="1.2"/><path d="M10.2 10.2L13.5 13.5" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>
        </button>`
      : "";
  const copyBtn = taskId
    ? `<button type="button" class="wb-inline-fail-ico" data-action="copy-gen-id" data-task-id="${escapeAttr(taskId)}" title="复制工作编号" aria-label="复制编号">
        <svg width="13" height="13" viewBox="0 0 16 16" fill="none" aria-hidden="true"><rect x="5.5" y="5.5" width="8" height="8" rx="1.2" stroke="currentColor" stroke-width="1.2"/><path d="M4 10.5H3.2A1.2 1.2 0 0 1 2 9.3V3.2A1.2 1.2 0 0 1 3.2 2h6.1A1.2 1.2 0 0 1 10.5 3.2V4" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>
      </button>`
    : "";
  const dismissBtn = recId
    ? `<button type="button" class="wb-inline-fail-ico wb-inline-fail-dismiss" data-action="dismiss-gen-error" data-node="${escapeAttr(recId)}" title="关闭错误提示" aria-label="关闭错误">
        <svg width="13" height="13" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M4 4l8 8M12 4L4 12" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"/></svg>
      </button>`
    : "";
  return `<div class="wb-inline-fail" title="${escapeAttr(err)}"><span class="wb-inline-fail-text">错误：${escapeHtml(msg)}</span>${recheckBtn}${rawBtn}${copyBtn}${dismissBtn}</div>`;
}
window.renderStickyGenErrorLine = renderStickyGenErrorLine;
window.recHasKeepablePreview = recHasKeepablePreview;

/** Compact work-id line under generating / failed preview (hidden after success). */
function renderGenWorkIdBar(node, { compact = false, showRaw = false } = {}) {
  const id = String(node?.taskId || "").trim();
  if (!id) return "";
  const st = String(node?.status || "");
  if (!["pending", "generating", "failed"].includes(st)) return "";
  const rawBtn =
    showRaw && isCanvasAdmin()
      ? `<button type="button" class="gen-work-id-btn is-icon" data-action="view-gen-raw" data-task-id="${escapeAttr(id)}" title="查看客户提示与原始返回" aria-label="查看原文">
          <svg class="gen-work-id-icon" width="12" height="12" viewBox="0 0 16 16" fill="none" aria-hidden="true"><circle cx="7" cy="7" r="4" stroke="currentColor" stroke-width="1.2"/><path d="M10.2 10.2L13.5 13.5" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>
        </button>`
      : "";
  const copyBtn = `<button type="button" class="gen-work-id-btn is-icon" data-action="copy-gen-id" data-task-id="${escapeAttr(id)}" title="复制工作编号" aria-label="复制编号">
    <svg class="gen-work-id-icon" width="12" height="12" viewBox="0 0 16 16" fill="none" aria-hidden="true"><rect x="5.5" y="5.5" width="8" height="8" rx="1.2" stroke="currentColor" stroke-width="1.2"/><path d="M4 10.5H3.2A1.2 1.2 0 0 1 2 9.3V3.2A1.2 1.2 0 0 1 3.2 2h6.1A1.2 1.2 0 0 1 10.5 3.2V4" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>
  </button>`;
  return `<div class="gen-work-id-bar${compact ? " is-compact" : ""}">
    <span class="gen-work-id-label">id</span>
    <code class="gen-work-id-code" title="${escapeAttr(id)}">${escapeHtml(id)}</code>
    <span class="gen-work-id-spacer" aria-hidden="true"></span>
    <span class="gen-work-id-actions">${rawBtn}${copyBtn}</span>
  </div>`;
}

async function copyGenWorkId(taskId) {
  const id = String(taskId || "").trim();
  if (!id) return;
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(id);
    } else {
      const ta = document.createElement("textarea");
      ta.value = id;
      ta.setAttribute("readonly", "");
      ta.style.position = "fixed";
      ta.style.left = "-9999px";
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      ta.remove();
    }
    if (typeof showCanvasToast === "function") showCanvasToast("已复制工作编号");
  } catch {
    if (typeof showCanvasToast === "function") showCanvasToast("复制失败");
  }
}

function stripGenErrorPrefixes(text) {
  return String(text || "")
    .trim()
    .replace(/^MyApi 创建视频任务失败：/, "")
    .replace(/^MyApi 生图失败：/, "")
    .replace(/^MyApi 文本失败：/, "")
    .replace(/^MyApi 图片失败：/, "")
    .replace(/^MyApi 视频失败：/, "")
    .replace(/^视频任务失败：/, "")
    .replace(/^图片任务失败：/, "")
    .replace(/^查询视频任务失败：/, "")
    .replace(/^查询图片任务失败：/, "")
    .replace(/^RuntimeError:\s*/i, "")
    .replace(/^GenerationPollError:\s*/i, "");
}

function extractAiOriginalText(rawError, rawResponse) {
  if (rawResponse != null && typeof rawResponse === "object") {
    for (const key of ["ai_original", "fail_text", "page_text_tail", "last_text"]) {
      const v = String(rawResponse[key] || "").trim();
      if (v) return v;
    }
    const st = rawResponse.status;
    if (st && typeof st === "object") {
      const fail = String(st.failText || st.raw || "").trim();
      if (fail) return fail;
    }
  }
  const raw = String(rawError || "").trim();
  if (!raw) return "";
  const lines = raw
    .split(/\r?\n/)
    .map((s) => s.trim())
    .filter(Boolean)
    .filter((s) => !/^↳/.test(s) && !/^(RuntimeError|GenerationPollError):?\s*$/i.test(s));
  const last = lines[lines.length - 1] || raw;
  return stripGenErrorPrefixes(last);
}

function formatGenRecordPayload(customerError, rawError, rawResponse, record = null) {
  const parts = [];
  const poll =
    record && typeof record === "object"
      ? [
          record.upstream_task_id ? `上游任务号: ${record.upstream_task_id}` : "",
          record.upstream_status ? `上游状态: ${record.upstream_status}` : "",
          record.upstream_stage ? `上游阶段: ${record.upstream_stage}` : "",
          record.last_poll_at ? `最后查询: ${record.last_poll_at}` : "",
          record.error_type ? `错误类型: ${record.error_type}` : "",
        ].filter(Boolean)
      : [];
  if (poll.length) parts.push("【轮询状态】\n" + poll.join("\n"));

  const aiOriginal = extractAiOriginalText(rawError, rawResponse);
  if (aiOriginal) {
    parts.push("【AI原文】\n" + aiOriginal);
  }

  const userMsg = String(customerError || "").trim();
  const userNorm = stripGenErrorPrefixes(userMsg);
  const aiNorm = stripGenErrorPrefixes(aiOriginal);
  if (userMsg && userNorm && userNorm !== aiNorm) {
    parts.push("【客户提示】\n" + userMsg);
  }

  let body = "";
  if (rawResponse != null && rawResponse !== "") {
    if (typeof rawResponse === "object") {
      const slim = { ...rawResponse };
      delete slim.ai_original;
      delete slim.fail_text;
      delete slim.page_text_tail;
      delete slim.last_text;
      if (Object.keys(slim).length) {
        try {
          body = JSON.stringify(slim, null, 2);
        } catch {
          body = String(rawResponse);
        }
      }
    } else {
      body = String(rawResponse).trim();
    }
  }
  if (body.trim()) {
    parts.push("【诊断信息】\n" + body.trim());
  }

  return parts.join("\n\n").trim() || "（暂无错误详情）";
}

async function openGenRecordDetail(taskId) {
  const id = String(taskId || "").trim();
  if (!id) return;
  if (!isCanvasAdmin()) {
    if (typeof showCanvasToast === "function") showCanvasToast("仅管理员可查看原文");
    return;
  }
  try {
    const res = await fetch(`/api/gen-records/${encodeURIComponent(id)}`, { credentials: "same-origin" });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      const msg = data?.detail?.message || data?.detail || data?.message || res.statusText || "加载失败";
      if (typeof AppDialog !== "undefined" && AppDialog.alert) {
        await AppDialog.alert(String(msg), { title: "工作编号 " + id });
      } else if (typeof showCanvasToast === "function") {
        showCanvasToast(String(msg));
      }
      return;
    }
    const body = formatGenRecordPayload(data.error, data.raw_error, data.raw_response, data);
    let dlg = document.getElementById("gen-record-detail-dialog");
    if (!dlg) {
      dlg = document.createElement("dialog");
      dlg.id = "gen-record-detail-dialog";
      dlg.className = "gen-record-dialog";
      dlg.innerHTML = `
        <form method="dialog" class="gen-record-dialog-inner">
          <header class="gen-record-dialog-head">
            <h3 id="gen-record-dialog-title">生成详情</h3>
            <button type="submit" class="btn btn-ghost btn-sm" aria-label="关闭">关闭</button>
          </header>
          <p class="gen-record-dialog-meta" id="gen-record-dialog-meta"></p>
          <pre class="gen-record-dialog-body" id="gen-record-dialog-body"></pre>
          <footer class="gen-record-dialog-foot">
            <button type="button" class="btn btn-ghost btn-sm" id="gen-record-copy-btn">复制全文</button>
            <button type="submit" class="btn primary btn-sm">关闭</button>
          </footer>
        </form>`;
      document.body.appendChild(dlg);
      dlg.querySelector("#gen-record-copy-btn")?.addEventListener("click", async () => {
        const text = dlg.querySelector("#gen-record-dialog-body")?.textContent || "";
        if (!text) return;
        try {
          if (navigator.clipboard?.writeText) await navigator.clipboard.writeText(text);
          else {
            const ta = document.createElement("textarea");
            ta.value = text;
            document.body.appendChild(ta);
            ta.select();
            document.execCommand("copy");
            ta.remove();
          }
          if (typeof showCanvasToast === "function") showCanvasToast("已复制详情");
        } catch {
          if (typeof showCanvasToast === "function") showCanvasToast("复制失败");
        }
      });
      dlg.addEventListener("close", () => {
        if (typeof dismissOverlay === "function") dismissOverlay(dlg, { immediate: true });
      });
      dlg.addEventListener("cancel", (e) => {
        e.preventDefault();
        if (typeof dismissOverlay === "function") dismissOverlay(dlg);
      });
    }
    const title = dlg.querySelector("#gen-record-dialog-title");
    const meta = dlg.querySelector("#gen-record-dialog-meta");
    const pre = dlg.querySelector("#gen-record-dialog-body");
    if (title) title.textContent = `工作编号 ${id}`;
    if (meta) {
      meta.textContent = [
        data.status === "failed" ? "生成失败" : data.status === "completed" ? "生成成功" : data.status === "generating" || data.status === "pending" ? "生成中" : data.status || "",
        data.account_name || data.account_id || "",
        data.kind || "",
      ].filter(Boolean).join(" · ");
    }
    if (pre) pre.textContent = body;
    if (typeof revealOverlay === "function") revealOverlay(dlg);
    else if (typeof dlg.showModal === "function") dlg.showModal();
  } catch (err) {
    if (typeof showCanvasToast === "function") showCanvasToast(err.message || "加载失败");
  }
}

function renderFailedPreview(node, title = "生成失败") {
  const aspectStyle = previewStyleForNode(node);
  const fullMsg = (node.error || "请稍后重试").trim();
  const displayMsg = formatNodeErrorDisplay(fullMsg);
  // Never put the raw stack / Playwright dump into the visible title — it stretches workbench columns.
  const failTitle = isPausedGenerationError(fullMsg)
    ? "已暂停"
    : title && title.length <= 12 && !/RuntimeError|Locator\.|Call log|Traceback/i.test(title)
      ? title
      : "生成失败";
  const workBar = node.status === "failed" ? renderGenWorkIdBar(node, { showRaw: true }) : "";
  return `<div class="node-preview error node-preview-error" ${aspectStyle} title="${escapeAttr(fullMsg)}">
    <div class="node-preview-error-body">
      <span class="preview-error-title">${escapeHtml(failTitle)}</span>
      <span class="preview-error-msg">${escapeHtml(displayMsg)}</span>
    </div>
    ${workBar}
  </div>`;
}

function renderPaidQuotaConfirmPreview(node) {
  const aspectStyle = previewStyleForNode(node);
  const msg =
    (node.userPromptMessage || "").trim() ||
    "今日免费额度已用完，继续将消耗付费额度。请选择「继续」或「跳过」换号。";
  const tid = String(node.taskId || "").trim();
  const nid = String(node.id || "").trim();
  return `<div class="node-preview generating paid-quota-confirm" ${aspectStyle}>
    <div class="paid-quota-confirm-body">
      <div class="paid-quota-confirm-title">付费额度确认</div>
      <div class="paid-quota-confirm-msg">${escapeHtml(msg)}</div>
      <div class="paid-quota-confirm-actions">
        <button type="button" class="btn-paid-quota-continue" data-task-user-action="continue" data-task-id="${escapeAttr(tid)}" data-node="${escapeAttr(nid)}">继续</button>
        <button type="button" class="btn-paid-quota-skip" data-task-user-action="skip" data-task-id="${escapeAttr(tid)}" data-node="${escapeAttr(nid)}">跳过</button>
      </div>
    </div>
  </div>`;
}

async function submitTaskUserAction(taskId, action, { nodeId } = {}) {
  const tid = String(taskId || "").trim();
  const act = String(action || "").trim().toLowerCase();
  if (!tid) {
    if (typeof showCanvasToast === "function") showCanvasToast("任务未绑定，无法确认，请重新生成");
    return;
  }
  if (act !== "continue" && act !== "skip") return;
  document.querySelectorAll(`[data-task-user-action][data-task-id="${CSS.escape(tid)}"]`).forEach((btn) => {
    btn.disabled = true;
  });
  try {
    const res = await fetch(`/api/tasks/${encodeURIComponent(tid)}/user-action`, {
      method: "POST",
      credentials: "same-origin",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ action: act }),
    });
    const data = await res.json().catch(() => ({}));
    if (!res.ok) {
      const detail = data.detail || data.message || `操作失败 (${res.status})`;
      throw new Error(typeof detail === "string" ? detail : `操作失败 (${res.status})`);
    }
    // Optimistic: leave confirm UI; poll will clear user_prompt_* and keep generating.
    if (typeof showCanvasToast === "function") {
      showCanvasToast(act === "skip" ? "已跳过，正在换号…" : "已确认继续，正在提交…");
    }
    // Local clear so preview returns to progress while worker acts.
    const clearLocal = (obj) => {
      if (!obj) return;
      obj.userPromptKind = null;
      obj.userPromptMessage = null;
      obj.userAction = act;
    };
    const board = CanvasStore.activeBoard?.();
    const node =
      (nodeId && board?.nodes?.find((n) => n.id === nodeId)) ||
      board?.nodes?.find((n) => n.taskId === tid);
    if (node) {
      clearLocal(node);
      const wrap = document.querySelector(`.node-wrap[data-id="${CSS.escape(node.id)}"]`);
      if (wrap) softPatchNodeGenUi(wrap, node);
    }
    if (typeof findWbClipAnywhere === "function" || typeof findWbClip === "function") {
      for (const wb of WorkbenchStore?.workbenches || []) {
        for (const ep of wb.episodes || []) {
          for (const clip of ep.clips || []) {
            if (clip.taskId !== tid) continue;
            clearLocal(clip);
            if (typeof refreshWorkbenchClipUi === "function") {
              refreshWorkbenchClipUi(wb, ep, clip, { forcePreview: true });
            }
          }
        }
      }
    }
    if (typeof WorkbenchAssetStudio !== "undefined") {
      const d =
        WorkbenchAssetStudio.draft?.taskId === tid
          ? WorkbenchAssetStudio.draft
          : typeof findWbStudioDraftByTaskId === "function"
            ? findWbStudioDraftByTaskId(tid)?.asset
            : null;
      if (d) {
        clearLocal(d);
        WorkbenchAssetStudio.refreshPreviewPane?.();
        WorkbenchAssetStudio.refreshUi?.();
      }
    }
  } catch (err) {
    document.querySelectorAll(`[data-task-user-action][data-task-id="${CSS.escape(tid)}"]`).forEach((btn) => {
      btn.disabled = false;
    });
    if (typeof showCanvasToast === "function") showCanvasToast(err.message || "操作失败");
  }
}

window.submitTaskUserAction = submitTaskUserAction;
window.renderPaidQuotaConfirmPreview = renderPaidQuotaConfirmPreview;

function estimateGenProgress(node) {
  const start = node.genStartedAt || Date.now();
  const elapsed = Math.max(0, (Date.now() - start) / 1000);
  let typical = 40;
  const op = node.mediaOp || "";
  if (node.status === "importing") {
    // Local upload — short curve so the bar moves during import.
    typical = 10;
  } else if (op === "upscale") {
    // Real-ESRGAN：分辨率/时长影响大，给较长曲线，避免早早卡在 90%+
    typical = 180;
  } else if (op && typeof isReferenceNode === "function" && isReferenceNode(node)) {
    typical = 45;
  } else if (node.type === "video") {
    // Video: official often ~5 min; longer clip → slower curve (4s≈3.5min, 10s≈5.5min)
    const dur = Number(node.duration) || 10;
    typical = Math.max(180, Math.min(360, 150 + dur * 18));
  } else if (node.type === "image") {
    typical = 50;
  }
  const pct = (1 - Math.exp(-elapsed / typical)) * 92;
  return Math.max(3, Math.min(92, Math.round(pct)));
}

function progressLabelForNode(node) {
  // Elapsed time lives in the top badge only — keep the center label short.
  if (node?.mediaOp === "ai-pass") return "AI过检中…";
  if (typeof isReferenceNode === "function" && isReferenceNode(node)) {
    const name = (node.customName || "处理").replace(/中…?$/, "");
    return `${name}中…`;
  }
  if (!node?.taskId && node?._genPayload) {
    if (isTextGenNode(node)) return isVoiceTextNode(node) ? "正在提交音色描述任务…" : "正在提交文本任务…";
    if (node.type === "voice") return "正在提交音频任务…";
    return node.type === "image" ? "正在提交图片任务…" : "正在提交视频任务…";
  }
  if (isTextGenNode(node)) return isVoiceTextNode(node) ? "音色描述生成中…" : "文本生成中…";
  if (node.type === "voice") return "音频生成中…";
  return node.type === "image" ? "图片生成中…" : "视频生成中…";
}

function renderGenProgressPreview(node, label) {
  const aspectStyle = previewStyleForNode(node);
  const pct = estimateGenProgress(node);
  const workBar = renderGenWorkIdBar(node, { compact: true });
  return `<div class="node-preview generating" ${aspectStyle} data-gen-progress="${node.id}">
    <div class="gen-scan-track" aria-hidden="true">
      <div class="gen-scan-bar" style="left:${pct}%"></div>
      <div class="gen-scan-fill" style="width:${pct}%"></div>
    </div>
    <span class="gen-progress-label">${escapeHtml(label)}</span>
    ${workBar}
    ${renderPauseGenBtn(node)}
  </div>`;
}

function renderWaitingPreview(node) {
  const aspectStyle = previewStyleForNode(node);
  let label = waitingLabelForNode(node);
  return `<div class="node-preview waiting" ${aspectStyle}>
    <span class="waiting-pulse" aria-hidden="true"></span>
    <span class="waiting-label">${escapeHtml(label)}</span>
    ${renderPauseGenBtn(node)}
  </div>`;
}

function waitingLabelForNode(node) {
  // Elapsed time lives in the top badge only.
  if (typeof isReferenceNode === "function" && isReferenceNode(node) && node.mediaOp === "upscale") {
    return "等待其他线程结束…";
  }
  if (isTextGenNode(node)) return isVoiceTextNode(node) ? "音色描述排队等待中…" : "文本排队等待中…";
  if (node.type === "voice") return "音频排队等待中…";
  const kind = node.type === "image" || node.type === "ref-image" ? "图片" : "视频";
  return `${kind}排队等待中…`;
}

/** Seconds before the pause button appears next to send. Always immediate so users can cancel pre-send. */
function pauseButtonDelaySec(node) {
  if (!node) return 0;
  return 0;
}

function isBytedancePauseChannel(node) {
  const channel =
    typeof normalizeChannel === "function"
      ? normalizeChannel(node?.channel, node?.model)
      : node?.channel;
  if (typeof isBytedanceFamilyChannel === "function") {
    return isBytedanceFamilyChannel(channel);
  }
  return (
    channel === "doubao" ||
    channel === "doubao_s" ||
    channel === "dola" ||
    channel === "dola_s"
  );
}

function isLocalMediaToolNode(node) {
  return Boolean(node?.mediaOp) && typeof isReferenceNode === "function" && isReferenceNode(node);
}

function isPauseEligibleChannel(node) {
  if (!node) return false;
  if (isLocalMediaToolNode(node)) return false;
  const channel =
    typeof normalizeChannel === "function"
      ? normalizeChannel(node.channel, node.model)
      : node.channel;
  // MyApi / BenDi: no pause button (async poll — same as MyApi).
  if (channel === "myapi" || (typeof isMyApiModel === "function" && isMyApiModel(node.model))) {
    return false;
  }
  if (channel === "bendi" || (typeof isBendiModel === "function" && isBendiModel(node.model))) {
    return false;
  }
  // Browser sim only: Doubao family.
  if (isBytedancePauseChannel(node)) return true;
  return false;
}

function shouldShowPauseButton(node) {
  if (!node) return false;
  if (node.mediaOp === "ai-pass" || node._aiPassSnapshot) return false;
  if (isLocalMediaToolNode(node)) return false;
  if (!isPauseEligibleChannel(node)) return false;
  if (!["waiting", "pending", "generating"].includes(node.status)) return false;
  // Message already submitted on the channel page — cannot cancel there; hide pause.
  if (node.promptSent) return false;
  const delay = pauseButtonDelaySec(node);
  if (delay <= 0) return true;
  const start = node.genStartedAt || Date.now();
  return (Date.now() - start) / 1000 >= delay;
}

function renderPauseGenBtn(node) {
  const icon = `<svg class="btn-gen-pause-icon" viewBox="0 0 14 14" width="12" height="12" aria-hidden="true"><rect x="3" y="2.5" width="2.75" height="9" rx="1.1"/><rect x="8.25" y="2.5" width="2.75" height="9" rx="1.1"/></svg>`;
  if (!shouldShowPauseButton(node)) {
    return `<button type="button" class="btn-gen-pause hidden" data-gen-pause="${node.id}" title="暂停" aria-label="暂停" aria-hidden="true">${icon}</button>`;
  }
  const tip = node.status === "waiting"
    ? "取消排队"
    : "停止（尚未发送到网页）";
  return `<button type="button" class="btn-gen-pause" data-gen-pause="${node.id}" title="${escapeAttr(tip)}" aria-label="${escapeAttr(tip)}">${icon}</button>`;
}

window.isPauseEligibleChannel = isPauseEligibleChannel;
window.shouldShowPauseButton = shouldShowPauseButton;

const DEFAULT_RESOLUTION_MULT = null; // unused — absolute resolution_prices preferred

function lookupResolutionPrice(prices, resolution) {
  if (!prices) return null;
  const key = String(resolution || "自动").trim() || "自动";
  if (prices[key] != null && prices[key] !== "") return parsePointsNumber(prices[key], 0);
  const want = key.toLowerCase();
  for (const [k, v] of Object.entries(prices)) {
    if (String(k).trim().toLowerCase() === want && v != null && v !== "") {
      return parsePointsNumber(v, 0);
    }
  }
  // Do not silently substitute 自动 when user picked a concrete resolution.
  if (want === "自动" || want === "auto") {
    for (const [k, v] of Object.entries(prices)) {
      if (String(k).trim() === "自动" && v != null && v !== "") return parsePointsNumber(v, 0);
    }
  }
  return null;
}

function unitPriceForResolution(meta, resolution, modelId = null) {
  const prices = resolutionPricesForModel(modelId || meta?.id, meta);
  const hit = lookupResolutionPrice(prices, resolution);
  if (hit != null) return hit;
  return parsePointsNumber(meta?.points_price, 0);
}

function formatPointsCostDisplay(value) {
  const n = parsePointsNumber(value, 0);
  if (!Number.isFinite(n) || n < 0) return "0";
  if (Math.abs(n - Math.round(n)) < 1e-9) return String(Math.round(n));
  return n.toLocaleString("en-US", { minimumFractionDigits: 0, maximumFractionDigits: 3 });
}


/** Model id the toolbar would show — used so points badge matches even if node.model is briefly empty. */
function resolveToolbarModelId(node) {
  if (!node) return "";
  const allowGpt = node.type !== "video";
  const channel = typeof resolveNodeChannel === "function"
    ? resolveNodeChannel(node, { allowGpt })
    : node.channel;
  const models =
    node.type === "video"
      ? videoModelsForNode(node)
      : isTextGenNode(node)
        ? textModelsForChannel(channel)
        : imageModelsForChannel(channel);
  if (models.some((m) => m.id === node.model)) return node.model;
  if (node.type === "video" && models[0]?.id) return models[0].id;
  if (typeof defaultModelForChannel === "function") {
    return defaultModelForChannel(channel, isTextGenNode(node) ? "text" : node.type) || node.model || "";
  }
  return node.model || "";
}

/** Estimate points for public models that require billing. Custom MyApi = 0. */
function resolveBillingMeta(modelId) {
  const id = String(modelId || "");
  if (!id) return null;
  const meta = getMyApiModelMeta(id);
  if (meta?.points_required) return meta;
  const hit =
    MYAPI_IMAGE_MODELS.find((m) => m.id === id) ||
    MYAPI_VIDEO_MODELS.find((m) => m.id === id) ||
    MYAPI_TEXT_MODELS.find((m) => m.id === id);
  if (!hit) return meta;
  return {
    ...(meta || {}),
    id: hit.id,
    kind: hit.kind || meta?.kind,
    public: !!(hit.public || meta?.public || id.startsWith("public_")),
    points_required: !!hit.points_required || !!meta?.points_required,
    billing_mode: hit.billing_mode || meta?.billing_mode || "per_use",
    points_price: hit.points_price || meta?.points_price || "0.000",
    resolution_prices: hit.resolution_prices || meta?.resolution_prices || null,
    name: hit.label || meta?.name,
    label: hit.label || meta?.label,
  };
}

function estimateNodePointsCost(node, opts = {}) {
  if (!node) return 0;
  const modelId =
    opts.modelId ||
    (node.type === "video" && typeof resolveEffectiveVideoModelId === "function"
      ? resolveEffectiveVideoModelId(node)
      : null) ||
    (typeof resolveToolbarModelId === "function" ? resolveToolbarModelId(node) : null) ||
    node.model;
  const mid = String(modelId || "");
  const channel = typeof normalizeChannel === "function" ? normalizeChannel(node.channel, mid || node.model) : node.channel;
  const isPublicId = mid.startsWith("public_");
  if (channel !== "myapi" && !isPublicId) return 0;
  const meta = resolveBillingMeta(modelId) || resolveBillingMeta(node.model);
  if (!meta) return 0;
  const isPublic = !!(meta.public || isPublicId || String(modelId || "").startsWith("public_"));
  if (!isPublic || !meta.points_required) return 0;
  const resolution = opts.resolution != null ? opts.resolution : node.resolution;
  const price = unitPriceForResolution(meta, resolution, modelId || node.model);
  if (price <= 0) return 0;
  const mode = String(meta.billing_mode || "per_use").toLowerCase();
  const kind = String(meta.kind || node.type || "").toLowerCase();
  if (kind === "video" && mode === "per_second") {
    const durModel = modelId || node.model;
    const dur =
      typeof clampVideoDuration === "function"
        ? clampVideoDuration(opts.duration ?? node.duration ?? 10, durModel, nodeUsesUpgradeDuration(node))
        : Number(opts.duration ?? node.duration) || 10;
    return price * Math.max(1, dur);
  }
  if (kind === "text" && (mode === "per_token" || mode === "per_char")) {
    const text = String(node.prompt || "");
    const estIn = Math.max(1, Math.ceil([...text].length / 2) || 1);
    const estOut = Math.max(64, Math.ceil(estIn / 2));
    return price * (estIn + estOut);
  }
  return price;
}

function genCostBadgeStarHtml() {
  return `<svg class="gen-points-cost-star" width="12" height="12" viewBox="0 0 16 16" aria-hidden="true"><path fill="currentColor" d="M8 1.6l1.7 3.7 4 .4-3 2.7.9 3.9L8 10.6 4.4 12.3l.9-3.9-3-2.7 4-.4z"/></svg>`;
}

/** Points preview beside generate: billed public → cost; other MyApi → 0. */
function renderGenCostBadge(node, opts = {}) {
  if (window.AppConfig?.points_enabled === false) return "";
  if (!node) return "";
  const mid = String(
    opts.modelId ||
      (typeof resolveToolbarModelId === "function" ? resolveToolbarModelId(node) : "") ||
      node.model ||
      ""
  );
  const channel = typeof normalizeChannel === "function" ? normalizeChannel(node.channel, mid || node.model) : node.channel;
  const isPublicId = mid.startsWith("public_");
  if (channel !== "myapi" && !isPublicId) return "";
  const cost = estimateNodePointsCost(node, { ...opts, modelId: opts.modelId || mid });
  const label = formatPointsCostDisplay(cost);
  const free = !(cost > 0);
  return `<span class="gen-points-cost${free ? " is-free" : ""}" data-gen-cost="${node.id}" title="${free ? "不扣积分" : "预计消耗积分"}">${genCostBadgeStarHtml()}<span class="gen-points-cost-val">${escapeHtml(label)}</span></span>`;
}

function updateGenCostBadge(nodeId, opts = {}) {
  const board = CanvasStore.activeBoard?.();
  let node = board?.nodes?.find((n) => n.id === nodeId);
  let wrap =
    document.querySelector(`.node-wrap[data-id="${CSS.escape(nodeId)}"]`) ||
    document.querySelector(`.node-panel[data-node="${CSS.escape(nodeId)}"]`)?.closest(".node-wrap");

  // Workbench clip / studio: cost badge lives outside canvas node-wrap.
  if (!wrap && typeof nodeId === "string") {
    if (nodeId.startsWith("wbclip-") && typeof parseWbClipNodeId === "function") {
      const clipId = parseWbClipNodeId(nodeId);
      const clip = typeof findWbClip === "function" ? findWbClip(clipId) : null;
      if (clip) {
        node =
          typeof clipToPreviewNode === "function" ? clipToPreviewNode(clip) : typeof clipToNode === "function" ? clipToNode(clip) : null;
        wrap = document.querySelector(`.workbench-clip-row[data-clip-id="${clipId}"]`);
        if (wrap && typeof refreshWbClipGenCost === "function") {
          refreshWbClipGenCost(clipId, opts);
          return;
        }
      }
    } else if (nodeId.startsWith("wbasset-") && typeof parseWbAssetNodeId === "function") {
      const assetId = parseWbAssetNodeId(nodeId);
      const item =
        (typeof findWbStudioItem === "function" ? findWbStudioItem(assetId) : null) ||
        (typeof WorkbenchAssetStudio !== "undefined"
          ? WorkbenchAssetStudio.items?.().find((i) => i.id === assetId)
          : null);
      if (item) {
        node =
          typeof studioItemToGenerationNode === "function"
            ? studioItemToGenerationNode(item)
            : typeof assetToNode === "function"
              ? assetToNode(item)
              : null;
        wrap = document.querySelector(`.wb-studio-item[data-item-id="${assetId}"]`);
      }
    }
  }

  if (!wrap) return;
  // Keep model pill label in sync (text nodes used to show raw public_… id).
  if (node) {
    const modelId = opts.modelId || node.model;
    const labelEl = wrap.querySelector(".video-model-btn-label");
    if (labelEl && typeof getNodeModelLabel === "function") {
      labelEl.textContent = getNodeModelLabel(node, modelId);
    }
  }
  const btn = wrap.querySelector(".btn-generate-inline, .btn-generate");
  let el = wrap.querySelector(`.gen-points-cost[data-gen-cost="${CSS.escape(nodeId)}"]`);
  const html = node ? renderGenCostBadge(node, opts) : "";
  if (!html) {
    el?.remove();
    return;
  }
  if (!el) {
    el = document.createElement("span");
    const actions = wrap.querySelector(".gen-action-btns");
    if (btn?.parentElement) btn.parentElement.insertBefore(el, btn);
    else if (actions) actions.prepend(el);
    else return;
  }
  const tmp = document.createElement("div");
  tmp.innerHTML = html;
  const next = tmp.firstElementChild;
  if (next) el.replaceWith(next);
}

window.estimateNodePointsCost = estimateNodePointsCost;
window.updateGenCostBadge = updateGenCostBadge;

function renderAutoRetryToggle(node, opts = {}) {
  const maxRetry = window.AUTO_RETRY_MAX ?? 3;
  const on = !!node.autoRetry;
  const used = Number(node.autoRetryCount) || 0;
  const badge =
    on && used > 0 ? `<span class="gen-auto-retry-badge">${used}/${maxRetry}</span>` : "";
  const title = on
    ? `API 生成失败后自动重试，最多 ${maxRetry} 次${used ? `（已重试 ${used}/${maxRetry}）` : ""}`
    : `API 生成失败后自动重试，最多 ${maxRetry} 次`;
  const placement = opts.placement === "tools" ? " gen-auto-retry--tools" : "";
  return `<button type="button" class="gen-auto-retry${placement}${on ? " is-on" : ""}" data-node="${node.id}" title="${escapeAttr(title)}" aria-pressed="${on ? "true" : "false"}">
    <span class="gen-auto-retry-check" aria-hidden="true"></span>
    <span class="gen-auto-retry-label">失败重试</span>${badge}
  </button>`;
}

function renderGenActionBtns(node, typeAttr) {
  const preparing = !!window.isGenPreparing?.(node.id);
  const genDisabled = preparing || isBusyGenStatus(node.status) ? "disabled" : "";
  const type = typeAttr || node.type;
  return `<span class="gen-action-btns">${renderPauseGenBtn(node)}${renderGenCostBadge(node)}<button type="button" class="btn-generate-inline btn-generate${preparing ? " is-preparing" : ""}" data-node="${node.id}" data-type="${type}" ${genDisabled} aria-busy="${preparing}" aria-label="${preparing ? "正在准备生成" : "生成"}" title="${preparing ? "正在准备生成" : "生成"}">${preparing ? "…" : "↑"}</button></span>`;
}

function tickGenProgressUI() {
  const board = CanvasStore.activeBoard();
  if (!board) return;
  const nodeMap = new Map(board.nodes.map((n) => [n.id, n]));
  let staleGeneratingDom = false;

  document.querySelectorAll(".node-wrap[data-id]").forEach((wrap) => {
    const node = nodeMap.get(wrap.dataset.id);
    if (!node) return;
    if (
      (node.status === "completed" || node.status === "failed") &&
      wrap.querySelector(".node-preview.generating, .node-preview.waiting, .gen-progress-label")
    ) {
      staleGeneratingDom = true;
      if (typeof softRefreshNodeMedia === "function") {
        softRefreshNodeMedia(node.id, { refreshHosts: false });
      }
    }
  });
  if (staleGeneratingDom) {
    scheduleRenderConnections(true);
    if (typeof HistoryDock !== "undefined") HistoryDock.refresh();
    return;
  }

  document.querySelectorAll(".node-preview.generating, .node-preview.waiting").forEach((preview) => {
    const wrap = preview.closest(".node-wrap[data-id]");
    if (!wrap) return;
    const node = nodeMap.get(wrap.dataset.id);
    if (!node) return;
    syncBusyPreviewIfNeeded(wrap, node);
    ensureNodeGenClock(node);
    const pauseBtns = wrap.querySelectorAll(".btn-gen-pause");
    if (pauseBtns.length) {
      const show = shouldShowPauseButton(node);
      pauseBtns.forEach((pauseBtn) => {
        pauseBtn.classList.toggle("hidden", !show);
        pauseBtn.setAttribute("aria-hidden", show ? "false" : "true");
        if (show) {
          pauseBtn.title =
            node.status === "waiting" ? "取消排队" : "停止（尚未发送到网页）";
          pauseBtn.setAttribute("aria-label", pauseBtn.title);
        }
      });
    }
    const waitingLabel = wrap.querySelector(".waiting-label");
    if (waitingLabel && node.status === "waiting") {
      waitingLabel.textContent = waitingLabelForNode(node);
    }
    const hint = wrap.querySelector(".preview-hint");
    if (hint && isTextGenNode(node) && ["waiting", "pending", "generating"].includes(node.status)) {
      hint.textContent = progressLabelForNode(node);
    }
    if (node.status === "pending" || node.status === "generating") {
      const pct = estimateGenProgress(node);
      const bar = wrap.querySelector(".gen-scan-bar");
      const fill = wrap.querySelector(".gen-scan-fill");
      const label = wrap.querySelector(".gen-progress-label");
      if (bar) bar.style.left = `${pct}%`;
      if (fill) fill.style.width = `${pct}%`;
      if (label) label.textContent = progressLabelForNode(node);
    }
    patchGenActionBtnsUI(node);
  });

  board.nodes.forEach((node) => {
    if (!["waiting", "pending", "generating"].includes(node.status)) return;
    ensureNodeGenClock(node);
    patchGenActionBtnsUI(node);
  });
}

function renderUploadingRefPreview(node, aspectStyle) {
  const pending = _pendingImportPreviews.get(node.id);
  const pctRaw = node.uploadPercent ?? pending?.percent;
  const pct =
    pctRaw == null || Number.isNaN(Number(pctRaw))
      ? null
      : Math.max(0, Math.min(100, Math.round(Number(pctRaw))));
  const badgeText = pct == null ? "上传中 0%" : `上传中 ${pct}%`;
  const badge = `<div class="ref-upload-badge"><div class="spinner"></div><span>${escapeHtml(badgeText)}</span></div>`;
  if (!pending?.url) {
    return `<div class="node-preview generating ref-media is-uploading" ${aspectStyle}>${badge}</div>`;
  }
  const src = escapeAttr(pending.url);
  if (node.type === "ref-image") {
    return `<div class="node-preview has-media ref-media is-uploading" ${aspectStyle} title="${escapeAttr(node.customName || "图片")}">
      <img class="node-preview-img is-media-loaded" src="${src}" alt="" draggable="false" decoding="async" data-node="${node.id}" />
      ${badge}
    </div>`;
  }
  if (node.type === "ref-video") {
    return `<div class="node-preview has-media has-video ref-media is-uploading is-frame-preview" ${aspectStyle} data-video-node="${node.id}" title="${escapeAttr(node.customName || "视频")}">
      <video class="node-preview-vid-el is-media-loaded" src="${src}" preload="metadata" playsinline muted draggable="false"></video>
      ${badge}
    </div>`;
  }
  return `<div class="node-preview ref-media is-uploading ref-audio-pending" ${aspectStyle}>
    <span class="preview-icon">${nodeTypeIconSvg("audio")}</span>
    <span class="preview-hint">${escapeAttr(node.customName || "音频")}</span>
    ${badge}
  </div>`;
}

function renderPreviewContent(node) {
  const aspectStyle = previewStyleForNode(node);

  if (isReferenceNode(node)) {
    if (node.status === "uploading") {
      return renderUploadingRefPreview(node, aspectStyle);
    }
    if (node.status === "waiting") {
      return renderWaitingPreview(node);
    }
    if (node.status === "generating" || node.status === "pending") {
      return renderGenProgressPreview(node, progressLabelForNode(node));
    }
    // 工具失败但已恢复原图：仍显示图片，不要盖成整块「处理失败」。
    if (node.status === "failed" && !(node.type === "ref-image" && node.imageUrl)) {
      return renderFailedPreview(node, "处理失败");
    }
    if (node.type === "ref-image" && node.imageUrl) {
      const { thumb, full } = nodeImagePreviewSources(node);
      return `<div class="node-preview has-media ref-media" ${aspectStyle} title="双击放大"><img class="node-preview-img" draggable="false" data-src="${escapeAttr(thumb)}" data-full-src="${escapeAttr(full)}" decoding="async" alt="" data-node="${node.id}" />${renderAiMarkOverlayHtml(node)}</div>`;
    }
    if (node.type === "ref-video" && node.videoUrl) {
      return renderVideoPreviewHtml(node, node.videoUrl, "ref-media");
    }
    if (node.type === "ref-audio" && node.audioUrl) {
      return renderAudioPreviewHtml(node);
    }
    const emptyIcon =
      node.type === "ref-image"
        ? nodeTypeIconSvg("image")
        : node.type === "ref-audio"
          ? nodeTypeIconSvg("audio")
          : nodeTypeIconSvg("video");
    return `<div class="node-preview empty ref-media" ${aspectStyle}><span class="preview-icon">${emptyIcon}</span><span class="preview-hint">引用素材</span></div>`;
  }

  const isImage = node.type === "image";
  const isVoice = node.type === "voice";
  const audioMode = isVoice ? getNodeAudioAppMode(node) : null;
  const emptyHint = isVoice
    ? audioMode === "record"
      ? "点击下方开始录音"
      : audioMode === "music"
        ? "输入风格与歌词生成音乐"
        : "输入文本生成语音"
    : isImage
      ? "输入提示词生成图片"
      : "输入提示词生成视频";
  const emptyIcon = isVoice
    ? nodeTypeIconSvg("voice")
    : isImage
      ? nodeTypeIconSvg("image")
      : nodeTypeIconSvg("video");

  if (node.status === "waiting") {
    return renderWaitingPreview(node);
  }
  if (
    (node.status === "generating" || node.status === "pending") &&
    node.userPromptKind === "paid_quota_confirm"
  ) {
    return renderPaidQuotaConfirmPreview(node);
  }
  if (node.status === "generating" || node.status === "pending") {
    return renderGenProgressPreview(node, progressLabelForNode(node));
  }
  if (isVoice && node.audioUrl) {
    return renderAudioPreviewHtml(node);
  }
  if (!isImage && !isVoice && node.videoUrl) {
    return renderVideoPreviewHtml(node, node.videoUrl);
  }
  if (isImage && node.imageUrl) {
    const { thumb, full } = nodeImagePreviewSources(node);
    return `<div class="node-preview has-media" ${aspectStyle} title="双击放大"><img class="node-preview-img" draggable="false" data-src="${escapeAttr(thumb)}" data-full-src="${escapeAttr(full)}" decoding="async" alt="" data-node="${node.id}" />${renderAiMarkOverlayHtml(node)}</div>`;
  }
  // Failed but still has cover/thumb (keepable like AI过检): show last poster, not full-bleed fail.
  if (
    node.status === "failed" &&
    typeof recHasKeepablePreview === "function" &&
    recHasKeepablePreview(node)
  ) {
    const poster = node.coverUrl || node.thumbUrl || node.imageUrl;
    if (poster) {
      const full = typeof resolveMediaUrl === "function" ? resolveMediaUrl(poster) : poster;
      const thumbSrc =
        typeof resolveMediaUrl === "function"
          ? resolveMediaUrl(node.thumbUrl || poster)
          : node.thumbUrl || poster;
      return `<div class="node-preview has-media" ${aspectStyle} title="双击放大"><img class="node-preview-img" draggable="false" data-src="${escapeAttr(thumbSrc)}" data-full-src="${escapeAttr(full)}" decoding="async" alt="" data-node="${node.id}" /></div>`;
    }
  }
  if (node.status === "failed") {
    return renderFailedPreview(node, "生成失败");
  }
  return `<div class="node-preview empty" ${aspectStyle}><span class="preview-icon">${emptyIcon}</span><span class="preview-hint">${emptyHint}</span></div>`;
}

function modelLabelFromMeta(modelId) {
  const meta = getMyApiModelMeta(modelId);
  if (!meta) return "";
  return String(meta.name || meta.label || "").trim();
}

function videoModelCatalogForChannel(channel) {
  if (channel === "volcengine") return VOLCENGINE_VIDEO_MODELS;
  if (channel === "bendi") return BENDI_VIDEO_MODELS;
  return isDolaFamilyChannel(channel) ? DOLA_VIDEO_MODELS : VIDEO_MODELS;
}

function getVideoModelLabel(modelId, channel) {
  const id = normalizeNodeModelId("video", modelId);
  if (!id) return "无";
  const primary = videoModelCatalogForChannel(channel);
  const fallback = primary === VIDEO_MODELS ? DOLA_VIDEO_MODELS : VIDEO_MODELS;
  const m = applyModelUiDisplay(
    primary.find((item) => item.id === id) ||
      fallback.find((item) => item.id === id) ||
      BENDI_VIDEO_MODELS.find((item) => item.id === id) ||
      VOLCENGINE_VIDEO_MODELS.find((item) => item.id === id) ||
      MYAPI_VIDEO_MODELS.find((item) => item.id === id)
  );
  return m?.label || modelLabelFromMeta(id) || id;
}

function getImageModelLabel(modelId) {
  const id = normalizeNodeModelId("image", modelId);
  if (!id) return "无";
  const m = applyModelUiDisplay(
    IMAGE_MODELS.find((item) => item.id === id) ||
      BENDI_IMAGE_MODELS.find((item) => item.id === id) ||
      VOLCENGINE_IMAGE_MODELS.find((item) => item.id === id) ||
      MYAPI_IMAGE_MODELS.find((item) => item.id === id)
  );
  return m?.label || modelLabelFromMeta(id) || id;
}

function getTextModelLabel(modelId) {
  const id = String(modelId || "");
  if (!id) return "无";
  if (id === "doubao_chat") {
    return applyModelUiDisplay({
      id,
      label: "Seed Chat",
    }).label;
  }
  const m = applyModelUiDisplay(
    (typeof BENDI_TEXT_MODELS !== "undefined" && BENDI_TEXT_MODELS.find((item) => item.id === id)) ||
      (typeof BENDI_LOCAL_TEXT_MODELS !== "undefined" &&
        BENDI_LOCAL_TEXT_MODELS.find((item) => item.id === id)) ||
      (typeof VOLCENGINE_TEXT_MODELS !== "undefined" &&
        VOLCENGINE_TEXT_MODELS.find((item) => item.id === id)) ||
      MYAPI_TEXT_MODELS.find((item) => item.id === id)
  );
  return m?.label || modelLabelFromMeta(id) || id;
}

function getVoiceModelLabel(modelId) {
  const id = String(modelId || "");
  if (!id) return "无";
  const m = applyModelUiDisplay(
    (typeof VOLCENGINE_VOICE_MODELS !== "undefined" &&
      VOLCENGINE_VOICE_MODELS.find((item) => item.id === id)) ||
      MYAPI_VOICE_MODELS.find((item) => item.id === id)
  );
  return m?.label || modelLabelFromMeta(id) || id;
}

function getNodeModelLabel(nodeOrType, modelId) {
  const type = typeof nodeOrType === "string" ? nodeOrType : nodeOrType?.type;
  const id = modelId || (typeof nodeOrType === "object" ? nodeOrType?.model : "") || "";
  const channel =
    typeof nodeOrType === "object" && nodeOrType
      ? resolveNodeChannel(nodeOrType, { allowGpt: type !== "video" })
      : null;
  if (type === "image") return getImageModelLabel(id);
  if (type === "text" || type === "voice-text") return getTextModelLabel(id);
  if (type === "voice") return getVoiceModelLabel(id);
  return getVideoModelLabel(id, channel);
}

function videoUpgradeMaxDuration(modelId) {
  const id = normalizeNodeModelId("video", modelId);
  if (id === "seedance_v2.5") return 30;
  if (
    id === "seedance_v2.0" ||
    id === "seedance_v2.0_fast" ||
    id === "seedance_v2.0_mini" ||
    id === "seedance_v2.0_mini_chat" ||
    id === "ic_mini"
  ) {
    return 15;
  }
  return null;
}

function isUpgradeDoubaoVideoModel(modelId) {
  const id = normalizeNodeModelId("video", modelId);
  // Dola 模型不设升级门槛（站内均可选）
  if (isDolaVideoModel(id)) return false;
  const m = VIDEO_MODELS.find((item) => item.id === id);
  return !!(m && m.upgrade);
}

function findVideoModelMeta(modelId, channel) {
  const id = normalizeNodeModelId("video", modelId);
  const primary = videoModelCatalogForChannel(channel);
  const fallback = primary === VIDEO_MODELS ? DOLA_VIDEO_MODELS : VIDEO_MODELS;
  return (
    primary.find((item) => item.id === id) ||
    fallback.find((item) => item.id === id) ||
    BENDI_VIDEO_MODELS.find((item) => item.id === id) ||
    VOLCENGINE_VIDEO_MODELS.find((item) => item.id === id) ||
    null
  );
}

function videoDurationBounds(modelId, useUpgrade = false) {
  const m = getMyApiModelMeta(modelId);
  if (m?.kind === "video") {
    const min = m.duration_min ?? 4;
    const max = m.duration_max ?? 10;
    return { min: Math.min(min, max), max: Math.max(min, max) };
  }
  const id = normalizeNodeModelId("video", modelId);
  const meta = findVideoModelMeta(id);
  if (meta && (meta.duration_min != null || meta.duration_max != null)) {
    const min = meta.duration_min ?? VIDEO_DURATION_MIN;
    let max = meta.duration_max ?? VIDEO_DURATION_MAX;
    if (useUpgrade) {
      const upMax = videoUpgradeMaxDuration(id);
      if (upMax != null) max = upMax;
    }
    return { min: Math.min(min, max), max: Math.max(min, max) };
  }
  return { min: VIDEO_DURATION_MIN, max: VIDEO_DURATION_MAX };
}

function videoDurationDiscreteTicks(modelId, useUpgrade = false, channel) {
  const id = normalizeNodeModelId("video", modelId);
  const meta = findVideoModelMeta(id, channel);
  if (meta && Array.isArray(meta.duration_ticks) && meta.duration_ticks.length) {
    return meta.duration_ticks.slice();
  }
  return null;
}

function videoDurationTicksForModel(modelId, useUpgrade = false, channel) {
  const discrete = videoDurationDiscreteTicks(modelId, useUpgrade, channel);
  if (discrete?.length) return discrete;
  const { min, max } = videoDurationBounds(modelId, useUpgrade);
  if (max <= min) return [min];
  const span = max - min;
  if (span <= 6) {
    return Array.from({ length: span + 1 }, (_, i) => min + i);
  }
  // Visual reference marks only — slider stays continuous between min/max.
  const step = span > 20 ? 5 : span > 10 ? 2 : 1;
  const ticks = [min];
  for (let t = Math.ceil(min / step) * step; t < max; t += step) {
    if (t > min) ticks.push(t);
  }
  if (ticks[ticks.length - 1] !== max) ticks.push(max);
  return ticks;
}

function videoDurationTickPercent(value, min, max) {
  if (max <= min) return 0;
  return ((value - min) / (max - min)) * 100;
}

function renderVideoDurationTickHtml(t, duration, min, max) {
  const pct = videoDurationTickPercent(t, min, max);
  const edge = pct <= 0 ? " is-edge-start" : pct >= 100 ? " is-edge-end" : "";
  return `<span class="video-duration-tick${edge}${t === duration ? " active" : ""}" data-value="${t}" style="left:${pct}%">${t}s</span>`;
}

/** Doubao / Doubao S / BenDi：新建与切模型时默认 16:9 + 该模型最长时长 */
function prefersMaxVideoDefaults(channel, modelId) {
  const ch =
    typeof normalizeChannel === "function" ? normalizeChannel(channel, modelId) : String(channel || "");
  return ch === "doubao" || ch === "doubao_s" || ch === "bendi";
}

function pickPreferredRatio(ratios, fallback = "自动") {
  const list = Array.isArray(ratios) ? ratios : [];
  if (list.includes("16:9")) return "16:9";
  const concrete = list.filter((r) => r && r !== "自动");
  return concrete[0] || list[0] || fallback;
}

function defaultImageRatioForModel(modelId) {
  return pickPreferredRatio(imageRatiosForModel(modelId), "自动");
}

function defaultVideoRatioForChannel(channel, modelId) {
  const ch =
    typeof normalizeChannel === "function" ? normalizeChannel(channel, modelId) : String(channel || "");
  const ratios = videoRatiosForModel(modelId, ch);
  // 所有视频渠道：有 16:9 就默认 16:9
  return pickPreferredRatio(ratios, "16:9");
}

window.defaultImageRatioForModel = defaultImageRatioForModel;

function defaultVideoDurationForModel(modelId, useUpgrade = false, channel) {
  const discrete = videoDurationDiscreteTicks(modelId, useUpgrade, channel);
  if (discrete?.length) return discrete[discrete.length - 1];
  const { max } = videoDurationBounds(modelId, useUpgrade);
  return max;
}

function clampVideoDuration(value, modelId, useUpgrade = false, channel) {
  const discrete = videoDurationDiscreteTicks(modelId, useUpgrade, channel);
  const n = parseInt(value, 10);
  if (discrete?.length) {
    if (!Number.isFinite(n)) {
      if (prefersMaxVideoDefaults(channel, modelId)) return discrete[discrete.length - 1];
      if (discrete.includes(15)) return 15;
      if (discrete.includes(10)) return 10;
      return discrete[Math.floor(discrete.length / 2)];
    }
    return discrete.reduce((best, t) => (Math.abs(t - n) < Math.abs(best - n) ? t : best), discrete[0]);
  }
  const { min, max } = videoDurationBounds(modelId, useUpgrade);
  if (!Number.isFinite(n)) {
    return prefersMaxVideoDefaults(channel, modelId) ? max : Math.round((min + max) / 2);
  }
  return Math.min(max, Math.max(min, n));
}

function videoRatiosForModel(modelId, channel) {
  const m = getMyApiModelMeta(modelId);
  if (m?.kind === "video" && Array.isArray(m.ratios) && m.ratios.length) {
    return withoutAutoRatioRes(m.ratios);
  }
  if (channel === "volcengine" || isVolcengineModel(modelId)) {
    const vm = VOLCENGINE_VIDEO_MODELS.find((x) => x.id === modelId);
    if (vm?.ratios?.length) return withoutAutoRatioRes(vm.ratios);
    return ["16:9", "9:16", "1:1", "4:3", "3:4", "21:9"];
  }
  if (channel === "bendi" || isBendiModel(modelId)) {
    const bm = BENDI_VIDEO_MODELS.find((x) => x.id === modelId);
    if (bm?.ratios?.length) return bm.ratios.slice();
    if (typeof getBendiMode === "function" && getBendiMode() === "local") {
      return BENDI_LOCAL_VIDEO_RATIOS.slice();
    }
    return BENDI_VIDEO_RATIOS.slice();
  }
  if (isMyApiModel(modelId)) return MYAPI_DEFAULT_VIDEO_RATIOS.slice();
  if (isDolaFamilyChannel(channel) || isDolaVideoModel(modelId)) {
    return DOLA_VIDEO_RATIOS.slice();
  }
  return VIDEO_RATIOS;
}

function videoResolutionsForModel(modelId) {
  if (isBendiModel(modelId)) return [];
  if (isVolcengineModel(modelId)) {
    const vm = VOLCENGINE_VIDEO_MODELS.find((x) => x.id === modelId);
    if (vm?.resolutions?.length) return withoutAutoRatioRes(vm.resolutions);
    return ["480p", "720p", "1080p"];
  }
  const m = getMyApiModelMeta(modelId);
  if (m?.kind === "video" && Array.isArray(m.resolutions) && m.resolutions.length) {
    return withoutAutoRatioRes(m.resolutions);
  }
  if (isMyApiModel(modelId)) return DEFAULT_VIDEO_RESOLUTIONS.slice();
  return [];
}

function resolveEffectiveVideoModelId(node) {
  if (!node) return "";
  const channel = resolveNodeChannel(node, { allowGpt: false });
  const models = videoModelsForNode(node);
  if (!models.length) return "";
  if (node.model && models.some((m) => m.id === node.model)) return node.model;
  if (isMyApiModel(node.model) && models.some((m) => m.id === node.model)) return node.model;
  return models[0]?.id || "";
}

function syncMyApiVideoNodesFromModelConfig() {
  if (!CanvasStore?.boards) return;
  let changed = false;
  for (const board of CanvasStore.boards) {
    for (const node of board.nodes || []) {
      if (node.type !== "video") continue;
      const channel = resolveNodeChannel(node, { allowGpt: false });
      if (channel !== "myapi" && !isMyApiModel(node.model)) continue;
      const modelId = resolveEffectiveVideoModelId(node);
      const patch = normalizeVideoSettingsForModel(node, modelId);
      const before = JSON.stringify({
        ratio: node.ratio,
        resolution: node.resolution,
        duration: node.duration,
      });
      const after = JSON.stringify({
        ratio: patch.ratio ?? node.ratio,
        resolution: patch.resolution ?? node.resolution,
        duration: patch.duration ?? node.duration,
      });
      if (before !== after) {
        CanvasStore.updateNode(node.id, patch, false);
        changed = true;
      }
    }
  }
  if (changed) CanvasStore.save();
}

function imageRatiosForModel(modelId) {
  if (isVolcengineModel(modelId)) {
    const vm = VOLCENGINE_IMAGE_MODELS.find((x) => x.id === modelId);
    if (vm?.ratios?.length) return vm.ratios.slice();
    return ["自动", "16:9", "9:16", "1:1"];
  }
  if (isBendiModel(modelId) || modelId === "bendi_image") {
    const bm = BENDI_IMAGE_MODELS.find((x) => x.id === modelId);
    if (bm?.ratios?.length) return bm.ratios.slice();
    if (typeof getBendiMode === "function" && getBendiMode() === "local") {
      return BENDI_LOCAL_IMAGE_RATIOS.slice();
    }
    return BENDI_IMAGE_RATIOS.slice();
  }
  const m = getMyApiModelMeta(modelId);
  if (m?.kind === "image" && Array.isArray(m.ratios) && m.ratios.length) {
    // 图片比例写进提示词；「自动」= 不附加画面比例。模型配置里常无此项，前台补上。
    const list = withoutAutoRatioRes(m.ratios);
    return ["自动", ...list];
  }
  return IMAGE_RATIOS;
}

function normalizeVideoSettingsForModel(node, modelId) {
  const useUpgrade = typeof nodeUsesUpgradeDuration === "function" ? nodeUsesUpgradeDuration(node) : !!node.useUpgrade;
  const channel = typeof resolveNodeChannel === "function"
    ? resolveNodeChannel({ ...node, model: modelId }, { allowGpt: false })
    : normalizeChannel(node?.channel, modelId);
  const ratios = videoRatiosForModel(modelId, channel);
  const resolutions = videoResolutionsForModel(modelId);
  const bounds = videoDurationBounds(modelId, useUpgrade);
  const preferMax = prefersMaxVideoDefaults(channel, modelId);
  const fallbackDur = preferMax
    ? defaultVideoDurationForModel(modelId, useUpgrade, channel)
    : isDolaFamilyChannel(channel) && typeof DEFAULT_DOLA_VIDEO_DURATION === "number"
      ? DEFAULT_DOLA_VIDEO_DURATION
      : bounds.min;
  const patch = {
    duration: preferMax
      ? defaultVideoDurationForModel(modelId, useUpgrade, channel)
      : clampVideoDuration(node.duration ?? fallbackDur, modelId, useUpgrade, channel),
  };
  if (isDoubaoSChannel(normalizeChannel(node.channel, modelId))) {
    patch.useUpgrade = true;
  }
  const isApiVideo =
    isMyApiModel(modelId) ||
    isBendiModel(modelId) ||
    isVolcengineModel(modelId) ||
    !!getMyApiModelMeta(modelId);
  const preferredRatio = defaultVideoRatioForChannel(channel, modelId);
  const ratio = node.ratio || preferredRatio;
  if (!ratios.includes(ratio) || !node.ratio || node.ratio === "自动") {
    patch.ratio = preferredRatio || pickPreferredRatio(ratios, isApiVideo ? "16:9" : "自动");
  }
  const defaultRes = isApiVideo && resolutions.length ? resolutions[0] : "自动";
  const res = node.resolution || defaultRes;
  if (resolutions.length) {
    if (!resolutions.includes(res)) patch.resolution = resolutions[0] || defaultRes;
  } else if (isApiVideo) {
    patch.resolution = null;
  } else {
    patch.resolution = "自动";
  }
  return patch;
}

function formatVideoSettingsSummary(node) {
  if (!hasActiveModelsForNode(node)) return "无";
  const modelId = resolveEffectiveVideoModelId(node);
  if (!modelId) return "无";
  const channel = resolveNodeChannel(node, { allowGpt: false });
  const useUpgrade = nodeUsesUpgradeDuration(node);
  const ratios = videoRatiosForModel(modelId, channel);
  const ratio = node.ratio && ratios.includes(node.ratio) ? node.ratio : ratios[0] || "自动";
  const dur = clampVideoDuration(node.duration ?? 10, modelId, useUpgrade, channel);
  const res = node.resolution || "自动";
  const resolutions = videoResolutionsForModel(modelId);
  const parts = [ratio];
  if (resolutions.length) parts.push(res);
  parts.push(`${dur}s`);
  if (isDoubaoSChannel(channel) && isUpgradeDoubaoVideoModel(modelId)) parts.push("S");
  return parts.join(" · ");
}

window.normalizeVideoSettingsForModel = normalizeVideoSettingsForModel;
window.videoRatiosForModel = videoRatiosForModel;
window.videoResolutionsForModel = videoResolutionsForModel;
window.resolveEffectiveVideoModelId = resolveEffectiveVideoModelId;
window.syncMyApiVideoNodesFromModelConfig = syncMyApiVideoNodesFromModelConfig;
window.isUpgradeDoubaoVideoModel = isUpgradeDoubaoVideoModel;
window.videoDurationBounds = videoDurationBounds;
window.clampVideoDuration = clampVideoDuration;
window.prefersMaxVideoDefaults = prefersMaxVideoDefaults;
window.defaultVideoRatioForChannel = defaultVideoRatioForChannel;
window.defaultVideoDurationForModel = defaultVideoDurationForModel;

function imageResolutionsForChannel(channel) {
  if (channel === "volcengine") return ["1K", "2K", "3K", "4K"];
  return channel === "myapi" ? MYAPI_IMAGE_RESOLUTIONS.slice() : [];
}

function formatImageSettingsSummary(node) {
  if (!hasActiveModelsForNode(node)) return "无";
  const ratio = node.ratio || "自动";
  const channel = resolveNodeChannel(node, { allowGpt: true });
  if (channel !== "myapi" && channel !== "volcengine") return ratio;
  const res = node.resolution || (channel === "volcengine" ? "2K" : DEFAULT_MYAPI_IMAGE_RESOLUTION);
  if (!res || res === "默认") return ratio;
  return `${ratio} · ${res}`;
}

function renderModelPickerBlock(node, models, modelId, nodeType) {
  if (!models.length) {
    return `<div class="video-model-picker is-unconfigured" data-node="${node.id}">${renderMediaEmptyPill()}</div>`;
  }
  const selected = models.some((m) => m.id === modelId) ? modelId : models[0]?.id;
  const label =
    nodeType === "image"
      ? getImageModelLabel(selected)
      : nodeType === "text"
        ? getTextModelLabel(selected)
        : nodeType === "voice"
          ? getVoiceModelLabel(selected)
          : getVideoModelLabel(selected, resolveNodeChannel(node, { allowGpt: false }));
  return `<div class="video-model-picker" data-node="${node.id}">
      <button type="button" class="video-model-btn pill-select" data-node="${node.id}">
        <span class="video-model-btn-label">${escapeHtml(label)}</span>
        <span class="video-model-btn-caret">▾</span>
      </button>
      <div class="video-model-menu hidden" data-node="${node.id}">${renderModelMenu(node, models, selected)}</div>
    </div>`;
}

function renderSettingsPickerBlock(node, summary, popoverHtml) {
  if (!hasActiveModelsForNode(node)) {
    return `<div class="video-settings-picker is-unconfigured" data-node="${node.id}">${renderMediaEmptyPill()}</div>`;
  }
  return `<div class="video-settings-picker" data-node="${node.id}">
      <button type="button" class="video-settings-btn pill-select" data-node="${node.id}">
        ${escapeHtml(summary)}
      </button>
      ${popoverHtml}
    </div>`;
}

function renderRatioAspectShape(ratio) {
  const parts = String(ratio || "16:9").split(":");
  const w = parseFloat(parts[0]) || 16;
  const h = parseFloat(parts[1]) || 9;
  const landscape = w >= h;
  const style = landscape
    ? `width:100%;max-width:28px;aspect-ratio:${w}/${h}`
    : `height:100%;max-height:28px;aspect-ratio:${w}/${h}`;
  return `<span class="ratio-shape" style="${style}"></span>`;
}

function renderModelMenu(node, models, selectedId) {
  const selected = normalizeNodeModelId(node.type, selectedId) || models[0]?.id;
  return models
    .map(
      (m) => `
      <button type="button" class="video-model-option${m.id === selected ? " active" : ""}" data-node="${node.id}" data-model="${escapeAttr(m.id)}">
        <span class="video-model-option-copy">
          <span class="video-model-option-label">${escapeHtml(m.label)}</span>
          ${m.desc ? `<span class="video-model-option-desc">${escapeHtml(m.desc)}</span>` : ""}
        </span>
        ${m.id === selected ? '<span class="video-model-check">✓</span>' : ""}
      </button>`
    )
    .join("");
}

function renderRatioSettingsPopover(node, ratios, opts = {}) {
  const modelId = opts.modelId || resolveEffectiveVideoModelId(node);
  const ratio = node.ratio || "自动";
  const ratioList = Array.isArray(ratios) ? ratios : [];
  const showRatioPicker = ratioList.length > 1;
  const ratioBtns = showRatioPicker
    ? ratioList
        .map(
          (r) =>
            `<button type="button" class="video-ratio-btn${r === ratio ? " active" : ""}" data-node="${node.id}" data-ratio="${escapeAttr(r)}" title="${escapeAttr(r)}">
        <span class="video-ratio-shape">${renderRatioAspectShape(r === "自动" ? "16:9" : r)}</span>
        <span class="video-ratio-text">${escapeHtml(r)}</span>
      </button>`
        )
        .join("")
    : "";
  const durationBlock =
    opts.showDuration === false
      ? ""
      : (() => {
          const channel = resolveNodeChannel(node, { allowGpt: false });
          const useUpgrade = nodeUsesUpgradeDuration(node);
          const bounds = videoDurationBounds(modelId, useUpgrade);
          const duration = clampVideoDuration(node.duration ?? bounds.min, modelId, useUpgrade, channel);
          const tickMarks = videoDurationTicksForModel(modelId, useUpgrade, channel)
            .map((t) => renderVideoDurationTickHtml(t, duration, bounds.min, bounds.max))
            .join("");
          const upgradeToggle = opts.dolaHint
            ? `<div class="video-use-upgrade-wrap is-hint">Dola 插件 · 2.5 可选 5/10/15/30s · 其余 5/10/15s</div>`
            : opts.sChannelHint
            ? `<div class="video-use-upgrade-wrap is-hint">Seed S · 2.5 最长 30s · 2.0 / Fast / Mini 最长 15s</div>`
            : "";
          return `
      <div class="vset-block">
        <div class="vset-label">时长</div>
        ${upgradeToggle}
        <div class="video-duration-row">
          <div class="video-duration-track">
            <input type="range" class="video-duration-slider" data-node="${node.id}" min="${bounds.min}" max="${bounds.max}" step="1" value="${duration}" />
            <div class="video-duration-ticks">${tickMarks}</div>
          </div>
          <span class="video-duration-value">${duration}s</span>
        </div>
      </div>`;
        })();

  const resolutions = Array.isArray(opts.resolutions) ? opts.resolutions : [];
  const showResPicker = resolutions.length > 1;
  const resolutionBlock = !showResPicker
    ? ""
    : (() => {
        const defaultRes = opts.resolutionDefault || "自动";
        const res = node.resolution || defaultRes;
        const resBtns = resolutions
          .map(
            (r) =>
              `<button type="button" class="video-res-btn${r === res ? " active" : ""}" data-node="${node.id}" data-resolution="${escapeAttr(r)}">${escapeHtml(r)}</button>`
          )
          .join("");
        const label = opts.resolutionLabel || "分辨率";
        return `
      <div class="vset-block">
        <div class="vset-label">${escapeHtml(label)}</div>
        <div class="video-res-group">${resBtns}</div>
      </div>`;
      })();

  const ratioBlock = !showRatioPicker
    ? ""
    : `
      <div class="vset-block">
        <div class="vset-label">宽高比</div>
        <div class="video-ratio-grid">${ratioBtns}</div>
      </div>`;

  return `
    <div class="video-settings-pop hidden" data-node="${node.id}">
      ${durationBlock}
      ${resolutionBlock}
      ${ratioBlock}
    </div>`;
}

function renderVideoModelMenu(node) {
  const channel = resolveNodeChannel(node, { allowGpt: false });
  const models = videoModelsForNode(node);
  return renderModelMenu(node, models, node.model || models[0]?.id || defaultModelForChannel(channel, "video"));
}

function renderVideoSettingsPopover(node, modelId) {
  const mid = modelId || resolveEffectiveVideoModelId(node);
  const channel = resolveNodeChannel(node, { allowGpt: false });
  const sChannelHint = channel === "doubao_s";
  const dolaHint = isDolaFamilyChannel(channel);
  return renderRatioSettingsPopover(node, videoRatiosForModel(mid, channel), {
    showDuration: true,
    resolutions: videoResolutionsForModel(mid),
    modelId: mid,
    sChannelHint,
    dolaHint,
  });
}

function renderImageStyleMenu(node) {
  const selected = node.style || "";
  const clearBtn = `
    <button type="button" class="image-style-option${!selected ? " active" : ""}" data-node="${node.id}" data-style="">
      <span class="image-style-option-label">不选风格</span>
      ${!selected ? '<span class="video-model-check">✓</span>' : ""}
    </button>`;
  const items = IMAGE_STYLES.map(
    (s) => `
    <button type="button" class="image-style-option${selected === s ? " active" : ""}" data-node="${node.id}" data-style="${escapeAttr(s)}">
      <span class="image-style-option-label">${escapeHtml(s)}</span>
      ${selected === s ? '<span class="video-model-check">✓</span>' : ""}
    </button>`
  ).join("");
  return clearBtn + items;
}

function renderImageStylePicker(node) {
  const label = node.style || "风格";
  return `
    <div class="image-style-picker" data-node="${node.id}">
      <button type="button" class="image-style-btn pill-select" data-node="${node.id}" title="风格（可选）">
        <span class="image-style-btn-label">${escapeHtml(label)}</span>
        <span class="video-model-btn-caret">▾</span>
      </button>
      <div class="image-style-menu hidden" data-node="${node.id}">${renderImageStyleMenu(node)}</div>
    </div>`;
}

function renderImageToolbar(node) {
  const channel = resolveNodeChannel(node, { allowGpt: true });
  const models = imageModelsForChannel(channel);
  const modelId = models.some((m) => m.id === node.model) ? node.model : defaultModelForChannel(channel, "image");
  const styleHtml = "";
  const prefixHtml =
    typeof renderPrefixPicker === "function"
      ? renderPrefixPicker({ nodeId: node.id, mediaType: "image", prefixId: node.promptPrefixId })
      : "";
  const imageRes = imageResolutionsForChannel(channel);
  const imageResDefault = channel === "volcengine" ? "2K" : DEFAULT_MYAPI_IMAGE_RESOLUTION;
  return `
    ${renderChannelPicker(node, { allowGpt: true })}
    ${renderModelPickerBlock(node, models, modelId, "image")}
    ${renderSettingsPickerBlock(
      node,
      formatImageSettingsSummary(node),
      renderRatioSettingsPopover(node, imageRatiosForModel(modelId), {
        showDuration: false,
        resolutions: imageRes,
        resolutionLabel: "清晰度",
        resolutionDefault: imageResDefault,
      })
    )}
    ${styleHtml}
    ${prefixHtml}
    <span class="panel-toolbar-spacer"></span>
    ${renderGenActionBtns(node, node.type)}`;
}

function renderVideoToolbar(node) {
  const channel = resolveNodeChannel(node, { allowGpt: false });
  const models = videoModelsForNode(node);
  const modelId = models.some((m) => m.id === node.model)
    ? node.model
    : models[0]?.id || defaultModelForChannel(channel, "video");
  const prefixHtml =
    typeof renderPrefixPicker === "function"
      ? renderPrefixPicker({ nodeId: node.id, mediaType: "video", prefixId: node.promptPrefixId })
      : "";
  return `
    ${renderChannelPicker(node, { allowGpt: false })}
    ${renderModelPickerBlock(node, models, modelId, "video")}
    ${renderSettingsPickerBlock(
      node,
      formatVideoSettingsSummary(node),
      renderVideoSettingsPopover(node, modelId)
    )}
    ${prefixHtml}
    <span class="panel-toolbar-spacer"></span>
    ${renderGenActionBtns(node, "video")}`;
}

function hidePillPicker(el, opts = {}) {
  if (!el) return;
  if (typeof dismissOverlay === "function") dismissOverlay(el, opts);
  else el.classList.add("hidden");
}

function showPillPicker(el) {
  if (!el) return;
  if (typeof revealOverlay === "function") revealOverlay(el);
  else el.classList.remove("hidden");
}

function closeVideoPickers(except) {
  // except: DOM element to keep open, or null/undefined to close all.
  // (Legacy string nodeId is ignored — same-row pickers must also be mutually exclusive.)
  const exceptEl = except && typeof except !== "string" ? except : null;
  document
    .querySelectorAll(
      ".video-model-menu, .video-settings-pop, .image-style-menu, .channel-menu, .prefix-menu"
    )
    .forEach((el) => {
      if (exceptEl && el === exceptEl) return;
      hidePillPicker(el);
    });
}

function refreshVideoPickerLabels(nodeId, opts = {}) {
  const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
  const wrap = document.querySelector(`.node-wrap[data-id="${nodeId}"]`);
  if (!node || !wrap) return;
  const modelId =
    node.type === "video"
      ? resolveEffectiveVideoModelId(node)
      : node.model || (node.type === "image" ? DEFAULT_IMAGE_MODEL : DEFAULT_VIDEO_MODEL);
  const modelLabel = wrap.querySelector(".video-model-btn-label");
  if (modelLabel) {
    modelLabel.textContent = getNodeModelLabel(node, modelId);
  }
  const settingsBtn = wrap.querySelector(".video-settings-btn");
  if (settingsBtn) {
    settingsBtn.textContent =
      node.type === "image"
        ? formatImageSettingsSummary(node)
        : isTextGenNode(node)
          ? ""
          : formatVideoSettingsSummary(node);
  }
  const durVal = wrap.querySelector(".video-duration-value");
  const durSlider = wrap.querySelector(".video-duration-slider");
  const useUpgrade = nodeUsesUpgradeDuration(node);
  const channel = resolveNodeChannel(node, { allowGpt: false });
  const bounds = node.type === "video" ? videoDurationBounds(modelId, useUpgrade) : videoDurationBounds(node.model);
  const dur = clampVideoDuration(node.duration ?? bounds.min, modelId, useUpgrade, channel);
  if (durVal) durVal.textContent = `${dur}s`;
  if (durSlider) {
    durSlider.min = String(bounds.min);
    durSlider.max = String(bounds.max);
    durSlider.value = String(dur);
  }
  const upgradeCb = wrap.querySelector(".video-use-upgrade");
  if (upgradeCb) upgradeCb.checked = !!node.useUpgrade;
  wrap.querySelectorAll(".video-duration-tick").forEach((el) => {
    el.classList.toggle("active", Number(el.dataset.value) === dur);
  });
  const activeModel = modelId;
  wrap.querySelectorAll(".video-model-option").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.model === activeModel);
    const check = btn.querySelector(".video-model-check");
    if (check) check.remove();
    if (btn.classList.contains("active")) {
      btn.insertAdjacentHTML("beforeend", '<span class="video-model-check">✓</span>');
    }
  });
  wrap.querySelectorAll(".video-ratio-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.ratio === (node.ratio || "自动"));
  });
  wrap.querySelectorAll(".video-res-btn").forEach((btn) => {
    const fallback =
      node.type === "image" ? DEFAULT_MYAPI_IMAGE_RESOLUTION : "自动";
    btn.classList.toggle("active", btn.dataset.resolution === (node.resolution || fallback));
  });
  const styleLabel = wrap.querySelector(".image-style-btn-label");
  if (styleLabel) styleLabel.textContent = node.style || "风格";
  wrap.querySelectorAll(".image-style-option").forEach((btn) => {
    const val = btn.dataset.style || "";
    const active = val === (node.style || "");
    btn.classList.toggle("active", active);
    const check = btn.querySelector(".video-model-check");
    if (check) check.remove();
    if (active) btn.insertAdjacentHTML("beforeend", '<span class="video-model-check">✓</span>');
  });
  const prefixVal = wrap.querySelector(".prefix-btn-label");
  if (prefixVal && typeof PromptPrefixStore !== "undefined") {
    const mediaType = node.type === "video" ? "video" : "image";
    const label = PromptPrefixStore.getEffectiveLabel(node.promptPrefixId, mediaType);
    prefixVal.textContent = label.length > 8 ? `${label.slice(0, 7)}…` : label;
    const effectiveId = PromptPrefixStore.getEffectivePrefixId(node.promptPrefixId, mediaType);
    wrap.querySelectorAll(".prefix-option").forEach((btn) => {
      const id = btn.dataset.prefix || "";
      const active = id ? id === effectiveId : !effectiveId;
      btn.classList.toggle("active", active);
      const check = btn.querySelector(".video-model-check");
      if (check) check.remove();
      if (active) btn.insertAdjacentHTML("beforeend", '<span class="video-model-check">✓</span>');
    });
  }
  const badge = wrap.querySelector(".node-ratio");
  if (badge) badge.textContent = node.ratio || "自动";
  if (opts.resize !== false) applyNodePreviewSize(nodeId);
  if (typeof updateGenCostBadge === "function") {
    updateGenCostBadge(nodeId, {
      modelId,
      resolution: node.resolution,
      duration: node.duration,
    });
  }
}

window.closeVideoPickers = closeVideoPickers;
window.hidePillPicker = hidePillPicker;
window.showPillPicker = showPillPicker;
window.refreshVideoPickerLabels = refreshVideoPickerLabels;
window.applyNodePreviewSize = applyNodePreviewSize;

function renderModelOptionsHtml(models, selectedId) {
  return models
    .map(
      (m) =>
        `<option value="${escapeAttr(m.id)}" ${m.id === selectedId ? "selected" : ""}>${escapeHtml(m.label)}</option>`
    )
    .join("");
}

function renderTextToolbar(node) {
  const channel = resolveNodeChannel(node, { allowGpt: false });
  const models = textModelsForChannel(channel);
  const modelId =
    channel === "myapi"
      ? models.some((m) => m.id === node.model)
        ? node.model
        : defaultModelForChannel("myapi", "text")
      : channel === "volcengine"
        ? models.some((m) => m.id === node.model)
          ? node.model
          : defaultModelForChannel("volcengine", "text") || models[0]?.id || ""
      : channel === "bendi"
        ? models.some((m) => m.id === node.model)
          ? node.model
          : defaultModelForChannel("bendi", "text") || models[0]?.id || "dola-chat"
        : "doubao_chat";
  // MyApi / BenDi / 火山引擎 text show model pill; browser DouBao text has no separate model pill.
  const modelPicker =
    channel === "myapi" || channel === "bendi" || channel === "volcengine" || !isBrowserChannelEnabled()
      ? renderModelPickerBlock(node, models, modelId, "text")
      : "";
  return `
    ${renderChannelPicker(node, { allowGpt: false })}
    ${modelPicker}
    <span class="panel-toolbar-spacer"></span>
    ${renderGenActionBtns(node, "text")}`;
}

function renderVoiceToolbar(node) {
  const channel = resolveNodeChannel(node, { allowGpt: false });
  const models = voiceModelsForChannel(channel);
  const modelId = models.some((m) => m.id === node.model)
    ? node.model
    : defaultModelForChannel(channel, "voice") || models[0]?.id || "";
  return `
    ${renderChannelPicker(node, { allowGpt: false })}
    ${renderModelPickerBlock(node, models, modelId, "voice")}
    <span class="panel-toolbar-spacer"></span>
    ${renderGenActionBtns(node, "voice")}`;
}

const TEXT_SHORTCUT_REVERSE_PROMPT = `请详细分析这张图片，反向推导出能够重新生成该图片的完整提示词。请用中文输出，并包含以下要素：
1. 主体描述：人物、物体、场景元素的具体特征
2. 艺术风格与媒介：绘画风格、渲染方式
3. 光影与色彩：光源方向、色温、主色调
4. 构图与视角：镜头角度、景别、画面布局
5. 氛围与情绪：整体意境和情感表达
6. 技术参数：分辨率、画质描述词

请将结果整理为一段可直接用于图像生成的结构化提示词。`;

const TEXT_SHORTCUTS = [
  {
    id: "reverse",
    title: "反推图片提示词",
    desc: "分析图片内容，反向推导出可生成该图的详细提示词",
    needsInput: false,
    prompt: TEXT_SHORTCUT_REVERSE_PROMPT,
  },
  {
    id: "polish",
    title: "提示词润色增强",
    desc: "将简单描述扩展为专业、详细的图像生成提示词",
    needsInput: true,
    placeholder: "例如：一只猫在窗边",
    build(input) {
      return `请将以下简单描述润色增强为专业、详细、可直接用于图像生成的提示词：\n\n${input.trim()}`;
    },
  },
  {
    id: "translate",
    title: "中英提示词互译",
    desc: "将中文描述译为英文提示词，或将英文译为中文",
    needsInput: true,
    placeholder: "输入中文或英文提示词",
    build(input) {
      return `请对以下提示词做中英互译：若为中文则译为英文图像生成提示词，若为英文则译为中文。只输出翻译结果。\n\n${input.trim()}`;
    },
  },
  {
    id: "structure",
    title: "提示词结构化整理",
    desc: "将零散描述整理为标准层级化结构化提示词",
    needsInput: true,
    placeholder: "输入需要整理的描述",
    build(input) {
      return `请将以下零散描述整理为标准层级化的结构化图像生成提示词（含主体、风格、光影、构图、氛围、技术参数等），输出可直接使用：\n\n${input.trim()}`;
    },
  },
  {
    id: "style",
    title: "风格迁移提示词",
    desc: "按指定风格生成可用于风格迁移的提示词",
    needsInput: true,
    placeholder: "例如：吉卜力动画、赛博朋克、水彩画",
    build(input) {
      return `请结合参考图片，生成「${input.trim()}」风格的风格迁移提示词。需详细描述主体、构图、光影与该风格的视觉特征，输出可直接用于图像生成的完整提示词。`;
    },
  },
];

/** Ranges of dialogue / quoted spans that quick-mention must not touch. */
function collectQuotedRanges(text) {
  const src = String(text || "");
  const ranges = [];
  let i = 0;
  while (i < src.length) {
    const ch = src[i];
    let close = null;
    if (ch === '"') close = '"';
    else if (ch === "\u201c") close = "\u201d";
    else if (ch === "「") close = "」";
    else if (ch === "『") close = "』";
    if (!close) {
      i += 1;
      continue;
    }
    const start = i;
    i += 1;
    while (i < src.length && src[i] !== close) i += 1;
    if (i < src.length) {
      ranges.push([start, i + 1]);
      i += 1;
    }
  }
  return ranges;
}

function indexInQuotedRange(index, ranges) {
  return ranges.some(([a, b]) => index >= a && index < b);
}

/** Quick-mention suffix already on a name: @ref:mat or @ref:mat（音色@ref:voice） */
const QUICK_MENTION_SUFFIX_RE = /^@ref:([a-z0-9]+)(?:（音色@ref:([a-z0-9]+)）)?/i;

function getQuickMentionRecords(node) {
  return Array.isArray(node?.quickMentionRecords) ? node.quickMentionRecords.filter(Boolean) : [];
}

function quickMentionRecordLabel(rec, board) {
  const mat = board?.nodes?.find((n) => n.id === rec.materialId);
  const matName = mat ? getNodeDisplayName(mat, board) : "素材";
  const voice = rec.voiceId ? board?.nodes?.find((n) => n.id === rec.voiceId) : null;
  if (voice) {
    if (isVoiceTextNode(voice)) {
      return `${rec.name}@${matName} · 发送→（音色描述：…）`;
    }
    return `${rec.name}@${matName}（音色@${getNodeDisplayName(voice, board)}）`;
  }
  return `${rec.name}@${matName}`;
}

function quickMentionInlineVoiceId(rec, board) {
  const voice = String(rec?.voiceId || "").trim();
  if (!voice) return "";
  const b = board || CanvasStore.activeBoard();
  const voiceNode =
    b?.nodes?.find((n) => n.id === voice) ||
    (typeof resolveWbMentionNode === "function" ? resolveWbMentionNode(voice) : null);
  if (isVoiceTextNode(voiceNode)) return "";
  return voice;
}

function quickMentionRecordSuffix(rec, board) {
  const mat = String(rec?.materialId || "").trim();
  if (!mat) return "";
  const voice = quickMentionInlineVoiceId(rec, board);
  return voice ? `@ref:${mat}（音色@ref:${voice}）` : `@ref:${mat}`;
}

/** Strip trailing 角色（音色/音色描述：@ref:id） lines previously appended for 音色文本. */
const VOICE_TEXT_FOOTER_LINE_RE = /^(.+?)（(?:音色|音色描述)：@ref:([a-z0-9]+)）\s*$/i;

function stripVoiceTextFooter(prompt) {
  const src = String(prompt || "");
  if (!src.trim()) return src;
  const lines = src.split("\n");
  while (lines.length) {
    const last = lines[lines.length - 1];
    if (!String(last).trim()) {
      lines.pop();
      continue;
    }
    if (VOICE_TEXT_FOOTER_LINE_RE.test(String(last).trim())) {
      lines.pop();
      continue;
    }
    break;
  }
  return lines.join("\n").replace(/\s+$/u, "");
}

function collectVoiceTextQuickRecords(records, board) {
  const b = board || CanvasStore.activeBoard();
  const out = [];
  const seen = new Set();
  for (const rec of records || []) {
    const voiceId = String(rec?.voiceId || "").trim();
    const name = String(rec?.name || "").trim();
    if (!voiceId || !name) continue;
    const voice =
      b?.nodes?.find((n) => n.id === voiceId) ||
      (typeof resolveWbMentionNode === "function" ? resolveWbMentionNode(voiceId) : null);
    if (!isVoiceTextNode(voice)) continue;
    const key = `${name}\0${voiceId}`;
    if (seen.has(key)) continue;
    seen.add(key);
    out.push({ name, voiceId, voice });
  }
  return out;
}

/** Rebuild end-of-prompt 音色文本 lines from quick-mention records. */
function rebuildVoiceTextFooter(prompt, records, board) {
  const body = stripVoiceTextFooter(prompt);
  const voiceRecs = collectVoiceTextQuickRecords(records, board);
  if (!voiceRecs.length) return body;
  // 编辑器里仍用 @ref；发送时 resolve 成（音色描述：正文）
  const lines = voiceRecs.map((r) => `${r.name}（音色描述：@ref:${r.voiceId}）`);
  return `${body}${body ? "\n\n" : ""}${lines.join("\n")}`;
}

function applyVoiceTextFooterToNode(nodeId, promptOverride) {
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  if (!node) return promptOverride ?? "";
  const board = CanvasStore.activeBoard();
  const base = promptOverride != null ? promptOverride : node.prompt || "";
  // 只给提示词里仍带 @ 绑定的记录写末尾行，避免「清除」后又被加回来
  const active = getQuickMentionRecords(node).filter(
    (r) => countQuickMentionApplied(node, r, base) > 0
  );
  return rebuildVoiceTextFooter(base, active, board);
}

/** Prefer live prompt editors so ×N badges track deletes without waiting for a remount. */
function getLivePromptForNode(nodeId) {
  const nid = String(nodeId || "").trim();
  if (!nid) return "";
  try {
    if (
      typeof PromptExpand !== "undefined" &&
      PromptExpand.isOpen?.() &&
      PromptExpand.nodeId === nid
    ) {
      const ed = PromptExpand.editor?.();
      if (ed?.dataset?.peMounted === "1" && ed.dataset.node === nid) {
        return PromptEditor.getValue(ed);
      }
    }
  } catch {
    /* ignore */
  }
  const inline = document.querySelector(
    `.node-wrap[data-id="${CSS.escape(nid)}"] .prompt-editor[data-node="${CSS.escape(nid)}"]`
  );
  if (inline?.dataset?.peMounted === "1") {
    return PromptEditor.getValue(inline);
  }
  return CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nid)?.prompt || "";
}

function countQuickMentionApplied(node, rec, promptOverride) {
  const src = String(promptOverride != null ? promptOverride : node?.prompt || "");
  const needle = String(rec?.name || "").trim();
  const suffix = quickMentionRecordSuffix(rec);
  if (!needle || !suffix) return 0;
  const ranges = collectQuotedRanges(src);
  let count = 0;
  let from = 0;
  while (from < src.length) {
    const idx = src.indexOf(needle, from);
    if (idx < 0) break;
    const after = idx + needle.length;
    if (indexInQuotedRange(idx, ranges)) {
      from = after;
      continue;
    }
    if (src.slice(after, after + suffix.length) === suffix) count += 1;
    from = after + 1;
  }
  return count;
}

function formatQuickMentionStatusText(applied, roomy) {
  if (roomy) return applied > 0 ? `已应用×${applied}` : "未应用";
  return applied > 0 ? `×${applied}` : "未";
}

/** Update ×N / 已应用 badges in place (avoids stale UI when full remount is skipped). */
function patchQuickMentionStatusInHost(host, node, prompt, roomy) {
  if (!host || !node) return;
  const records = getQuickMentionRecords(node);
  const byId = new Map(records.map((r) => [String(r.id), r]));
  host.querySelectorAll(".qm-record-card[data-qm-record]").forEach((card) => {
    const rec = byId.get(String(card.dataset.qmRecord || ""));
    if (!rec) return;
    const applied = countQuickMentionApplied(node, rec, prompt);
    const statusEl = card.querySelector(".qm-card-status");
    if (!statusEl) return;
    const text = formatQuickMentionStatusText(applied, roomy);
    if (statusEl.textContent !== text) statusEl.textContent = text;
    statusEl.classList.toggle("is-on", applied > 0);
  });
}

function clearQuickNameMentions(prompt, name, materialId, voiceId) {
  const needle = String(name || "").trim();
  const mat = String(materialId || "").trim();
  if (!needle || !mat) return { prompt: prompt || "", count: 0 };
  const board = CanvasStore.activeBoard();
  const voiceNode = voiceId ? board?.nodes?.find((n) => n.id === voiceId) : null;
  const inlineVoice = voiceId && !isVoiceTextNode(voiceNode) ? String(voiceId).trim() : "";
  const suffix = inlineVoice ? `@ref:${mat}（音色@ref:${inlineVoice}）` : `@ref:${mat}`;
  const src = String(prompt || "");
  const ranges = collectQuotedRanges(src);
  const hits = [];
  let from = 0;
  while (from < src.length) {
    const idx = src.indexOf(needle, from);
    if (idx < 0) break;
    const after = idx + needle.length;
    if (indexInQuotedRange(idx, ranges)) {
      from = after;
      continue;
    }
    if (src.slice(after, after + suffix.length) === suffix) {
      hits.push({ idx, end: after + suffix.length });
    }
    from = after + 1;
  }
  let out = src;
  for (let h = hits.length - 1; h >= 0; h -= 1) {
    const { idx, end } = hits[h];
    out = out.slice(0, idx) + needle + out.slice(end);
  }
  return { prompt: out, count: hits.length };
}

function deleteQuickMentionRecord(nodeId, recordId) {
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  if (!node) return;
  const kept = getQuickMentionRecords(node).filter((r) => r.id !== recordId);
  if (kept.length === getQuickMentionRecords(node).length) return;
  const prompt = node.prompt || "";
  const stillOn = kept.filter((r) => countQuickMentionApplied(node, r, prompt) > 0);
  const nextPrompt = rebuildVoiceTextFooter(prompt, stillOn, CanvasStore.activeBoard());
  const patch = { quickMentionRecords: kept };
  if (nextPrompt !== prompt) patch.prompt = nextPrompt;
  CanvasStore.updateNode(nodeId, patch);
  if (patch.prompt != null) syncPromptEditorsForNode(nodeId, patch.prompt);
}

function reapplyQuickMentionRecord(nodeId, recordId) {
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  const rec = getQuickMentionRecords(node).find((r) => r.id === recordId);
  if (!node || !rec) return;
  const { prompt, count } = applyQuickNameMentions(
    node.prompt || "",
    rec.name,
    rec.materialId,
    rec.voiceId
  );
  if (!count) {
    showCanvasToast("未找到可替换的名字（引号内已跳过，或已带 @）");
    return;
  }
  if (rec.voiceId) softAddReference(nodeId, rec.voiceId, { silent: true });
  const next = applyVoiceTextFooterToNode(nodeId, prompt);
  CanvasStore.updateNode(nodeId, { prompt: next });
  syncPromptEditorsForNode(nodeId, next);
  refreshNodeInputRefs(nodeId);
  showCanvasToast(`已添加 ${count} 处`);
}

/** Apply every quick-mention record once, in list order. */
function reapplyAllQuickMentionRecords(nodeId) {
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  if (!node) return;
  pruneQuickMentionRecords(nodeId);
  const fresh = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId) || node;
  const records = getQuickMentionRecords(fresh);
  if (records.length <= 2) {
    showCanvasToast("记录不足，无需一键添加");
    return;
  }
  let prompt = "";
  if (typeof PromptExpand !== "undefined" && PromptExpand.isOpen() && PromptExpand.nodeId === nodeId) {
    prompt = PromptEditor.getValue(PromptExpand.editor()) || fresh.prompt || "";
  } else {
    const inline = document.querySelector(
      `.node-wrap[data-id="${nodeId}"] .prompt-editor[data-node="${nodeId}"]`
    );
    prompt =
      inline?.dataset?.peMounted === "1"
        ? PromptEditor.getValue(inline) || fresh.prompt || ""
        : fresh.prompt || "";
  }
  let total = 0;
  let hitRecords = 0;
  for (const rec of records) {
    const { prompt: next, count } = applyQuickNameMentions(
      prompt,
      rec.name,
      rec.materialId,
      rec.voiceId
    );
    prompt = next;
    if (count) {
      total += count;
      hitRecords += 1;
    }
  }
  if (!total) {
    showCanvasToast("未找到可替换的名字（引号内已跳过，或已带 @）");
    return;
  }
  prompt = applyVoiceTextFooterToNode(nodeId, prompt);
  CanvasStore.updateNode(nodeId, { prompt });
  syncPromptEditorsForNode(nodeId, prompt);
  refreshNodeInputRefs(nodeId);
  refreshQuickMentionRecords(nodeId);
  showCanvasToast(`一键添加：${hitRecords} 条记录，共 ${total} 处`);
}

function renderQuickMentionApplyAllBtn(nodeId, { expand = false } = {}) {
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  const count = getQuickMentionRecords(node).length;
  if (count <= 2) return "";
  const cls = expand
    ? "btn-quick-mention-all btn-quick-mention-all-expand"
    : "btn-quick-mention-all";
  return `<button type="button" class="${cls}" data-qm-apply-all="${escapeAttr(nodeId)}" title="按全部记录一键写入提示词（引号内对话跳过）">一键添加</button>`;
}

function syncQuickMentionApplyAllButtons(nodeId) {
  if (!nodeId) return;
  const panelTools = document.querySelector(
    `.node-wrap[data-id="${nodeId}"] .panel-prompt-tools`
  );
  if (panelTools) {
    const existing = panelTools.querySelector(".btn-quick-mention-all");
    const html = renderQuickMentionApplyAllBtn(nodeId);
    if (html) {
      if (existing) {
        existing.outerHTML = html;
      } else {
        const qmBtn = panelTools.querySelector(".btn-quick-mention");
        if (qmBtn) qmBtn.insertAdjacentHTML("afterend", html);
        else panelTools.insertAdjacentHTML("afterbegin", html);
      }
    } else {
      existing?.remove();
    }
  }
  const expandActions = document.querySelector("#prompt-expand .prompt-expand-header-actions");
  if (expandActions) {
    const existing = expandActions.querySelector(".btn-quick-mention-all-expand");
    const show =
      typeof PromptExpand !== "undefined" &&
      PromptExpand.isOpen() &&
      PromptExpand.nodeId === nodeId;
    const html = show ? renderQuickMentionApplyAllBtn(nodeId, { expand: true }) : "";
    if (html) {
      if (existing) existing.outerHTML = html;
      else expandActions.insertAdjacentHTML("afterbegin", html);
    } else {
      existing?.remove();
    }
  }
}

function clearQuickMentionRecordFromPrompt(nodeId, recordId) {
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  const rec = getQuickMentionRecords(node).find((r) => r.id === recordId);
  if (!node || !rec) return;
  const { prompt, count } = clearQuickNameMentions(
    node.prompt || "",
    rec.name,
    rec.materialId,
    rec.voiceId
  );
  if (!count) {
    showCanvasToast("提示词中无此记录的 @ 绑定");
    return;
  }
  // 记录保留；末尾音色文本行只保留仍带 @ 绑定的那些
  const board = CanvasStore.activeBoard();
  const stillOn = getQuickMentionRecords(node).filter(
    (r) => countQuickMentionApplied(node, r, prompt) > 0
  );
  const next = rebuildVoiceTextFooter(prompt, stillOn, board);
  CanvasStore.updateNode(nodeId, { prompt: next });
  syncPromptEditorsForNode(nodeId, next);
  refreshNodeInputRefs(nodeId);
  refreshQuickMentionRecords(nodeId);
  showCanvasToast(`已清除 ${count} 处`);
}

function renderQuickMentionRecordsHtml(node, opts = {}) {
  const roomy = !!opts.roomy;
  const nodeId = node?.id;
  if (nodeId) pruneQuickMentionRecords(nodeId);
  const fresh = nodeId
    ? CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId)
    : node;
  const records = getQuickMentionRecords(fresh);
  if (!records.length) return "";
  const board = CanvasStore.activeBoard();
  const promptSrc =
    opts.promptOverride != null
      ? opts.promptOverride
      : fresh?.id
        ? getLivePromptForNode(fresh.id)
        : fresh?.prompt || "";
  const cards = records
    .map((rec) => {
      const mat = board?.nodes?.find((n) => n.id === rec.materialId);
      if (!mat) return "";
      const voice = rec.voiceId ? board?.nodes?.find((n) => n.id === rec.voiceId) : null;
      const matName = getNodeDisplayName(mat, board);
      const voiceName = voice ? getNodeDisplayName(voice, board) : "";
      const matThumb = `<span class="mention-item-thumb">${renderMediaThumbHtml(mat)}</span>`;
      const applied = countQuickMentionApplied(fresh, rec, promptSrc);
      const statusText = formatQuickMentionStatusText(applied, roomy);
      const statusClass = applied > 0 ? "is-on" : "";
      const voiceTip = voiceName ? ` · 音色 ${voiceName}` : "";
      const tip = `${rec.name} · ${matName}${voiceTip}`;
      const actions = `
        <span class="qm-card-actions">
          <button type="button" class="qm-rec-ico is-apply" data-qm-reapply title="再次应用到提示词" aria-label="应用">
            <svg viewBox="0 0 16 16" width="11" height="11" aria-hidden="true"><path fill="currentColor" d="M4.2 2.6a.8.8 0 0 1 1.22-.68l8.2 5.1a.8.8 0 0 1 0 1.36l-8.2 5.1A.8.8 0 0 1 4 12.8V3.2c0-.2.07-.4.2-.6z"/></svg>
            ${roomy ? `<span class="qm-rec-ico-label">应用</span>` : ""}
          </button>
          <button type="button" class="qm-rec-ico is-clear" data-qm-clear title="清除提示词中此记录的 @ 绑定" aria-label="清除">
            <svg viewBox="0 0 16 16" width="12" height="12" aria-hidden="true"><path fill="currentColor" d="M6.2 2.5h3.6c.3 0 .55.25.55.55V4h2.4a.55.55 0 1 1 0 1.1H3.25a.55.55 0 1 1 0-1.1H5.65V3.05c0-.3.25-.55.55-.55zm.55 1.5h2.5V3.6h-2.5v.4zM4.1 6.2h7.8l-.55 6.05A1.55 1.55 0 0 1 9.81 13.7H6.19a1.55 1.55 0 0 1-1.54-1.45L4.1 6.2zm1.65 1.4a.55.55 0 0 0-.54.56l.2 4.1a.55.55 0 1 0 1.1.05l-.2-4.1a.55.55 0 0 0-.56-.61zm2.25 0a.55.55 0 0 0-.55.55v4.15a.55.55 0 1 0 1.1 0V8.15a.55.55 0 0 0-.55-.55zm2.25 0a.55.55 0 0 0-.56.61l-.2 4.1a.55.55 0 1 0 1.1-.05l.2-4.1a.55.55 0 0 0-.54-.56z"/></svg>
            ${roomy ? `<span class="qm-rec-ico-label">清除</span>` : ""}
          </button>
          <button type="button" class="qm-rec-ico is-danger" data-qm-delete title="删除此记录" aria-label="删除">
            <svg viewBox="0 0 16 16" width="12" height="12" aria-hidden="true"><path fill="currentColor" d="M4.2 4.2a.75.75 0 0 1 1.06 0L8 6.94l2.74-2.74a.75.75 0 1 1 1.06 1.06L9.06 8l2.74 2.74a.75.75 0 1 1-1.06 1.06L8 9.06l-2.74 2.74a.75.75 0 1 1-1.06-1.06L6.94 8 4.2 5.26a.75.75 0 0 1 0-1.06z"/></svg>
            ${roomy ? `<span class="qm-rec-ico-label">删除</span>` : ""}
          </button>
        </span>`;
      if (roomy) {
        const voiceHtml = voiceName
          ? `<span class="qm-card-voice${isVoiceTextNode(voice) ? " is-voice-text" : ""}" title="${escapeAttr(voiceName)}">${isVoiceTextNode(voice) ? nodeTypeIconSvg("voice-text") : "♪"} ${escapeHtml(truncateRefLabel(voiceName, 10))}</span>`
          : "";
        return `<div class="qm-record-card is-roomy" data-qm-record="${escapeAttr(rec.id)}" data-host="${escapeAttr(fresh.id)}" title="${escapeAttr(tip)}">
          <div class="qm-card-main">
            ${matThumb}
            <span class="qm-card-status ${statusClass}" title="提示词中已绑定次数">${escapeHtml(statusText)}</span>
            <span class="qm-card-name">${escapeHtml(rec.name)}</span>
            <span class="qm-card-mat" title="${escapeAttr(matName)}">${escapeHtml(truncateRefLabel(matName, 14))}</span>
            ${voiceHtml}
          </div>
          ${actions}
        </div>`;
      }
      return `<div class="qm-record-card" data-qm-record="${escapeAttr(rec.id)}" data-host="${escapeAttr(fresh.id)}" title="${escapeAttr(tip)}">
        ${matThumb}
        <span class="qm-card-status ${statusClass}" title="提示词中已绑定次数">${escapeHtml(statusText)}</span>
        <span class="qm-card-name">${escapeHtml(rec.name)}</span>
        ${actions}
      </div>`;
    })
    .join("");
  const gridClass = roomy ? "qm-records-grid is-roomy" : "qm-records-grid";
  return `<div class="panel-qm-records" aria-label="快速添加记录">
    <div class="${gridClass}">${cards}</div>
  </div>`;
}

function appendQuickMentionRecord(nodeId, { name, materialId, voiceId }) {
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  if (!node) return;
  const records = [
    ...getQuickMentionRecords(node),
    {
      id: uid(),
      name: String(name || "").trim(),
      materialId: String(materialId || "").trim(),
      voiceId: String(voiceId || "").trim(),
      createdAt: Date.now(),
    },
  ];
  CanvasStore.updateNode(nodeId, { quickMentionRecords: records });
}

function isQuickMentionRecordValid(nodeId, rec, board) {
  const b = board || CanvasStore.activeBoard();
  if (!b || !rec?.materialId) return false;
  const mat = b.nodes.find((n) => n.id === rec.materialId);
  if (!mat || !isReferableNode(mat)) return false;
  const allowed = new Set(getMentionableNodes(nodeId).map((n) => n.id));
  if (!allowed.has(rec.materialId)) return false;
  if (rec.voiceId && !allowed.has(rec.voiceId)) return false;
  return true;
}

function pruneQuickMentionRecords(nodeId) {
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  if (!node) return false;
  const board = CanvasStore.activeBoard();
  const records = getQuickMentionRecords(node);
  const kept = records.filter((r) => isQuickMentionRecordValid(nodeId, r, board));
  if (kept.length === records.length) return false;
  const nextPrompt = rebuildVoiceTextFooter(node.prompt || "", kept, board);
  const patch = { quickMentionRecords: kept };
  if (nextPrompt !== (node.prompt || "")) patch.prompt = nextPrompt;
  CanvasStore.updateNode(nodeId, patch, false);
  if (patch.prompt != null) syncPromptEditorsForNode(nodeId, patch.prompt);
  CanvasStore.save();
  return true;
}

function remapQuickMentionRecordsOnClone(records, idMap) {
  if (!Array.isArray(records) || !records.length) return [];
  return records.map((r) => ({
    ...r,
    id: uid(),
    materialId: idMap.get(r.materialId) || r.materialId,
    voiceId: r.voiceId ? idMap.get(r.voiceId) || r.voiceId : "",
  }));
}

function refreshQuickMentionRecords(nodeId) {
  pruneQuickMentionRecords(nodeId);
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  const livePrompt = node ? getLivePromptForNode(nodeId) : "";
  // Keep store aligned with the editor so counts and persistence stay consistent.
  if (node && livePrompt !== (node.prompt || "")) {
    const edOpen =
      typeof PromptExpand !== "undefined" &&
      PromptExpand.isOpen?.() &&
      PromptExpand.nodeId === nodeId;
    const ed = edOpen
      ? PromptExpand.editor?.()
      : document.querySelector(
          `.node-wrap[data-id="${CSS.escape(nodeId)}"] .prompt-editor[data-node="${CSS.escape(nodeId)}"]`
        );
    if (ed?.dataset?.peMounted === "1") {
      CanvasStore.updateNode(nodeId, { prompt: livePrompt }, false);
    }
  }
  const fresh = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId) || node;
  const promptSrc = livePrompt || fresh?.prompt || "";
  const panelHost = document.querySelector(`.node-wrap[data-id="${nodeId}"] .panel-qm-records-host`);
  const expandHost = document.getElementById("prompt-expand-qm-records");
  if (panelHost) {
    const qmKey = fresh
      ? getQuickMentionRecordsRenderKey(fresh, { promptOverride: promptSrc })
      : "";
    if (panelHost.dataset.refsKey !== qmKey) {
      panelHost.dataset.refsKey = qmKey;
      panelHost.innerHTML = fresh
        ? renderQuickMentionRecordsHtml(fresh, { promptOverride: promptSrc })
        : "";
      hydrateMediaThumbs(panelHost);
      stripCanvasTitles(panelHost);
    } else {
      patchQuickMentionStatusInHost(panelHost, fresh, promptSrc, false);
    }
  }
  if (expandHost && PromptExpand.nodeId === nodeId) {
    const qmKey = fresh
      ? getQuickMentionRecordsRenderKey(fresh, { roomy: true, promptOverride: promptSrc })
      : "";
    if (expandHost.dataset.refsKey !== qmKey) {
      expandHost.dataset.refsKey = qmKey;
      expandHost.innerHTML = fresh
        ? renderQuickMentionRecordsHtml(fresh, { roomy: true, promptOverride: promptSrc }) ||
          `<div class="prompt-expand-qm-empty">暂无记录。点「快速添加」填写名字并选素材后应用，记录会出现在这里。</div>`
        : "";
      hydrateMediaThumbs(expandHost);
      stripCanvasTitles(expandHost);
    } else {
      patchQuickMentionStatusInHost(expandHost, fresh, promptSrc, true);
    }
    ensurePromptExpandQmDock(nodeId);
  }
  syncQuickMentionApplyAllButtons(nodeId);
}

function setPromptExpandQmVisible(on) {
  const wrap = document.getElementById("prompt-expand-qm");
  const expandOpen = typeof PromptExpand !== "undefined" && PromptExpand.isOpen();
  if (!wrap) return;
  if (on || expandOpen) wrap.removeAttribute("hidden");
  else wrap.setAttribute("hidden", "");
}

function ensurePromptExpandQmDock(nodeId) {
  if (!nodeId || typeof PromptExpand === "undefined" || !PromptExpand.isOpen() || PromptExpand.nodeId !== nodeId) {
    return;
  }
  setPromptExpandQmVisible(true);
  const panel = document.getElementById("prompt-expand-qm-panel");
  if (!panel) return;
  const hasForm = panel.querySelector(".quick-mention-float");
  const hasHint = panel.querySelector(".prompt-expand-qm-empty");
  if (!hasForm && !hasHint && typeof QuickMention !== "undefined") {
    QuickMention.openPanel(nodeId, { force: true, keepOpen: true });
  }
}

function syncPromptExpandQmRecords(nodeId) {
  const host = document.getElementById("prompt-expand-qm-records");
  if (!host || !nodeId) return;
  const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
  if (!node) {
    host.innerHTML = "";
    host.dataset.refsKey = "";
    return;
  }
  pruneQuickMentionRecords(nodeId);
  const qmKey = getQuickMentionRecordsRenderKey(node, { roomy: true });
  if (host.dataset.refsKey === qmKey && host.childElementCount > 0) {
    syncQuickMentionApplyAllButtons(nodeId);
    return;
  }
  host.dataset.refsKey = qmKey;
  const html = renderQuickMentionRecordsHtml(node, { roomy: true });
  host.innerHTML =
    html ||
    `<div class="prompt-expand-qm-empty">暂无记录。点「快速添加」填写名字并选素材后应用，记录会出现在这里。</div>`;
  hydrateMediaThumbs(host);
  stripCanvasTitles(host);
  syncQuickMentionApplyAllButtons(nodeId);
}

/**
 * Replace bare name occurrences with name@material（音色@voice）.
 * Skips quoted dialogue and names that already have @ref:… suffix.
 */
function applyQuickNameMentions(prompt, name, materialId, voiceId) {
  const src = String(prompt || "");
  const needle = String(name || "").trim();
  const mat = String(materialId || "").trim();
  if (!needle || !mat) return { prompt: src, count: 0 };

  const board = CanvasStore.activeBoard();
  const voiceNode =
    (voiceId && board?.nodes?.find((n) => n.id === voiceId)) ||
    (voiceId && typeof resolveWbMentionNode === "function" ? resolveWbMentionNode(voiceId) : null);
  // 音频音色走行内（音色@ref）；音色文本节点改写到提示词末尾，不塞进名字后面
  const inlineVoice = voiceId && !isVoiceTextNode(voiceNode) ? String(voiceId).trim() : "";
  const suffix = inlineVoice ? `@ref:${mat}（音色@ref:${inlineVoice}）` : `@ref:${mat}`;
  const replacement = needle + suffix;
  const ranges = collectQuotedRanges(src);
  const hits = [];
  let from = 0;
  while (from < src.length) {
    const idx = src.indexOf(needle, from);
    if (idx < 0) break;
    const after = idx + needle.length;
    if (indexInQuotedRange(idx, ranges)) {
      from = after;
      continue;
    }
    let replaceEnd = after;
    if (src[after] === "@") {
      const tail = QUICK_MENTION_SUFFIX_RE.exec(src.slice(after));
      if (tail) {
        from = after + tail[0].length;
        continue;
      }
      from = after;
      continue;
    }
    hits.push({ idx, replaceEnd });
    from = after;
  }

  let out = src;
  for (let h = hits.length - 1; h >= 0; h -= 1) {
    const { idx, replaceEnd } = hits[h];
    out = out.slice(0, idx) + replacement + out.slice(replaceEnd);
  }
  return { prompt: out, count: hits.length };
}

window.applyQuickNameMentions = applyQuickNameMentions;
window.syncPromptEditorsForNode = syncPromptEditorsForNode;
window.appendQuickMentionRecord = appendQuickMentionRecord;

function listQuickMentionAssets(hostNodeId) {
  const board = CanvasStore.activeBoard();
  const host = board?.nodes?.find((n) => n.id === hostNodeId);
  if (!host) return { materials: [], voices: [] };
  const wiredTextIds = new Set(getWiredTextRefNodes(hostNodeId).map((n) => n.id));
  const available = getMentionableNodes(hostNodeId);
  const mentioned = getReferencedNodes(hostNodeId, host.prompt || "");
  const seen = new Set();
  const materials = [];
  const voices = [];
  for (const n of [...available, ...mentioned]) {
    if (!n || seen.has(n.id) || n.id === hostNodeId || wiredTextIds.has(n.id)) continue;
    seen.add(n.id);
    if (isVoiceTextNode(n) || nodeReferenceKind(n) === "audio") {
      voices.push(n);
      continue;
    }
    const kind = nodeReferenceKind(n);
    if (kind === "image" || kind === "video") materials.push(n);
  }
  return { materials, voices };
}

function syncPromptEditorsForNode(nodeId, prompt) {
  if (!nodeId) return;
  const text = prompt || "";
  const selectors = [
    `.node-wrap[data-id="${nodeId}"] .prompt-editor[data-node="${nodeId}"]`,
    "#prompt-expand-editor",
  ];
  const seen = new Set();
  for (const sel of selectors) {
    const el = document.querySelector(sel);
    if (!el || el.dataset.node !== nodeId || seen.has(el)) continue;
    seen.add(el);
    PromptEditor.mount(el, text, { force: true });
  }
}

const QuickMention = {
  nodeId: null,
  open: false,
  materialId: "",
  voiceId: "",
  _previewTimer: null,

  hidePickPreview() {
    clearTimeout(this._previewTimer);
    this._previewTimer = null;
    const previewMedia = document.getElementById("mention-preview-media");
    if (previewMedia) {
      previewMedia.querySelectorAll("video, audio").forEach((v) => {
        try {
          v.pause();
          v.removeAttribute("src");
          v.load();
        } catch (_) {}
      });
      previewMedia.innerHTML = "";
      resetPreviewMediaBox(previewMedia);
    }
    dismissOverlay(document.getElementById("mention-preview"));
  },

  schedulePickPreview(node, menu) {
    clearTimeout(this._previewTimer);
    if (!node || !menu) return;
    this._previewTimer = setTimeout(() => {
      if (menu.classList.contains("hidden")) return;
      this.showPickPreview(node, menu);
    }, 140);
  },

  showPickPreview(node, menu) {
    const box = document.getElementById("mention-preview");
    const media = document.getElementById("mention-preview-media");
    if (!box || !media || !menu || !node) return;
    MentionUI.fillPreviewMedia(node, media, {
      onReady: () => this.positionPickPreview(menu),
      maxSize: 142,
    });
    revealOverlay(box);
    this.positionPickPreview(menu);
  },

  positionPickPreview(menu) {
    const preview = document.getElementById("mention-preview");
    if (!preview || preview.classList.contains("hidden") || !menu) return;
    const rect = menu.getBoundingClientRect();
    const previewW = preview.offsetWidth || 140;
    const previewH = preview.offsetHeight || 140;
    const gap = 10;
    let pLeft = rect.right + gap;
    if (pLeft + previewW > window.innerWidth - 8) {
      pLeft = rect.left - previewW - gap;
    }
    if (pLeft < 8) {
      const spaceRight = window.innerWidth - rect.right;
      const spaceLeft = rect.left;
      pLeft =
        spaceRight >= spaceLeft
          ? Math.min(rect.right + gap, window.innerWidth - previewW - 8)
          : Math.max(8, rect.left - previewW - gap);
    }
    let pTop = rect.top + (rect.height - previewH) / 2;
    pLeft = Math.min(Math.max(8, pLeft), window.innerWidth - previewW - 8);
    pTop = Math.min(Math.max(8, pTop), window.innerHeight - previewH - 8);
    preview.style.left = `${pLeft}px`;
    preview.style.top = `${pTop}px`;
  },

  getEditor(nodeId) {
    if (typeof PromptExpand !== "undefined" && PromptExpand.isOpen() && PromptExpand.nodeId === nodeId) {
      return PromptExpand.editor();
    }
    return document.querySelector(
      `.node-wrap[data-id="${nodeId}"] .prompt-editor[data-node="${nodeId}"]`
    );
  },

  hostEl(nodeId) {
    if (typeof PromptExpand !== "undefined" && PromptExpand.isOpen() && PromptExpand.nodeId === nodeId) {
      return document.getElementById("prompt-expand-qm-panel");
    }
    return document.querySelector(`.node-wrap[data-id="${nodeId}"] .node-panel-wrap`);
  },

  setOpenFlag(nodeId, on) {
    const wrap = document.querySelector(`.node-wrap[data-id="${nodeId}"]`);
    wrap?.classList.toggle("is-qm-open", !!on);
  },

  close(opts = {}) {
    const prevId = this.nodeId;
    const wasExpand =
      typeof PromptExpand !== "undefined" && PromptExpand.isOpen() && PromptExpand.nodeId === prevId;
    // Expand dock stays pinned — ignore dismiss unless expand itself is closing.
    if (wasExpand && !opts.allowExpandDismiss) {
      this.closeMenus();
      this.hidePickPreview();
      return;
    }
    this.closeMenus();
    this.hidePickPreview();
    document.querySelectorAll(".quick-mention-float").forEach((el) => el.remove());
    if (prevId) this.setOpenFlag(prevId, false);
    const panel = document.getElementById("prompt-expand-qm-panel");
    if (panel && !wasExpand) panel.innerHTML = "";
    else if (panel && wasExpand && opts.allowExpandDismiss) panel.innerHTML = "";
    if (wasExpand && prevId && !opts.allowExpandDismiss) {
      setPromptExpandQmVisible(true);
      syncPromptExpandQmRecords(prevId);
    }
    this.nodeId = null;
    this.open = false;
    this.materialId = "";
    this.voiceId = "";
  },

  itemHtml(n, board, { none = false } = {}) {
    if (none) {
      return `<button type="button" class="mention-item qm-pick-item" data-id="" title="无">
        <span class="mention-item-thumb"><span class="ref-icon">—</span></span>
        <span class="mention-item-label">无</span>
      </button>`;
    }
    const name = getNodeDisplayName(n, board);
    const thumb = isVoiceTextNode(n)
      ? `<span class="mention-item-thumb"><span class="ref-voice-txt" title="音色描述">${nodeTypeIconSvg("voice-text")}</span></span>`
      : `<span class="mention-item-thumb">${renderMediaThumbHtml(n)}</span>`;
    return `<button type="button" class="mention-item qm-pick-item" data-id="${escapeAttr(n.id)}" title="${escapeAttr(name)}">
      ${thumb}
      <span class="mention-item-label">${escapeHtml(name)}</span>
    </button>`;
  },

  triggerHtml(kind, label, node, board) {
    let thumb;
    if (node) {
      thumb = isVoiceTextNode(node)
        ? `<span class="mention-item-thumb"><span class="ref-voice-txt" title="音色描述">${nodeTypeIconSvg("voice-text")}</span></span>`
        : `<span class="mention-item-thumb">${renderMediaThumbHtml(node)}</span>`;
    } else {
      thumb = `<span class="mention-item-thumb"><span class="ref-icon">${kind === "voice" ? "♪" : "—"}</span></span>`;
    }
    const id = node ? node.id : "";
    return `<button type="button" class="qm-pick-trigger" data-qm-pick="${kind}" aria-haspopup="listbox">
      ${thumb}
      <span class="qm-pick-label">${escapeHtml(label)}</span>
      <span class="qm-pick-chevron" aria-hidden="true">▾</span>
    </button>
    <input type="hidden" class="qm-${kind === "material" ? "material" : "voice"}" value="${escapeAttr(id)}" />`;
  },

  fillMenu(menu, box, kind, nodes, { allowNone = false } = {}) {
    if (!menu) return;
    const board = CanvasStore.activeBoard();
    const items = [];
    if (allowNone) items.push(this.itemHtml(null, board, { none: true }));
    for (const n of nodes) items.push(this.itemHtml(n, board));
    menu.innerHTML = items.length
      ? `<div class="mention-list">${items.join("")}</div>`
      : `<div class="mention-empty">暂无可用${kind === "voice" ? "音色" : "素材"}</div>`;
    hydrateMediaThumbs(menu);
    const selected = kind === "material" ? this.materialId : this.voiceId;
    menu.querySelectorAll(".qm-pick-item").forEach((btn) => {
      if ((btn.dataset.id || "") === (selected || "")) btn.classList.add("is-active");
      btn.addEventListener("mouseenter", () => {
        menu.querySelectorAll(".qm-pick-item").forEach((b) => b.classList.remove("is-active"));
        btn.classList.add("is-active");
        const id = btn.dataset.id || "";
        if (!id) {
          this.hidePickPreview();
          return;
        }
        const node = board.nodes.find((n) => n.id === id);
        if (node) this.schedulePickPreview(node, menu);
      });
      btn.addEventListener("mousedown", (e) => {
        e.preventDefault();
        e.stopPropagation();
        this.pick(box, kind, btn.dataset.id || "");
      });
    });
    this.hidePickPreview();
  },

  syncTrigger(box, kind) {
    const trigger = box.querySelector(`[data-qm-pick="${kind}"]`);
    const hidden = box.querySelector(`.qm-${kind === "material" ? "material" : "voice"}`);
    if (!trigger || !hidden) return;
    const board = CanvasStore.activeBoard();
    const id = kind === "material" ? this.materialId : this.voiceId;
    hidden.value = id || "";
    const node = id ? board?.nodes?.find((n) => n.id === id) : null;
    const label = node ? getNodeDisplayName(node, board) : kind === "voice" ? "无" : "选择素材";
    let thumb;
    if (node) {
      thumb = isVoiceTextNode(node)
        ? `<span class="mention-item-thumb"><span class="ref-voice-txt" title="音色描述">${nodeTypeIconSvg("voice-text")}</span></span>`
        : `<span class="mention-item-thumb">${renderMediaThumbHtml(node)}</span>`;
    } else {
      thumb = `<span class="mention-item-thumb"><span class="ref-icon">${kind === "voice" ? "♪" : "—"}</span></span>`;
    }
    trigger.innerHTML = `${thumb}<span class="qm-pick-label">${escapeHtml(label)}</span><span class="qm-pick-chevron" aria-hidden="true">▾</span>`;
    hydrateMediaThumbs(trigger);
  },

  closeMenus(except = null) {
    this.hidePickPreview();
    document.querySelectorAll(".qm-pick-menu").forEach((menu) => {
      if (except && menu === except) return;
      menu.classList.add("hidden");
      menu.classList.remove("is-overlay-open");
      menu.remove();
    });
    document.querySelectorAll(".qm-pick-trigger.is-open").forEach((el) => el.classList.remove("is-open"));
  },

  ensureMenu(kind) {
    let menu = document.querySelector(`.qm-pick-menu[data-qm-menu="${kind}"]`);
    if (!menu) {
      menu = document.createElement("div");
      menu.className = "qm-pick-menu mention-menu hidden";
      menu.dataset.qmMenu = kind;
      menu.setAttribute("role", "listbox");
      document.body.appendChild(menu);
    }
    return menu;
  },

  toggleMenu(box, kind) {
    const trigger = box.querySelector(`[data-qm-pick="${kind}"]`);
    if (!trigger) return;
    const existing = document.querySelector(`.qm-pick-menu[data-qm-menu="${kind}"]:not(.hidden)`);
    if (existing) {
      this.closeMenus();
      return;
    }
    this.closeMenus();
    // Don't stack with @ mention picker
    if (typeof MentionUI !== "undefined") MentionUI.hide?.();
    const menu = this.ensureMenu(kind);
    const { materials, voices } = listQuickMentionAssets(this.nodeId);
    if (kind === "material") this.fillMenu(menu, box, "material", materials);
    else this.fillMenu(menu, box, "voice", voices, { allowNone: true });
    menu.classList.remove("hidden");
    trigger.classList.add("is-open");
    this.positionMenu(menu, trigger);
  },

  positionMenu(menu, trigger) {
    const rect = trigger.getBoundingClientRect();
    const menuW = Math.max(rect.width, 200);
    menu.style.position = "fixed";
    menu.style.left = "0px";
    menu.style.top = "0px";
    menu.style.width = `${menuW}px`;
    menu.style.right = "auto";
    menu.style.zIndex = "3000";
    // Measure after visible so height is accurate
    const menuH = Math.min(220, menu.offsetHeight || 180);
    let left = rect.left;
    let top = rect.bottom + 4;
    if (top + menuH > window.innerHeight - 8) {
      top = Math.max(8, rect.top - menuH - 4);
    }
    left = Math.min(Math.max(8, left), window.innerWidth - menuW - 8);
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
  },

  pick(box, kind, id) {
    if (kind === "material") this.materialId = id;
    else this.voiceId = id;
    this.syncTrigger(box, kind);
    this.closeMenus();
    this.updatePreview(box);
  },

  openPanel(nodeId, opts = {}) {
    const host = this.hostEl(nodeId);
    if (!host) return;
    const inExpand =
      typeof PromptExpand !== "undefined" && PromptExpand.isOpen() && PromptExpand.nodeId === nodeId;
    const keepOpen = !!(opts.keepOpen || inExpand);
    if (this.open && this.nodeId === nodeId) {
      // Expand form is always on — don't toggle closed.
      if (keepOpen) return;
      if (!opts.force) {
        this.close();
        return;
      }
    }
    this.close({ allowExpandDismiss: true });
    if (typeof TextShortcuts !== "undefined") TextShortcuts.close();

    const board = CanvasStore.activeBoard();
    const { materials, voices } = listQuickMentionAssets(nodeId);
    if (inExpand) {
      setPromptExpandQmVisible(true);
      syncPromptExpandQmRecords(nodeId);
    }
    if (!materials.length) {
      if (inExpand) {
        this.nodeId = nodeId;
        this.open = true;
        this.setOpenFlag(nodeId, true);
        const panel = document.getElementById("prompt-expand-qm-panel");
        if (panel) {
          panel.innerHTML = `<div class="prompt-expand-qm-empty">请先在上方素材区点 <strong>+</strong> 添加图片/视频，或牵线引用后再快速添加</div>`;
        }
      }
      showCanvasToast(
        inExpand
          ? "请先在上方素材区点 + 添加图片/视频，或牵线引用后再快速添加"
          : "请先在上方添加图片/视频素材"
      );
      return;
    }

    this.nodeId = nodeId;
    this.open = true;
    this.hidePickPreview();
    this.setOpenFlag(nodeId, true);
    this.materialId = materials[0]?.id || "";
    this.voiceId = "";
    const matNode = materials[0] || null;
    const box = document.createElement("div");
    box.className = `quick-mention-float${inExpand ? " is-in-expand" : ""}`;
    box.innerHTML = `
      <div class="quick-mention-head">
        <span>快速添加描述</span>
        ${
          keepOpen
            ? ""
            : `<button type="button" class="quick-mention-close" data-qm-close title="关闭"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button>`
        }
      </div>
      <div class="quick-mention-row">
        <label class="quick-mention-col">
          <span class="qm-col-label">名字</span>
          <input type="text" class="qm-name" placeholder="如：小三" autocomplete="off" spellcheck="false" />
        </label>
        <div class="quick-mention-col">
          <span class="qm-col-label">素材</span>
          <div class="qm-pick" data-qm-kind="material">
            ${this.triggerHtml("material", matNode ? getNodeDisplayName(matNode, board) : "选择素材", matNode, board)}
          </div>
        </div>
        <div class="quick-mention-col">
          <span class="qm-col-label">音色</span>
          <div class="qm-pick" data-qm-kind="voice">
            ${this.triggerHtml("voice", "无", null, board)}
          </div>
        </div>
      </div>
      <div class="quick-mention-preview" data-qm-preview></div>
      <div class="quick-mention-foot">
        <span class="quick-mention-hint">引号「」"" 内对话不替换</span>
        <button type="button" class="btn btn-primary qm-apply" data-qm-apply>应用</button>
      </div>`;
    host.appendChild(box);
    if (inExpand) {
      setPromptExpandQmVisible(true);
      syncPromptExpandQmRecords(nodeId);
    }
    hydrateMediaThumbs(box);
    this.syncTrigger(box, "material");
    this.syncTrigger(box, "voice");
    this.updatePreview(box);
    box.querySelector(".qm-name")?.addEventListener("input", () => this.updatePreview(box));
    if (!inExpand) {
      requestAnimationFrame(() => focusCanvasEditable(box.querySelector(".qm-name")));
    }
  },

  updatePreview(box) {
    const preview = box?.querySelector("[data-qm-preview]");
    if (!preview || !this.nodeId) return;
    const board = CanvasStore.activeBoard();
    const name = (box.querySelector(".qm-name")?.value || "").trim() || "名字";
    const matId = this.materialId || box.querySelector(".qm-material")?.value || "";
    const voiceId = this.voiceId || box.querySelector(".qm-voice")?.value || "";
    const matNode = board?.nodes?.find((n) => n.id === matId);
    const voiceNode = voiceId ? board?.nodes?.find((n) => n.id === voiceId) : null;
    const matLabel = matNode ? getNodeDisplayName(matNode, board) : "素材";
    let text = `${name}@${matLabel}`;
    if (voiceNode) {
      if (isVoiceTextNode(voiceNode)) {
        text = `${name}@${matLabel} → 发送时（音色描述：音色正文）`;
      } else {
        text = `${name}@${matLabel}（音色@${getNodeDisplayName(voiceNode, board)}）`;
      }
    }
    preview.textContent = `效果：${text}`;
  },

  apply() {
    const nodeId = this.nodeId;
    const host = this.hostEl(nodeId);
    const box = host?.querySelector(".quick-mention-float");
    if (!nodeId || !box) return;

    const name = (box.querySelector(".qm-name")?.value || "").trim();
    const materialId = this.materialId || box.querySelector(".qm-material")?.value || "";
    const voiceId = this.voiceId || box.querySelector(".qm-voice")?.value || "";
    if (!name) {
      showCanvasToast("请填写名字");
      box.querySelector(".qm-name")?.focus();
      return;
    }
    if (!materialId) {
      showCanvasToast("请选择素材");
      return;
    }

    const editor = this.getEditor(nodeId);
    const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
    const current = editor ? PromptEditor.getValue(editor) : node?.prompt || "";
    const { prompt, count } = applyQuickNameMentions(current, name, materialId, voiceId);
    if (!count) {
      showCanvasToast("未找到可替换的名字（引号内已跳过，或已带 @）");
      return;
    }

    appendQuickMentionRecord(nodeId, { name, materialId, voiceId });
    if (voiceId) softAddReference(nodeId, voiceId, { silent: true });
    const next = applyVoiceTextFooterToNode(nodeId, prompt);
    CanvasStore.updateNode(nodeId, { prompt: next });
    syncPromptEditorsForNode(nodeId, next);
    refreshNodeInputRefs(nodeId);
    refreshQuickMentionRecords(nodeId);
    if (typeof PromptExpand !== "undefined" && PromptExpand.isOpen() && PromptExpand.nodeId === nodeId) {
      syncPromptExpandQmRecords(nodeId);
    }
    const voiceNode = voiceId
      ? CanvasStore.activeBoard()?.nodes?.find((n) => n.id === voiceId)
      : null;
    if (isVoiceTextNode(voiceNode) && !getTextNodeBody(voiceNode)) {
      showCanvasToast(`已添加 ${count} 处（音色描述尚未生成，发送时会引用空描述）`);
    } else {
      showCanvasToast(`已添加 ${count} 处`);
    }
    const nameInput = box.querySelector(".qm-name");
    if (nameInput) {
      nameInput.value = "";
      nameInput.focus();
    }
    this.updatePreview(box);
    this.closeMenus();
  },
};

window.QuickMention = QuickMention;

/** 快速添加：仅画布空白处点击才视为关闭 */
function isQuickMentionCanvasDismissClick(target) {
  if (!target) return false;
  if (
    target.closest(
      ".quick-mention-float, .qm-pick-menu, .btn-quick-mention, .prompt-editor, #mention-preview, .node-wrap, #prompt-expand, .prompt-expand-qm, .prompt-expand-qm-dock, .prompt-expand-layout"
    )
  ) {
    return false;
  }
  return !!target.closest("#viewport, #canvas-world, #nodes-layer");
}

function initQuickMention() {
  const dismissOpenPickMenus = (e) => {
    const openMenu = document.querySelector(".qm-pick-menu:not(.hidden)");
    if (!openMenu) return false;
    // Keep open when interacting with the menu or its trigger / live preview
    if (e.target?.closest?.(".qm-pick-menu, [data-qm-pick], #mention-preview")) return false;
    QuickMention.closeMenus();
    return true;
  };

  // pointerdown closes stuck pick menus even when click is swallowed by editors
  document.addEventListener(
    "pointerdown",
    (e) => {
      dismissOpenPickMenus(e);
    },
    true
  );

  const onClick = (e) => {
    const closeBtn = e.target.closest("[data-qm-close]");
    if (closeBtn) {
      e.preventDefault();
      e.stopPropagation();
      QuickMention.close();
      return;
    }
    const applyBtn = e.target.closest("[data-qm-apply]");
    if (applyBtn) {
      e.preventDefault();
      e.stopPropagation();
      QuickMention.apply();
      return;
    }
    const pickTrigger = e.target.closest("[data-qm-pick]");
    if (pickTrigger) {
      e.preventDefault();
      e.stopPropagation();
      const box = pickTrigger.closest(".quick-mention-float");
      if (box) QuickMention.toggleMenu(box, pickTrigger.dataset.qmPick);
      return;
    }
    const reapplyBtn = e.target.closest("[data-qm-reapply]");
    if (reapplyBtn) {
      e.preventDefault();
      e.stopPropagation();
      const row = reapplyBtn.closest(".qm-record-card, .qm-record-row");
      const nodeId = row?.dataset?.host;
      const recordId = row?.dataset?.qmRecord;
      if (nodeId && recordId) reapplyQuickMentionRecord(nodeId, recordId);
      return;
    }
    const clearRecBtn = e.target.closest("[data-qm-clear]");
    if (clearRecBtn) {
      e.preventDefault();
      e.stopPropagation();
      const row = clearRecBtn.closest(".qm-record-card, .qm-record-row");
      const nodeId = row?.dataset?.host;
      const recordId = row?.dataset?.qmRecord;
      if (nodeId && recordId) clearQuickMentionRecordFromPrompt(nodeId, recordId);
      return;
    }
    const deleteRecBtn = e.target.closest("[data-qm-delete]");
    if (deleteRecBtn) {
      e.preventDefault();
      e.stopPropagation();
      const row = deleteRecBtn.closest(".qm-record-card, .qm-record-row");
      const nodeId = row?.dataset?.host;
      const recordId = row?.dataset?.qmRecord;
      if (nodeId && recordId) {
        const node = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === nodeId);
        const rec = getQuickMentionRecords(node).find((r) => r.id === recordId);
        const recName = rec?.name ? String(rec.name).trim() : "此记录";
        void AppDialog.confirm(`确定删除记录「${recName}」？`, {
          title: "删除记录",
          okText: "删除",
          danger: true,
        }).then((ok) => {
          if (!ok) return;
          deleteQuickMentionRecord(nodeId, recordId);
          refreshNodeInputRefs(nodeId);
          showCanvasToast("已删除记录");
        });
      }
      return;
    }
    const openBtn = e.target.closest(".btn-quick-mention");
    if (openBtn && !openBtn.classList.contains("btn-quick-mention-all")) {
      e.preventDefault();
      e.stopPropagation();
      const nodeId = openBtn.dataset.node || (typeof PromptExpand !== "undefined" ? PromptExpand.nodeId : null);
      if (nodeId) QuickMention.openPanel(nodeId);
      return;
    }
    const applyAllBtn = e.target.closest("[data-qm-apply-all]");
    if (applyAllBtn) {
      e.preventDefault();
      e.stopPropagation();
      const nodeId = applyAllBtn.dataset.qmApplyAll;
      if (nodeId) reapplyAllQuickMentionRecords(nodeId);
      return;
    }
    // Menu is portaled to body — ignore clicks inside it (items use mousedown)
    if (e.target.closest(".qm-pick-menu")) return;

    dismissOpenPickMenus(e);
    if (e.target.closest(".quick-mention-float, .qm-pick-menu, #mention-preview")) return;
    if (QuickMention.open && isQuickMentionCanvasDismissClick(e.target)) {
      QuickMention.close();
    }
  };

  document.addEventListener("click", onClick, true);

  document.addEventListener("keydown", (e) => {
    if (!QuickMention.open) return;
    if (e.key === "Escape") {
      e.preventDefault();
      if (document.querySelector(".qm-pick-menu:not(.hidden)")) {
        QuickMention.closeMenus();
        return;
      }
      // Expand dock form stays open — Esc only closes pick menus there.
      const inExpand =
        typeof PromptExpand !== "undefined" &&
        PromptExpand.isOpen() &&
        PromptExpand.nodeId === QuickMention.nodeId;
      if (inExpand) return;
      QuickMention.close();
      return;
    }
    if (e.key === "Enter" && (e.ctrlKey || e.metaKey) && document.activeElement?.closest?.(".quick-mention-float")) {
      e.preventDefault();
      QuickMention.apply();
    }
  });
}

const TextShortcuts = {
  nodeId: null,
  mode: null, // "menu" | "input" | null
  shortcutId: null,

  wrap(nodeId) {
    return document.querySelector(`.node-wrap[data-id="${nodeId}"] .node-panel-wrap`);
  },

  close() {
    const wrap = this.nodeId ? this.wrap(this.nodeId) : null;
    wrap?.querySelector(".text-shortcut-menu")?.remove();
    wrap?.querySelector(".text-shortcut-input")?.remove();
    this.nodeId = null;
    this.mode = null;
    this.shortcutId = null;
  },

  applyPrompt(nodeId, text) {
    const prompt = String(text || "").trim();
    if (!prompt) return;
    CanvasStore.updateNode(nodeId, { prompt });
    const editor =
      document.getElementById("prompt-expand-editor")?.dataset.node === nodeId
        ? document.getElementById("prompt-expand-editor")
        : document.querySelector(`.node-wrap[data-id="${nodeId}"] .prompt-editor[data-node="${nodeId}"]`);
    if (editor) PromptEditor.mount(editor, prompt, { force: true });
    refreshNodeInputRefs(nodeId);
  },

  openMenu(nodeId) {
    const wrap = this.wrap(nodeId);
    if (!wrap) return;
    this.close();
    this.nodeId = nodeId;
    this.mode = "menu";
    const items = TEXT_SHORTCUTS.map((s) => {
      const badge = s.needsInput ? `<span class="text-shortcut-badge">需输入</span>` : "";
      return `<button type="button" class="text-shortcut-item" data-shortcut="${escapeAttr(s.id)}">
        <span class="text-shortcut-item-main">
          <span class="text-shortcut-item-title">${escapeHtml(s.title)}</span>
          <span class="text-shortcut-item-desc">${escapeHtml(s.desc)}</span>
        </span>
        ${badge}
      </button>`;
    }).join("");
    const menu = document.createElement("div");
    menu.className = "text-shortcut-float text-shortcut-menu";
    menu.innerHTML = `
      <div class="text-shortcut-head">
        <span>快捷提示词</span>
        <button type="button" class="text-shortcut-close" data-text-shortcut-close title="关闭"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button>
      </div>
      <div class="text-shortcut-list">${items}</div>`;
    wrap.appendChild(menu);
  },

  openInput(nodeId, shortcutId) {
    const wrap = this.wrap(nodeId);
    const sc = TEXT_SHORTCUTS.find((s) => s.id === shortcutId);
    if (!wrap || !sc?.needsInput) return;
    this.close();
    this.nodeId = nodeId;
    this.mode = "input";
    this.shortcutId = shortcutId;
    const box = document.createElement("div");
    box.className = "text-shortcut-float text-shortcut-input";
    box.innerHTML = `
      <div class="text-shortcut-head">
        <span>${escapeHtml(sc.title)}</span>
        <button type="button" class="text-shortcut-close" data-text-shortcut-close title="关闭"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button>
      </div>
      <textarea class="text-shortcut-textarea" rows="2" placeholder="${escapeAttr(sc.placeholder || "")}"></textarea>
      <div class="text-shortcut-input-foot">
        <button type="button" class="text-shortcut-submit" data-text-shortcut-submit title="填入提示词">↑</button>
      </div>`;
    wrap.appendChild(box);
    const ta = box.querySelector(".text-shortcut-textarea");
    requestAnimationFrame(() => ta?.focus());
  },

  pick(shortcutId) {
    const nodeId = this.nodeId;
    const sc = TEXT_SHORTCUTS.find((s) => s.id === shortcutId);
    if (!nodeId || !sc) return;
    if (!sc.needsInput) {
      this.applyPrompt(nodeId, sc.prompt || "");
      this.close();
      return;
    }
    this.openInput(nodeId, shortcutId);
  },

  submitInput() {
    const nodeId = this.nodeId;
    const sc = TEXT_SHORTCUTS.find((s) => s.id === this.shortcutId);
    const wrap = nodeId ? this.wrap(nodeId) : null;
    const ta = wrap?.querySelector(".text-shortcut-textarea");
    const raw = (ta?.value || "").trim();
    if (!nodeId || !sc?.build) return;
    if (!raw) {
      ta?.focus();
      showCanvasToast("请先输入内容");
      return;
    }
    this.applyPrompt(nodeId, sc.build(raw));
    this.close();
  },
};

window.TextShortcuts = TextShortcuts;

function initTextShortcuts() {
  const layer = document.getElementById("nodes-layer");
  if (!layer) return;

  layer.addEventListener("click", (e) => {
    const closeBtn = e.target.closest("[data-text-shortcut-close]");
    if (closeBtn) {
      e.preventDefault();
      e.stopPropagation();
      TextShortcuts.close();
      return;
    }
    const submitBtn = e.target.closest("[data-text-shortcut-submit]");
    if (submitBtn) {
      e.preventDefault();
      e.stopPropagation();
      TextShortcuts.submitInput();
      return;
    }
    const item = e.target.closest(".text-shortcut-item");
    if (item) {
      e.preventDefault();
      e.stopPropagation();
      TextShortcuts.pick(item.dataset.shortcut);
      return;
    }
    const openBtn = e.target.closest(".btn-text-shortcuts");
    if (openBtn) {
      e.preventDefault();
      e.stopPropagation();
      const nodeId = openBtn.dataset.node;
      if (TextShortcuts.mode === "menu" && TextShortcuts.nodeId === nodeId) {
        TextShortcuts.close();
      } else {
        TextShortcuts.openMenu(nodeId);
      }
      return;
    }
    if (
      TextShortcuts.mode &&
      !e.target.closest(".text-shortcut-float") &&
      !e.target.closest(".btn-text-shortcuts")
    ) {
      TextShortcuts.close();
    }
  });

  layer.addEventListener("keydown", (e) => {
    if (!e.target.closest?.(".text-shortcut-textarea")) return;
    if (e.key === "Escape") {
      e.preventDefault();
      TextShortcuts.close();
      return;
    }
    if (e.key === "Enter" && (e.ctrlKey || e.metaKey)) {
      e.preventDefault();
      TextShortcuts.submitInput();
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape" || !TextShortcuts.mode) return;
    if (document.activeElement?.closest?.(".text-shortcut-float")) {
      TextShortcuts.close();
    }
  });
}

function renderVideoModeTabs(node) {
  return "";
}

function renderAudioAppModeTabs(node) {
  if (!node || node.type !== "voice") return "";
  const active = getNodeAudioAppMode(node);
  const tabs = AUDIO_APP_MODES.map(
    (m) =>
      `<button type="button" class="video-mode-tab audio-mode-tab${m.id === active ? " active" : ""}" data-node="${node.id}" data-audio-mode="${m.id}">${escapeHtml(m.label)}</button>`
  ).join("");
  return `<div class="panel-video-modes panel-audio-modes" role="tablist" aria-label="音频模式">${tabs}</div>`;
}

function renderAudioRecordPanel(node) {
  const recording = !!node._recording;
  const secs = Math.max(0, Number(node._recordElapsedSec) || 0);
  const label = recording ? `录音中 ${secs}s` : "准备录音";
  const hint = recording ? "最长 60 秒，再次点击结束" : "最长 1 分钟";
  const btnLabel = recording ? "停止录音" : "开始录音";
  return `
    <div class="audio-record-panel" data-node="${node.id}">
      <div class="audio-record-meta">
        <span class="audio-record-mic" aria-hidden="true">🎙</span>
        <div class="audio-record-copy">
          <div class="audio-record-title">${escapeHtml(label)}</div>
          <div class="audio-record-hint">${escapeHtml(hint)}</div>
        </div>
      </div>
      <button type="button" class="btn btn-primary btn-sm audio-record-btn${recording ? " is-recording" : ""}" data-action="audio-record-toggle" data-node="${node.id}">
        <span class="audio-record-dot" aria-hidden="true"></span>
        ${escapeHtml(btnLabel)}
      </button>
    </div>`;
}

function renderAudioMusicExtras(node) {
  const lyrics = String(node.lyrics || "");
  return `
    <div class="audio-music-block" data-node="${node.id}">
      <div class="audio-music-head">
        <span class="audio-music-label">歌词</span>
        <button type="button" class="btn-ghost btn-sm audio-lyrics-ai" data-action="audio-lyrics-hint" data-node="${node.id}" title="把上方风格描述展开为歌词草稿（写入歌词框）">AI 生成歌词</button>
      </div>
      <textarea class="audio-lyrics-input" data-node="${node.id}" data-field="lyrics" rows="4" spellcheck="false" placeholder="歌词内容，可手动编辑；支持 [Verse 1]、[Chorus] 等标记分段">${escapeHtml(lyrics)}</textarea>
    </div>`;
}

function renderNodePanel(node) {
  const isImage = node.type === "image";
  const isVideo = node.type === "video";
  const isVoice = node.type === "voice";
  const isText = isTextGenNode(node);
  const videoMode = isVideo ? getNodeVideoGenMode(node) : null;
  const audioMode = isVoice ? getNodeAudioAppMode(node) : null;
  const needsAssets = isVoice
    ? audioAppModeNeedsAssets(audioMode)
    : !isVideo || videoModeNeedsAssets(videoMode);
  const placeholder = isImage
    ? "请输入图片描述…"
    : isVideo
      ? videoPromptPlaceholder(videoMode)
      : isVoice
        ? audioAppPromptPlaceholder(audioMode)
        : isVoiceTextNode(node)
          ? "牵线人物图后生成一句话音色描述；也可直接改提示词…"
          : "请输入您的问题或指令，输入 / 查看快捷提示词，@ 引用参考素材…";
  const ratios = isImage ? IMAGE_RATIOS : VIDEO_RATIOS;
  const ratioBtns = ratios
    .map(
      (r) =>
        `<button type="button" class="pill-btn ratio-btn ${node.ratio === r ? "active" : ""}" data-node="${node.id}" data-ratio="${r}">${r}</button>`
    )
    .join("");
  const statusText = node.status === "failed" ? node.error || "失败" : "";
  const toolbar =
    isVoice && audioMode === "record"
      ? ""
      : isVideo
        ? renderVideoToolbar(node)
        : isImage
          ? renderImageToolbar(node)
          : isVoice
            ? renderVoiceToolbar(node)
            : isText
              ? renderTextToolbar(node)
              : `${renderChannelPicker(node, { allowGpt: node.type !== "video" })}
        <span class="panel-ratio-label">比例</span>
        <div class="ratio-group">${ratioBtns}</div>
        <span class="panel-toolbar-spacer"></span>
        ${renderGenActionBtns(node, node.type)}`;
  const shortcutsBtn = isText && !isVoiceTextNode(node)
    ? `<button type="button" class="btn-text-shortcuts" data-node="${node.id}" title="快捷提示词">快捷提示词 <span class="btn-text-shortcuts-mark">&gt;_</span></button>`
    : "";
  const quickMentionBtn =
    isVoiceTextNode(node) || !needsAssets || (isVoice && audioMode === "record")
      ? ""
      : `<button type="button" class="btn-quick-mention" data-node="${node.id}" title="按名字批量加上 @素材（引号内对话跳过）">快速添加</button>`;
  const quickMentionAllBtn =
    isVoiceTextNode(node) || !needsAssets || (isVoice && audioMode === "record")
      ? ""
      : renderQuickMentionApplyAllBtn(node.id);
  const retryToggle =
    isVoice && audioMode === "record" ? "" : renderAutoRetryToggle(node, { placement: "tools" });
  const modeTabs = isVideo
    ? renderVideoModeTabs(node)
    : isVoice
      ? renderAudioAppModeTabs(node)
      : "";
  const refsBlock = needsAssets
    ? `<div class="panel-refs">
        <div class="ref-inputs">${renderInputRefsHtml(node)}</div>
      </div>`
    : "";
  const musicExtras = isVoice && audioMode === "music" ? renderAudioMusicExtras(node) : "";
  const recordBody = isVoice && audioMode === "record" ? renderAudioRecordPanel(node) : "";
  const isMusicMode = isVoice && audioMode === "music";
  // Music: hide「快速添加」— refs are audio chips only; style field is the main prompt.
  const musicPromptTools = isMusicMode
    ? `<div class="panel-prompt-tools"><span class="panel-prompt-tools-spacer" aria-hidden="true"></span>${retryToggle}</div>`
    : `<div class="panel-prompt-tools">${shortcutsBtn}${quickMentionBtn}${quickMentionAllBtn}<span class="panel-prompt-tools-spacer" aria-hidden="true"></span>${retryToggle}</div>`;
  const styleLabel = isMusicMode
    ? `<div class="audio-music-head audio-style-head"><span class="audio-music-label">风格</span></div>`
    : "";
  const promptBlock =
    isVoice && audioMode === "record"
      ? ""
      : `${musicPromptTools}
      <div class="panel-qm-records-host">${needsAssets && !isMusicMode ? renderQuickMentionRecordsHtml(node) : ""}</div>
      ${styleLabel}
      <div class="panel-prompt-wrap${isMusicMode ? " audio-style-wrap" : ""}${isVoice && audioMode === "tts" ? " audio-tts-wrap" : ""}">
        <div class="prompt-editor node-prompt" contenteditable="true" spellcheck="false" data-node="${node.id}" data-placeholder="${escapeAttr(placeholder)}"></div>
      </div>
      ${musicExtras}
      <div class="panel-text-wires-host">${renderWiredTextRefsHtml(node)}</div>`;

  return `
    <div class="node-panel${isVideo ? ` video-mode-${escapeAttr(videoMode)}` : ""}${isVoice ? ` audio-mode-${escapeAttr(audioMode)}` : ""}">
      ${
        isVoice && audioMode === "record"
          ? ""
          : `<button type="button" class="btn-expand-prompt" data-node="${node.id}" title="放大描述">⤢</button>`
      }
      ${modeTabs}
      ${refsBlock}
      ${promptBlock}
      ${recordBody}
      ${
        node.status === "failed" && String(node.error || "").trim() && recHasKeepablePreview(node)
          ? renderStickyGenErrorLine(node)
          : statusText
            ? `<div class="node-status node-status-error">${escapeHtml(formatNodeErrorDisplay(node.error || statusText, statusText))}</div>`
            : ""
      }
      ${toolbar ? `<div class="panel-toolbar${isVideo ? " video-toolbar" : ""}">${toolbar}</div>` : ""}
    </div>`;
}

function renderNodeShell(node) {
  const selected = isNodeExpanded(node);
  const isRef = isReferenceNode(node);
  const hasMediaTools = nodeHasCapturableVideo(node) || nodeHasAudio(node) || nodeHasImage(node);
  const wrapW = getNodeWrapWidth(node);
  const panelBlock =
    isRef || !selected ? "" : `<div class="node-panel-wrap">${renderNodePanel(node)}</div>`;

  return `
    <div class="node-wrap${selected ? " is-selected expanded" : " compact"}${CanvasStore.selectedIds.includes(node.id) && !selected ? " is-picked" : ""}${isRef ? " is-ref-node" : ""}${hasMediaTools ? " has-media-tools" : ""}" data-id="${node.id}" data-type="${node.type}" style="left:${getNodeVisualX(node)}px;top:${node.y}px;width:${wrapW}px">
      <div class="node-preview-col" style="width:${getNodeWidth(node)}px">${renderNodeBody(node)}</div>
      ${panelBlock}
    </div>`;
}

function applyNodeDragging(nodeId, dragging) {
  const wrap = document.querySelector(`.node-wrap[data-id="${nodeId}"]`);
  if (!wrap) return;
  const node = CanvasStore.activeBoard().nodes.find((n) => n.id === nodeId);
  wrap.classList.toggle("is-dragging", dragging);
  if (dragging && node) {
    wrap.style.width = getNodeWidth(node) + "px";
    wrap.style.left = getNodeVisualX(node) + "px";
    wrap.style.top = node.y + "px";
    wrap.style.transform = "";
  }
}

function nodeTypeIconSvg(kind) {
  const common = 'width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true"';
  if (kind === "image" || kind === "ref-image") {
    return `<svg ${common}><rect x="2.5" y="3.5" width="11" height="9" rx="1.5" stroke="currentColor" stroke-width="1.2"/><circle cx="5.8" cy="6.8" r="1" fill="currentColor"/><path d="M3.5 11.2l3-3.1 2.2 2.1 1.8-1.5 2.5 2.5" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
  }
  if (kind === "video" || kind === "ref-video") {
    return `<svg ${common}><rect x="2" y="4" width="9" height="8" rx="1.4" stroke="currentColor" stroke-width="1.2"/><path d="M11.2 6.6L14 5.2v5.6l-2.8-1.4V6.6z" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/></svg>`;
  }
  if (kind === "audio" || kind === "ref-audio") {
    return `<svg ${common}><path d="M6.2 12.2a1.8 1.8 0 110-3.6 1.8 1.8 0 010 3.6z" stroke="currentColor" stroke-width="1.2"/><path d="M8 10.4V3.8l5-1.1v6.4" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M13 9.1a1.6 1.6 0 11-3.2 0 1.6 1.6 0 013.2 0z" stroke="currentColor" stroke-width="1.2"/></svg>`;
  }
  if (kind === "voice-text") {
    // Waveform + text lines — reads as “timbre description”, not plain text / audio file
    return `<svg ${common}><path d="M2.5 8.2v-1.2M4.3 10V5.5M6.1 11.2V4.2M7.9 9.4V6" stroke="currentColor" stroke-width="1.25" stroke-linecap="round"/><path d="M10 4.2h4.2M10 7h3.2M10 9.8h4.2" stroke="currentColor" stroke-width="1.2" stroke-linecap="round"/></svg>`;
  }
  if (kind === "voice") {
    return `<svg ${common}><path d="M6.2 12.2a1.8 1.8 0 110-3.6 1.8 1.8 0 010 3.6z" stroke="currentColor" stroke-width="1.2"/><path d="M8 10.4V3.8l5-1.1v6.4" stroke="currentColor" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/><path d="M13 9.1a1.6 1.6 0 11-3.2 0 1.6 1.6 0 013.2 0z" stroke="currentColor" stroke-width="1.2"/></svg>`;
  }
  return `<svg ${common}><path d="M4.5 3.5h5.2L12 5.8v6.7H4.5V3.5z" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/><path d="M9.5 3.5V6H12" stroke="currentColor" stroke-width="1.2" stroke-linejoin="round"/></svg>`;
}

function nodeTypeMeta(node) {
  if (node.type === "ref-image") return { icon: nodeTypeIconSvg("image"), label: "图片引用", kind: "image" };
  if (node.type === "ref-video") return { icon: nodeTypeIconSvg("video"), label: "视频引用", kind: "video" };
  if (node.type === "ref-audio") return { icon: nodeTypeIconSvg("audio"), label: "音频", kind: "audio" };
  if (node.type === "image") return { icon: nodeTypeIconSvg("image"), label: "图片生成", kind: "image" };
  if (node.type === "video") return { icon: nodeTypeIconSvg("video"), label: "视频生成", kind: "video" };
  if (node.type === "voice") return { icon: nodeTypeIconSvg("voice"), label: "音频生成", kind: "voice" };
  if (node.type === "voice-text") return { icon: nodeTypeIconSvg("voice-text"), label: "音色描述", kind: "text" };
  return { icon: nodeTypeIconSvg("text"), label: "文本生成", kind: "text" };
}

function renderAudioWaveBarsHtml(count = 28) {
  return Array.from({ length: count }, (_, i) => {
    const h = 20 + ((i * 37) % 55);
    return `<span style="height:${h}%"></span>`;
  }).join("");
}

function renderAudioPreviewHtml(node) {
  const src = resolveMediaUrl(node.audioUrl);
  const fmt = audioFmtLabel(node.audioUrl);
  const rate = Number(node.audioRate) > 0 ? Number(node.audioRate) : 1;
  return `<div class="node-preview has-media ref-media ref-audio-preview" data-audio-node="${node.id}">
    <div class="audio-card" title="点击播放按钮播放/暂停">
      <button type="button" class="audio-card-dl" data-action="tool-download" data-node="${node.id}" title="下载" aria-label="下载">
        <svg width="14" height="14" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="M8 2v8m0 0L5.5 7.5M8 10l2.5-2.5M3 13h10" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round"/></svg>
      </button>
      <div class="audio-wave" aria-hidden="true">${renderAudioWaveBarsHtml(28)}</div>
      <div class="audio-card-foot">
        <span class="audio-time" data-audio-time="${node.id}">0:00 / --:--</span>
        <button type="button" class="audio-play-btn" data-action="audio-toggle" data-node="${node.id}" title="播放/暂停" aria-label="播放">
          <svg class="audio-play-icon" width="12" height="12" viewBox="0 0 12 12" fill="currentColor" aria-hidden="true"><path d="M3 1.8v8.4l7-4.2-7-4.2z"/></svg>
          <svg class="audio-pause-icon" width="12" height="12" viewBox="0 0 12 12" fill="currentColor" aria-hidden="true"><path d="M2.5 2h2.2v8H2.5V2zm4.8 0H9.5v8H7.3V2z"/></svg>
        </button>
        <span class="audio-fmt">${escapeHtml(fmt)}</span>
      </div>
      <audio src="${escapeAttr(src)}" preload="metadata" data-audio-el="${node.id}" data-rate="${rate}"></audio>
    </div>
  </div>`;
}

function formatAudioClock(sec) {
  if (!Number.isFinite(sec) || sec < 0) return "0:00";
  const s = Math.floor(sec);
  const m = Math.floor(s / 60);
  const r = s % 60;
  return `${m}:${String(r).padStart(2, "0")}`;
}

function bindMentionPreviewAudio(container) {
  const wrap = container?.querySelector?.(".mention-preview-audio");
  const audio = wrap?.querySelector("audio");
  const timeEl = wrap?.querySelector(".mention-audio-time");
  if (!wrap || !audio || !timeEl || audio.dataset.mentionAudioBound === "1") return;
  audio.dataset.mentionAudioBound = "1";
  const sync = () => {
    const dur = Number.isFinite(audio.duration) && audio.duration > 0 ? audio.duration : 0;
    timeEl.textContent = `${formatAudioClock(audio.currentTime)} / ${dur ? formatAudioClock(dur) : "--:--"}`;
  };
  audio.addEventListener("loadedmetadata", sync);
  audio.addEventListener("durationchange", sync);
  audio.addEventListener("timeupdate", sync);
  audio.addEventListener("play", sync);
  audio.addEventListener("pause", sync);
  audio.addEventListener("ended", sync);
  sync();
}

function pauseOtherCanvasAudio(exceptId) {
  document.querySelectorAll("audio[data-audio-el]").forEach((el) => {
    if (el.dataset.audioEl === exceptId) return;
    if (!el.paused) {
      try {
        el.pause();
      } catch (_) {}
    }
  });
}

function bindAudioCard(root) {
  (root || document).querySelectorAll(".ref-audio-preview audio[data-audio-el]").forEach((audio) => {
    if (audio.dataset.bound) return;
    audio.dataset.bound = "1";
    const id = audio.dataset.audioEl;
    const card = audio.closest(".audio-card") || audio.closest(".ref-audio-preview");
    const timeEl = document.querySelector(`[data-audio-time="${id}"]`);
    const btn = document.querySelector(`.audio-play-btn[data-node="${id}"]`);
    const sync = () => {
      const dur = Number.isFinite(audio.duration) ? audio.duration : 0;
      if (timeEl) {
        timeEl.textContent = `${formatAudioClock(audio.currentTime)} / ${dur ? formatAudioClock(dur) : "--:--"}`;
      }
      btn?.classList.toggle("is-playing", !audio.paused);
      card?.classList.toggle("is-playing", !audio.paused);
    };
    audio.addEventListener("loadedmetadata", sync);
    audio.addEventListener("timeupdate", sync);
    audio.addEventListener("play", sync);
    audio.addEventListener("pause", sync);
    audio.addEventListener("ended", () => {
      try {
        audio.currentTime = 0;
      } catch (_) {}
      sync();
    });
    const rate = Number(audio.dataset.rate) > 0 ? Number(audio.dataset.rate) : 1;
    audio.playbackRate = rate;
    sync();
  });
}

function renderNodeLabelRow(node) {
  const { icon } = nodeTypeMeta(node);
  const board = CanvasStore.activeBoard();
  const name = getNodeDisplayName(node, board);
  const isRef = isReferenceNode(node);
  const ratio =
    !isRef && node.ratio && !isTextGenNode(node)
      ? `<span class="node-ratio">${escapeHtml(node.ratio)}</span>`
      : "";
  const genTime = !isRef ? renderGenTimeBadge(node) : "";
  const okBadge =
    isRef && node.status === "completed"
      ? `<span class="node-ok-badge" title="已就绪" aria-label="已就绪"><svg width="10" height="10" viewBox="0 0 12 12" fill="none" aria-hidden="true"><circle cx="6" cy="6" r="5.2" fill="#22c55e"/><path d="M3.6 6.1l1.6 1.6 3.2-3.3" stroke="#04140a" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg></span>`
      : "";
  const newBadge = shouldShowNodeNewBadge(node) ? renderNodeNewBadgeHtml() : "";
  const errorBadge = shouldShowNodeErrorBadge(node) ? renderNodeErrorBadgeHtml(node.id) : "";
  const deleteBtn = isRef
    ? `<button type="button" class="node-ref-delete node-delete" data-node="${node.id}" title="删除"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M6 6l12 12M18 6L6 18" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg></button>`
    : "";
  return `
    <div class="node-label-row">
      <div class="node-label" aria-label="${isRef ? "引用节点，双击重命名" : "双击重命名"}">
        <span class="node-label-icon">${icon}</span>
        <span class="node-label-text" data-node="${node.id}">${escapeHtml(name)}</span>
        ${ratio}
        ${genTime}
        ${okBadge}
        ${errorBadge}
        ${newBadge}
      </div>
      ${deleteBtn}
    </div>`;
}

function renderNodeBody(node) {
  let preview;
  if (isTextGenNode(node)) {
    preview = renderTextPreview(node);
  } else {
    preview = renderPreviewContent(node);
  }
  const stickyFail =
    isReferenceNode(node) &&
    node.status === "failed" &&
    String(node.error || "").trim() &&
    typeof recHasKeepablePreview === "function" &&
    recHasKeepablePreview(node) &&
    typeof renderStickyGenErrorLine === "function"
      ? renderStickyGenErrorLine(node)
      : "";
  return `
    ${renderNodeLiteChrome(node)}
    ${renderMediaToolbar(node)}
    ${renderNodeLabelRow(node)}
    <div class="node-body">
      <div class="node-port-zone port-zone-in left" data-node="${node.id}" data-side="in" title="输入 · 接收上游"></div>
      <button type="button" class="node-port port-in left" data-node="${node.id}" title="输入 · 接收上游" aria-label="输入"></button>
      ${preview}
      <button type="button" class="node-port port-out right" data-node="${node.id}" title="输出 · 拖到下游" aria-label="输出"></button>
      <div class="node-port-zone port-zone-out right" data-node="${node.id}" data-side="out" title="输出 · 拖到下游"></div>
    </div>
    ${stickyFail}`;
}

function renderTextPreview(node) {
  const w = getNodeWidth(node);
  const h = getNodePreviewHeight(node);
  const style = `style="width:${w}px;height:${h}px;aspect-ratio:auto;"`;
  const voice = isVoiceTextNode(node);
  if (node.status === "generating" || node.status === "pending" || node.status === "waiting") {
    const workBar =
      node.status === "waiting"
        ? ""
        : renderGenWorkIdBar(node, { compact: true });
    return `<div class="node-preview generating${voice ? " is-voice-text" : ""}" ${style} data-text-node="${node.id}">
      <div class="gen-scan-track"><div class="gen-scan-bar"></div></div>
      <span class="preview-hint">${escapeHtml(progressLabelForNode(node))}</span>
      ${workBar}
    </div>`;
  }
  if (node.status === "failed") {
    const paused = isPausedGenerationError(node.error);
    const workBar = renderGenWorkIdBar(node, { showRaw: true });
    return `<div class="node-preview error node-preview-error${voice ? " is-voice-text" : ""}" ${style} data-text-node="${node.id}">
      <div class="node-preview-error-body">
        <div class="preview-error-title">${paused ? "已暂停" : "生成失败"}</div>
        <div class="preview-hint">${escapeHtml(formatNodeErrorDisplay(node.error || "失败", "失败"))}</div>
      </div>
      ${workBar}
    </div>`;
  }
  const body = String(node.resultText || "").trim();
  if (body) {
    if (voice) {
      const oneLine = normalizeVoiceTextResult(body);
      return `<div class="node-preview voice-text-result has-media" ${style} data-text-node="${node.id}" title="双击放大编辑">
        <div class="voice-text-card">
          <div class="voice-text-wave" aria-hidden="true">${renderAudioWaveBarsHtml(12)}</div>
          <div class="voice-text-body">${escapeHtml(oneLine)}</div>
        </div>
        <span class="text-result-expand-hint">双击编辑</span>
      </div>`;
    }
    return `<div class="node-preview text-result has-media" ${style} data-text-node="${node.id}" title="双击放大编辑">
      <div class="text-result-inner">${escapeHtml(body)}</div>
      <span class="text-result-expand-hint">双击编辑</span>
    </div>`;
  }
  if (voice) {
    return `<div class="node-preview empty is-voice-text" ${style} data-text-node="${node.id}">
      <div class="voice-text-empty-wave" aria-hidden="true">${renderAudioWaveBarsHtml(10)}</div>
      <span class="preview-icon">${nodeTypeIconSvg("voice-text")}</span>
      <span class="preview-hint">牵线图片，生成音色描述</span>
    </div>`;
  }
  return `<div class="node-preview empty" ${style} data-text-node="${node.id}">
    <span class="preview-icon">${nodeTypeIconSvg("text")}</span>
    <span class="preview-hint">输入提示词生成文本</span>
  </div>`;
}

function renderNodeCard(node) {
  return renderNodeShell(node);
}

function selectNode(nodeId, opts) {
  selectSingle(nodeId, opts);
}

function deselectNode() {
  clearSelection();
}

function updateNodeCount() {
  const board = CanvasStore.activeBoard();
  const n = board?.nodes?.length || 0;
  const c = board?.connections?.length || 0;
  const nodeNum = document.getElementById("node-count-num");
  const connNum = document.getElementById("conn-count-num");
  if (nodeNum) nodeNum.textContent = String(n);
  if (connNum) connNum.textContent = String(c);
  const listBtn = document.getElementById("canvas-status-bar");
  if (listBtn) listBtn.setAttribute("aria-label", `所有节点 ${n}`);
  if (typeof NodeListPanel !== "undefined") NodeListPanel.refreshIfOpen();
}

/**
 * Bottom / top chrome popovers are exclusive — opening one closes the others.
 * @param {string} except node-list|agent|log|nav|user|internal|board|avatar|menu
 */
function closeExclusiveChromePopovers(except = "") {
  if (except !== "agent") {
    try {
      window.AgentPanel?.close?.();
    } catch {
      /* ignore */
    }
  }
  if (except !== "node-list") {
    try {
      if (typeof NodeListPanel !== "undefined") NodeListPanel.close();
      else window.NodeListPanel?.close?.();
    } catch {
      /* ignore */
    }
  }
  if (except !== "board-history") {
    try {
      BoardHistoryPanel?.close?.();
    } catch {
      /* ignore */
    }
  }
  if (except !== "dock-settings") {
    try {
      ChromeDock?.closeSettings?.();
    } catch {
      /* ignore */
    }
  }
  if (except !== "log") {
    if (typeof window.closeLogPanel === "function") {
      window.closeLogPanel();
    } else {
      const logPanel = document.getElementById("log-panel");
      if (logPanel && typeof isOverlayOpen === "function" && isOverlayOpen(logPanel)) {
        dismissOverlay(logPanel);
        document.getElementById("btn-logs")?.setAttribute("aria-pressed", "false");
      }
    }
  }
  if (except !== "nav") {
    const nav = document.getElementById("nav-panel");
    if (nav && typeof isOverlayOpen === "function" && isOverlayOpen(nav)) {
      dismissOverlay(nav);
    }
  }
  if (except === "user") {
    window.CanvasAuth?.closeInternalPop?.();
  } else if (except === "internal") {
    window.CanvasAuth?.closeUserPop?.();
  } else if (except !== "user" && except !== "internal") {
    window.CanvasAuth?.closeAllAccountPops?.();
  }
  if (except !== "board" && except !== "avatar") {
    if (typeof closeBoardMenus === "function") closeBoardMenus();
  }
  if (except !== "menu" && typeof hideContextMenus === "function") {
    hideContextMenus({ immediate: true });
  }
}
window.closeExclusiveChromePopovers = closeExclusiveChromePopovers;

const NodeListPanel = {
  filter: "all",
  query: "",
  page: 1,
  pageSize: 20,
  _bound: false,
  _activeId: "",

  filters: [
    { id: "all", label: "全部" },
    { id: "image", label: "图" },
    { id: "video", label: "视" },
    { id: "audio", label: "音" },
    { id: "text", label: "文" },
  ],

  shortTypeLabel(node) {
    const kind = nodeTypeMeta(node)?.kind || "text";
    if (kind === "image") return "图片";
    if (kind === "video") return "视频";
    if (kind === "audio") return "音频";
    return "文本";
  },

  categoryOf(node) {
    return nodeTypeMeta(node)?.kind || "text";
  },

  els() {
    return {
      wrap: document.getElementById("status-bar-wrap"),
      bar: document.getElementById("canvas-status-bar"),
      panel: document.getElementById("node-list-panel"),
      body: document.getElementById("node-list-body"),
      pager: document.getElementById("node-list-pager"),
      pageLabel: document.getElementById("node-list-page-label"),
      search: document.getElementById("node-list-search"),
      filters: document.getElementById("node-list-filters"),
      close: document.getElementById("node-list-close"),
    };
  },

  isOpen() {
    const { panel } = this.els();
    return !!(panel && typeof isOverlayOpen === "function" && isOverlayOpen(panel));
  },

  open() {
    const { bar, panel } = this.els();
    if (!panel) return;
    closeExclusiveChromePopovers("node-list");
    this.render();
    revealOverlay(panel);
    panel.setAttribute("aria-hidden", "false");
    bar?.setAttribute("aria-expanded", "true");
    document.getElementById("btn-dock-locate")?.classList.add("is-active");
    document.getElementById("btn-dock-locate")?.setAttribute("aria-expanded", "true");
  },

  close() {
    const { bar, panel, search } = this.els();
    if (!panel) return;
    dismissOverlay(panel);
    panel.setAttribute("aria-hidden", "true");
    bar?.setAttribute("aria-expanded", "false");
    document.getElementById("btn-dock-locate")?.classList.remove("is-active");
    document.getElementById("btn-dock-locate")?.setAttribute("aria-expanded", "false");
    if (search && document.activeElement === search) search.blur();
  },

  toggle() {
    if (this.isOpen()) this.close();
    else this.open();
  },

  refreshIfOpen() {
    if (!this.isOpen()) return;
    const { body } = this.els();
    const scrollTop = body?.scrollTop || 0;
    this.render();
    if (body) body.scrollTop = scrollTop;
  },

  filteredNodes() {
    const board = CanvasStore.activeBoard();
    const nodes = board?.nodes || [];
    const q = String(this.query || "").trim().toLowerCase();
    return nodes
      .map((node, index) => ({ node, index, name: getNodeDisplayName(node, board) }))
      .filter(({ node, name }) => {
        if (this.filter !== "all" && this.categoryOf(node) !== this.filter) return false;
        if (!q) return true;
        const type = this.shortTypeLabel(node);
        const meta = nodeTypeMeta(node)?.label || "";
        return (
          name.toLowerCase().includes(q) ||
          type.toLowerCase().includes(q) ||
          meta.toLowerCase().includes(q) ||
          String(node.id || "").toLowerCase().includes(q)
        );
      });
  },

  pageInfo(total) {
    const size = Math.max(1, this.pageSize || 20);
    const pages = Math.max(1, Math.ceil(total / size));
    const page = Math.min(Math.max(1, this.page || 1), pages);
    this.page = page;
    const start = (page - 1) * size;
    return { size, pages, page, start, end: start + size };
  },

  setPage(next) {
    const rows = this.filteredNodes();
    const { pages } = this.pageInfo(rows.length);
    const page = Math.min(Math.max(1, Number(next) || 1), pages);
    if (page === this.page) return;
    this.page = page;
    const { body } = this.els();
    this.render();
    if (body) body.scrollTop = 0;
  },

  counts() {
    const board = CanvasStore.activeBoard();
    const nodes = board?.nodes || [];
    const out = { all: nodes.length, image: 0, video: 0, audio: 0, text: 0 };
    for (const n of nodes) {
      const k = this.categoryOf(n);
      if (out[k] != null) out[k] += 1;
    }
    return out;
  },

  renderFilters() {
    const { filters } = this.els();
    if (!filters) return;
    const counts = this.counts();
    filters.innerHTML = this.filters
      .map((f) => {
        const count = counts[f.id] ?? 0;
        const label = f.id === "all" || count > 0 ? `${f.label} ${count}` : f.label;
        return `<button type="button" class="node-list-filter${this.filter === f.id ? " is-active" : ""}" data-filter="${f.id}" role="tab" aria-selected="${this.filter === f.id ? "true" : "false"}">${escapeHtml(label)}</button>`;
      })
      .join("");
  },

  renderPager(total) {
    const { pager, pageLabel } = this.els();
    if (!pager) return;
    if (!total) {
      pager.hidden = true;
      return;
    }
    const { page, pages } = this.pageInfo(total);
    pager.hidden = false;
    if (pageLabel) pageLabel.textContent = `${page} / ${pages}`;
    const atFirst = page <= 1;
    const atLast = page >= pages;
    pager.querySelectorAll("[data-page]").forEach((btn) => {
      const kind = btn.dataset.page;
      const disabled =
        (kind === "first" || kind === "prev" ? atFirst : false) ||
        (kind === "last" || kind === "next" ? atLast : false);
      btn.disabled = disabled;
    });
  },

  render() {
    const { body } = this.els();
    if (!body) return;
    this.renderFilters();
    const selected = new Set(getSelectedIds?.() || CanvasStore.selectedIds || []);
    if (CanvasStore.primaryId) selected.add(CanvasStore.primaryId);
    const rows = this.filteredNodes();
    this.renderPager(rows.length);
    if (!rows.length) {
      body.innerHTML = `<div class="node-list-empty">${escapeHtml(this.query || this.filter !== "all" ? "没有匹配的节点" : "画布上还没有节点")}</div>`;
      return;
    }
    const { start, end } = this.pageInfo(rows.length);
    const pageRows = rows.slice(start, end);
    body.innerHTML = pageRows
      .map(({ node, index, name }) => {
        const type = this.shortTypeLabel(node);
        const thumb = renderMediaThumbHtml(node) || nodeTypeMeta(node).icon;
        const active = this._activeId === node.id;
        const isSel = selected.has(node.id);
        return `<button type="button" class="node-list-item${active ? " is-active" : ""}${isSel ? " is-selected" : ""}" data-node-id="${escapeAttr(node.id)}" title="${escapeAttr(name)}">
          <span class="node-list-thumb">
            <span class="node-list-idx">${index + 1}</span>
            ${thumb}
          </span>
          <span class="node-list-meta">
            <span class="node-list-name">${escapeHtml(name)}</span>
            <span class="node-list-type">${escapeHtml(type)}</span>
          </span>
          <span class="node-list-go" aria-hidden="true">
            <svg width="12" height="12" viewBox="0 0 16 16" fill="none"><path d="M6 3.5L10.5 8 6 12.5" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>
          </span>
        </button>`;
      })
      .join("");
    if (typeof hydrateMediaThumbs === "function") hydrateMediaThumbs(body);
  },

  locate(nodeId) {
    if (!nodeId) return;
    this._activeId = nodeId;
    this.render();
    if (typeof focusNodeOnCanvasSmooth === "function") {
      focusNodeOnCanvasSmooth(nodeId, { durationMs: 560, save: true });
    } else if (typeof focusNodeOnCanvas === "function") {
      focusNodeOnCanvas(nodeId);
    }
  },
};

function initNodeListPanel() {
  const panelApi = NodeListPanel;
  const { bar, panel, body, pager, search, filters, close } = panelApi.els();
  if (!bar || !panel || panelApi._bound) return;
  panelApi._bound = true;

  bar.addEventListener("click", (e) => {
    e.stopPropagation();
    panelApi.toggle();
  });

  close?.addEventListener("click", (e) => {
    e.stopPropagation();
    panelApi.close();
  });

  panel.addEventListener("click", (e) => e.stopPropagation());

  body?.addEventListener("click", (e) => {
    const item = e.target.closest(".node-list-item[data-node-id]");
    if (!item) return;
    e.preventDefault();
    e.stopPropagation();
    panelApi.locate(item.dataset.nodeId);
  });

  pager?.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-page]");
    if (!btn || btn.disabled) return;
    e.stopPropagation();
    const rows = panelApi.filteredNodes();
    const { page, pages } = panelApi.pageInfo(rows.length);
    const kind = btn.dataset.page;
    if (kind === "first") panelApi.setPage(1);
    else if (kind === "prev") panelApi.setPage(page - 1);
    else if (kind === "next") panelApi.setPage(page + 1);
    else if (kind === "last") panelApi.setPage(pages);
  });

  filters?.addEventListener("click", (e) => {
    const btn = e.target.closest("[data-filter]");
    if (!btn) return;
    e.stopPropagation();
    panelApi.filter = btn.dataset.filter || "all";
    panelApi.page = 1;
    panelApi.render();
  });

  let searchTimer = 0;
  search?.addEventListener("input", () => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => {
      panelApi.query = search.value || "";
      panelApi.page = 1;
      panelApi.render();
    }, 80);
  });
  search?.addEventListener("keydown", (e) => {
    if (e.key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      if (search.value) {
        search.value = "";
        panelApi.query = "";
        panelApi.page = 1;
        panelApi.render();
      } else {
        panelApi.close();
      }
    }
  });

  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape" && panelApi.isOpen()) {
      e.preventDefault();
      panelApi.close();
    }
  });

  document.addEventListener("click", (e) => {
    if (!panelApi.isOpen()) return;
    if (e.target.closest("#status-bar-wrap")) return;
    panelApi.close();
  });
}

window.NodeListPanel = NodeListPanel;

function shouldPauseCanvasSync({ ignorePending = false } = {}) {
  if (!ignorePending && CanvasStore._persistence?.pending) return true;
  if (CanvasStore.isDragging || CanvasStore.drag || ConnectionUI?.dragging || MarqueeUI?.active) {
    return true;
  }
  const ae = document.activeElement;
  if (
    ae?.matches?.(
      ".prompt-editor, #prompt-expand-editor, .node-panel select, .node-panel input, .node-panel textarea, .node-account, .video-duration-slider, .image-style-btn"
    )
  ) {
    return true;
  }
  if (document.querySelector(".prompt-editor:focus, #prompt-expand-editor:focus")) return true;
  if (document.querySelector(".video-model-menu:not(.hidden), .video-settings-pop:not(.hidden), .image-style-menu:not(.hidden), .channel-menu:not(.hidden), .media-tool-menu:not(.hidden)")) {
    return true;
  }
  if (typeof FrameCapture !== "undefined" && (FrameCapture.busy || FrameCapture.customNodeId)) {
    return true;
  }
  if (typeof MediaTools !== "undefined" && MediaTools.busy) {
    return true;
  }
  if (document.querySelector("dialog[open], .prompt-expand:not(.hidden), .video-lightbox:not(.hidden), .history-drawer:not(.hidden), .fc-studio:not(.hidden), .vt-studio:not(.hidden), .vc-modal:not(.hidden), .vg-modal:not(.hidden), .vcrop-studio:not(.hidden), .icrop-studio:not(.hidden), .igrid-studio:not(.hidden), .at-studio:not(.hidden)")) return true;
  return false;
}

function findCanvasTaskBinding(task) {
  if (!task?.id) return null;
  for (const board of CanvasStore.boards || []) {
    const node = (board.nodes || []).find((item) => item.taskId === task.id);
    if (node) return { board, node, rebound: false };
  }

  // A refresh can happen after the backend created the task but before the
  // returned taskId reached canvas storage. The task row is the durable link.
  if (!task.node_id || task.workbench_id) return null;
  const status = String(task.status || "");
  const active = status === "pending" || status === "generating";
  const boards = task.board_id
    ? (CanvasStore.boards || []).filter((board) => board.id === task.board_id)
    : CanvasStore.boards || [];
  for (const board of boards) {
    const node = (board.nodes || []).find((item) => item.id === task.node_id);
    if (!node || (node.taskId && node.taskId !== task.id)) continue;
    const kind = String(task.kind || "video");
    const compatible =
      (kind === "video" && node.type === "video") ||
      (kind === "image" && node.type === "image") ||
      (kind === "voice" && node.type === "voice") ||
      (kind === "text" && (node.type === "text" || node.type === "voice-text" || isTextGenNode(node)));
    if (!compatible) continue;
    if (node.generationStopped || node.stoppedTaskId === task.id) continue;
    if (typeof isPausedGenerationError === "function" && isPausedGenerationError(node.error)) continue;
    const locallyInFlight =
      ["waiting", "pending", "generating"].includes(node.status) || !!node._genPayload;
    // An idle snapshot can predate submission. Recover only an exact board/node
    // match, preserving explicit stops and the user's selected history result.
    if (!locallyInFlight && (!task.board_id || node.status !== "idle" || node.activeHistoryId)) continue;
    // Never rebind an old cancelled/failed task onto a fresh generate (taskId was
    // cleared). That used to flash「已手动暂停」and orphan-cancel the new job.
    if (!active) continue;
    return { board, node, rebound: true };
  }
  return null;
}

function syncNodeFromTask(task) {
  const binding = findCanvasTaskBinding(task);
  if (!binding) return false;
  const { board, node, rebound } = binding;
    const prevStatus = node.status;
    const next = {
      taskId: task.id,
      status: task.status,
      videoUrl: task.video_url || null,
      imageUrl: task.image_url || null,
      audioUrl: task.audio_url || null,
      coverUrl: task.cover_url || null,
      thumbUrl: task.thumb_url || null,
      mediaWidth: task.width > 0 ? task.width : node.mediaWidth || null,
      mediaHeight: task.height > 0 ? task.height : node.mediaHeight || null,
      error: task.error || null,
    };
    // Never wipe the user's ratio with empty / default task.ratio (common on MyApi polls).
    const taskRatio = task.ratio != null ? String(task.ratio).trim() : "";
    if (taskRatio) {
      const localRatio = String(node.ratio || "").trim();
      const taskAuto = taskRatio === "自动" || taskRatio.toLowerCase() === "auto";
      const localConcrete =
        !!localRatio && localRatio !== "自动" && localRatio.toLowerCase() !== "auto";
      if (!(taskAuto && localConcrete)) {
        next.ratio = taskRatio;
      }
    }
    if (task.kind === "text" || isTextGenNode(node)) {
      if (task.text != null && String(task.text).length) {
        let body = String(task.text);
        if (isVoiceTextNode(node)) body = normalizeVoiceTextResult(body);
        // 已完成后不要反复用服务端原文盖掉用户在「生成结果」里手改的内容
        const local = String(node.resultText || "");
        const alreadyDone = prevStatus === "completed" || prevStatus === "failed";
        if (!alreadyDone || !local.trim()) {
          next.resultText = body;
        }
      }
    }
    // Keep local media while in-flight / failed so preview +「错」 sticky work like AI过检.
    // (UI still shows progress via status; do not wipe URLs on pending/generating polls.)
    // But never keep an old cover/thumb after the task switches to a *different* video/image —
    // otherwise copied nodes all show the source video's first frame forever.
    if (
      task.status === "pending" ||
      task.status === "generating" ||
      task.status === "failed" ||
      task.status === "completed"
    ) {
      const prevVideoKey = normalizeUploadUrlKey(node.videoUrl || "");
      const prevImageKey = normalizeUploadUrlKey(node.imageUrl || "");
      const prevAudioKey = normalizeUploadUrlKey(node.audioUrl || "");
      const taskVideoKey = normalizeUploadUrlKey(task.video_url || "");
      const taskImageKey = normalizeUploadUrlKey(task.image_url || "");
      const taskAudioKey = normalizeUploadUrlKey(task.audio_url || "");
      const videoSwitched = !!(taskVideoKey && prevVideoKey && taskVideoKey !== prevVideoKey);
      const imageSwitched = !!(taskImageKey && prevImageKey && taskImageKey !== prevImageKey);
      const audioSwitched = !!(taskAudioKey && prevAudioKey && taskAudioKey !== prevAudioKey);
      if (!next.videoUrl && node.videoUrl) next.videoUrl = node.videoUrl;
      if (!next.imageUrl && node.imageUrl) next.imageUrl = node.imageUrl;
      if (!next.audioUrl && node.audioUrl && !audioSwitched) next.audioUrl = node.audioUrl;
      if (!next.coverUrl && node.coverUrl && !videoSwitched && !imageSwitched) {
        next.coverUrl = node.coverUrl;
      }
      if (!next.thumbUrl && node.thumbUrl && !videoSwitched && !imageSwitched) {
        next.thumbUrl = node.thumbUrl;
      }
      if (isTextGenNode(node) && !next.resultText && node.resultText) {
        next.resultText = node.resultText;
      }
      // Drop leftover poster that clearly belongs to another upload stem.
      if (next.videoUrl && next.coverUrl && videoStillCoverMatches(next.videoUrl, next.coverUrl) === false) {
        next.coverUrl = null;
        if (next.thumbUrl && videoStillCoverMatches(next.videoUrl, next.thumbUrl) === false) {
          next.thumbUrl = null;
        }
      }
    }
    if ((task.status === "pending" || task.status === "generating") && !node.genStartedAt) {
      const fromTask = Date.parse(task.created_at || "");
      next.genStartedAt = Number.isFinite(fromTask) && fromTask > 0 ? fromTask : Date.now();
    }
    if (task.prompt_sent) {
      next.promptSent = true;
    }
    const prevPromptKind = node.userPromptKind || null;
    const decidedAction = String(task.user_action || "").trim().toLowerCase();
    // Once the user chose continue/skip, never resurrect the confirm gate from a
    // stale user_prompt_kind (API clears kind, but a concurrent poll can race).
    if (decidedAction === "continue" || decidedAction === "skip") {
      next.userPromptKind = null;
      next.userPromptMessage = null;
    } else if (task.user_prompt_kind) {
      next.userPromptKind = task.user_prompt_kind;
      next.userPromptMessage = task.user_prompt_message || null;
    } else if (prevPromptKind) {
      next.userPromptKind = null;
      next.userPromptMessage = null;
    }
    if ((task.status === "pending" || task.status === "generating") && typeof window.ensureProgressTicker === "function") {
      window.ensureProgressTicker();
    }
    if (task.status === "completed" || task.status === "failed") {
      if (node.genStartedAt) {
        next.lastGenMs = Math.max(0, Date.now() - node.genStartedAt);
      }
      next.genStartedAt = null;
      next.promptSent = false;
      next.userPromptKind = null;
      next.userPromptMessage = null;
      if (prevStatus !== task.status) {
        void window.CanvasAuth?.refreshPointsBalance?.();
      }
    }
    if (task.status === "completed") {
      next.autoRetryCount = 0;
      next.isError = false;
    }
    if (task.status === "completed" && (next.videoUrl || next.imageUrl || task.video_url || task.image_url || next.resultText)) {
      if (!isTextGenNode(node)) {
        const entry = buildGenHistoryEntry(
          { ...node, ...next, prompt: node.prompt, model: node.model, duration: node.duration, style: node.style },
          task,
          "success"
        );
        const genHistory = pushGenHistory(node, entry);
        next.genHistory = genHistory;
        const kept = genHistory.find((h) => h.taskId === entry.taskId) || genHistory.find((h) => (h.videoUrl || h.imageUrl) === (entry.videoUrl || entry.imageUrl)) || entry;
        next.activeHistoryId = kept.id;
      }
      // Mark unread「新」only when this completion just arrived and user hasn't selected the node.
      if (prevStatus !== "completed" && isGenerativeNode(node) && !isReferenceNode(node)) {
        const alreadyLooking =
          CanvasStore.selectedIds?.includes(node.id) ||
          CanvasStore.primaryId === node.id ||
          CanvasStore.selectedNodeId === node.id;
        next.isNew = !alreadyLooking;
      }
    }
    if (task.status === "failed") {
      const entry = buildGenHistoryEntry(
        { ...node, ...next, prompt: node.prompt, model: node.model, duration: node.duration, style: node.style, error: task.error || node.error },
        task,
        "failed"
      );
      next.genHistory = pushGenHistory(node, entry);
      // Older polls may have wiped URLs mid-flight — restore last successful history media.
      if (typeof recHasKeepablePreview === "function" && !recHasKeepablePreview({ ...node, ...next })) {
        const hist = Array.isArray(next.genHistory) ? next.genHistory : node.genHistory || [];
        const lastOk = [...hist]
          .reverse()
          .find(
            (h) =>
              h &&
              h.status === "success" &&
              (h.videoUrl || h.imageUrl || h.thumbUrl || h.coverUrl || String(h.resultText || "").trim())
          );
        if (lastOk) {
          if (!next.videoUrl && lastOk.videoUrl) next.videoUrl = lastOk.videoUrl;
          if (!next.imageUrl && lastOk.imageUrl) next.imageUrl = lastOk.imageUrl;
          if (!next.coverUrl && lastOk.coverUrl) next.coverUrl = lastOk.coverUrl;
          if (!next.thumbUrl && lastOk.thumbUrl) next.thumbUrl = lastOk.thumbUrl;
          if (isTextGenNode(node) && !next.resultText && lastOk.resultText) {
            next.resultText = lastOk.resultText;
          }
        }
      }
      Object.assign(
        next,
        withKeepableGenErrorFlag({ ...node, ...next }, {
          error: next.error || task.error || node.error || "生成失败",
        })
      );
      const retryPatch =
        typeof window.scheduleAutoRetryPatch === "function"
          ? window.scheduleAutoRetryPatch(node.id, task.error || node.error || "生成失败")
          : null;
      if (retryPatch) {
        Object.assign(next, retryPatch);
        Object.assign(next, withKeepableGenErrorFlag({ ...node, ...next }, { error: next.error }));
      } else {
        const used = Number(node.autoRetryCount) || 0;
        const maxRetry = window.AUTO_RETRY_MAX ?? 3;
        if (node.autoRetry && used >= maxRetry) {
          const base = (task.error || node.error || "生成失败").trim();
          next.error = `${base}（已自动重试 ${maxRetry} 次）`;
          Object.assign(next, withKeepableGenErrorFlag({ ...node, ...next }, { error: next.error }));
        }
      }
    }
    const changed = Object.keys(next).some((key) => {
      if (key === "genHistory") {
        return JSON.stringify(node.genHistory || []) !== JSON.stringify(next.genHistory || []);
      }
      return node[key] !== next[key];
    });
    if (!changed) return false;

    Object.assign(node, next);
    if (
      node.status === "completed" &&
      node.videoUrl &&
      !nodeVideoPosterUrl(node) &&
      typeof ensureMediaThumbRemote === "function"
    ) {
      void ensureMediaThumbRemote(node.videoUrl, "video").then((meta) => {
        if (!meta?.cover_url) return;
        const live = CanvasStore.activeBoard()?.nodes?.find((n) => n.id === node.id);
        if (!live || live.videoUrl !== node.videoUrl) return;
        if (live.coverUrl && videoStillCoverMatches(live.videoUrl, live.coverUrl) === true) return;
        applyMediaThumbMetaToNode(node.id, meta);
      });
    }
    if (node.status === "completed" || node.status === "failed") {
      CanvasStore.save();
      CanvasStore.flushSave();
      if (typeof window.onGenerationSlotFreed === "function") {
        window.onGenerationSlotFreed(node.id);
      }
    } else if (prevStatus !== node.status || rebound) {
      CanvasStore.save();
      if (rebound) void CanvasStore.flushSave();
    }
    if (board.id === CanvasStore.activeBoardId) {
      const becameTerminal =
        (node.status === "completed" || node.status === "failed") &&
        prevStatus !== node.status;
      const retryWaiting =
        node.status === "waiting" &&
        (Number(node.autoRetryCount) || 0) > 0 &&
        prevStatus !== node.status;
      const mediaArrived =
        (!!node.imageUrl && node.imageUrl !== (node._lastPaintedImageUrl || null)) ||
        (!!node.videoUrl && node.videoUrl !== (node._lastPaintedVideoUrl || null));
      const promptKindNow = node.userPromptKind || null;
      const paidPromptChanged = prevPromptKind !== promptKindNow;
      // Result / terminal must paint even if prompt editor is focused — pause only
      // blocks intermediate poll redraws; deferring forever left UI stuck on「正在生成」.
      if (becameTerminal || mediaArrived || retryWaiting) {
        node._lastPaintedImageUrl = node.imageUrl || null;
        node._lastPaintedVideoUrl = node.videoUrl || null;
        paintTaskResultNow(node.id);
      } else if (paidPromptChanged) {
        const wrap = document.querySelector(`.node-wrap[data-id="${CSS.escape(node.id)}"]`);
        if (wrap && !isCanvasInteractionActive()) softPatchNodeGenUi(wrap, node);
        else paintTaskResultNow(node.id);
      }
    }
    return true;
}

function paintTaskResultNow(nodeId) {
  if (isCanvasInteractionActive()) {
    _canvasPendingTaskPaints.add(String(nodeId || ""));
    scheduleCanvasBackgroundWork();
    return;
  }
  if (scheduleDeferredNodeRender._timer) {
    clearInterval(scheduleDeferredNodeRender._timer);
    scheduleDeferredNodeRender._timer = null;
  }
  const id = String(nodeId || "").trim();
  // Single-node path: soft-update that card only — do not rehydrate the whole board.
  if (id && typeof softRefreshNodeMedia === "function") {
    const wrap = document.querySelector(`.node-wrap[data-id="${CSS.escape(id)}"]`);
    if (wrap && CanvasStore.activeBoard()?.nodes?.some((n) => n.id === id)) {
      softRefreshNodeMedia(id, { refreshHosts: true });
      scheduleRenderConnections(true);
      if (typeof HistoryDock !== "undefined") HistoryDock.refresh();
      CanvasMinimap.scheduleRender();
      return;
    }
  }
  renderNodes({ immediate: true });
  if (typeof HistoryDock !== "undefined") HistoryDock.refresh();
}

function scheduleDeferredNodeRender() {
  if (scheduleDeferredNodeRender._timer) return;
  const started = Date.now();
  scheduleDeferredNodeRender._timer = setInterval(() => {
    // Force paint after ~2s even if still "paused" (focus/menus)
    if (shouldPauseCanvasSync() && Date.now() - started < 2000) return;
    clearInterval(scheduleDeferredNodeRender._timer);
    scheduleDeferredNodeRender._timer = null;
    renderNodes();
    if (typeof HistoryDock !== "undefined") HistoryDock.refresh();
  }, 400);
}

function escapeHtml(str) {
  const d = document.createElement("div");
  d.textContent = str || "";
  return d.innerHTML;
}

function escapeAttr(str) {
  return (str || "").replace(/"/g, "&quot;");
}

